		public void SearchOtherMods()
		{
			string path = "BepInEx/plugins";
			if (!Directory.Exists(path))
			{
				return;
			}
			string[] files = Directory.GetFiles(path, "*.dll", SearchOption.AllDirectories);
			foreach (string text in files)
			{
				string text2 = text;
				if (text2.Contains("/"))
				{
					text2 = Helper.GetLastString(text, "/");
				}
				if (text2.Contains("\\"))
				{
					text2 = Helper.GetLastString(text, "\\");
				}
				if (text2.Contains("KKS_UncensorSelector") && !OtherMods.Contains(Enums.Mod.UNCS))
				{
					OtherMods.Add(Enums.Mod.UNCS);
				}
				if (text2.Contains("KKS_BetterPenetration") && !OtherMods.Contains(Enums.Mod.BP))
				{
					OtherMods.Add(Enums.Mod.BP);
				}
				if (text2.Contains("KKS_Pushup") && !OtherMods.Contains(Enums.Mod.PSHUP))
				{
					OtherMods.Add(Enums.Mod.PSHUP);
				}
				if (text2.Contains("KKS_BrowserFolders_Hooks") && !OtherMods.Contains(Enums.Mod.BrwsFoldHooks))
				{
					OtherMods.Add(Enums.Mod.BrwsFoldHooks);
				}
			}
			foreach (Enums.Mod otherMod in OtherMods)
			{
				DebugInfos.InConsoleCompact(" Found the mod " + otherMod, "Core");
			}
		}

		internal void Awake()
		{
			try
			{
				SetCfg();
				SceneManager.sceneLoaded += OnSceneLoad;
				SearchOtherMods();
				AvailableFonts = new List<string>();
				string[] oSInstalledFontNames = Font.GetOSInstalledFontNames();
				foreach (string item in oSInstalledFontNames)
				{
					AvailableFonts.Add(item);
				}
			}
			catch
			{
			}
		}

		public void SetCfg()
		{
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			//IL_0039: Unknown result type (might be due to invalid IL or missing references)
			//IL_0043: Expected O, but got Unknown
			//IL_0043: Expected O, but got Unknown
			string empty = string.Empty;
			empty = PlugText.GetOp("tHMisc");
			ChangeDickMat = ((BaseUnityPlugin)this).Config.Bind<bool>(new ConfigDefinition(empty, PlugText.GetOp("oPenisMat")), false, new ConfigDescription(PlugText.GetOp("hPenisMat"), (AcceptableValueBase)null, new object[0]));
		}

		private static void OnSceneLoad(Scene scene, LoadSceneMode scnMode)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0076: Unknown result type (might be due to invalid IL or missing references)
			//IL_007b: Unknown result type (might be due to invalid IL or missing references)
			//IL_008b: Expected O, but got Unknown
			//IL_0090: Unknown result type (might be due to invalid IL or missing references)
			//IL_009a: Expected O, but got Unknown
			//IL_0115: Unknown result type (might be due to invalid IL or missing references)
			if ((int)scnMode != 0 || RunInVR)
			{
				return;
			}
			if (((Scene)(ref scene)).name == "VRTitle" && (Object)(object)dealer == (Object)null)
			{
				RunInVR = true;
				OtherMods.Clear();
				AvailableFonts.Clear();
				DebugInfos.InConsole("Running in VR ! ksPlug is disabled...", "Core");
				return;
			}
			if (((Scene)(ref scene)).name == "Title" && (Object)(object)dealer == (Object)null)
			{
				GameObject val = new GameObject();
				dealer = val.AddComponent<Dealer>();
				Object.DontDestroyOnLoad((Object)val);
				harmonyGlobal = new Harmony("ksPlugHarmony_global");
				harmonyGlobal.PatchAll(typeof(Core));
			}
			if (((Scene)(ref scene)).name == "Action")
			{
				Dealer.SetInStory(isInStory: true);
			}
			if (((Scene)(ref scene)).name == "Title" && (Object)(object)dealer != (Object)null && dealer.InStory)
			{
				Dealer.SetInStory(isInStory: false);
			}
			DebugInfos.InConsole("Load Scene " + ((Scene)(ref scene)).name, "Core");
			CurScene = scene;
		}

