		public static void HPointMove_PreStart()
		{
			if (!Settings.FreeStoryH)
			{
				return;
			}
			HFlag instance = Singleton<HFlag>.Instance;
			if (Object.op_Implicit((Object)(object)instance))
			{
				freeHStatePointMove = instance.isFreeH;
				instance.isFreeH = true;
				GameObject commonSpace = Scene.commonSpace;
				if ((Object)(object)commonSpace != (Object)null)
				{
					DeliveryHPointData component = commonSpace.GetComponent<DeliveryHPointData>();
					if (Object.op_Implicit((Object)(object)component))
					{
						DebugInfos.InConsole("HPointMove_PreStart , Found DeliveryHPointData and Force Free H State");
						component.isFreeH = true;
					}
				}
			}
			DebugInfos.InConsole("HPointMove_PreStart , Free H at Entry " + freeHStatePointMove);
		}

