	public class Dealer : MonoBehaviour
	{
		public enum Context
		{
			Default,
			H,
			Event,
			Esthetic,
			EstResult
		}

		public enum GoToMyHouseCase
		{
			ByGame,
			ByCallHome,
			ByGetNews,
			ByEndDay
		}

		public enum MenuCtx
		{
			NotInMenu,
			SaveLoad,
			Booking,
			Album,
			Config
		}

		public enum MapAskAction
		{
