			if (InStory && ((CtrlHome.IsActive && (Object)(object)freeCam != (Object)null) || (Ctx == Context.Default && MapID == 32 && PlayerIsChase) || (Ctx == Context.Event && MapID == 32)) && Keys.DressMenu)
