		public static void Log_AnimMapper()
		{
			if (!Core.debug)
			{
				return;
			}
			string text = "log_animMaper";
			try
			{
				StreamWriter streamWriter = new StreamWriter(debugFilePath + text + ".txt", append: false);
				Dictionary<string, string> dictionary = new Dictionary<string, string>();
				string text2 = "BepInEx/plugins/ksPlug/UIText/";
				if (File.Exists(text2 + "EN_poseNames.txt"))
				{
					dictionary = PlugText.BuildDicFromFile(text2 + "EN_poseNames.txt");
				}
				foreach (HAnims.AnimInfo hAnimInfo in HCtrl.Get.HAnimInfos)
				{
					string value = string.Empty;
					if (!dictionary.TryGetValue(hAnimInfo.plugName, out value))
					{
						value = hAnimInfo.plugName;
					}
					if (hAnimInfo.plugName == "Unknown")
					{
						streamWriter.WriteLine("!!! output[\"" + hAnimInfo.plugName + "\"] =  \"JP:" + hAnimInfo.animList.nameAnimation + "\"; (" + hAnimInfo.baseAsset + "/" + hAnimInfo.asset + "/ ctx = " + hAnimInfo.ctx.ToString() + ") " + value);
					}
					else
					{
						streamWriter.WriteLine("output[\"" + hAnimInfo.plugName + "\"] =  \"JP:" + hAnimInfo.animList.nameAnimation + "\"; (" + hAnimInfo.baseAsset + "/" + hAnimInfo.asset + "/ ctx = " + hAnimInfo.ctx.ToString() + ") " + value);
					}
				}
				streamWriter.Close();
			}
			catch (Exception)
			{
			}
		}

