		public static string FindFreeFileName(string path, string fileName, string ext)
		{
			if (!Directory.Exists(path))
			{
				Directory.CreateDirectory(path);
			}
			int num = 1;
			string text = ((num < 10) ? ("0" + num) : num.ToString());
			while (File.Exists(path + fileName + text + "." + ext))
			{
				num++;
				text = ((num < 10) ? ("0" + num) : num.ToString());
			}
			return path + fileName + text + "." + ext;
		}
