	public static class IListExtensions
	{
		public static void Shuffle<T>(this IList<T> toShuffle)
		{
			int count = toShuffle.Count;
			int num = count - 1;
			for (int i = 0; i < num; i++)
			{
				int index = Random.Range(i, count);
				T value = toShuffle[i];
				toShuffle[i] = toShuffle[index];
				toShuffle[index] = value;
			}
		}
	}
	public class Messenger : MonoBehaviour
	{
		public enum Height
		{
			Top,
			Middle,
			Bottom,
			Undefined
		}

		public enum Type
		{
			TopCorner_L,
			BotCorner_L,
			TopCorner_R,
			Undefined
		}

		public enum TagMsg
		{
			Undefined,
			Sex,
			Peep,
			Break
		}

		public class Timer
		{
			public float start;

			public float length;
		}

		public class Message
		{
			public Type typ = Type.Undefined;

			public Height height = Height.Undefined;

			public string text = string.Empty;

			public Timer timer = new Timer();

			public int fontSize = 10;

			public bool isAdditive;

			public bool write;

			public bool lerp;

			public GUIStyle GuiStyle;

			public Color mainColor = Color.white;

			public Color lerpColor = Color.white;

			public Color shdwColor = Color.white;

			public float heightFact_d1;

			public float heightFact_d0;

			public int id = -1;

			public TagMsg tagMsg;
		}

		private static string cmpName = "Messenger";

		private bool _dealerInProcess;

		private List<Message> messages = new List<Message>();

		private Message inProcessMsg;

		public bool InConfig => Core.dealer.InConfig;

		public bool DealerInProcess => Core.dealer.InProcess;

		private void Start()
		{
			ReceiveMessage(Type.BotCorner_L, PlugText.GetUiText("Start"), 5f);
			DebugInfos.InConsole("Start Component", cmpName);
		}

		private void LateUpdate()
		{
			if (_dealerInProcess != DealerInProcess)
			{
				_dealerInProcess = DealerInProcess;
				if (DealerInProcess)
				{
					inProcessMsg = ReceiveMessage(Type.BotCorner_L, PlugText.GetUiText("InProcess") + "...", float.PositiveInfinity);
				}
				else if (inProcessMsg != null)
				{
					inProcessMsg.timer.length = 0f;
				}
			}
			List<Message> list = new List<Message>();
			for (int i = 0; i < messages.Count; i++)
			{
				if (messages[i].timer.length == 0f || string.IsNullOrEmpty(messages[i].text))
				{
					list.Add(messages[i]);
				}
			}
			_ = messages.Count;
			foreach (Message item in list)
			{
				messages.Remove(item);
				DebugInfos.InConsoleCompact("Remove expired message \"" + item.text + "\"");
			}
		}

		private void OnGUI()
		{
			Dictionary<Type, List<int>> dictionary = MessageIdsNewDic();
			for (int i = 0; i < messages.Count; i++)
			{
				if (messages[i].GuiStyle == null)
				{
					DefineMsgStyle(messages[i]);
					DebugInfos.InConsole("Init GUIStyle for message " + messages[i].text, cmpName);
				}
				if (messages[i].timer.length > 0f && TimerHasExpired(messages[i].timer))
				{
					messages[i].timer.length = 0f;
				}
				if (messages[i].isAdditive)
				{
					for (int j = 0; j < 200; j++)
					{
						List<int> value = new List<int>();
						if (dictionary.TryGetValue(messages[i].typ, out value) && !value.Contains(j))
						{
							messages[i].id = j;
							value.Add(j);
							dictionary[messages[i].typ] = value;
							break;
						}
					}
				}
				DrawMessage(messages[i]);
			}
		}

		private static Dictionary<Type, List<int>> MessageIdsNewDic()
		{
			return new Dictionary<Type, List<int>>
			{
				[Type.TopCorner_L] = new List<int>(),
				[Type.TopCorner_R] = new List<int>(),
				[Type.BotCorner_L] = new List<int>()
			};
		}

		public Message ReceiveMessage(Type mTyp, string text, float duration, bool replace = true, bool write = false, bool lerp = false, TagMsg airTagMsg = TagMsg.Undefined)
		{
			Message message = new Message();
			message.typ = mTyp;
			message.height = ((!IsTop(message)) ? Height.Bottom : Height.Top);
			message.text = text;
			message.timer.length = duration;
			message.timer.start = (InConfig ? Time.unscaledTime : Time.time);
			message.write = write;
			message.lerp = lerp;
			message.fontSize = (IsTop(message) ? 12 : 10);
			message.tagMsg = airTagMsg;
			message.isAdditive = !replace;
			DefineMsgColors(message);
			DefineMsgPosition(message);
			if (!message.isAdditive)
			{
				List<Message> list = new List<Message>();
				bool flag = false;
				for (int i = 0; i < messages.Count; i++)
				{
					if (messages[i].typ == message.typ)
					{
						messages[i] = message;
						if (!flag)
						{
							flag = true;
						}
						else
						{
							list.Add(messages[i]);
						}
					}
				}
				foreach (Message item in list)
				{
					messages.Remove(item);
				}
				if (!flag)
				{
					messages.Add(message);
				}
			}
			else
			{
				messages.Add(message);
			}
			return message;
		}

		public void ReceiveStringList(List<string> msgs, Type msgTyp = Type.TopCorner_R, float wait = 0.15f)
		{
			((MonoBehaviour)this).StartCoroutine(IE_ReceiveStringList(msgs, msgTyp, wait));
		}

		private IEnumerator IE_ReceiveStringList(List<string> msgs, Type msgTyp = Type.TopCorner_R, float wait = 0.15f)
		{
			foreach (string msg in msgs)
			{
				Sound.Play((SystemSE)0);
				ReceiveMessage(msgTyp, msg, 6f, replace: false);
				yield return (object)new WaitForSeconds(wait);
			}
		}

