		public static void SaveMenuEdits(BaseMenu menu)
		{
			//IL_009a: Unknown result type (might be due to invalid IL or missing references)
			//IL_009f: Unknown result type (might be due to invalid IL or missing references)
			//IL_00bd: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c2: Unknown result type (might be due to invalid IL or missing references)
			string path = string.Concat("BepInEx/plugins/ksPlug/UserPrefs/MenusPref/", menu.MenuTyp, ".txt");
			if (!menu.IsPosEdited && !menu.IsSizeEdited && File.Exists(path))
			{
				File.Delete(path);
				return;
			}
			if (!Directory.Exists("BepInEx/plugins/ksPlug/UserPrefs/MenusPref"))
			{
				Directory.CreateDirectory("BepInEx/plugins/ksPlug/UserPrefs/MenusPref");
			}
			StreamWriter streamWriter = new StreamWriter(path, append: false);
			if (menu.IsSizeEdited)
			{
				streamWriter.WriteLine("Size = " + menu.MenuSize);
			}
			if (menu.IsPosEdited && menu.MenuTyp != BaseMenu.Type.GuestAction)
			{
				streamWriter.WriteLine("AnchorX = " + menu.CustomAnchors.x);
				streamWriter.WriteLine("AnchorY = " + menu.CustomAnchors.y);
			}
			streamWriter.Close();
		}

		public static void ReadMenuEdits(BaseMenu menu, ref float xAnchor, ref float yAnchor, ref float size)
		{
			string path = string.Concat("BepInEx/plugins/ksPlug/UserPrefs/MenusPref/", menu.MenuTyp, ".txt");
			if (!File.Exists(path))
			{
				return;
			}
			StreamReader streamReader = new StreamReader(path);
			string text = streamReader.ReadToEnd();
			streamReader.Close();
			string[] array = text.Split(new string[1] { "\n" }, StringSplitOptions.None);
			foreach (string text2 in array)
			{
				if (text2.Contains("Size ="))
				{
					size = ReadFloat(text2);
				}
				if (text2.Contains("AnchorX ="))
				{
					xAnchor = ReadFloat(text2);
				}
				if (text2.Contains("AnchorY ="))
				{
					yAnchor = ReadFloat(text2);
				}
			}
		}

		public static void SaveBinderEdits(Dictionary<string, string> binderPrefDic)
		{
			if (!Directory.Exists("BepInEx/plugins/ksPlug/UserPrefs/BinderPref"))
			{
				Directory.CreateDirectory("BepInEx/plugins/ksPlug/UserPrefs/BinderPref");
			}
			StreamWriter streamWriter = new StreamWriter("BepInEx/plugins/ksPlug/UserPrefs/BinderPref/UserPrefs.txt", append: false);
			foreach (KeyValuePair<string, string> item in binderPrefDic)
			{
				streamWriter.WriteLine(item.Key + "=" + item.Value);
			}
			streamWriter.Close();
		}

		public static Dictionary<string, string> ReadBinderEdits()
		{
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			string path = "BepInEx/plugins/ksPlug/UserPrefs/BinderPref/UserPrefs.txt";
			if (!File.Exists(path))
			{
				return dictionary;
			}
			StreamReader streamReader = new StreamReader(path);
			string text = streamReader.ReadToEnd();
			streamReader.Close();
			string[] array = text.Split(new string[1] { "\n" }, StringSplitOptions.None);
			foreach (string text2 in array)
			{
				if (text2.Contains("="))
				{
					dictionary[Helper.GetStringAtIndex(text2, "=", 1)] = Helper.GetStringAtIndex(text2, "=", 2).Trim();
				}
			}
			return dictionary;
		}

		public static T ReadEnum<T>(string line)
		{
			return (T)Enum.Parse(typeof(T), Helper.GetLastString(line, "="));
		}

		public static bool ReadBool(string line)
		{
			return bool.Parse(Helper.GetLastString(line, "="));
		}

		public static int ReadInt(string line)
		{
			return int.Parse(Helper.GetLastString(line, "="));
		}

		public static float ReadFloat(string line)
		{
			return float.Parse(Helper.GetLastString(line, "="));
		}

		public static void ReadMultiChoice<T>(string line, ref T[] option)
		{
			string lastString = Helper.GetLastString(line, "=");
			List<string> list = new List<string>();
			if (!lastString.Contains(","))
			{
				list.Add(lastString.Trim());
			}
			else
			{
				string[] array = lastString.Split(new string[1] { "," }, StringSplitOptions.None);
				foreach (string text in array)
				{
					list.Add(text.Trim());
				}
			}
			List<T> list2 = new List<T>();
			T[] array2 = (T[])Enum.GetValues(typeof(T));
			for (int i = 0; i < array2.Length; i++)
			{
				T item = array2[i];
				if (list.Contains(item.ToString()))
				{
					list2.Add(item);
				}
			}
			option = new T[list2.Count];
			for (int j = 0; j < list2.Count; j++)
			{
				option[j] = list2[j];
			}
		}

		public static string MultiChoiceToString<T>(T[] options)
		{
			string text = string.Empty;
			for (int i = 0; i < options.Length; i++)
			{
				text = text + ((i != 0) ? "," : "") + options[i].ToString();
			}
			return text;
		}

		public static List<T> GetMultiChoiceAsList<T>(T[] options)
		{
			List<T> list = new List<T>();
			foreach (T item in options)
			{
				list.Add(item);
			}
			return list;
		}
	}
