			//IL_0134: Unknown result type (might be due to invalid IL or missing references)
			//IL_0149: Unknown result type (might be due to invalid IL or missing references)
			//IL_015e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0232: Unknown result type (might be due to invalid IL or missing references)
			//IL_0238: Unknown result type (might be due to invalid IL or missing references)
			string text = string.Empty;
			Vector3 val = default(Vector3);
			((Vector3)(ref val))..ctor(color.r * 255f, color.g * 255f, color.b * 255f);
			float num = float.PositiveInfinity;
			foreach (KeyValuePair<string, Color> item in HairColors())
			{
				float lenght = Helper.GetLenght(val, new Vector3(item.Value.r, item.Value.g, item.Value.b), confHeight: false);
				if (lenght < num)
				{
					num = lenght;
					text = item.Key;
				}
			}
			float num2 = (color.r + color.g + color.b) / 3f;
			float num3 = 300f;
			if (text.Contains("purple") && (color.g >= color.b || Mathf.Abs(color.g - color.b) < 0.025f))
			{
				text = "brown";
			}
			else if (!text.Contains("purple") && !text.Contains("orange") && !text.Contains("pink"))
			{
				float num4 = Helper.Round(val.x / num3);
				float num5 = Helper.Round(val.y / num3);
				float num6 = Helper.Round(val.z / num3);
				if (num4 == num5 && num5 == num6 && num2 > 0.65f)
				{
					text = "silver";
				}
			}
			else if (text.Contains("orange"))
			{
				float num7 = Helper.Round(val.x / num3);
				float num8 = Helper.Round(val.y / num3);
				if (num7 == num8 || Mathf.Abs(color.r - color.g) < 0.175f)
				{
					text = "brown";
				}
			}
			else if (text.Contains("pink"))
			{
				float num9 = Helper.Round(val.y / num3);
				if ((Helper.Round(val.z / num3) == num9 || Mathf.Abs(color.r - color.g) < 0.05f) && num2 < 0.75f)
				{
					text = "red";
				}
			}
			if (num2 < 0.4f && text.Contains("brown"))
			{
				text = "black";
			}
			string text2 = "";
			if (text != "silver")
			{
				text2 = ((num2 > 0.75f) ? "light " : ((num2 < 0.52f) ? "deep " : ""));
			}
			text = text2 + (text.Contains("_") ? Helper.GetStringAtIndex(text, "_", 1) : text);
			if (text.Contains("yellow"))
			{
				text = "blonde";
			}
			if (text.Contains("orange"))
			{
				text = "red";
			}
			return text;
		}
	}
