		private static void ListFromFolder(string bgmpath, ref List<string> files, ref List<Descr> descrs, ref int creationId)
		{
			descrs = new List<Descr>();
			if (!Directory.Exists(bgmpath))
			{
				return;
			}
			files = (from f in Directory.EnumerateFiles(bgmpath)
				where f.ToLower().EndsWith("wav") || f.ToLower().EndsWith("ogg")
				select f).ToList();
			foreach (string file in files)
			{
				string text = file.Replace("\\", "/");
				Descr item = new Descr
				{
					typ = Typ.Custom,
					name = Helper.GetLastString(text, "/", rmvExt: true),
					bundleOrPath = text,
					id = creationId
				};
				descrs.Add(item);
				creationId++;
			}
		}

		public static void ListBgms()
		{
			//IL_003c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0041: Unknown result type (might be due to invalid IL or missing references)
			//IL_0047: Unknown result type (might be due to invalid IL or missing references)
