			//IL_0063: Unknown result type (might be due to invalid IL or missing references)
			//IL_006f: Unknown result type (might be due to invalid IL or missing references)
			creationId = 0;
			ListFromFolder(CustomBgmPath, ref customBgmFiles, ref bgmDescrs, ref creationId);
			foreach (BGM value in Enum.GetValues(typeof(BGM)))
			{
				if (!bgmExcluded.Contains(value))
				{
					Descr item = new Descr
					{
						typ = Typ.Game,
						bgm = value,
						name = GetBgmName(value),
						bundleOrPath = SettingBGM.Convert(value),
						id = creationId
					};
					bgmDescrs.Add(item);
					creationId++;
				}
			}
			int num = 0;
			ListFromFolder(OverBgmPath, ref overBgmFiles, ref overBgmDescrs, ref num);
		}

