				}
				if (asset == "kks_bgm_02" && overBgmDescr.name == "overHScene")
				{
					toPlayOver = overBgmDescr;
					break;
				}
				if (asset == "kks_bgm_08" && overBgmDescr.name == "overTalkEvent")
				{
					toPlayOver = overBgmDescr;
					break;
				}
				if (asset == "kks_bgm_03" && overBgmDescr.name == "overEsthetic")
				{
					toPlayOver = overBgmDescr;
					break;
				}
				if (asset == "kks_bgm_24" && overBgmDescr.name == "overMaker")
				{
					toPlayOver = overBgmDescr;
					break;
				}
			}
			yield return (object)new WaitForSeconds(Time.deltaTime);
			DebugInfos.InConsole(" try to search substitute to :" + asset, "Music.IE_PlayOverBgm");
			if (toPlayOver != null)
			{
				Sound.PauseBGM();
				if (wRequest != null)
				{
					wRequest.Dispose();
				}
				string bundleOrPath = toPlayOver.bundleOrPath;
				AudioType val = (AudioType)(bundleOrPath.EndsWith(".ogg") ? 14 : 20);
				wRequest = UnityWebRequestMultimedia.GetAudioClip(bundleOrPath, val);
				yield return wRequest.SendWebRequest();
				AudioSource component = Sound.currentBGM.GetComponent<AudioSource>();
				AudioClip content = DownloadHandlerAudioClip.GetContent(wRequest);
				((Object)content).name = Helper.GetLastString(toPlayOver.bundleOrPath, "/", rmvExt: true);
				component.clip = content;
				Sound.PlayBGM(0f);
				component.Play();
			}
		}

		public static IEnumerator IE_PlayBgm(int id)
		{
			yield return (object)new WaitUntil((Func<bool>)(() => (Object)(object)Sound.currentBGM != (Object)null));
			Descr descr = bgmDescrs[id];
			switch (descr.typ)
			{
			case Typ.Game:
			{
				playFromMenu = true;
				Setting val2 = new Setting();
				val2.loader.bundle = descr.bundleOrPath;
				val2.loader.asset = Helper.GetLastString(descr.bundleOrPath, "/", rmvExt: true);
				val2.loader.type = (Type)0;
				Sound.Play(val2);
				break;
			}
			case Typ.Custom:
			{
				if (wRequest != null)
				{
					wRequest.Dispose();
				}
				string bundleOrPath = descr.bundleOrPath;
				AudioType val = (AudioType)(bundleOrPath.EndsWith(".ogg") ? 14 : (bundleOrPath.EndsWith(".mp3") ? 13 : 20));
				wRequest = UnityWebRequestMultimedia.GetAudioClip(bundleOrPath, val);
				yield return wRequest.SendWebRequest();
				AudioSource component = Sound.currentBGM.GetComponent<AudioSource>();
				AudioClip content = DownloadHandlerAudioClip.GetContent(wRequest);
				((Object)content).name = Helper.GetLastString(descr.bundleOrPath, "/", rmvExt: true);
				component.clip = content;
				component.Play();
				break;
			}
			}
			SetCurrentBgmId();
			if (playFromMenu)
			{
				yield return (object)new WaitForSeconds(Time.deltaTime);
				playFromMenu = false;
			}
		}
	}
