		public static void FovControl(ref float fovValue, ref float editTime)
		{
			float num = fovValue;
			if (Keys.CamFovClose)
			{
				fovValue = Mathf.Clamp(fovValue - 10.5f * Time.deltaTime * Mathf.Clamp(editTime + 0.25f, 1f, 4f), 20f, 100f);
			}
			if (Keys.CamFovOpen)
			{
				fovValue = Mathf.Clamp(fovValue + 10.5f * Time.deltaTime * Mathf.Clamp(editTime + 0.25f, 1f, 4f), 20f, 100f);
			}
			if (Keys.CamFovReset)
			{
				fovValue = Settings.FpvFocal;
			}
			if (fovValue != num)
			{
				Settings.FpvFocal = (int)fovValue;
				editTime += Time.deltaTime * 2f;
				Settings.Save();
			}
			else
			{
				editTime = 0f;
			}
		}

