					value = Helper.GetStringAtIndex(item.Key, "*", 2);
				}
				if ((item.Key == "Default" || state.Contains(text)) && (!state.Contains(text) || string.IsNullOrEmpty(value) || !state.Contains(value)))
				{
					goalsWeight = item.Value;
					result = true;
					if (text != "Default")
					{
						break;
					}
				}
			}
			return result;
		}

