		public static void AdaptChothesToMap(int mapId, ChaControl cha)
		{
			if (mapId <= 99)
			{
				int id = 0;
				bool flag = true;
				bool flag2 = false;
				if (RoomIDS.Contains(mapId) && (ambiance == AmbTyp.Dawn || (!mapHasChangeInH && ambiance == AmbTyp.Night)))
				{
					id = 2;
				}
				if (swimIds.Contains(mapId))
				{
					id = 1;
				}
				if (bathIds.Contains(mapId))
				{
					id = 3;
				}
				if (RoomIDS.Contains(mapId) || mapId == 13 || mapId == 14 || mapId == 16 || mapId == 17)
				{
					flag = false;
				}
				if (mapId == 17)
				{
					flag2 = true;
				}
				Clothes.SetCoordinate(cha, id);
				cha.SetClothesStateAll((byte)0);
				if (!flag)
				{
					cha.SetClothesState(7, (byte)3, true);
					cha.SetClothesState(8, (byte)3, true);
				}
				if (flag2)
				{
					cha.SetClothesState(0, (byte)3, true);
					cha.SetClothesState(1, (byte)3, true);
				}
				if (Object.op_Implicit((Object)(object)HCtrl.Get) && HCtrl.Get.IsInit && (Object)(object)Core.dealer.MainGirlCha == (Object)(object)cha && (Core.dealer.HCtx == HAnims.Context.Piston || Core.dealer.HCtrl.CurAnim.isSpSrv))
				{
					Clothes.RevealCrotch(cha);
				}
			}
		}

