		public static bool MapInfoContainsHSpot(int id, HAnims.Spot spot)
		{
			if (spot == HAnims.Spot.Sofa)
			{
				spot = HAnims.Spot.Bench;
			}
			if (spot == HAnims.Spot.Fence)
			{
				spot = HAnims.Spot.Wall;
			}
			List<Info> value = new List<Info>();
			if (MapPosInfos.TryGetValue(id, out value))
			{
				for (int i = 0; i < value.Count; i++)
				{
					if (value[i].spot == spot)
					{
						return true;
					}
				}
			}
			return false;
		}

