		private static IEnumerator IE_AfterLoadMap(ActionMap actMap, int mapId)
		{
			HCtrl hCtrl = HCtrl.Get;
			bool inFpv = (Object)(object)hCtrl.FpvCtrl != (Object)null;
			yield return (object)new WaitUntil((Func<bool>)(() => !((BaseMap)actMap).isMapLoading));
			Cam.CheckCameraFocalTransform();
			yield return (object)new WaitForSeconds(Time.deltaTime);
			SetAmbiance(ambiance);
			if (!Core.dealer.InStory && Settings.AdaptClothesToMap)
			{
				foreach (ChaCore item in Core.dealer.ChaCoresInH)
				{
					AdaptChothesToMap(mapId, item.Cha);
				}
			}
			hCtrl.HFlag.ctrlCamera.CleraVanishCollider();
			hCtrl.HFlag.ctrlCamera.LoadVanish("h/list", ((BaseMap)actMap).ConvertMapName(Core.dealer.MapID), ((BaseMap)actMap).mapRoot);
			((BaseCameraControl_Ver2)hCtrl.HFlag.ctrlCamera).SetWorldBase(((ChaInfo)((CharaData)hCtrl.HFlag.lstHeroine[0]).chaCtrl).objTop.transform);
			GlobalMethod.LoadCamera(hCtrl.HFlag.ctrlCamera, "h/list/", hCtrl.HFlag.nowAnimationInfo.paramFemale.nameCamera, false);
			if (mapId > 99)
			{
				AddExtraCollider();
			}
			if (mapId > 99)
			{
				yield return (object)new WaitForSeconds(Time.deltaTime);
				if (!hCtrl.InPointMove)
				{
					HCtrl.Get.HFlag.click = (ClickKind)34;
				}
				yield return (object)new WaitForSeconds(Time.deltaTime);
				HPointMove pointmove = Object.FindObjectOfType<HPointMove>();
				if ((Object)(object)pointmove != (Object)null)
				{
					_ = Vector3.zero;
					_ = Quaternion.identity;
					GameObject fieldValue = pointmove.GetFieldValue<GameObject>("objMapNull");
					if ((Object)(object)fieldValue != (Object)null)
					{
						List<int> list = HAnims.CatListFromSpotTyp();
						HPointData[] componentsInChildren = fieldValue.GetComponentsInChildren<HPointData>(true);
						List<HPointData> list2 = new List<HPointData>();
						for (int num = 0; num < componentsInChildren.Length; num++)
						{
							int[] category = componentsInChildren[num].category;
							for (int num2 = 0; num2 < category.Length; num2++)
							{
								if (list.Contains(category[num2]))
								{
									list2.Add(componentsInChildren[num]);
									break;
								}
							}
						}
						if (list2.Count != 0)
						{
							HPointData obj = Helper.RandomInList(list2);
							_ = Vector3.zero;
							Vector3 fieldValue2 = obj.GetFieldValue<Vector3>("_offsetPos");
							_ = Vector3.zero;
							Vector3 fieldValue3 = obj.GetFieldValue<Vector3>("_offsetAngle");
							Vector3 val = ((Component)obj).gameObject.transform.position + fieldValue2;
							Quaternion rotation = ((Component)obj).gameObject.transform.rotation;
							((Component)Core.dealer.MainGirlCha).transform.SetPositionAndRotation(val, rotation);
							((Component)Core.dealer.MainGirlCha).transform.Rotate(fieldValue3);
							if ((Object)(object)Core.dealer.MainBoyCha != (Object)null)
							{
								((Component)Core.dealer.MainBoyCha).transform.SetPositionAndRotation(val, rotation);
								((Component)Core.dealer.MainBoyCha).transform.Rotate(fieldValue3);
							}
							if (hCtrl.HasSecondGirl)
							{
								((Component)hCtrl.SecondGirl.Cha).transform.SetPositionAndRotation(val, rotation);
								((Component)hCtrl.SecondGirl.Cha).transform.Rotate(fieldValue3);
							}
						}
						yield return (object)new WaitForSeconds(Time.deltaTime * 1f);
						if ((Object)(object)pointmove != (Object)null)
						{
							pointmove.Return();
						}
					}
				}
			}
			inChangeMap = false;
			if (inFpv)
			{
				yield return (object)new WaitForSeconds(Time.deltaTime);
				hCtrl.AddFPV();
			}
		}

		public static void AddExtraCollider()
		{
			MeshRenderer[] componentsInChildren = ((BaseMap)Object.FindObjectOfType<ActionMap>()).mapRoot.GetComponentsInChildren<MeshRenderer>(true);
			List<string> list = new List<string>
			{
				"table", "Table", "PCTable", "bed", "Bed", "PlayerBed", "futon", "chair", "Chair", "bench",
				"seat", "sit", "sofa", "Sofa", "isu", "floor", "Floor", "yuka", "kyoudai00", "ground",
				"Ground", "RoomMain"
			};
			MeshRenderer[] array = componentsInChildren;
			foreach (MeshRenderer val in array)
			{
				bool flag = false;
				if (((Object)val).name.Contains("kage"))
				{
					continue;
				}
				foreach (string item in list)
				{
					if (((Object)val).name.Contains(item))
					{
						flag = true;
						break;
					}
				}
				if (flag && (Object)(object)((Component)val).GetComponent<Collider>() == (Object)null)
				{
					((Component)val).gameObject.AddComponent<MeshCollider>();
				}
			}
		}

