		private bool isInit;

		private int _action;

		private ActTyp _prevAct;

		private int _mapId;

		private bool _isArrival;

		private Type _cycle = (Type)2;

		private float breakChance;

		private string girl = string.Empty;

		public Dealer Dealer => Core.dealer;

		public NPC Npc => chaCore.Npc;

		public Fix FixNpc => chaCore.FixNpc;

		public int MapID => chaCore.npcInfo.map;

		public int Action
		{
			get
			{
				if (!((Object)(object)chaCore.Npc != (Object)null))
				{
					return -1;
				}
