			}
		}

		public Type CycleTyp => Core.dealer.NowCycle;

		public int Relation
		{
			get
			{
				if (!((Object)(object)chaCore.Npc != (Object)null))
				{
					if (!((Object)(object)chaCore.FixNpc != (Object)null))
					{
						return 0;
					}
					return ((Base)FixNpc).heroine.relationNPC;
				}
				return ((Base)Npc).heroine.relation;
			}
		}

		public Heroine Her
		{
			get
