		public float BreakIncrement
		{
			get
			{
				if (Relation != 0)
				{
					if (Relation != 1)
					{
						if (Her.lewdness >= 80)
						{
							return 0f;
						}
						return 0.5f;
					}
					if (Her.lewdness >= 50)
					{
						return 2.5f;
					}
					return 1f;
				}
				return 5f;
			}
		}

		public ActTyp Act { get; private set; }

		public bool IsSexAct => new List<ActTyp>
		{
			ActTyp.Onanism,
			ActTyp.Lez
		}.Contains(Act);

		public bool IsPeepAct => new List<ActTyp>
		{
			ActTyp.Wash,
			ActTyp.Pee
		}.Contains(Act);

		private void Start()
		{
			//IL_0047: Unknown result type (might be due to invalid IL or missing references)
			//IL_004c: Unknown result type (might be due to invalid IL or missing references)
			chaCore = ((Component)cha).GetComponent<ChaCore>();
			girl = ChaCore.Name(((ChaInfo)chaCore.Cha).fileParam);
			_action = Action;
			_isArrival = IsArrival;
			_cycle = CycleTyp;
			_mapId = MapID;
			Act = ParseAction(Action);
			_prevAct = Act;
			MenuDiary.SubscribeAirTag(this);
			((MonoBehaviour)this).StartCoroutine(IE_Init());
			DebugInfos.InConsoleCompact("Start on " + girl, "AirTag");
		}

		private void LateUpdate()
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0007: Unknown result type (might be due to invalid IL or missing references)
			if (_cycle != CycleTyp)
			{
				SendNotification(GetEndByCycleMsg(girl), Messenger.TagMsg.Break, 4.5f);
				Object.Destroy((Object)(object)this);
			}
			if (!isInit || Dealer.Ctx == Dealer.Context.H)
			{
				return;
			}
			if (_mapId != MapID)
			{
				if (MapID != Dealer.MapID)
				{
					breakChance = Mathf.Min(breakChance + BreakIncrement, 100f);
					BreakOnMapChange(_mapId);
				}
				_mapId = MapID;
			}
			if (_action == Action && _isArrival == IsArrival)
			{
				return;
			}
			if (_action != Action)
			{
				_action = Action;
				Act = ParseAction(Action);
				DebugInfos.InConsole(girl + " action has changed to " + _action, "AirTag");
			}
			if (_isArrival != IsArrival)
			{
				_isArrival = IsArrival;
				DebugInfos.InConsole(girl + " action has changed to " + _action, "AirTag");
			}
			if (IsArrival)
			{
				if (Act == ActTyp.Pee || Act == ActTyp.Wash)
				{
					SendNotification(GetActionMsg(girl, MapID, Act), Messenger.TagMsg.Peep);
				}
				if (Act == ActTyp.Onanism || (Act == ActTyp.Lez && (Object)(object)Npc.AI.target != (Object)null))
				{
					SendNotification(GetActionMsg(girl, MapID, Act, Npc), Messenger.TagMsg.Sex);
				}
			}
			if ((_prevAct == ActTyp.Pee && Act != ActTyp.Pee) || (_prevAct == ActTyp.Wash && Act != ActTyp.Wash))
			{
				BreakAfterAction(_prevAct);
			}
			_prevAct = Act;
		}

		private void OnDestroy()
		{
			DebugInfos.InConsoleCompact("Destroyed on " + girl, "AirTag");
		}

		public string Query(ref Messenger.TagMsg tagMsg)
		{
			string result = "Query AirTag®: " + (((IsSexAct || IsPeepAct) && IsArrival) ? GetActionMsg(girl, MapID, Act, Npc) : (girl + " is at " + Map.GetName(MapID)));
			tagMsg = (((IsSexAct || IsPeepAct) && IsArrival) ? ((!IsPeepAct) ? Messenger.TagMsg.Sex : Messenger.TagMsg.Peep) : Messenger.TagMsg.Undefined);
			return result;
		}

		private void BreakOnMapChange(int mapId)
		{
			float num = Random.Range(0f, 100f);
			if (num < breakChance)
			{
				DebugInfos.InConsoleCompact(girl + "'s device broke on map change (rnd:" + num + ",limit:" + breakChance + ")", "AirTag");
				SendNotification(GetEndOnMapChange(girl, mapId), Messenger.TagMsg.Break);
				Object.Destroy((Object)(object)this);
			}
		}

		private void BreakAfterAction(ActTyp prevAct)
		{
			if (((Base)Npc).heroine.relation != 2)
			{
				float num = Random.Range(0f, 100f);
				float num2 = ((((Base)Npc).heroine.relation == 0) ? 80 : 30);
				if (num < num2)
				{
					SendNotification(GetEndByActMsg(girl, prevAct), Messenger.TagMsg.Break);
					Object.Destroy((Object)(object)this);
				}
			}
		}

		private void SendNotification(string text, Messenger.TagMsg tagMsg = Messenger.TagMsg.Undefined, float duration = 8f)
		{
			Dealer.Msgn.ReceiveMessage(Messenger.Type.TopCorner_R, "AirTag® info: " + text, duration, replace: false, write: false, lerp: true, tagMsg);
			Sound.Play((SystemSE)1);
		}

		private IEnumerator IE_Init()
		{
			yield return (object)new WaitForSeconds(2f);
			isInit = true;
		}

		public static string GetAttachMsg(string name, ChaTools.Part bp)
		{
			switch (bp)
			{
			case ChaTools.Part.Head:
				return "Discreetly hid an AirTag® in " + name + "'s hair";
			case ChaTools.Part.BreastL:
			case ChaTools.Part.BreastR:
				return "Stuck an AirTag® between " + name + "'s boobs";
			case ChaTools.Part.Chest:
				return "Hid an AirTag® on " + name + "'s back";
			case ChaTools.Part.Hip:
			case ChaTools.Part.Kokan:
			case ChaTools.Part.Anal:
			case ChaTools.Part.ButtL:
			case ChaTools.Part.ButtR:
				return "Gently stuck an AirTag® on " + name + "'s butt";
			case ChaTools.Part.Leg:
				return "Put an AirTag® on " + name + "'s legs";
			case ChaTools.Part.Arm:
				return "placed an AirTag® on " + name + "'s arms";
			default:
				return string.Empty;
			}
		}

		private static string GetActionMsg(string name, int mapId, ActTyp actTyp, NPC npc = null)
		{
			switch (actTyp)
			{
			case ActTyp.Pee:
				return name + " pees at " + Map.GetName(mapId);
			case ActTyp.Wash:
				return name + " washes at " + Map.GetName(mapId);
			case ActTyp.Onanism:
				return name + " pleasures herself at " + Map.GetName(mapId);
			case ActTyp.Lez:
				if ((Object)(object)npc != (Object)null && (Object)(object)npc.AI.target != (Object)null)
				{
					return name + " is having fun with " + ChaCore.Name(((ChaInfo)npc.AI.target.chaCtrl).fileParam) + " at " + Map.GetName(mapId);
				}
				break;
			}
			return string.Empty;
		}

		private static string GetEndByCycleMsg(string name)
		{
			float num = Random.Range(0f, 100f);
			if (!(num <= 25f))
			{
				if (!(num <= 50f))
				{
					if (!(num <= 75f))
					{
						return name + "'s device is broken";
					}
					return "ERROR2077 => can't find " + name + "'s AirTag®";
				}
				return "Phone OS update, " + name + "'s AirTag® is not recognized";
			}
			return "built-in obsolescence, " + name + "'s AirTag® is dead";
		}

		private static string GetEndByActMsg(string name, ActTyp actTyp)
		{
			float num = Random.Range(0f, 100f);
			switch (actTyp)
			{
			case ActTyp.Pee:
				if (!(num < 50f))
				{
					return "Toilets flush takes away " + name + "'s AirTag®";
				}
				return name + "'s device felt in Toilets";
			case ActTyp.Wash:
				if (!(num < 50f))
				{
					return "high humidity detected, lost connection with " + name + "'s AirTag®";
				}
				return name + "'s device didn't pass the waterproof test";
			default:
				return string.Empty;
			}
		}

		private static string GetEndOnMapChange(string name, int mapId)
		{
			Random.Range(0f, 100f);
			return name + " lost it at " + Map.GetName(mapId);
		}

		private static ActTyp ParseAction(int action)
		{
			return action switch
			{
				1 => ActTyp.Pee, 
				2 => ActTyp.Wash, 
				4 => ActTyp.Onanism, 
				27 => ActTyp.Lez, 
				_ => ActTyp.Undefined, 
			};
		}

		public static AirTag GetOrCreate(ChaControl cha)
		{
			if (Object.op_Implicit((Object)(object)((Component)cha).GetComponent<AirTag>()))
			{
				return ((Component)cha).GetComponent<AirTag>();
			}
			AirTag airTag = ((Component)cha).gameObject.AddComponent<AirTag>();
			airTag.cha = cha;
			return airTag;
		}

		public static bool Create(ChaControl cha)
		{
			if (Object.op_Implicit((Object)(object)((Component)cha).GetComponent<AirTag>()))
			{
				return false;
			}
			((Component)cha).gameObject.AddComponent<AirTag>().cha = cha;
			return true;
		}
	}
