		private void OnNextClick()
		{
			havClickNext = true;
			RemoveFreeCam();
		}

		private void RemoveFreeCam()
		{
			if (InFreeCam)
			{
				Object.Destroy((Object)(object)Core.dealer.freeCam);
				((MonoBehaviour)this).StartCoroutine(IE_ResetCamPos());
			}
		}

		private void DestroyAllGirlsAndReset(bool reCreate = false)
		{
			for (int i = 0; i < GirlsAtHome.Count; i++)
			{
				foreach (GameObject relatedGo in GirlsAtHome[i].relatedGos)
				{
					Object.Destroy((Object)(object)relatedGo);
				}
				if ((Object)(object)GirlsAtHome[i].root != (Object)null)
				{
					Object.Destroy((Object)(object)GirlsAtHome[i].root);
				}
			}
			GirlsAtHome.Clear();
			AvailableNrSpots.Clear();
			Core.dealer.ChaMovers.Clear();
			isInitAtWakeUp = false;
			inInitAtWake = false;
			camPosIsInit = false;
			camInitTime = 0f;
			havClickNext = false;
			waitEcchiForDel = false;
			Character.enableCorrectHandSize = true;
			if ((Object)(object)camEff != (Object)null)
			{
				camEff.SetDOFTarget((Transform)null);
			}
			if ((Object)(object)camDofTarg != (Object)null)
			{
				Object.Destroy((Object)(object)((Component)camDofTarg).gameObject);
			}
			if (reCreate)
			{
				GC.Collect();
				((MonoBehaviour)this).StartCoroutine(IE_InitAtWakeUp(Time.deltaTime * 3f));
			}
		}

		private IEnumerator IE_WaitBookingEnd()
		{
			inBookingMenu = true;
			BreastPusher.SuspendAll();
			BellyCtrl.SuspendAll();
			yield return (object)new WaitUntil((Func<bool>)(() => Core.dealer.NotInMenu));
			inBookingMenu = false;
			yield return (object)new WaitForSeconds(Time.deltaTime);
			bool stillThere = false;
			foreach (GirlAtHome item in GirlsAtHome)
			{
				if ((Object)(object)item.cha != (Object)null)
				{
					stillThere = true;
					break;
				}
			}
			yield return (object)new WaitForSeconds(Time.deltaTime);
			if (stillThere)
			{
				BreastPusher.PostSuspend();
				BellyCtrl.PostSuspend();
			}
			else
			{
				DestroyAllGirlsAndReset(reCreate: true);
			}
		}

		private IEnumerator IE_ResetCamPos()
		{
			yield return (object)new WaitForSeconds(Time.deltaTime);
			CamTrs.position = camTargPos;
			CamTrs.localEulerAngles = camTargEul;
			Camera.main.fieldOfView = 45f;
			Camera.main.focalLength = 50f;
		}

		private IEnumerator IE_InitAtWakeUp(float waitAtStart = 0f)
		{
			inInitAtWake = true;
			isInitAtWakeUp = true;
			if (Singleton<ActionScene>.Instance.Cycle.withHeroine != null)
			{
				yield return (object)new WaitUntil((Func<bool>)(() => Core.dealer.Ctx == Dealer.Context.Event));
				yield return (object)new WaitUntil((Func<bool>)(() => Core.dealer.Ctx != Dealer.Context.Event));
				yield return (object)new WaitUntil((Func<bool>)(() => Core.dealer.Ctx == Dealer.Context.Event));
				yield return (object)new WaitUntil((Func<bool>)(() => Core.dealer.Ctx != Dealer.Context.Event));
				yield return (object)new WaitForSeconds(Time.deltaTime);
			}
			yield return (object)new WaitForSeconds(waitAtStart);
			yield return (object)new WaitUntil((Func<bool>)(() => !Scene.IsNowLoading && !Scene.IsFadeNow));
			DefineCamPosition(StayPlace, this);
			GameObject val = new GameObject("dof target");
			camDofTarg = val.transform;
			camDofTarg.SetParent(((Component)Camera.main).transform);
			camEff = Object.FindObjectOfType<CameraEffector>();
			camEff.SetDOFTarget(camDofTarg);
			foreach (Spot item in StayPlaceSpotList(StayPlace))
			{
				SetClipsToSpot(item);
				if (item.spotTyp == SpotTyp.Special)
				{
					AvailableSpSpots.Add(item);
				}
				else
				{
					AvailableNrSpots.Add(item);
				}
			}
			List<Heroine> heroines = new List<Heroine>();
			for (int num = 0; num < Game.HeroineList.Count; num++)
			{
				if (Statistic.IsStayingWithPlayer(Game.HeroineList[num], (int)StayPlace))
				{
					heroines.Add(Game.HeroineList[num]);
				}
			}
			ChaCore.CreationComesFromCtrlHome = true;
			Cam.DoFade(3f);
			for (int num2 = 0; num2 < heroines.Count; num2++)
			{
				((MonoBehaviour)this).StartCoroutine(IE_CreateGirl(AvailableNrSpots[num2], heroines[num2]));
			}
			yield return (object)new WaitForSeconds(Time.deltaTime * 5f);
			GameAssets.CreateBubble(Vector3.zero);
			ChaCore.CreationComesFromCtrlHome = false;
			Character.enableCorrectHandSize = false;
			for (int num3 = 0; num3 < heroines.Count; num3++)
			{
				Statistic.SetDailyEvent(heroines[num3], new List<Statistic.DailyEvent> { Statistic.DailyEvent.wakeTogether });
			}
			inInitAtWake = false;
			yield return (object)new WaitForSeconds(Time.deltaTime);
			foreach (GirlAtHome item2 in GirlsAtHome)
			{
				Statistic.Daily daily = Statistic.GetDaily(item2.her);
				if (daily != null && daily.pregnant)
				{
					BellyCtrl.ForceInflation(item2.cha, daily.bellyBuldge);
				}
			}
		}

		private IEnumerator IE_InviteGirl(Heroine her)
		{
			Spot spot = FindFreeSpot();
			if (spot != null)
			{
				ChaCore.CreationComesFromCtrlHome = true;
				Cam.DoFade(0.5f);
				((MonoBehaviour)this).StartCoroutine(IE_CreateGirl(spot, her));
				yield return (object)new WaitForSeconds(Time.deltaTime * 2f);
				ChaCore.CreationComesFromCtrlHome = false;
			}
		}

		private IEnumerator IE_CreateGirl(Spot spot, Heroine her)
		{
			GameObject root = new GameObject();
			root.transform.position = spot.pos;
			ChaControl cha = ChaTools.CreateFemale(root, 1, ((CharaData)her).charFile);
			cha.Load(false);
			((ChaFile)((ChaInfo)cha).chaFile).status.coordinateType = 2;
			cha.ChangeCoordinateTypeAndReload(Clothes.GetCoordTyp(2), true);
			yield return (object)new WaitUntil((Func<bool>)(() => (Object)(object)((Component)cha).gameObject.GetComponent<AIGuest>() != (Object)null));
			AIGuest component = ((Component)cha).gameObject.GetComponent<AIGuest>();
			GirlAtHome girlAtHome = new GirlAtHome
			{
				root = root,
				her = her,
				cha = cha,
				ai = component,
				spot = spot,
				coordinateId = 2
			};
			component.homeActions = HomeActions.Create(component, spot, girlAtHome);
			spot.attachedGirl = girlAtHome;
			GirlsAtHome.Add(girlAtHome);
		}

		private IEnumerator IE_WaitCustomMoveEnd(bool useAlt = true)
		{
			if (InFreeCam)
			{
				((Behaviour)Core.dealer.freeCam.CamCtrl).enabled = false;
			}
			yield return (object)new WaitUntil((Func<bool>)delegate
			{
				if (!useAlt)
				{
					return !Keys.RmbHold;
				}
				return !Keys.AltMod || !Keys.RmbHold;
			});
			moverInCustomMove.inCustomMove = false;
			moverInCustomMove.cantDraw = false;
			moverInCustomMove = null;
			if (InFreeCam)
			{
				((Behaviour)Core.dealer.freeCam.CamCtrl).enabled = true;
			}
		}

		public GirlAtHome FindGirl(ChaControl cha)
		{
			foreach (GirlAtHome item in GirlsAtHome)
			{
				if ((Object)(object)cha == (Object)(object)item.cha)
				{
					return item;
				}
			}
			return null;
		}

		public GirlAtHome FindGirl(Heroine her)
		{
			foreach (GirlAtHome item in GirlsAtHome)
			{
				if (her == item.her)
				{
					return item;
				}
			}
			return null;
		}

		public bool GetNextSpot(ref Spot nextSpot, Spot curSpot, bool includeSpecial, int specialAddTime = 1)
		{
			if (spotChangeDelay != 0f)
			{
				return false;
			}
			List<Spot> list = new List<Spot>();
			list.AddRange(AvailableNrSpots);
			if (includeSpecial)
			{
				for (int i = 0; i < specialAddTime; i++)
				{
					list.AddRange(AvailableSpSpots);
				}
			}
			list.Shuffle();
			foreach (Spot item in list)
			{
				if (item.IsFree && (curSpot == null || curSpot.spotTyp != item.spotTyp))
				{
					spotChangeDelay = 0.1f;
					nextSpot = item;
					nextSpot.isTargeted = true;
					return true;
				}
			}
			return false;
		}

		public Spot FindFreeSpot()
		{
			foreach (Spot availableNrSpot in AvailableNrSpots)
			{
				if (availableNrSpot.IsFree)
				{
					return availableNrSpot;
				}
			}
			return null;
		}

