		private static void SetClipsToSpot(Spot spot)
		{
			if (spot.clips.Count == 0)
			{
				List<Animations.Clip> list = new List<Animations.Clip>();
				if (spot.spotTyp == SpotTyp.Bed)
				{
					list.AddRange(new List<Animations.Clip>
					{
						Animations.Clip.Sleep_01,
						Animations.Clip.Sleep_02,
						Animations.Clip.Sleep_03,
						Animations.Clip.Sleep_04
					});
				}
				if (spot.spotTyp == SpotTyp.Chair)
				{
					list.AddRange(new List<Animations.Clip>
					{
						Animations.Clip.Sit_02,
						Animations.Clip.Sit_03,
						Animations.Clip.Sit_04
					});
				}
				if (spot.spotTyp == SpotTyp.BedEdge)
				{
					list.AddRange(new List<Animations.Clip>
					{
						Animations.Clip.Sit_01,
						Animations.Clip.Sit_02,
						Animations.Clip.Sit_03,
						Animations.Clip.Sit_04
					});
				}
				if (spot.spotTyp == SpotTyp.Wall)
				{
					list.AddRange(new List<Animations.Clip>
					{
						Animations.Clip.Wall_01,
						Animations.Clip.Wall_02
					});
				}
				if (spot.spotTyp == SpotTyp.Window)
				{
					list.AddRange(new List<Animations.Clip>
					{
						Animations.Clip.Home_03,
						Animations.Clip.Home_04,
						Animations.Clip.Stretch_03,
						Animations.Clip.Stretch_04
					});
				}
				if (spot.spotTyp == SpotTyp.Special)
				{
					list.AddRange(new List<Animations.Clip>
					{
						Animations.Clip.Dance_01,
						Animations.Clip.Dance_02,
						Animations.Clip.Dance_03,
						Animations.Clip.Dance_04,
						Animations.Clip.Dance_05
					});
				}
				if (list.Count == 0)
				{
					list.AddRange(new List<Animations.Clip>
					{
						Animations.Clip.Home_01,
						Animations.Clip.Home_02,
						Animations.Clip.Home_01,
						Animations.Clip.Home_02,
						Animations.Clip.Stretch_05
					});
				}
				spot.clips = list;
			}
		}

