					mover.cantDraw = true;
					Sound.Play(GameSounds.ConfirmGuestInter);
					((MonoBehaviour)this).StartCoroutine(IE_WaitCustomMoveEnd(useAlt: false));
					{
						foreach (Mover chaMover4 in Core.dealer.ChaMovers)
						{
							chaMover4.CollideInMove(Mover.MoveType.Custom);
						}
						return;
					}
				}
				moverInCustomMove.isDraw = !moverInCustomMove.cantDraw;
				return;
			}
			foreach (Mover chaMover5 in Core.dealer.ChaMovers)
			{
				chaMover5.isDraw = false;
			}
		}

		private IEnumerator IE_WaitCustomMoveEnd(bool useAlt = true)
		{
