			{
				((Behaviour)estCam).enabled = false;
			}
			yield return (object)new WaitUntil((Func<bool>)delegate
			{
				if (!useAlt)
				{
					return !Keys.RmbHold;
				}
				return !Keys.AltMod || !Keys.RmbHold;
			});
			moverInCustomMove.inCustomMove = false;
			moverInCustomMove.cantDraw = false;
			moverInCustomMove = null;
			if (Object.op_Implicit((Object)(object)estCam))
			{
				((Behaviour)estCam).enabled = true;
			}
		}

