			}
			if (SingletonInitializer<ActionScene>.instance.Cycle.withHeroine != null && ChaCore.Name(((CharaData)SingletonInitializer<ActionScene>.instance.Cycle.withHeroine).parameter) == ChaCore.Name(((ChaFile)((ChaInfo)eventInfo.chas[0]).chaFile).parameter))
			{
