				return;
			}
			Player player = SingletonInitializer<ActionScene>.instance.Player;
			if ((Object)(object)player.chaser != (Object)null && ((Base)player.chaser).heroine != null && ChaCore.Name(((CharaData)((Base)player.chaser).heroine).parameter) == ChaCore.Name(((ChaFile)((ChaInfo)eventInfo.chas[0]).chaFile).parameter))
