	public class GManage
	{
		public class ChaSnapshot
		{
			public Dictionary<int, byte> clothStates = new Dictionary<int, byte>();

			public byte[] siruStates = new byte[0];

			public bool isPlayer;

			public int orgAtEcchiEnd;
		}

		private static Dictionary<CharaData, ChaSnapshot> chaSnaphots = new Dictionary<CharaData, ChaSnapshot>();

		public static void ClearChaSnapshot()
		{
			chaSnaphots.Clear();
		}

		public static void DoChaInEcchiSnapshots()
		{
			chaSnaphots.Clear();
			foreach (ChaCore item in Core.dealer.ChaCoresInH)
			{
				bool flag = (Object)(object)item.Cha == (Object)(object)Core.dealer.HCtrl.MainBoy.Cha;
				if ((item.Sex == ChaCore.Gender.Girl && item.HSaveData != null) || flag)
				{
					ChaSnapshot chaSnapshot = new ChaSnapshot();
					chaSnapshot.clothStates = Clothes.ClothStatesDic(item.Cha);
					chaSnapshot.siruStates = ChaTools.GetSiruOnGirl(item.Cha);
					chaSnapshot.isPlayer = flag;
					if (flag)
					{
						chaSnapshot.orgAtEcchiEnd = Count.MainBoyOrgasms();
					}
					else if (item.HInfo.HCount != null)
					{
						chaSnapshot.orgAtEcchiEnd = Count.GirlOrgasms(item.HInfo.HCount);
					}
					chaSnaphots[(CharaData)(flag ? ((object)Core.dealer.HCtrl.HFlag.player) : ((object)item.HSaveData))] = chaSnapshot;
				}
			}
		}

		public static ChaSnapshot GetAndApplySnapshot(CharaData charaData, ChaControl cha, bool rmvKey = false)
		{
			if (!Core.dealer.InStory)
			{
				return null;
			}
			ChaSnapshot value = null;
			if (chaSnaphots.TryGetValue(charaData, out value))
			{
				ApplySnapshot(value, cha);
				if (rmvKey)
				{
					chaSnaphots.Remove(charaData);
				}
				return value;
			}
			return null;
		}

		public static void ApplySnapshot(ChaSnapshot snapshot, ChaControl cha)
		{
			Clothes.ApplyClothStatesDic(cha, snapshot.clothStates);
			if (((ChaInfo)cha).hiPoly)
			{
				ChaTools.SetSiruOnCha(cha, snapshot.siruStates);
				return;
			}
			try
			{
				ChaTools.SetSiruOnLow(cha, snapshot.siruStates);
			}
			catch
			{
			}
		}
	}
