		public static void Feed(ref HAnims.AnimInfo anim)
		{
			string text = (anim.asset.Contains("/") ? Helper.GetLastString(anim.asset, "/") : anim.asset);
			List<string> list = new List<string>();
			if (text.Contains("khs"))
			{
				list = ListInfoPiston(text);
			}
			if (text.Contains("kht"))
			{
				list = ListInfoMast(text);
			}
			foreach (string item in list)
			{
				string stringAtIndex = Helper.GetStringAtIndex(item, ":", 1);
				string info = item.Replace(" ", "");
				if (stringAtIndex == "IkF")
				{
					HExtraAnims.ReadIK(info, ref anim.IkF);
				}
				if (stringAtIndex == "IkM")
				{
					HExtraAnims.ReadIK(info, ref anim.IkM);
				}
				if (stringAtIndex == "IkF2")
				{
					HExtraAnims.ReadIK(info, ref anim.IkF2);
				}
			}
			anim.gameAnmIkDicExists = list.Count != 0;
		}

