		public static GameObject CreateLiquid(LiquidTyp typ, bool collide = false)
		{
			//IL_00fd: Unknown result type (might be due to invalid IL or missing references)
			//IL_0102: Unknown result type (might be due to invalid IL or missing references)
			//IL_0108: Unknown result type (might be due to invalid IL or missing references)
			//IL_010d: Unknown result type (might be due to invalid IL or missing references)
			string text = string.Empty;
			string text2 = hComBundle1;
			bool flag = false;
			string text3 = string.Empty;
			string text4 = string.Empty;
			switch (typ)
			{
			case LiquidTyp.Pee:
				text = "LiquidToilet";
				break;
			case LiquidTyp.Squirt:
				text = "LiquidSio";
				break;
			case LiquidTyp.SquirtGhost:
				text2 = "studio/00.unity3d";
				text = "p_koi_syu_LiquidSio_00_00";
				text3 = "h/common/01.unity3d";
				text4 = "uLiquid - Water - Steam MAT";
				flag = true;
				break;
			case LiquidTyp.SpermLow:
				text = "LiquidSiru";
				break;
			case LiquidTyp.SpermGhost:
				text2 = "studio/00.unity3d";
				text = "p_koi_syu_LiquidSiru_00_00";
				text3 = "h/common/01.unity3d";
				text4 = "uLiquid - Particle 1 MAT";
				break;
			case LiquidTyp.Water:
				text = "e_ks_ef_water00";
				text2 = studioBundle1;
				break;
			}
			GameObject val = CommonLib.LoadAsset<GameObject>(text2, text, true, string.Empty, true);
			AssetBundleManager.UnloadAssetBundle(text2, true, (string)null, false);
			bool flag2 = !string.IsNullOrEmpty(text3) && !string.IsNullOrEmpty(text4);
			Material material = null;
			if (flag2)
			{
				material = CommonLib.LoadAsset<Material>(text3, text4, true, string.Empty, true);
			}
			ParticleSystem[] componentsInChildren = val.GetComponentsInChildren<ParticleSystem>();
			ParticleSystem[] array = componentsInChildren;
			for (int i = 0; i < array.Length; i++)
			{
				_ = array[i];
				CollisionModule collision = componentsInChildren[0].collision;
				MainModule main = componentsInChildren[0].main;
				if (flag)
				{
					((MainModule)(ref main)).loop = false;
				}
				((CollisionModule)(ref collision)).enabled = collide;
			}
			if (flag2)
			{
				Renderer[] componentsInChildren2 = val.GetComponentsInChildren<Renderer>();
				for (int i = 0; i < componentsInChildren2.Length; i++)
				{
					componentsInChildren2[i].material = material;
				}
				AssetBundleManager.UnloadAssetBundle(text3, true, (string)null, false);
			}
			if (Core.dealer.Ctx == Dealer.Context.Event && (Object)(object)Core.dealer.MainGirlCha != (Object)null)
			{
				array = componentsInChildren;
				for (int i = 0; i < array.Length; i++)
				{
					((Component)array[i]).gameObject.layer = ((ChaInfo)Core.dealer.MainGirlCha).objBody.layer;
				}
			}
			return val;
		}

		private static void GetBodyMeshs(GameObject root, ref SkinnedMeshRenderer body, ref SkinnedMeshRenderer dan, ref SkinnedMeshRenderer ball, bool srchBody = true, bool srchDan = true, bool srchBall = true)
		{
			if ((Object)(object)root == (Object)null)
			{
				DebugInfos.InConsole("ROOT IS NULL", "SearchBodyMeshes");
			}
			SkinnedMeshRenderer[] componentsInChildren = root.GetComponentsInChildren<SkinnedMeshRenderer>(true);
			foreach (SkinnedMeshRenderer val in componentsInChildren)
			{
				if (srchBody && ((Object)val).name == "o_body_a")
				{
					body = val;
				}
				if (srchDan && ((Object)val).name == "o_dankon")
				{
					dan = val;
				}
				if (srchBall && ((Object)val).name == "o_dan_f")
				{
					ball = val;
				}
			}
			if ((Object)(object)ball == (Object)null)
			{
				ball = root.GetComponentsInChildren<SkinnedMeshRenderer>(true).FirstOrDefault();
			}
		}

		private static void TransferBonesToSkinMesh(SkinnedMeshRenderer src, SkinnedMeshRenderer dest)
		{
			if ((Object)(object)src == (Object)null || (Object)(object)dest == (Object)null)
			{
				return;
			}
			dest.bones = src.bones.Where((Transform b) => (Object)(object)b != (Object)null && dest.bones.Any((Transform t) => ((Object)t).name.Equals(((Object)b).name))).ToArray();
		}

		public static void ReplaceBodyGender(ChaControl destCha, int gender, bool forceDan)
		{
			GameObject obj = CommonLib.LoadAsset<GameObject>(bodyBundle, (gender == 0) ? bodyAssetM : bodyAssetF, true, "", true);
			SkinnedMeshRenderer body = null;
			SkinnedMeshRenderer dan = null;
			SkinnedMeshRenderer ball = null;
			GetBodyMeshs(obj, ref body, ref dan, ref ball);
			GameObject val = null;
			if (forceDan && gender == 1)
			{
				val = CommonLib.LoadAsset<GameObject>(bodyBundle, bodyAssetM, true, "", true);
				GetBodyMeshs(val, ref body, ref dan, ref ball, srchBody: false);
			}
			SkinnedMeshRenderer body2 = null;
			SkinnedMeshRenderer dan2 = null;
			SkinnedMeshRenderer ball2 = null;
			GetBodyMeshs(((Component)destCha).gameObject, ref body2, ref dan2, ref ball2);
			TransferBonesToSkinMesh(body2, body);
			body2.sharedMesh = body.sharedMesh;
			TransferBonesToSkinMesh(dan2, dan);
			TransferBonesToSkinMesh(ball2, ball);
			if (gender == 0 || forceDan)
			{
				dan2.sharedMesh = dan.sharedMesh;
				ball2.sharedMesh = ball.sharedMesh;
				((ChaInfo)destCha).fileStatus.visibleSonAlways = true;
			}
			if (gender == 1)
			{
				destCha.InitDynamicBoneBust();
			}
			AssetBundleManager.UnloadAssetBundle(bodyBundle, true, (string)null, false);
			Object.Destroy((Object)(object)obj);
			if ((Object)(object)val != (Object)null)
			{
				Object.Destroy((Object)(object)val);
			}
		}

