		public static Dictionary<string, string> BuildDicFromFile(string filePath)
		{
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			if (!File.Exists(filePath))
			{
				return dictionary;
			}
			string[] array = ReadFile(filePath).Split(new string[1] { "\n" }, StringSplitOptions.None);
			foreach (string text in array)
			{
				if (!text.Contains("//") && text.Contains("=") && text.Contains("[") && text.Contains("]"))
				{
					string stringAtIndex = Helper.GetStringAtIndex(text, "=", 1);
					stringAtIndex = Helper.GetStringAtIndex(stringAtIndex, "\"", 2);
					string stringAtIndex2 = Helper.GetStringAtIndex(text, "=", 2);
					stringAtIndex2 = Helper.GetStringAtIndex(stringAtIndex2, "\"", 2);
					dictionary[stringAtIndex] = stringAtIndex2;
				}
			}
			return dictionary;
		}

		public static string ReadFile(string path)
		{
			StreamReader streamReader = new StreamReader(path);
			string result = streamReader.ReadToEnd();
			streamReader.Close();
			return result;
		}

