		public static List<string> ParseStringList(string line, string[] symboles)
		{
			line = Helper.GetStringAtIndex(line, symboles[0], 2);
			line = Helper.GetStringAtIndex(line, symboles[1], 1);
			List<string> list = new List<string>();
			if (line.Contains(symboles[2]))
			{
				string[] array = line.Split(new string[1] { symboles[2] }, StringSplitOptions.None);
				foreach (string item in array)
				{
					list.Add(item);
				}
			}
			else
			{
				list.Add(line);
			}
			return list;
		}

		public static HeightType GetCharaHeightType(MenuDiary.Chara chara)
		{
			float num = ((ChaFile)chara.data.charFile).custom.body.shapeValueBody[0];
			if (!((double)num > 0.65))
			{
				if (!((double)num > 0.35))
				{
					if (!((double)num > -0.2))
					{
						return HeightType.VerySmall;
					}
					return HeightType.Small;
				}
				return HeightType.Medium;
			}
			return HeightType.Tall;
		}

		public static BoobSize GetCharaBoobsSize(MenuDiary.Chara chara)
		{
			float num = ((ChaFile)chara.data.charFile).custom.body.shapeValueBody[4];
			if (!((double)num > 0.55))
			{
				if (!((double)num > 0.27))
				{
					return BoobSize.Small;
				}
				return BoobSize.Average;
			}
			return BoobSize.Big;
		}

