		public override void LateUpdate()
		{
			if ((opCtx == OpenContext.Home && !CtrlHome.IsActive) || ((opCtx == OpenContext.ShopMap || opCtx == OpenContext.ShopEvent) && Core.dealer.MapID != 32) || (opCtx == OpenContext.H && !Core.dealer.InH))
			{
				DebugInfos.InConsole(" unsuitable context DESTROY " + opCtx, "MenuDress");
				Object.Destroy((Object)(object)this);
			}
			if ((Object)(object)cha_ != (Object)null && (Object)(object)Cha != (Object)null && (Object)(object)cha_ != (Object)(object)Cha && ShowMenu)
			{
				chaHasChanged = true;
				ShowMenu = false;
				((MonoBehaviour)this).StartCoroutine(IE_WaitAndReopen());
			}
			cha_ = Cha;
			if (Settings.InConfigMenu && ShowMenu)
			{
				ShowMenu = false;
			}
			if (ShowMenu && !showMenu_)
			{
				LoadOrAssumeDefault();
				opCtx = GetOpCtx();
				DebugInfos.InConsole(" opening context is " + opCtx, "MenuDress");
			}
			showMenu_ = ShowMenu;
			if (ShowMenu && (Object)(object)Cha == (Object)null)
			{
				ShowMenu = false;
			}
			if (ShowMenu && IsCursorOverMenuUpEdge() && Keys.LmbClick && !base.InEditPos)
			{
				((MonoBehaviour)this).StartCoroutine(IE_StartEditMenu());
			}
		}

		public List<string> GetTabNames<T>(List<T> tabs)
		{
			List<string> list = new List<string>();
			for (int i = 0; i < tabs.Count; i++)
			{
				string text = tabs[i].ToString();
				if (text == "DressCostume")
				{
					text = "Dressing";
				}
				if (text == "HairAndAcc")
				{
					text = "Hair & Acc";
				}
				if (text == "DressClothes")
				{
					text = "Clothes";
				}
				list.Add(text);
			}
			return list;
		}

		public override void OnGUI()
		{
			//IL_005e: Unknown result type (might be due to invalid IL or missing references)
			if (!GUIIsInit)
			{
				InitGUIStyle();
			}
			if (ShowMenu && !Scene.IsOverlap && !((Object)(object)Cha == (Object)null))
			{
				if (base.InEditPos)
				{
					EditMenu();
				}
				UIS.RezToSpc(40f, UIS.UiSpc.Vertical);
				GUILayout.BeginArea(new Rect(xAnchor, yAnchor, w, h));
				GUILayout.BeginVertical(styls.background, (GUILayoutOption[])(object)new GUILayoutOption[0]);
				UIS.Title("¤  " + ((ChaInfo)Cha).fileParam.firstname + "'s Dressing  ¤", closeBut: true, w * 0.99f, styls.title, styls.closeBut, delegate
				{
					ShowMenu = false;
				});
				if (opCtx != OpenContext.H)
				{
					GUILayout.Space(h * 0.01f);
					float hOffset = 0f;
					MainTab[] source = Enum.GetValues(typeof(MainTab)) as MainTab[];
					UIS.DrawTabs(GetTabNames(source.ToList()), (GUIStyle[])(object)new GUIStyle[2] { styls.tab1_act, styls.tab1_rest }, w * 0.99f, UIS.UiSpc.Horizontal, 0.75f, 15, 5, ref activeMainTabId, ref hOffset);
					GUILayout.Space(h * 0.01f);
				}
				else
				{
					activeMainTabId = 0;
				}
				MainTab mainTab = (MainTab)activeMainTabId;
				switch (mainTab)
				{
				case MainTab.DressCostume:
					DrawDressCostume();
					break;
				case MainTab.HairAndAcc:
					DrawHairAndAcc();
					break;
				case MainTab.DressClothes:
					DrawDressClothes();
					break;
				}
				GUILayout.EndVertical();
				GUILayout.EndArea();
				if (mainTab == MainTab.DressCostume)
				{
					UIS.DisplayToolTip(styls.toolTip);
				}
				chaHasChanged = false;
			}
		}

