			if ((Object)(object)Cha != (Object)null && saveTyp == SaveTyp.Hair && (opCtx == OpenContext.ShopMap || opCtx == OpenContext.ShopEvent) && Save != null)
			{
				SetHairColorToChaFile(((CharaData)Save).charFile);
				if (opCtx == OpenContext.ShopEvent)
				{
					foreach (NPC npc in SingletonInitializer<ActionScene>.instance.npcList)
					{
						if (((Base)npc).heroine == Save)
						{
							SetHairColorToChaFile(((ChaInfo)((Base)npc).chaCtrl).chaFile);
							if ((Object)(object)npcToReload == (Object)null)
							{
								((MonoBehaviour)this).StartCoroutine(IE_WaitForNpcReload(npc));
							}
							break;
						}
					}
				}
			}
			inWaitForSliderRelease = false;
		}

