					{
						((MonoBehaviour)this).StartCoroutine(IE_WaitForNpcReload(npc));
					}
					break;
				}
			}
		}

		private void SetClothes(CustomSelectInfo cusInfo)
		{
			if (clothActiveTabId == 0)
			{
				Cha.ChangeClothes(0, cusInfo.index, 0, 0, 0, false);
			}
			if (clothActiveTabId == 1)
			{
				Cha.ChangeClothesBot(cusInfo.index, false, true);
			}
			if (clothActiveTabId == 2)
			{
				Cha.ChangeClothesBra(cusInfo.index, false, true);
			}
			if (clothActiveTabId == 3)
			{
				Cha.ChangeClothesShorts(cusInfo.index, false, true);
			}
			if (clothActiveTabId == 4)
			{
				Cha.ChangeClothesGloves(cusInfo.index, false);
			}
			if (clothActiveTabId == 5)
			{
				Cha.ChangeClothesPanst(cusInfo.index, false, true);
			}
			if (clothActiveTabId == 6)
			{
				Cha.ChangeClothesSocks(cusInfo.index, false);
			}
			if (clothActiveTabId == 7)
			{
				Cha.ChangeClothesShoes(1, cusInfo.index, false);
			}
			if (Save == null)
			{
				return;
			}
			int num = ((opCtx == OpenContext.ShopMap || opCtx == OpenContext.ShopEvent) ? ((ChaInfo)Cha).fileStatus.coordinateType : ((ChaFile)((ChaInfo)Cha).chaFile).status.coordinateType);
			((ChaFile)((CharaData)Save).charFile).coordinate[num].clothes.parts[TabToPart].id = Cha.nowCoordinate.clothes.parts[TabToPart].id;
			if ((opCtx == OpenContext.ShopMap || opCtx == OpenContext.ShopEvent) && (Object)(object)((CharaData)Save).charaBase != (Object)null && (Object)(object)((CharaData)Save).charaBase.chaCtrl != (Object)null)
			{
				((ChaFile)((ChaInfo)((CharaData)Save).chaCtrl).chaFile).coordinate[num].LoadBytes(Cha.nowCoordinate.SaveBytes(), ChaFileDefine.ChaFileCoordinateVersion);
			}
			if (opCtx != OpenContext.ShopEvent)
			{
				return;
			}
			foreach (NPC npc in SingletonInitializer<ActionScene>.instance.npcList)
			{
				if (((Base)npc).heroine == Save)
				{
					((ChaFile)((ChaInfo)((Base)npc).chaCtrl).chaFile).coordinate[num].LoadBytes(Cha.nowCoordinate.SaveBytes(), ChaFileDefine.ChaFileCoordinateVersion);
					if ((Object)(object)npcToReload == (Object)null)
					{
						((MonoBehaviour)this).StartCoroutine(IE_WaitForNpcReload(npc));
					}
					break;
				}
			}
		}

		private void GetAllCoordinates(bool main = true, bool ksPlug = true)
		{
			List<string> files = new List<string>();
			if (main)
			{
				if (Directory.Exists("DefaultData/coordinate/"))
				{
					File.GetAllFiles("DefaultData/coordinate/", "*.png", ref files);
				}
				if (Directory.Exists(UserData.Path + "coordinate/"))
				{
					File.GetAllFiles(UserData.Path + "coordinate/", "*.png", ref files);
				}
				GetCoordListFromFiles(files, ref infosMainCoord);
			}
			if (ksPlug)
			{
				files = new List<string>();
				if (Directory.Exists(Settings.CoordPath))
				{
					File.GetAllFiles(Settings.CoordPath, "*.png", ref files);
				}
				GetCoordListFromFiles(files, ref infosKsPlugCoord);
			}
		}

		private static void GetCoordListFromFiles(List<string> files, ref List<CoordInfo> coordInfos, bool dbg = false)
		{
			//IL_0007: Unknown result type (might be due to invalid IL or missing references)
			//IL_000d: Expected O, but got Unknown
			//IL_0069: Unknown result type (might be due to invalid IL or missing references)
			//IL_006f: Expected O, but got Unknown
			for (int i = 0; i < files.Count; i++)
			{
				ChaFileCoordinate val = new ChaFileCoordinate();
				bool num = val.LoadFile(files[i]);
				if (num)
				{
					val.pngData = PngFile.LoadPngBytes(files[i]);
					coordInfos.Add(new CoordInfo
					{
						name = Helper.GetLastString(files[i], "/", rmvExt: true),
						coordinate = val,
						fileFullPath = files[i]
					});
				}
				if (!num)
				{
					ChaFileControl val2 = new ChaFileControl();
					if (val2.LoadCharaFile(files[i], byte.MaxValue, false, true))
					{
						val.pngData = PngFile.LoadPngBytes(files[i]);
						coordInfos.Add(new CoordInfo
						{
							name = Helper.GetLastString(files[i], "/", rmvExt: true),
							chaFileCtrl = val2,
							fileFullPath = files[i]
						});
					}
				}
			}
		}

		private void OnButApplyCoordinate(CoordInfo coordInfo, ChaControl targetCha, bool delIsPossible)
		{
			if (opCtx != OpenContext.H && delIsPossible && Keys.RmbHold)
			{
				File.Delete(coordInfo.fileFullPath);
				infosKsPlugCoord.Clear();
				GetAllCoordinates(main: false);
			}
			else
			{
				((MonoBehaviour)this).StartCoroutine(IE_ApplyCoordinate(coordInfo, targetCha));
			}
		}

		private void ApplyCoordinate(CoordInfo coordInfo, ChaControl targetCha)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Expected O, but got Unknown
			ChaFileCoordinate val = new ChaFileCoordinate();
			if (!val.LoadFile(coordInfo.fileFullPath))
			{
				return;
			}
			ApplyCoordinate(val, targetCha);
			if (!Core.dealer.InH || !spreadOnLoad)
			{
				return;
			}
			foreach (ChaCore item in Core.dealer.ChaCoresInH)
			{
				if ((Object)(object)item.Cha != (Object)(object)targetCha && ((ChaInfo)item.Cha).sex == ((ChaInfo)targetCha).sex)
				{
					ApplyCoordinate(val, item.Cha);
				}
			}
		}

		private IEnumerator IE_WaitAndRestoreExtraCmp(ChaControl targetCha, float bellyInfl)
		{
			yield return (object)new WaitForSeconds(Time.deltaTime * 3f);
			yield return (object)new WaitForSeconds(Time.deltaTime);
			BreastPusher.Create(targetCha);
			BellyCtrl.Create(targetCha);
			BellyCtrl.ForceInflation(targetCha, bellyInfl);
			DebugInfos.InConsole(" Wait and restored Component on " + ((ChaInfo)targetCha).fileParam.fullname, "MenuDress");
		}

		private IEnumerator IE_ApplyCoordinate(CoordInfo coordInfo, ChaControl targetCha)
		{
			Cam.DoFade(1.5f);
			if (coordInfo.IsCha)
			{
				if (!Core.dealer.InH)
				{
					if ((Object)(object)((Component)targetCha).gameObject.GetComponent<BreastPusher>() != (Object)null)
					{
						Object.Destroy((Object)(object)((Component)targetCha).gameObject.GetComponent<BreastPusher>());
					}
					float bellyInfl = 0f;
					if ((Object)(object)((Component)targetCha).gameObject.GetComponent<BellyCtrl>() != (Object)null)
					{
						bellyInfl = ((Component)targetCha).gameObject.GetComponent<BellyCtrl>().inflation;
						Object.Destroy((Object)(object)((Component)targetCha).gameObject.GetComponent<BellyCtrl>());
					}
					((MonoBehaviour)this).StartCoroutine(IE_WaitAndRestoreExtraCmp(targetCha, bellyInfl));
					yield return (object)new WaitForSeconds(Time.deltaTime);
				}
				ChaFile.CopyChaFile((ChaFile)(object)((ChaInfo)targetCha).chaFile, (ChaFile)(object)coordInfo.chaFileCtrl);
				if (!loadFullChaCloth)
				{
					((ChaFile)((ChaInfo)targetCha).chaFile).coordinate[((ChaInfo)targetCha).fileStatus.coordinateType].accessory = ((ChaFile)coordInfo.chaFileCtrl).coordinate[((ChaInfo)targetCha).fileStatus.coordinateType].accessory;
				}
				targetCha.Reload(false, false, false, false);
				targetCha.ChangeCoordinateTypeAndReload(true);
			}
			else
			{
				ApplyCoordinate(coordInfo, targetCha);
			}
		}

		private void ApplyCoordinate(ChaFileCoordinate chaFileCoord, ChaControl targetCha)
		{
			if (!applyAcc)
			{
				chaFileCoord.accessory = Clothes.CloneAccessories(targetCha.nowCoordinate.accessory);
			}
			if (applyAcc && skipHairAcc)
			{
				Clothes.CopyHeadAccs(ref chaFileCoord.accessory, targetCha.nowCoordinate.accessory);
			}
			targetCha.AssignCoordinate((CoordinateType)((ChaInfo)targetCha).fileStatus.coordinateType, chaFileCoord);
			targetCha.ChangeCoordinateTypeAndReload(true);
			targetCha.SetClothesStateAll((byte)0);
			targetCha.SetAccessoryStateAll(true);
			if (opCtx == OpenContext.ShopEvent)
			{
				foreach (NPC npc in SingletonInitializer<ActionScene>.instance.npcList)
				{
					if (((Base)npc).heroine == Save)
					{
						((ChaFile)((ChaInfo)((Base)npc).chaCtrl).chaFile).coordinate[((ChaInfo)targetCha).fileStatus.coordinateType].LoadBytes(targetCha.nowCoordinate.SaveBytes(), ChaFileDefine.ChaFileCoordinateVersion);
						if ((Object)(object)npcToReload == (Object)null)
						{
							((MonoBehaviour)this).StartCoroutine(IE_WaitForNpcReload(npc));
						}
						break;
					}
				}
			}
			if ((opCtx == OpenContext.ShopEvent || opCtx == OpenContext.ShopMap) && Save != null)
			{
				((ChaFile)((CharaData)Save).charFile).AssignCoordinate((CoordinateType)((ChaInfo)targetCha).fileStatus.coordinateType, chaFileCoord);
			}
		}

		private IEnumerator IE_ShootCoordPhoto()
		{
			_ = Vector3.zero;
			Quaternion baseRot = ((Component)Camera.main).transform.rotation;
			Vector3 position = ChaTools.FindInCha(Cha, Core.dealer.HasFreeCam ? "cf_j_neck" : "cf_j_spine01").position;
			Vector3 basePos = (Core.dealer.HasFreeCam ? Core.dealer.FreeCam.CamCtrl.TargetPos : ((Component)Camera.main).transform.position);
			Vector3 dir = Helper.GetDir(basePos, position, Core.dealer.HasFreeCam);
			if (Core.dealer.HasFreeCam)
			{
				BaseCameraControl_Ver2 camCtrl = Core.dealer.FreeCam.CamCtrl;
				camCtrl.TargetPos += dir;
			}
			else
			{
				((Component)Camera.main).transform.rotation = Quaternion.LookRotation(((Vector3)(ref dir)).normalized, Vector3.up);
			}
			yield return (object)new WaitForEndOfFrame();
			CustomCapture.CreatePng(ref Cha.nowCoordinate.pngData, 252, 352, (Camera)null, (Camera)null, Camera.main, (Camera)null);
			if (Core.dealer.HasFreeCam)
			{
				Core.dealer.FreeCam.CamCtrl.TargetPos = basePos;
			}
			else
			{
				((Component)Camera.main).transform.rotation = baseRot;
			}
		}

		private IEnumerator IE_SaveCoordinate()
		{
			yield return IE_ShootCoordPhoto();
			if (savAsFullCha)
			{
				string fileName = ChaCore.Name(((ChaInfo)Cha).fileParam).Replace(" ", "") + "_Cha_";
				string fullPath = Helper.FindFreeFileName(Settings.CoordPath, fileName, "png");
				GameAssets.SaveCha(Cha, fullPath);
			}
			else if (Core.OtherMods.Contains(Enums.Mod.BrwsFoldHooks))
			{
				WriteAndSaveCoordinate();
			}
			else
			{
				string coordPath = Settings.CoordPath;
				string text = ChaCore.Name(((ChaInfo)Cha).fileParam).Replace(" ", "") + "_" + ((object)(CoordinateType)((ChaInfo)Cha).fileStatus.coordinateType/*cast due to .constrained prefix*/).ToString() + "_";
				int num = 1;
				List<string> list = new List<string>();
				while (File.Exists(coordPath + text + num + ".png"))
				{
					list.Add(coordPath + text + num + ".png");
					num++;
				}
				string text2 = ((singleSavByOutfits && list.Count != 0) ? list[list.Count - 1] : (coordPath + text + num + ".png"));
				string directoryName = Path.GetDirectoryName(text2);
				if (!Directory.Exists(directoryName))
				{
					Directory.CreateDirectory(directoryName);
				}
				Cha.nowCoordinate.SaveFile(text2);
			}
			infosKsPlugCoord.Clear();
			GetAllCoordinates(main: false);
		}

		private void WriteAndSaveCoordinate()
		{
			//IL_003b: Unknown result type (might be due to invalid IL or missing references)
			string coordPath = Settings.CoordPath;
			string text = ChaCore.Name(((ChaInfo)Cha).fileParam).Replace(" ", "") + "_" + ((object)(CoordinateType)((ChaInfo)Cha).fileStatus.coordinateType/*cast due to .constrained prefix*/).ToString() + "_";
			int num = 1;
			List<string> list = new List<string>();
			while (File.Exists(coordPath + text + num + ".png"))
			{
				list.Add(coordPath + text + num + ".png");
				num++;
			}
			string path = ((singleSavByOutfits && list.Count != 0) ? list[list.Count - 1] : (coordPath + text + num + ".png"));
			string directoryName = Path.GetDirectoryName(path);
			if (!Directory.Exists(directoryName))
			{
				Directory.CreateDirectory(directoryName);
			}
			using (FileStream output = new FileStream(path, FileMode.Create, FileAccess.Write))
			{
				using BinaryWriter binaryWriter = new BinaryWriter(output);
				if (Cha.nowCoordinate.pngData != null)
				{
					binaryWriter.Write(Cha.nowCoordinate.pngData);
				}
				binaryWriter.Write(100);
				binaryWriter.Write("【KoiKatuClothes】");
				binaryWriter.Write(ChaFileDefine.ChaFileCoordinateVersion.ToString());
				binaryWriter.Write(Path.GetFileName(path));
				byte[] array = Cha.nowCoordinate.SaveBytes();
				binaryWriter.Write(array.Length);
				binaryWriter.Write(array);
			}
			infosKsPlugCoord.Clear();
			GetAllCoordinates(main: false);
		}

		private OpenContext GetOpCtx()
		{
			if (CtrlHome.IsActive)
			{
				return OpenContext.Home;
			}
			if (Core.dealer.Ctx == Dealer.Context.Default && Core.dealer.MapID == 32 && Core.dealer.PlayerIsChase)
			{
				return OpenContext.ShopMap;
			}
			if (Core.dealer.Ctx == Dealer.Context.Event && Core.dealer.MapID == 32)
			{
				return OpenContext.ShopEvent;
			}
			if (Core.dealer.Ctx == Dealer.Context.H)
			{
				return OpenContext.H;
			}
			return OpenContext.Undefined;
		}

		private IEnumerator IE_WaitForNpcReload(NPC npc)
		{
			npcToReload = npc;
			yield return (object)new WaitUntil((Func<bool>)(() => ((Base)npcToReload).chaCtrl.GetActiveTop()));
			yield return (object)new WaitForSeconds(Time.deltaTime);
			((Base)npcToReload).chaCtrl.Reload(true, true, false, true);
			((Base)npcToReload).chaCtrl.ChangeCoordinateTypeAndReload(true);
			npcToReload = null;
		}

		private IEnumerator IE_WaitAndReopen()
		{
			yield return (object)new WaitForSeconds(Time.deltaTime * 2f);
			ShowMenu = true;
		}

		private ChaControl FindCha()
		{
			switch (opCtx)
			{
			case OpenContext.Home:
				if (!Object.op_Implicit((Object)(object)Core.dealer.freeCam))
				{
					return null;
				}
				return Core.dealer.freeCam.girlAtHome.cha;
			case OpenContext.ShopMap:
				if (!Object.op_Implicit((Object)(object)Core.dealer.ActScene.Player) || !Object.op_Implicit((Object)(object)Core.dealer.ActScene.Player.chaser))
				{
					return null;
				}
				return ((Base)Core.dealer.ActScene.Player.chaser).chaCtrl;
			case OpenContext.ShopEvent:
				if (!((Object)(object)Core.dealer.EventCha != (Object)null))
				{
					return null;
				}
				return Core.dealer.EventCha;
			case OpenContext.H:
				return chaInH;
			default:
				return null;
			}
		}

		private Heroine FindSav()
		{
			switch (opCtx)
			{
			case OpenContext.Home:
				if (!Object.op_Implicit((Object)(object)Core.dealer.freeCam))
				{
					return null;
				}
				return Core.dealer.freeCam.girlAtHome.her;
			case OpenContext.ShopMap:
				return ChaCore.TryToGetSaveFromChaCore(((Component)((Base)Core.dealer.ActScene.Player.chaser).chaCtrl).gameObject);
			case OpenContext.ShopEvent:
				if (Core.dealer.eventInfo.saves.Count == 0)
				{
					return null;
				}
				return Core.dealer.eventInfo.saves[0];
			case OpenContext.H:
				return null;
			default:
				return null;
			}
		}

		public static void SetChaInH(ChaControl cha)
		{
			if (!((Object)(object)Core.dealer == (Object)null) && Core.dealer.DMenus != null && !((Object)(object)Core.dealer.DMenus.dress == (Object)null))
			{
				(Core.dealer.DMenus.dress as MenuDress).chaInH = cha;
			}
		}

		public static bool IsAttachedToThisCha(ChaControl cha, bool includeMenuShow = false)
		{
			if ((Object)(object)Core.dealer == (Object)null || Core.dealer.DMenus == null || (Object)(object)Core.dealer.DMenus.dress == (Object)null)
			{
				return false;
			}
			MenuDress menuDress = Core.dealer.DMenus.dress as MenuDress;
			if (!includeMenuShow)
			{
				if ((Object)(object)menuDress.Cha != (Object)null)
				{
					return (Object)(object)menuDress.Cha == (Object)(object)cha;
				}
				return false;
			}
			if ((Object)(object)menuDress.Cha != (Object)null && (Object)(object)menuDress.Cha == (Object)(object)cha)
			{
				return menuDress.ShowMenu;
			}
			return false;
		}
	}
