		public override void LateUpdate()
		{
			if (!ShowMenu && showMenu_)
			{
				Settings.Save();
			}
			if (ShowMenu && !showMenu_)
			{
				Settings.Load();
				LoadOrAssumeDefault();
				DefineSizeAndAnchors(Type.Config, ref xAnchor, ref yAnchor, ref w, ref h);
			}
			showMenu_ = ShowMenu;
			if (ShowMenu && IsCursorOverMenuUpEdge() && Keys.LmbClick && !base.InEditPos)
			{
				((MonoBehaviour)this).StartCoroutine(IE_StartEditMenu());
			}
		}

