			if (IsCursorOverCorner() && !ShowMenu)
			{
				ShowMenu = true;
			}
			if (ShowMenu && !IsCursorOverCorner() && !IsCursorOver() && !inExit)
			{
				inExit = true;
				calcY = yAnchor;
			}
			if (ShowMenu && !_showMenu)
			{
				calcY = yAnchor + (float)Screen.height * 0.025f;
			}
			_showMenu = ShowMenu;
			if (Settings.InConfigMenu)
			{
