			{
				return;
			}
			calcY = (inExit ? Mathf.MoveTowards(calcY, yAnchor + (float)Screen.height * 0.025f, Time.deltaTime * 65f) : Mathf.MoveTowards(calcY, yAnchor, Time.deltaTime * 50f));
			if (inExit && Mathf.Abs(calcY - (yAnchor + (float)Screen.height * 0.025f)) < 0.01f)
