			if (contents.Contains(Content.MapSel) && GUILayout.Button(UIS.TurnToString(Content.MapSel), Settings.InConfigMenu ? styls.but1_rest : (hCtrl.HMenus.mapSel.ShowMenu ? styls.but1_on : styls.but1_act), (GUILayoutOption[])(object)new GUILayoutOption[1] { GUILayout.Width(num) }))
