		public bool IsCursorOverCorner()
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0005: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			//IL_001a: Unknown result type (might be due to invalid IL or missing references)
			Vector3 mousePosition = Input.mousePosition;
			if (mousePosition.x > (float)Screen.width * 0.94f && mousePosition.y < (float)Screen.height - (float)Screen.height * 0.96f)
			{
				return true;
			}
			return false;
		}

		public static List<Content> SettingAsList()
		{
			List<Content> multiChoiceAsList = Settings.GetMultiChoiceAsList(Settings.CornerMenu);
			multiChoiceAsList.Remove(Content.Nothing);
			if (Core.dealer.HCtrl.StartTyp != HAnims.StartTyp.Normal && multiChoiceAsList.Contains(Content.InvMenu))
			{
				multiChoiceAsList.Remove(Content.InvMenu);
			}
			if (Core.dealer.HCtrl.StartTyp != HAnims.StartTyp.Normal && multiChoiceAsList.Contains(Content.RndInv))
			{
				multiChoiceAsList.Remove(Content.RndInv);
			}
			return multiChoiceAsList;
		}
	}
