			{
				foreach (Mover chaMover in Core.dealer.ChaMovers)
				{
					if ((Object)(object)chaMover.Ai != (Object)(object)Ai && !chaMover.Ai.InAction)
					{
						list.Add(chaMover.Ai);
					}
				}
				if ((Object)(object)Ai.Cha != (Object)(object)hCtrl.MainGirl.Cha)
				{
					list.Add(((Component)hCtrl.MainGirl.Cha).GetComponent<AI>());
				}
				if ((Object)(object)hCtrl.SecondGirl != (Object)null && (Object)(object)Ai.Cha != (Object)(object)hCtrl.SecondGirl.Cha)
				{
					list.Add(((Component)hCtrl.SecondGirl.Cha).GetComponent<AI>());
				}
			}
			int num = 0;
			foreach (AI item in list)
			{
				if (item.IsGirl && item.Typ == AI.Type.MainGirl && MainCanStrip(item))
				{
					bool doTop = (typ == ClothButTyp.StripTop || typ == ClothButTyp.StripFull) && Clothes.HasTopCloth(item.Cha);
					bool doBot = (typ == ClothButTyp.StripBot || typ == ClothButTyp.StripFull) && Clothes.HasBotCloth(item.Cha);
