					mainActionOver.doTop = doTop;
					mainActionOver.doBot = doBot;
					item.HideActionMenu();
				}
				if (item.IsGirl && item.Typ == AI.Type.Guest && (item as AIGuest).AskForStrip(null, typ == ClothButTyp.StripTop || typ == ClothButTyp.RemoveAll, typ == ClothButTyp.StripBot || typ == ClothButTyp.RemoveAll))
				{
					item.HideActionMenu();
				}
				num++;
			}
		}

