		private void GetAvailablePositions()
		{
			availablePos.Clear();
			PosInfoTyp posInfoTyp = ((!InAction || clipActs.Contains(Ai.gAction.Typ)) ? PosInfoTyp.Clip : ((InAction && animInfActs.Contains(Ai.gAction.Typ)) ? PosInfoTyp.AnimInfo : ((InAction && posDescrActs.Contains(Ai.gAction.Typ)) ? PosInfoTyp.BinderPosDescr : PosInfoTyp.Undefined)));
			AIGuest aIGuest = Ai as AIGuest;
			switch (posInfoTyp)
			{
			case PosInfoTyp.Clip:
			{
				List<Animations.Clip> list = new List<Animations.Clip>();
				if (!Ai.InAction)
				{
					if (aIGuest.AnimTyp == Animations.Type.Crouch || aIGuest.AnimTyp == Animations.Type.Stand)
					{
						list.AddRange(Animations.GetClipListFromTyp(Animations.Type.Crouch, aIGuest.GuestTyp));
						list.AddRange(Animations.GetClipListFromTyp(Animations.Type.Stand, aIGuest.GuestTyp));
					}
					else
					{
						list = Animations.GetClipListFromTyp(aIGuest.AnimTyp, aIGuest.GuestTyp);
					}
				}
				else
				{
					list = Ai.gAction.GetAvailableAnimClips();
				}
				{
					foreach (Animations.Clip item4 in list)
					{
						PoseInfo item2 = new PoseInfo
						{
							posName = item4.ToString(),
							clip = item4,
							displayName = Animations.ClipDisplayName(item4),
							assetName = Animations.GetAssetNameFromClip(item4),
							animTyp = Animations.GetTypFromClip(item4),
							infoTyp = posInfoTyp
						};
						availablePos.Add(item2);
					}
					break;
				}
			}
			case PosInfoTyp.AnimInfo:
			{
				if (!Ai.InAction)
				{
					break;
				}
				List<HAnims.AnimInfo> availableAnimInfos = Ai.gAction.GetAvailableAnimInfos();
				Animations.Type animTyp = ((Ai.gAction.Typ == GuestAction.Type.Piston || Ai.gAction.Typ == GuestAction.Type.Piston3P) ? Animations.Type.Piston : Animations.Type.Service);
				{
					foreach (HAnims.AnimInfo item5 in availableAnimInfos)
					{
						string assetName = (item5.asset.Contains("/") ? Helper.GetLastString(item5.asset, "/") : item5.asset);
						string value = string.Empty;
						if (!MenuPose.PoseNames.TryGetValue(item5.plugName, out value))
						{
							value = item5.plugName;
						}
						PoseInfo item3 = new PoseInfo
						{
							posName = item5.plugName,
							displayName = value,
							animInf = item5,
							assetName = assetName,
							animTyp = animTyp,
							infoTyp = posInfoTyp
						};
						availablePos.Add(item3);
					}
					break;
				}
			}
			case PosInfoTyp.BinderPosDescr:
				if (!Ai.InAction)
				{
					break;
				}
				{
					foreach (Binders.PoseDescr item6 in Ai.gAction.GetAvailablePoseDescr())
					{
						PoseInfo item = new PoseInfo
						{
							posName = item6.posName,
							displayName = item6.posName.Replace("_", " "),
							posDescr = item6,
							animTyp = Animations.Type.Bound,
							infoTyp = PosInfoTyp.BinderPosDescr
						};
						availablePos.Add(item);
					}
					break;
				}
			}
		}

		private bool IsPosButtonActive(PoseInfo posInfo)
		{
			AIGuest aIGuest = Ai as AIGuest;
			if ((Object)(object)(Ai as AIMain) != (Object)null)
			{
				return !MainActionOver.CurClipIsThisOne(posInfo.clip, Ai.ChaCore);
			}
			if ((Object)(object)aIGuest != (Object)null)
			{
				if (aIGuest.InSwap)
				{
					return false;
				}
				if (posInfo.infoTyp == PosInfoTyp.Clip)
				{
					return posInfo.clip != aIGuest.AnimClip;
				}
				if (posInfo.infoTyp == PosInfoTyp.AnimInfo)
				{
					return (aIGuest.AnimAsset.Contains("/") ? Helper.GetLastString(aIGuest.AnimAsset, "/") : aIGuest.AnimAsset) != posInfo.assetName;
				}
				if (posInfo.infoTyp == PosInfoTyp.BinderPosDescr)
				{
					return posInfo.posName != Bound.ActionAs(Ai.gAction).CurPos.posName;
				}
			}
			return false;
		}

