			//IL_004b: Unknown result type (might be due to invalid IL or missing references)
			SetDefaultSizeAndAnchors(Type.Diary);
			DefineSizeAndAnchors(Type.Diary, ref xAnchor, ref yAnchor, ref w, ref h);
			imageH = Screen.height / 6;
			imageW = (int)((float)imageH * 0.7f);
