		public override void LateUpdate()
		{
			//IL_0009: Unknown result type (might be due to invalid IL or missing references)
			//IL_000f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0025: Unknown result type (might be due to invalid IL or missing references)
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			if (InStory && _nowCycle != NowCycle)
			{
				((MonoBehaviour)this).StartCoroutine(IE_OnCycleChange());
				_nowCycle = NowCycle;
			}
			if (_inStory && !InStory)
			{
				Reset();
			}
			_inStory = InStory;
			if (Core.dealer.InH && !_inH)
			{
				inEcchiOnlyFilter = true;
			}
			_inH = Core.dealer.InH;
			if (_firstnameFirst != Settings.FirstNameFirst)
			{
				_firstnameFirst = Settings.FirstNameFirst;
				foreach (Chara storyChaData in storyChaDatas)
				{
					if (storyChaData.guiIsInit)
					{
						storyChaData.guiContent.tooltip = ChaCore.Name(storyChaData.data.parameter, Settings.FirstNameFirst);
					}
				}
			}
			if (curChara != _curChara)
			{
				if (curChara != null && curChara.her != null)
				{
					Statistic.ClampHExpTo100(curChara.her);
				}
				_curChara = curChara;
			}
			if (MenuCtx == Dealer.MenuCtx.Booking && !waitBookingMenuExit)
			{
				((MonoBehaviour)this).StartCoroutine(IE_WaitAndResetBookingExit());
			}
			if (ShowMenu && !showMenu_)
			{
				OnOpen();
			}
			showMenu_ = ShowMenu;
			if (ShowMenu && IsCursorOverMenuUpEdge() && Keys.LmbClick && !base.InEditPos)
			{
				((MonoBehaviour)this).StartCoroutine(IE_StartEditMenu());
			}
		}

		public override void OnGUI()
