				GUILayout.BeginVertical(styls.background, (GUILayoutOption[])(object)new GUILayoutOption[0]);
				string text = "Personal Diary";
				UIS.Title("¤  " + text + "  ¤", closeBut: true, w, styls.title, styls.closeBut, delegate
				{
					ShowMenu = false;
				});
				upperPartHeight = (float)UIS.RezToSpc(30f, UIS.UiSpc.Vertical) * base.MenuSize;
				DrawCharaSelect();
				if (curChara != null)
				{
					DrawSelectedChara(curChara);
