		private void Reset()
		{
			storyChaDatas.Clear();
			FuckedYesterday.Clear();
			filters.Clear();
			curChara = null;
			curFilter = Filter.All;
		}

		private IEnumerator IE_OnCycleChange()
		{
			yield return (object)new WaitUntil((Func<bool>)(() => !Scene.IsNowLoading && !Scene.IsNowLoadingFade));
			curChara = null;
			curFilter = Filter.All;
			if ((int)NowCycle == 0)
			{
				vTransform = new GameObject("vTransform").transform;
				vTransform.SetParent(((Component)Camera.main).transform, false);
				foreach (Chara storyChaData in storyChaDatas)
				{
					if (storyChaData.her != null && (Object)(object)storyChaData.npc != (Object)null)
					{
						storyChaData.npc = null;
					}
					if (storyChaData.her != null && (Object)(object)storyChaData.fixNpc != (Object)null)
					{
						storyChaData.fixNpc = null;
					}
				}
			}
			else if ((Object)(object)vTransform != (Object)null)
			{
				Object.Destroy((Object)(object)((Component)vTransform).gameObject);
			}
			if ((int)NowCycle == 1)
			{
				foreach (NPC npc in SingletonInitializer<ActionScene>.instance.npcList)
				{
					foreach (Chara storyChaData2 in storyChaDatas)
					{
						if (storyChaData2.her != null && storyChaData2.her == ((Base)npc).heroine)
						{
							storyChaData2.npc = npc;
							break;
						}
					}
				}
				Fix fixChara = SingletonInitializer<ActionScene>.instance.fixChara;
				if ((Object)(object)fixChara != (Object)null)
				{
					foreach (Chara storyChaData3 in storyChaDatas)
					{
						if (storyChaData3.typ == CharaTyp.LocalGirl)
						{
							storyChaData3.fixNpc = fixChara;
							break;
						}
					}
				}
			}
			GUIIsInit = false;
			styls.diary_chaName_spFont = false;
			styls.diary_infoBold_spFont = false;
			styls.diary_info_spFont = false;
			styls.diary_markPink_spFont = false;
			styls.diary_markYellow_spFont = false;
		}

		private void OnOpen()
		{
			if (!photosAreInit)
			{
				GetPhotos();
			}
			if ((DealCtx != Dealer.Context.Event && DealCtx != Dealer.Context.Esthetic && DealCtx != Dealer.Context.EstResult) || Core.dealer.eventInfo == null || Core.dealer.eventInfo.saves.Count == 0)
			{
				return;
			}
			foreach (Chara storyChaData in storyChaDatas)
			{
				if (storyChaData.her != null && storyChaData.her == Core.dealer.eventInfo.saves[0])
				{
					curChara = storyChaData;
					break;
				}
			}
		}

