			GUILayout.EndHorizontal();
			GUILayout.BeginVertical((GUILayoutOption[])(object)new GUILayoutOption[1] { GUILayout.Width(num3 * 0.58f) });
			GUILayout.Space(num * 0.025f);
			GUILayout.BeginHorizontal(Array.Empty<GUILayoutOption>());
