		private static string NpcAction(NPC npc)
		{
			int actionNo = npc.AI.actionNo;
			switch (actionNo)
			{
			case -1:
				return "Standing idle";
			case 0:
				if (!npc.AI.isRunning)
				{
					return "Doing nothing";
				}
				break;
			}
			switch (actionNo)
			{
			case 1:
				if (npc.AI.isArrival)
				{
					return "Pee";
				}
				return "Going for pee";
			case 2:
				if (npc.AI.isArrival)
				{
					return "Taking shower";
				}
				return "Going to take shower";
			case 3:
				return "Sit";
			case 4:
				if (npc.AI.isArrival)
				{
					return "Playing with herself";
				}
				return "Searching a place for masturbate";
			case 16:
				if (npc.AI.isArrival)
				{
					return "Resting on a deck chair";
				}
				break;
			}
			switch (actionNo)
			{
			case 29:
				if (npc.AI.isArrival)
				{
					return "Want sex with you";
				}
				return "Searching you for sex";
			case 33:
				return "Sit at pool side";
			case 44:
				if (npc.AI.isArrival)
				{
					return "Sleeping";
				}
				break;
			}
			if (npc.AI.isRunning && !npc.AI.isArrival)
			{
				return "Moving" + (Core.debug ? (" " + actionNo) : "");
			}
			return actionNo.ToString();
		}

