		public static List<Photo> GetPhotoList()
		{
			if (!Directory.Exists(Settings.PhotoPath))
			{
				return new List<Photo>();
			}
			List<Photo> list = new List<Photo>();
			List<string> list2 = new List<string>();
			File.GetAllFiles(Settings.PhotoPath, "*.png", ref list2);
			foreach (string item2 in list2)
			{
				string text = (item2.Contains("/") ? Helper.GetLastString(item2, "/", rmvExt: true) : item2);
				text = (text.Contains("_") ? Helper.GetStringAtIndex(text, "_", 1) : text);
				try
				{
					using FileStream input = new FileStream(item2, FileMode.Open, FileAccess.Read);
					using BinaryReader binaryReader = new BinaryReader(input);
					long pngSize = PngFile.GetPngSize(binaryReader);
					byte[] array = binaryReader.ReadBytes((int)pngSize);
					Photo item = new Photo
					{
						png = array,
						img = (Texture)(object)PngAssist.ChangeTextureFromByte(array, imageW, imageH),
						prefix = text,
						path = item2
					};
					list.Add(item);
				}
				catch
				{
				}
			}
			return list;
		}

