		private IEnumerator IE_InviteGirlsAround()
		{
			IsBusy = true;
			inAutoInvite = true;
			List<ChaList.FileInfo> filesToInv = new List<ChaList.FileInfo>();
			int num = (Settings.AutoInvite ? ((GirlsAround.Count < Settings.AutoInvLimit) ? GirlsAround.Count : Settings.AutoInvLimit) : 0);
			foreach (ChaList.FileInfo girlFile in girlFiles)
			{
				for (int i = 0; i < num; i++)
				{
					if (((Object)(object)GirlsAround[i].Npc != (Object)null && ((Base)GirlsAround[i].Npc).heroine == girlFile.Save) || ((Object)(object)GirlsAround[i].FixNpc != (Object)null && ((Base)GirlsAround[i].FixNpc).heroine == girlFile.Save))
					{
						filesToInv.Add(girlFile);
						break;
					}
				}
			}
			if (filesToInv.Count > 0)
			{
				yield return (object)new WaitForSeconds(1.5f);
				int i2 = 0;
				while (i2 < filesToInv.Count)
				{
					InviteSomeone(filesToInv[i2], girlsTabInf, girlFiles);
					yield return (object)new WaitForSeconds((i2 == filesToInv.Count - 1) ? 0f : 1.65f);
					int num2 = i2 + 1;
					i2 = num2;
				}
			}
			GirlsAround.Clear();
			inAutoInvite = false;
			IsBusy = false;
		}

		private IEnumerator IE_InviteGirlsFromHome(Dealer.StoryHInfo storyHInfo)
		{
			IsBusy = true;
			inAutoInvite = true;
			List<ChaList.FileInfo> filesToInv = new List<ChaList.FileInfo>();
			int num = (Settings.AutoInvite ? ((storyHInfo.girlsToMigrateInH.Count < Settings.AutoInvLimit) ? storyHInfo.girlsToMigrateInH.Count : Settings.AutoInvLimit) : 0);
			foreach (ChaList.FileInfo girlFile in girlFiles)
			{
				for (int i = 0; i < num; i++)
				{
					if (storyHInfo.girlsToMigrateInH[i] == girlFile.Save)
					{
						filesToInv.Add(girlFile);
						break;
					}
				}
			}
			storyHInfo.hasInvGirlsToMigate = true;
			if (filesToInv.Count > 0)
			{
				yield return (object)new WaitForSeconds(1.25f);
				int i2 = 0;
				while (i2 < filesToInv.Count)
				{
					InviteSomeone(filesToInv[i2], girlsTabInf, girlFiles);
					yield return (object)new WaitForSeconds((i2 == filesToInv.Count - 1) ? 0f : 1.65f);
					int num2 = i2 + 1;
					i2 = num2;
				}
			}
			inAutoInvite = false;
			IsBusy = false;
		}

		private void GuestCondSelector(float mainButSpace)
		{
			List<GuestCond> list = new List<GuestCond>
			{
				GuestCond.AsMain,
				GuestCond.Virgin,
				GuestCond.Rookie,
				GuestCond.Expert,
				GuestCond.Nympho
			};
			int count = list.Count;
			float num = (w - mainButSpace) * 0.8f / (float)count;
			for (int i = 0; i < count; i++)
			{
				bool flag = guestCond == list[i];
				if (GUILayout.Button(GuestCondToString(list[i]), flag ? styls.but1_rest : styls.but1_act, (GUILayoutOption[])(object)new GUILayoutOption[1] { GUILayout.Width(num) }) && !flag)
				{
					guestCond = list[i];
					showConditionSelect = false;
					break;
				}
			}
		}

		public static void InvFromOtherComponent(Heroine her)
		{
			if ((Object)(object)HCtrl.Get == (Object)null || HCtrl.Get.HMenus == null || (Object)(object)HCtrl.Get.HMenus.invite == (Object)null)
			{
