		}

		private void InviteSomeone(ChaList.FileInfo chaFile, TabInfo tabInfo, List<ChaList.FileInfo> chaFilesInfo)
		{
			//IL_001b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0021: Expected O, but got Unknown
			//IL_0032: Unknown result type (might be due to invalid IL or missing references)
			//IL_0038: Expected O, but got Unknown
			Cam.DoFade(0.5f);
			int sex = ((ChaFile)chaFile.File).parameter.sex;
			ChaFileControl val = new ChaFileControl();
			((ChaFile)val).CopyAll((ChaFile)(object)chaFile.File);
			GameObject val2 = new GameObject("GuestRoot");
			ChaControl val3 = ((sex == 1) ? ChaTools.CreateFemale(val2, 1, val) : ChaTools.CreateMale(val2, 1, val));
			((ChaFile)val).facePngData = ((ChaFile)chaFile.File).facePngData;
			chaFile.isCreated = true;
			val3.Load(false);
			if (Core.dealer.InStory && IsForH && sex == 1 && chaFile.Save != null)
			{
				Clothes.SetClothesFromBase(chaFile.Save, val3);
				if (Core.dealer.StoryHInf != null && Core.dealer.StoryHInf.IsSexAtHome)
				{
					int whreLiveSelection = Game.Player.whreLiveSelection;
					if (!Statistic.IsStayingWithPlayer(chaFile.Save, whreLiveSelection) && !Statistic.RoomIsFull(whreLiveSelection))
					{
						Statistic.SetStayWithPlayerPlace(chaFile.Save, whreLiveSelection);
					}
				}
			}
