		}

		public static void CleanCreatedFileInfo(int id, ChaControl cha)
		{
			if (!((Object)(object)Core.dealer.HCtrl == (Object)null) && !((Object)(object)Core.dealer.HCtrl.HMenus.invite == (Object)null))
			{
				MenuInvite obj = Core.dealer.HCtrl.HMenus.invite as MenuInvite;
				ChaList.FileInfo value = null;
