		private void CheckFiltersAfterInvite(ChaList.FileInfo chaFile, TabInfo tabInfo, List<ChaList.FileInfo> chaFilesInfo)
		{
			if (tabInfo.filters.Count < 1)
			{
				return;
			}
			string filter = chaFile.filter;
			List<string> list = new List<string>();
			for (int i = 0; i < chaFilesInfo.Count; i++)
			{
				if (!chaFilesInfo[i].isCreated && chaFilesInfo[i].canBeInvited && !(chaFilesInfo[i].filter == "All") && chaFilesInfo[i].filter == filter)
				{
					list.Add(chaFilesInfo[i].filter);
				}
			}
			if (list.Count == 0)
			{
				if (tabInfo.filters[tabInfo.filterId] == filter)
				{
					tabInfo.filterId = 0;
				}
				tabInfo.filters.Remove(filter);
			}
		}

		private void SearchAndAddInfoToChaList(List<ChaList.FileInfo> chaFilesInfo, TabInfo tabInf)
		{
			List<string> list = new List<string>();
			foreach (ChaList.FileInfo item in chaFilesInfo)
			{
				AddInfoAboutMainsToFileInfo(item);
				if (!list.Contains(item.filter))
				{
					list.Add(item.filter);
				}
			}
			if (list.Count < 2)
			{
				return;
			}
			tabInf.filters = new List<string> { "All" };
			foreach (string item2 in list)
			{
				if (!tabInf.filters.Contains(item2))
				{
					tabInf.filters.Add(item2);
				}
			}
		}

		private IEnumerator IE_ChaCoreAddInfo(ChaControl cha, ChaList.FileInfo chaFile, int creationId)
		{
			yield return (object)new WaitUntil((Func<bool>)(() => (Object)(object)((Component)cha).gameObject.GetComponent<ChaCore>() != (Object)null));
			ChaCore component = ((Component)cha).gameObject.GetComponent<ChaCore>();
			component.CanBeInteractInH = true;
			Heroine val = null;
			component.HSaveData = (Core.dealer.InStory ? chaFile.Save : val);
			Statistic.PreventMaxLewdness(Core.dealer.InStory ? chaFile.Save : val);
			component.HInfo = Count.CreateInfo(Core.dealer.InStory ? chaFile.Save : val, null, !Core.dealer.InStory && Keys.RmbHold);
			component.FaceTxt = ChaCore.CreateFaceText(((ChaFile)((ChaInfo)cha).chaFile).facePngData);
			component.SetCreationId(creationId);
			if (IsForH)
			{
				ChaCore.InformNpcWhoIsInH(component.HSaveData);
			}
		}

		private void AddInfoAboutMainsToFileInfo(ChaList.FileInfo fileInfo)
		{
			switch (Core.dealer.InStory)
			{
			case false:
				if (((ChaFile)((CharaData)hCtrl.HFlag.lstHeroine[0]).charFile).charaFileName == ((ChaFile)fileInfo.File).charaFileName && !foundMainGirl)
				{
					fileInfo.isCreated = true;
					foundMainGirl = true;
					idAndChaFile[0] = fileInfo;
				}
				if (hCtrl.HFlag.lstHeroine.Count > 1 && ((ChaFile)((CharaData)hCtrl.HFlag.lstHeroine[1]).charFile).charaFileName == ((ChaFile)fileInfo.File).charaFileName && !foundSecGirl)
				{
					fileInfo.isCreated = true;
					foundSecGirl = true;
					idAndChaFile[1] = fileInfo;
				}
				break;
			case true:
				if (IsForH && hCtrl.HFlag.lstHeroine[0] == fileInfo.Save)
				{
					fileInfo.isCreated = true;
					idAndChaFile[0] = fileInfo;
				}
				if (IsForH && hCtrl.HFlag.lstHeroine.Count > 1 && hCtrl.HFlag.lstHeroine[1] == fileInfo.Save)
				{
					fileInfo.isCreated = true;
					idAndChaFile[1] = fileInfo;
				}
				if (!IsForH && creaCtx == Dealer.Context.Esthetic && (Object)(object)Core.dealer.EstCtrl != (Object)null && Core.dealer.EstCtrl.Save == fileInfo.Save)
				{
					fileInfo.isCreated = true;
					idAndChaFile[1] = fileInfo;
				}
				fileInfo.canBeInvited = fileInfo.Save == null || fileInfo.Save.relation > 0;
				fileInfo.canBeInteract = fileInfo.Save == null || fileInfo.Save.relation > 0;
				break;
			}
		}

		private static string GuestCondToString(GuestCond guestCond)
		{
			if (guestCond == GuestCond.AsMain)
			{
				return "Based on Main";
			}
			return guestCond.ToString();
		}
	}
