		public void EditMenu()
		{
			customXanchor = Helper.MouseXtoScreenSpace - (Helper.CalcXtoScreenSpace(mouseX_atEditStart) - anchorX_atEditStart);
			customYanchor = Helper.MouseYtoScreenSpace - (Helper.CalcYtoScreenSpace(mouseY_atEditStart) - anchorY_atEditStart);
			if (Core.dealer.mInfos.wheelIncr != 0f)
			{
				menuSize = Mathf.Clamp(menuSize + Core.dealer.mInfos.wheelIncr * -0.15f, sizeRange.x, sizeRange.y);
				InitGUIStyle();
			}
			if (Keys.MmbClick)
			{
				menuSize = 1f;
				InitGUIStyle();
			}
			DefineSizeAndAnchors(MenuTyp, ref xAnchor, ref yAnchor, ref w, ref h);
		}

		public IEnumerator IE_StartEditMenu()
		{
			inEditPos = true;
			mouseX_atEditStart = Input.mousePosition.x;
			mouseY_atEditStart = Input.mousePosition.y;
			anchorX_atEditStart = xAnchor;
			anchorY_atEditStart = yAnchor;
			yield return (object)new WaitUntil((Func<bool>)(() => !Keys.LmbHold || Keys.RmbClick || !ShowMenu));
			if (Keys.RmbClick)
			{
				customXanchor = defaultXanchor;
				customYanchor = defaultYanchor;
				DefineSizeAndAnchors(MenuTyp, ref xAnchor, ref yAnchor, ref w, ref h);
			}
			inEditPos = false;
			Settings.SaveMenuEdits(this);
		}

		public void LoadOrAssumeDefault()
		{
			customXanchor = defaultXanchor;
			customYanchor = defaultYanchor;
			menuSize = 1f;
			Settings.ReadMenuEdits(this, ref customXanchor, ref customYanchor, ref menuSize);
		}

