			switch (typ)
			{
			case Type.PoseSelector:
				xAnchor = ((defaultXanchor != customXanchor) ? customXanchor : defaultXanchor);
				yAnchor = ((defaultYanchor != customYanchor) ? customYanchor : defaultYanchor);
				w = (float)UIS.ClampScreenW * 0.25f * menuSize;
				h = (float)Screen.height * 0.75f * menuSize;
