		public static BaseMenu Create(GameObject root, Type typ)
		{
			BaseMenu baseMenu = null;
			if (typ == Type.Invitation)
			{
				baseMenu = root.AddComponent<MenuInvite>();
			}
			if (typ == Type.PoseSelector)
			{
				baseMenu = root.AddComponent<MenuPose>();
			}
			if (typ == Type.Corner)
			{
				baseMenu = root.AddComponent<MenuCorner>();
			}
			if (typ == Type.Config)
			{
				baseMenu = root.AddComponent<MenuConfig>();
			}
			if (typ == Type.MapSelector)
			{
				baseMenu = root.AddComponent<MenuMap>();
			}
			if (typ == Type.Jukebox)
			{
				baseMenu = root.AddComponent<MenuJukebox>();
			}
			if (typ == Type.GuestAction)
			{
				baseMenu = root.AddComponent<MenuChara>();
			}
			if (typ == Type.Diary)
			{
				baseMenu = root.AddComponent<MenuDiary>();
			}
			if (typ == Type.Sunburn)
			{
				baseMenu = root.AddComponent<MenuSunburn>();
			}
			if (typ == Type.Dress)
			{
				baseMenu = root.AddComponent<MenuDress>();
			}
			baseMenu.MenuTyp = typ;
			return baseMenu;
		}
	}
