		private void DrawButtons(List<HAnims.AnimInfo> anims)
		{
			float num = ((base.MenuSize < 1f) ? (0.9f * ((base.MenuSize - 1f) * 0.075f + 1f)) : 0.9f);
			for (int i = 0; i < anims.Count; i++)
			{
				if ((!Settings.FilterDblInPosUI || !anims[i].hasPlugVersion) && (HAnims.SharesCategoryWithCurrent(anims[i]) || !Settings.FilterCatInPosUI) && (curTab != Tab.Serv || curSrvTab == ServTab.None || ((curSrvTab != ServTab.HandFoot || anims[i].animList.kindHoushi == 0) && (curSrvTab != ServTab.Mouth || anims[i].animList.kindHoushi == 1) && (curSrvTab != ServTab.Boobs || anims[i].animList.kindHoushi == 2))))
				{
					GUIStyle val = ((hCtrl.CurAnim != anims[i] && (CanChangePos() ? true : false)) ? styls.but1_act : styls.but1_rest);
					if (GUILayout.Button(ButtonName(anims[i]), val, (GUILayoutOption[])(object)new GUILayoutOption[1] { GUILayout.Width(w * num) }))
					{
						SetSelectedAnim(anims[i], Keys.RmbHold);
					}
				}
			}
		}

		private string ButtonName(HAnims.AnimInfo anim)
		{
			string value = string.Empty;
			if (!poseNames.TryGetValue(anim.plugName, out value))
			{
				value = anim.plugName;
			}
			if (!HAnims.SharesCategoryWithCurrent(anim))
			{
				value = "! " + value;
			}
			if (Core.debug && anim.hasPlugVersion)
			{
				value += " ( CLONED )";
			}
			return value;
		}

		private void TabSelector(float w)
		{
			_ = UIS.IsSmallRez;
			GUILayout.BeginHorizontal((GUILayoutOption[])(object)new GUILayoutOption[0]);
			GUILayout.Space(w * 0.02f);
			if (availableTabs.Count != 0 && !availableTabs.Contains(curTab))
			{
				curTab = availableTabs[0];
			}
			float num = w * (0.94f / (float)availableTabs.Count);
			for (int i = 0; i < availableTabs.Count; i++)
			{
				GUIStyle val = ((curTab == availableTabs[i]) ? styls.tab1_act : styls.tab1_rest);
				if (GUILayout.Button(TabName(availableTabs[i]), val, (GUILayoutOption[])(object)new GUILayoutOption[1] { GUILayout.Width(num) }))
				{
					curTab = availableTabs[i];
				}
			}
			GUILayout.EndHorizontal();
		}

