		private void DefineTabAndAnimList()
		{
			teaseAnims.Clear();
			sexAnims.Clear();
			srvAnims.Clear();
			lezAnims.Clear();
			availableTabs.Clear();
			availableSrvTabs.Clear();
			List<string> list = new List<string>();
			List<HAnims.AnimInfo> list2 = new List<HAnims.AnimInfo>();
			List<HAnims.AnimInfo> list3 = new List<HAnims.AnimInfo>();
			foreach (HAnims.AnimInfo hAnimInfo in hCtrl.HAnimInfos)
			{
				if ((HAnims.IsAvailableForSel(hAnimInfo) || !filterUnavaiblePose) && !list.Contains(hAnimInfo.plugName))
				{
					if (hAnimInfo.ctx == HAnims.Context.Tease)
					{
						teaseAnims.Add(hAnimInfo);
					}
					if (hAnimInfo.ctx == HAnims.Context.Peep && hAnimInfo.plugName.Contains("Mast_"))
					{
						list2.Add(hAnimInfo);
					}
					if (hAnimInfo.isSpSrv)
					{
						list3.Add(hAnimInfo);
					}
					if (hAnimInfo.ctx == HAnims.Context.Service && !hAnimInfo.isSpSrv)
					{
						srvAnims.Add(hAnimInfo);
					}
					if (hAnimInfo.ctx == HAnims.Context.Piston)
					{
						sexAnims.Add(hAnimInfo);
					}
					if (hAnimInfo.ctx == HAnims.Context.Peep && hAnimInfo.plugName.Contains("Lez_"))
					{
						lezAnims.Add(hAnimInfo);
					}
					list.Add(hAnimInfo.plugName);
				}
			}
			if (teaseAnims.Count != 0 || list2.Count != 0 || list3.Count != 0)
			{
				availableTabs.Add(Tab.Tease);
			}
			if (srvAnims.Count != 0)
			{
				availableTabs.Add(Tab.Serv);
			}
			if (sexAnims.Count != 0)
			{
				availableTabs.Add(Tab.Sex);
			}
			foreach (HAnims.AnimInfo srvAnim in srvAnims)
			{
				if (srvAnim.animList.kindHoushi == 0 && !availableSrvTabs.Contains(ServTab.HandFoot))
				{
					availableSrvTabs.Add(ServTab.HandFoot);
				}
				if (srvAnim.animList.kindHoushi == 1 && !availableSrvTabs.Contains(ServTab.Mouth))
				{
					availableSrvTabs.Add(ServTab.Mouth);
				}
				if (srvAnim.animList.kindHoushi == 2 && !availableSrvTabs.Contains(ServTab.Boobs))
				{
					availableSrvTabs.Add(ServTab.Boobs);
				}
			}
			if (availableSrvTabs.Count != 0)
			{
				curSrvTab = availableSrvTabs[0];
			}
			if (hCtrl.StartTyp == HAnims.StartTyp.FFM || hCtrl.StartTyp == HAnims.StartTyp.Lesbian)
			{
				availableTabs = new List<Tab>
				{
					Tab.Lez,
					Tab.Serv,
					Tab.Sex
				};
			}
			if (hCtrl.StartTyp == HAnims.StartTyp.DressRoom)
			{
				availableTabs = new List<Tab>
				{
					Tab.Tease,
					Tab.Serv,
					Tab.Sex
				};
				availableSrvTabs = new List<ServTab>
				{
					ServTab.HandFoot,
					ServTab.Mouth,
					ServTab.Boobs
				};
			}
			if (availableTabs.Count != 0 && !availableTabs.Contains(curTab))
			{
				curTab = availableTabs[0];
			}
			HAnims.OrderAnimList(ref teaseAnims);
			HAnims.OrderAnimList(ref list2);
			teaseAnims.AddRange(list2);
			HAnims.OrderAnimList(ref list3);
			teaseAnims.AddRange(list3);
			HAnims.OrderAnimList(ref srvAnims);
			HAnims.OrderAnimList(ref sexAnims);
			HAnims.OrderAnimList(ref lezAnims);
		}

		private bool CanChangePos()
		{
			if (WaitPosChange || Core.dealer.InProcess || HAnims.IsOrgasm() || (hCtrl.CurAnim.ctx == HAnims.Context.Piston && hCtrl.CurState == HAnims.State.OLoop))
			{
				return false;
			}
			return true;
		}

		public bool SetSelectedAnim(HAnims.AnimInfo anim, bool relaunch)
		{
			//IL_005f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0065: Invalid comparison between Unknown and I4
			//IL_007e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0084: Invalid comparison between Unknown and I4
			if (hCtrl.CurAnim == anim || !CanChangePos())
			{
				return false;
			}
			int num = (HManage.IsSecondMain() ? 1 : 0);
			if (hCtrl.HFlag.voiceWait || hCtrl.HFlag.isDenialvoiceWait || (int)hCtrl.HProc.voice.nowVoices[0].state == 3 || (int)hCtrl.HProc.voice.nowVoices[num].state == 2)
			{
				hCtrl.HFlag.voiceWait = false;
				hCtrl.HFlag.isDenialvoiceWait = false;
				Voice.Stop(hCtrl.HProc.voice.voiceTrans[num]);
			}
			if (anim.plugName.Contains("Back") && (Object)(object)hCtrl.FpvCtrl != (Object)null && Config.HData.FemaleNeckCamera)
			{
				Config.HData.FemaleNeckCamera = false;
			}
			((MonoBehaviour)this).StartCoroutine(IE_SetAnim(anim, relaunch));
			return true;
		}

		private IEnumerator IE_SetAnim(HAnims.AnimInfo anim, bool relaunch)
		{
			string stateBefore = hCtrl.HFlag.nowAnimStateName;
			HAnims.Context ctx = hCtrl.CurAnim.ctx;
			HAnims.State motionBefore = hCtrl.CurState;
			float speedBefore = hCtrl.HFlag.speed;
			bool hasCondom = hCtrl.HFlag.isCondom;
			bool isAnalPlay = hCtrl.HFlag.isAnalPlay;
			List<HAnims.State> list = new List<HAnims.State>
			{
				HAnims.State.InsertIdle,
				HAnims.State.Motion
			};
			if (ctx == HAnims.Context.Service)
			{
				list.Add(HAnims.State.OLoop);
			}
			bool canBeRelaunched = hCtrl.CurAnim.ctx == ctx && (anim.ctx == HAnims.Context.Piston || anim.ctx == HAnims.Context.Service) && list.Contains(motionBefore);
			WaitPosChange = true;
			HAnims.AnimInfo _anim = hCtrl.CurAnim;
			hCtrl.HFlag.selectAnimationListInfo = anim.animList;
			yield return (object)new WaitUntil((Func<bool>)(() => _anim != hCtrl.CurAnim));
			ShowMenu = false;
			WaitPosChange = false;
			if (!(relaunch && canBeRelaunched))
			{
				yield break;
			}
			hCtrl.HFlag.isDenialvoiceWait = false;
			hCtrl.HFlag.voiceWait = false;
			if (stateBefore.Contains("A_") && !hCtrl.CurAnim.hasAnal)
			{
				stateBefore.Replace("A_", "");
			}
			HManage.PlayStateOnMains(stateBefore);
			HManage.ToggleCondom(hasCondom);
			if (hCtrl.CurAnim.ctx == HAnims.Context.Piston && motionBefore != HAnims.State.InsertIdle)
			{
				if (isAnalPlay && hCtrl.CurAnim.hasAnal)
				{
					hCtrl.HFlag.isAnalPlay = isAnalPlay;
				}
				yield return (object)new WaitUntil((Func<bool>)(() => hCtrl.CurState == HAnims.State.InsertIdle));
				hCtrl.HFlag.click = (ClickKind)28;
				yield return (object)new WaitForSeconds(Time.deltaTime);
				if (speedBefore > 1.75f)
				{
					hCtrl.HFlag.click = (ClickKind)6;
					yield return (object)new WaitForSeconds(Time.deltaTime);
				}
				HManage.AvoidMotionStop();
			}
			hCtrl.HFlag.SpeedUpClick(speedBefore - hCtrl.HFlag.speed, 1f);
		}

		public static void MoveInAnimList(Enums.Way way)
		{
			HCtrl get = HCtrl.Get;
			if ((Object)(object)get == (Object)null || get.HMenus == null || (Object)(object)get.HMenus.posSel == (Object)null)
			{
				return;
			}
			MenuPose menuPose = get.HMenus.posSel as MenuPose;
			List<HAnims.State> list = new List<HAnims.State>
			{
				HAnims.State.InsertIdle,
				HAnims.State.Motion,
				HAnims.State.OLoop,
				HAnims.State.OrgIdle
			};
			bool flag = get.HFlag.isAnalPlay && list.Contains(get.CurState);
			List<HAnims.AnimInfo> list2 = new List<HAnims.AnimInfo>();
			if (menuPose.teaseAnims.Contains(get.CurAnim))
			{
				foreach (HAnims.AnimInfo teaseAnim in menuPose.teaseAnims)
				{
					if (!Settings.FilterDblInPosUI || !teaseAnim.hasPlugVersion)
					{
						list2.Add(teaseAnim);
					}
				}
			}
			if (menuPose.srvAnims.Contains(get.CurAnim))
			{
				foreach (HAnims.AnimInfo srvAnim in menuPose.srvAnims)
				{
					if (!Settings.FilterDblInPosUI || !srvAnim.hasPlugVersion)
					{
						list2.Add(srvAnim);
					}
				}
			}
			if (menuPose.sexAnims.Contains(get.CurAnim))
			{
				foreach (HAnims.AnimInfo sexAnim in menuPose.sexAnims)
				{
					if ((!flag || sexAnim.hasAnal) && (!Settings.FilterDblInPosUI || !sexAnim.hasPlugVersion))
					{
						list2.Add(sexAnim);
					}
				}
			}
			if (menuPose.lezAnims.Contains(get.CurAnim))
			{
				foreach (HAnims.AnimInfo lezAnim in menuPose.lezAnims)
				{
					if (!Settings.FilterDblInPosUI || !lezAnim.hasPlugVersion)
					{
						list2.Add(lezAnim);
					}
				}
			}
			HAnims.AnimInfo curAnim = get.CurAnim;
			HAnims.AnimInfo animInfo = HAnims.NextOrPrevInList(list2, curAnim, way);
			DebugInfos.InConsole("Next Anim from " + curAnim.plugName + " is " + animInfo.plugName);
			if (animInfo != null)
			{
				menuPose.SetSelectedAnim(animInfo, relaunch: true);
			}
		}

		public static bool ChangeStartAnim(HAnims.Context ctx)
		{
			HCtrl get = HCtrl.Get;
			if ((Object)(object)get == (Object)null || get.HMenus == null || (Object)(object)get.HMenus.posSel == (Object)null)
			{
				return false;
			}
			MenuPose menuPose = get.HMenus.posSel as MenuPose;
			HAnims.AnimInfo animInfo = null;
			if (ctx == HAnims.Context.Piston && menuPose.sexAnims.Count != 0)
			{
				animInfo = Helper.RandomInList(menuPose.sexAnims);
			}
			if (ctx == HAnims.Context.Service && menuPose.srvAnims.Count != 0)
			{
				animInfo = Helper.RandomInList(menuPose.srvAnims);
			}
			if (ctx == HAnims.Context.Peep)
			{
				if ((Object)(object)get.SecondGirl == (Object)null)
				{
					List<HAnims.AnimInfo> list = new List<HAnims.AnimInfo>();
					foreach (HAnims.AnimInfo teaseAnim in menuPose.teaseAnims)
					{
						if (teaseAnim.plugName.Contains("Mast"))
						{
							list.Add(teaseAnim);
						}
					}
					if (list.Count != 0)
					{
						animInfo = Helper.RandomInList(list);
					}
				}
				else if (menuPose.lezAnims.Count != 0)
				{
					animInfo = Helper.RandomInList(menuPose.lezAnims);
				}
			}
			if (animInfo != null)
			{
				menuPose.SetSelectedAnim(animInfo, relaunch: false);
			}
			return animInfo != null;
		}

		public static bool ChainAnims(Enums.ChainTyp typ, bool isQuickChain)
		{
			HCtrl get = HCtrl.Get;
			if ((Object)(object)get == (Object)null || get.HMenus == null || (Object)(object)get.HMenus.posSel == (Object)null || typ == Enums.ChainTyp.None)
			{
				return false;
			}
			MenuPose menuPose = get.HMenus.posSel as MenuPose;
			if (menuPose.WaitPosChange)
			{
				return false;
			}
			string stringAtIndex = Helper.GetStringAtIndex(get.CurAnim.plugName, "_", 2);
			List<HAnims.AnimInfo> list = new List<HAnims.AnimInfo>();
			List<HAnims.AnimInfo> list2 = new List<HAnims.AnimInfo>();
			List<HAnims.AnimInfo> list3 = new List<HAnims.AnimInfo>();
			if (typ == Enums.ChainTyp.Vagina || typ == Enums.ChainTyp.Anal)
			{
				foreach (HAnims.AnimInfo sexAnim in menuPose.sexAnims)
				{
					if (HAnims.SharesCategoryWithCurrent(sexAnim) && sexAnim.plugName != get.CurAnim.plugName && (typ == Enums.ChainTyp.Vagina || (typ == Enums.ChainTyp.Anal && sexAnim.hasAnal)) && (bondageAnims.Contains(get.CurAnim.plugName) || !bondageAnims.Contains(sexAnim.plugName)) && (!bondageAnims.Contains(get.CurAnim.plugName) || bondageAnims.Contains(sexAnim.plugName)))
					{
						list2.Add(sexAnim);
					}
				}
				if (list2.Count == 0 && typ == Enums.ChainTyp.Anal)
				{
					foreach (HAnims.AnimInfo sexAnim2 in menuPose.sexAnims)
					{
						if (HAnims.SharesCategoryWithCurrent(sexAnim2) && sexAnim2.plugName != get.CurAnim.plugName && (!sexAnim2.hasPlugVersion || !Settings.FilterDblInPosUI))
						{
							list2.Add(sexAnim2);
						}
					}
				}
				foreach (HAnims.AnimInfo item in list2)
				{
					if ((stringAtIndex == "Lay" || stringAtIndex == "Stand") && item.plugName.Contains(stringAtIndex) && (typ == Enums.ChainTyp.Vagina || (typ == Enums.ChainTyp.Anal && item.hasAnal)) && (!item.hasPlugVersion || !Settings.FilterDblInPosUI))
					{
						list3.Add(item);
					}
				}
			}
			if (typ == Enums.ChainTyp.SrvMouth || typ == Enums.ChainTyp.SrvBreast || typ == Enums.ChainTyp.SrvHand || typ == Enums.ChainTyp.SrvFoot)
			{
				foreach (HAnims.AnimInfo srvAnim in menuPose.srvAnims)
				{
					if (HAnims.SharesCategoryWithCurrent(srvAnim) && srvAnim.plugName != get.CurAnim.plugName && (!srvAnim.hasPlugVersion || !Settings.FilterDblInPosUI))
					{
						list2.Add(srvAnim);
					}
				}
				foreach (HAnims.AnimInfo item2 in list2)
				{
					if ((typ == Enums.ChainTyp.SrvFoot && item2.plugName.Contains("Foot")) || (typ == Enums.ChainTyp.SrvHand && item2.animList.kindHoushi == 0 && !item2.plugName.Contains("Foot")) || (typ == Enums.ChainTyp.SrvMouth && item2.animList.kindHoushi == 1) || (typ == Enums.ChainTyp.SrvBreast && item2.animList.kindHoushi == 2))
					{
						if ((stringAtIndex == "Lay" || stringAtIndex == "Stand") && item2.plugName.Contains(stringAtIndex))
						{
							list3.Add(item2);
						}
						else
						{
							list3.Add(item2);
						}
					}
				}
			}
			if (typ == Enums.ChainTyp.SrvHump)
			{
				foreach (HAnims.AnimInfo srvAnim2 in menuPose.srvAnims)
				{
					if (HAnims.SharesCategoryWithCurrent(srvAnim2) && srvAnim2.plugName != get.CurAnim.plugName)
					{
						list2.Add(srvAnim2);
					}
				}
				foreach (HAnims.AnimInfo item3 in list2)
				{
					if (item3.plugName.Contains("Hump") || item3.plugName.Contains("ThighJob"))
					{
						list3.Add(item3);
					}
				}
			}
			if (typ == Enums.ChainTyp.Tease || typ == Enums.ChainTyp.Onani)
			{
				foreach (HAnims.AnimInfo teaseAnim in menuPose.teaseAnims)
				{
					if (HAnims.SharesCategoryWithCurrent(teaseAnim) && teaseAnim.plugName != get.CurAnim.plugName && ((typ == Enums.ChainTyp.Onani) ? teaseAnim.plugName.Contains("Mast") : (!teaseAnim.plugName.Contains("Mast"))))
					{
						list2.Add(teaseAnim);
					}
				}
				foreach (HAnims.AnimInfo item4 in list2)
				{
					if ((stringAtIndex == "Lay" || stringAtIndex == "Stand") && item4.plugName.Contains(stringAtIndex))
					{
						list3.Add(item4);
					}
				}
			}
			list = ((list3.Count != 0) ? list3 : list2);
			if (list.Count > 0)
			{
				get.HFlag.voiceWait = false;
				Voice.Stop(get.HProc.voice.voiceTrans[HManage.IsSecondMain() ? 1 : 0]);
				List<HAnims.State> list4 = new List<HAnims.State>
				{
					HAnims.State.Motion,
					HAnims.State.OLoop,
					HAnims.State.OrgF,
					HAnims.State.OrgIdle,
					HAnims.State.OralIdle
				};
				if (get.InChainOpen || list4.Contains(get.CurState))
				{
					Sound.Play((SystemSE)5);
					((MonoBehaviour)menuPose).StartCoroutine(IE_ChainAnims(typ, isQuickChain));
				}
				return menuPose.SetSelectedAnim(Helper.RandomInList(list), relaunch: false);
			}
			return false;
		}

		public static IEnumerator IE_ChainAnims(Enums.ChainTyp typ, bool isQuickChain, bool waitNextAnim = true)
		{
			DebugInfos.InConsole("Start IE_ChainAnims");
			HCtrl hCtrl = HCtrl.Get;
			_ = hCtrl.ChainTimer;
			if (waitNextAnim)
			{
				HAnims.AnimInfo curAnim = hCtrl.CurAnim;
				yield return (object)new WaitUntil((Func<bool>)(() => curAnim != hCtrl.CurAnim));
			}
			if (hCtrl.CurAnim.ctx == HAnims.Context.Piston)
			{
				yield return (object)new WaitForSeconds(0.2f);
				hCtrl.HFlag.voiceWait = false;
				hCtrl.HFlag.isDenialvoiceWait = false;
				Voice.Stop(hCtrl.HProc.voice.voiceTrans[HManage.IsSecondMain() ? 1 : 0]);
				hCtrl.HFlag.click = (ClickKind)((typ == Enums.ChainTyp.Anal && hCtrl.CurAnim.hasAnal) ? 4 : 2);
				yield return (object)new WaitForSeconds(Time.deltaTime);
				hCtrl.HFlag.voiceWait = false;
				hCtrl.HFlag.isDenialvoiceWait = false;
				Voice.Stop(hCtrl.HProc.voice.voiceTrans[0]);
				if (hCtrl.HasSecondGirl)
				{
					Voice.Stop(hCtrl.HProc.voice.voiceTrans[1]);
				}
				yield return (object)new WaitUntil((Func<bool>)(() => hCtrl.CurState == HAnims.State.InsertIdle));
				if (typ == Enums.ChainTyp.Anal)
				{
					_ = hCtrl.CurAnim.hasAnal;
				}
				yield return (object)new WaitForSeconds(Time.deltaTime);
				hCtrl.HFlag.click = (ClickKind)28;
				if (isQuickChain)
				{
					yield return (object)new WaitForSeconds(Time.deltaTime);
					hCtrl.HFlag.click = (ClickKind)6;
					hCtrl.HFlag.SpeedUpClick(2f, 1f);
					hCtrl.HFlag.gaugeMale = Mathf.Clamp(hCtrl.HFlag.gaugeMale + 15f, 0f, 100f);
					hCtrl.HFlag.gaugeFemale = Mathf.Clamp(hCtrl.HFlag.gaugeFemale + 15f, 0f, 100f);
				}
				yield return (object)new WaitForSeconds(Time.deltaTime);
				HManage.AvoidMotionStop();
			}
			if (hCtrl.CurAnim.ctx == HAnims.Context.Service)
			{
				yield return (object)new WaitForSeconds(0.1f);
				hCtrl.HFlag.voiceWait = false;
				Voice.Stop(hCtrl.HProc.voice.voiceTrans[HManage.IsSecondMain() ? 1 : 0]);
				hCtrl.HFlag.click = (ClickKind)5;
				if (isQuickChain)
				{
					yield return (object)new WaitForSeconds(Time.deltaTime);
					hCtrl.HFlag.click = (ClickKind)6;
					hCtrl.HFlag.SpeedUpClick(2f, 1f);
					hCtrl.HFlag.gaugeMale = Mathf.Clamp(hCtrl.HFlag.gaugeMale + 15f, 0f, 100f);
				}
			}
			if (hCtrl.CurAnim.ctx == HAnims.Context.Tease)
			{
				yield return (object)new WaitForSeconds(Time.deltaTime);
				Cam.DoFade(0.5f);
				HManage.PlayStateOnMains("Orgasm_A");
			}
		}
	}
