	public class Mouse
	{
		public class MouseInfo
		{
			public float lmb_stTime;

			public float lmb_lastTime;

			public bool lmbPress;

			public bool lmbShortPress;

			public bool lmbHold;

			public bool dblClickLmb;

			public float lmbDblHold_timer;

			public bool dblHoldClickLmb;

			public float rmb_stTime;

			public float rmb_lastTime;

			public bool rmbPress;

			public bool rmbHold;

			public bool dblClickRmb;

			public float mmb_stTime;

			public bool mmbPress;

			public bool mmbShortPress;

			public bool mmbHold;

			public float wheelIncr;

			public float dragLenght;
		}

		public static bool cancelNextMmbShort;

		private static Vector2 mouseDrag_;

		public static void FeedMouseInfo(ref MouseInfo mInfos)
		{
			if (Keys.MmbClick && !mInfos.mmbPress)
			{
				mInfos.mmbPress = true;
				mInfos.mmb_stTime = Time.unscaledTime;
			}
			mInfos.mmbShortPress = false;
			if (mInfos.mmbPress && !Keys.MmbHold)
			{
				if (Time.unscaledTime - mInfos.mmb_stTime <= 0.22f && !cancelNextMmbShort)
				{
					mInfos.mmbShortPress = true;
				}
				mInfos.mmbPress = false;
				cancelNextMmbShort = false;
			}
			mInfos.mmbHold = Keys.MmbHold;
			mInfos.wheelIncr = Keys.WheelIncr;
			if (Keys.LmbClick && !mInfos.lmbPress)
			{
				mInfos.lmbPress = true;
				mInfos.lmb_stTime = Time.unscaledTime;
			}
			if (Keys.LmbClick)
			{
				if (Time.unscaledTime - mInfos.lmb_lastTime <= 0.38f)
				{
					mInfos.dblHoldClickLmb = true;
					mInfos.lmbDblHold_timer = 0f;
				}
			}
			else if (mInfos.dblHoldClickLmb && (!Keys.LmbHold || mInfos.lmbDblHold_timer >= Time.deltaTime * 5f))
			{
				mInfos.dblHoldClickLmb = false;
			}
			mInfos.lmbDblHold_timer += Time.deltaTime;
			if (mInfos.lmbPress && Keys.LmbRelease)
			{
				if (Time.unscaledTime - mInfos.lmb_lastTime <= 0.38f)
				{
					mInfos.dblClickLmb = true;
				}
			}
			else if (mInfos.dblClickLmb)
			{
				mInfos.dblClickLmb = false;
			}
			if (mInfos.lmbPress && !Keys.LmbHold)
			{
				mInfos.lmbPress = false;
				if (Time.unscaledTime - mInfos.lmb_stTime <= 0.15f)
				{
					mInfos.lmbShortPress = true;
				}
				mInfos.lmb_lastTime = mInfos.lmb_stTime;
			}
			else if (mInfos.lmbShortPress)
			{
				mInfos.lmbShortPress = false;
			}
			mInfos.lmbHold = Keys.LmbHold;
			if (Keys.RmbClick && !mInfos.rmbPress)
			{
				mInfos.rmbPress = true;
				mInfos.rmb_stTime = Time.unscaledTime;
			}
			if (mInfos.rmbPress && !Keys.RmbHold)
			{
				if (Time.unscaledTime - mInfos.rmb_lastTime <= 0.38f)
				{
					mInfos.dblClickRmb = true;
				}
			}
			else if (mInfos.dblClickRmb)
			{
				mInfos.dblClickRmb = false;
			}
			if (mInfos.rmbPress && !Keys.RmbHold)
			{
				mInfos.rmbPress = false;
				mInfos.rmb_lastTime = mInfos.rmb_stTime;
			}
			mInfos.rmbHold = Keys.RmbHold;
			CalcMouseDrag(ref Core.dealer.mInfos.dragLenght);
		}

		public static void CalcMouseDrag(ref float dragDmp)
		{
			//IL_0011: Unknown result type (might be due to invalid IL or missing references)
			//IL_0016: Unknown result type (might be due to invalid IL or missing references)
			//IL_0017: Unknown result type (might be due to invalid IL or missing references)
			//IL_001c: Unknown result type (might be due to invalid IL or missing references)
			//IL_005f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0060: Unknown result type (might be due to invalid IL or missing references)
			Vector2 val = default(Vector2);
			((Vector2)(ref val))..ctor(Keys.MouseX, Keys.MouseY);
			Vector2 val2 = mouseDrag_ - val;
			float num = ((Vector2)(ref val2)).magnitude * Time.deltaTime * 0.5f;
			if (num < 0.0001f)
			{
				dragDmp = Mathf.MoveTowards(dragDmp, 0f, Time.deltaTime * 0.5f);
			}
			else
			{
				dragDmp = Mathf.Clamp01(dragDmp + num);
			}
			mouseDrag_ = val;
		}
	}
