	public class MainActionOver : MonoBehaviour
	{
		private HCtrl hCtrl;

		private ChaCore chaCore;

		private ChaControl cha;

		private AIMain ai;

		private Animations.Clip overClip = Animations.Clip.Dance_01;

		private bool aibuSelectAtStart;

		private bool isStriptease;

		public bool doTop;

		public bool doBot;

		private bool isInit;

		private const string overrideState = "A_Idle";

		private Vector2[] headAnimCtrlranges;

		private float runTimer;

		private float voiceTime;

		public List<Item> AnimItems { get; private set; }

		public bool InStrip => isStriptease;

		private void Start()
		{
			hCtrl = HCtrl.Get;
			cha = chaCore.Cha;
			ai = ((Component)chaCore).gameObject.GetComponent<AIMain>();
			AnimItems = new List<Item>();
			aibuSelectAtStart = hCtrl.InLockAibuOverUI;
			voiceTime = Random.Range(4f, 10f);
			if (isStriptease)
			{
				((MonoBehaviour)this).StartCoroutine(IE_DoStripTease(Random.Range(0f, 15f) / 100f, doTop, doBot));
			}
			else
			{
				((MonoBehaviour)this).StartCoroutine(IE_Init());
			}
		}

		private IEnumerator IE_Init()
		{
			float num = Random.Range(0f, 25f) / 100f;
			yield return (object)new WaitForSeconds(num);
			if ((Object)(object)hCtrl.HProc.hand != (Object)null)
			{
				hCtrl.HProc.hand.DetachAllItem();
			}
			if ((Object)(object)hCtrl.HProc.hand1 != (Object)null)
			{
				hCtrl.HProc.hand1.DetachAllItem();
			}
			ReplaceAnim();
			isInit = true;
		}

		private void LateUpdate()
		{
			//IL_015a: Unknown result type (might be due to invalid IL or missing references)
			//IL_015f: Unknown result type (might be due to invalid IL or missing references)
			if (!isInit)
			{
				return;
			}
			FullBodyBipedIK fullBodyIK = chaCore.CtrlIK.FullBodyIK;
			List<IKEffector> obj = new List<IKEffector>
			{
				fullBodyIK.solver.leftHandEffector,
				fullBodyIK.solver.rightHandEffector,
				fullBodyIK.solver.leftFootEffector,
				fullBodyIK.solver.rightFootEffector
			};
			List<FBIKChain> list = new List<FBIKChain>
			{
				fullBodyIK.solver.leftArmChain,
				fullBodyIK.solver.rightArmChain,
				fullBodyIK.solver.leftLegChain,
				fullBodyIK.solver.rightLegChain
			};
			foreach (IKEffector item in obj)
			{
				item.positionWeight = 0f;
				item.rotationWeight = 0f;
			}
			foreach (FBIKChain item2 in list)
			{
				item2.bendConstraint.weight = 0f;
			}
			((ChaInfo)cha).animBody.SetFloat("speed", 1f);
			hCtrl.HFlag.isAibuSelect = false;
			AnimatorStateInfo currentAnimatorStateInfo = ((ChaInfo)cha).animBody.GetCurrentAnimatorStateInfo(0);
			float normalizedTime = ((AnimatorStateInfo)(ref currentAnimatorStateInfo)).normalizedTime;
			for (int i = 0; i < headAnimCtrlranges.Length; i++)
			{
				cha.ChangeLookNeckPtn((!(headAnimCtrlranges[i].x < normalizedTime) || !(normalizedTime < headAnimCtrlranges[i].y)) ? 1 : 3, 1f);
			}
			runTimer += Time.unscaledDeltaTime;
			if (runTimer > voiceTime)
			{
				runTimer = 0f;
				voiceTime = Random.Range(6f, 13f);
				ai.Speak((Random.Range(0, 100) > 35) ? AIMain.VoiceType.Laught : AIMain.VoiceType.Comment);
			}
		}

		private IEnumerator IE_DoStripTease(float waitAtStart, bool top, bool bottom)
		{
			ai.Speak(AIMain.VoiceType.Yes);
			yield return (object)new WaitForSeconds(waitAtStart);
			isInit = true;
			List<int> available = Clothes.GetAvailables(cha);
			float partInbetween = 1f;
			if (top)
			{
				if (available.Contains(0) && Clothes.GetState(cha, 0) != 3)
				{
					overClip = Animations.Clip.StripTop_01;
					ReplaceAnim();
					yield return (object)new WaitForSeconds(1.25f);
					while (Clothes.GetState(cha, 0) != 3)
					{
						cha.SetClothesStateNext(0);
						yield return (object)new WaitForSeconds(partInbetween);
					}
				}
				if (available.Contains(2) && Clothes.GetState(cha, 2) != 3)
				{
					overClip = Animations.Clip.StripBra_01;
					ReplaceAnim();
					yield return (object)new WaitForSeconds(1.75f);
					while (Clothes.GetState(cha, 2) != 3)
					{
						cha.SetClothesStateNext(2);
						yield return (object)new WaitForSeconds(partInbetween);
					}
				}
			}
			if (bottom)
			{
				if (available.Contains(8) && Clothes.GetState(cha, 8) == 0)
				{
					overClip = Animations.Clip.PeepShower_01;
					ReplaceAnim(0.5f);
					yield return (object)new WaitForSeconds(2f);
					cha.SetClothesState(8, (byte)3, true);
					yield return (object)new WaitForSeconds(2f);
				}
				if (available.Contains(5) && Clothes.GetState(cha, 5) != 3)
				{
					overClip = Animations.Clip.StripBot_01;
					ReplaceAnim(0.5f);
					yield return (object)new WaitForSeconds(0.75f);
					while (Clothes.GetState(cha, 5) != 3)
					{
						cha.SetClothesStateNext(5);
						yield return (object)new WaitForSeconds(partInbetween);
					}
				}
				if (available.Contains(1) && Clothes.GetState(cha, 1) == 0)
				{
					if (overClip != Animations.Clip.StripBot_01)
					{
						overClip = Animations.Clip.StripBot_01;
						ReplaceAnim();
					}
					else
					{
						cha.syncPlay("A_Idle", 0, 0f);
					}
					yield return (object)new WaitForSeconds(1.5f);
					int rt = 0;
					while (Clothes.GetState(cha, 1) != 3)
					{
						cha.SetClothesStateNext(1);
						yield return (object)new WaitForSeconds(partInbetween);
						int num = rt + 1;
						rt = num;
						if (rt > 3)
						{
							break;
						}
					}
				}
				if (available.Contains(3) && Clothes.GetState(cha, 3) != 3)
				{
					if (overClip != Animations.Clip.PeepShower_01)
					{
						overClip = Animations.Clip.PeepShower_01;
						ReplaceAnim(0.35f);
					}
					else
					{
						cha.syncPlay("A_Idle", 0, 0.35f);
					}
					yield return (object)new WaitForSeconds(0.5f);
					while (Clothes.GetState(cha, 3) != 3)
					{
						cha.SetClothesStateNext(3);
						yield return (object)new WaitForSeconds(partInbetween);
					}
				}
			}
			yield return (object)new WaitForSeconds(partInbetween);
			yield return (object)new WaitForSeconds(1f);
			DestroyOverride(restore: true);
		}

		private void DestroyOverride(bool restore)
		{
			foreach (Item animItem in AnimItems)
			{
				Object.Destroy((Object)(object)animItem.objItem);
			}
			if (restore)
			{
				RuntimeAnimatorController val = CommonLib.LoadAsset<RuntimeAnimatorController>(hCtrl.CurAnim.animList.paramFemale.path.assetpath, hCtrl.CurAnim.animList.paramFemale.path.file, false, "", true);
				if ((Object)(object)val != (Object)null)
				{
					((ChaInfo)cha).animBody.runtimeAnimatorController = (RuntimeAnimatorController)(object)Animator.SetupAnimatorOverrideController(((ChaInfo)cha).animBody.runtimeAnimatorController, val);
				}
				AssetBundleManager.UnloadAssetBundle(hCtrl.CurAnim.animList.paramFemale.path.assetpath, true, (string)null, false);
				cha.syncPlay("Idle", 0, 0f);
			}
			Console.WriteLine("Do Destroy...");
			hCtrl.HFlag.isAibuSelect = aibuSelectAtStart;
			Object.Destroy((Object)(object)this);
		}

		private void ReplaceAnim(float nrTime = -1f)
		{
			//IL_00f6: Unknown result type (might be due to invalid IL or missing references)
			//IL_00fd: Expected O, but got Unknown
			//IL_00ff: Unknown result type (might be due to invalid IL or missing references)
