			RuntimeAnimatorController val3 = CommonLib.LoadAsset<RuntimeAnimatorController>(animInfo.animList.pathFemaleBase.assetpath, animInfo.animList.pathFemaleBase.file, false, "", true);
			AnimatorOverrideController val4 = new AnimatorOverrideController(((ChaInfo)cha).animBody.runtimeAnimatorController);
			AnimationClip[] animationClips = ((RuntimeAnimatorController)new AnimatorOverrideController(val3)).animationClips;
			for (int j = 0; j < animationClips.Length; j++)
			{
				if (j <= 50)
				{
					AnimationClip val5 = animationClips[j];
					val4[((Object)val5).name] = val2;
				}
			}
			((Object)val4).name = ((Object)val3).name;
			((ChaInfo)cha).animBody.runtimeAnimatorController = (RuntimeAnimatorController)(object)val4;
