			AssetBundleManager.UnloadAssetBundle(HCtrl.Get.CurAnim.animList.pathFemaleBase.assetpath, true, (string)null, false);
			AnimItems = GameAssets.CheckAndAddItemsToAnim(Animations.GetAssetNameFromClip(overClip), cha, 1);
