				((MonoBehaviour)this).StartCoroutine(IE_WaitEndAndReplay());
			}
		}

		private IEnumerator IE_WaitEndAndReplay()
		{
			yield return (object)new WaitForSeconds(Time.deltaTime);
			float num = ChaTools.StateDuration(cha) - Time.deltaTime;
			yield return (object)new WaitForSeconds(num);
			if (!Animations.perfectLoop.Contains(overClip))
			{
				yield return (object)new WaitForSeconds(2f);
			}
			Cam.DoFade(0.1f);
			cha.syncPlay("A_Idle", 0, 0f);
			foreach (Item animItem in AnimItems)
			{
				if ((Object)(object)animItem.animItem != (Object)null)
				{
					GameAssets.PlayAnimItemState(animItem, "A_Idle");
				}
			}
			((MonoBehaviour)this).StartCoroutine(IE_WaitEndAndReplay());
		}

		private IEnumerator IE_Restart()
		{
			yield return (object)new WaitForSeconds(Time.deltaTime);
			isInit = false;
			Start();
		}

