		public static MainActionOver CreateOrRefresh(ChaCore chaCore, Animations.Clip overClip, bool isStripTease = false)
		{
			MainActionOver mainActionOver = ((Component)chaCore).gameObject.GetComponent<MainActionOver>();
			if (!Object.op_Implicit((Object)(object)mainActionOver))
			{
				mainActionOver = ((Component)chaCore).gameObject.AddComponent<MainActionOver>();
				mainActionOver.isStriptease = isStripTease;
				mainActionOver.chaCore = chaCore;
				mainActionOver.overClip = overClip;
			}
			else if (mainActionOver.overClip != overClip)
			{
				mainActionOver.isStriptease = isStripTease;
				((MonoBehaviour)mainActionOver).StopAllCoroutines();
				mainActionOver.overClip = overClip;
				if (isStripTease)
				{
					((MonoBehaviour)mainActionOver).StartCoroutine(mainActionOver.IE_Restart());
				}
				if (!isStripTease)
				{
					mainActionOver.ReplaceAnim();
				}
			}
			return mainActionOver;
		}
	}
