			private IEnumerator IE_Rebind()
			{
				yield return (object)new WaitForSeconds(Time.deltaTime);
				AIGuest[] array = Object.FindObjectsOfType<AIGuest>();
				foreach (AIGuest aIGuest in array)
				{
					if (aIGuest.LastBinderKind != Kind.Undefined && aIGuest.LastBinderKind == Kind && !aIGuest.InAction)
					{
						(aIGuest.gAction = GuestAction.Create(aIGuest, GuestAction.Type.Bound)).SetBinder(this);
						break;
					}
				}
			}

			private void LateUpdate()
			{
				displayRnd.enabled = (forceDisplay || Input.GetKey((KeyCode)98)) && IsFree;
			}

			private void OnDestroy()
			{
				StoreUserPref();
			}

			private void StoreUserPref()
			{
				//IL_0081: Unknown result type (might be due to invalid IL or missing references)
				//IL_00a6: Unknown result type (might be due to invalid IL or missing references)
				//IL_00ab: Unknown result type (might be due to invalid IL or missing references)
				if (saveAndReadUserPref)
				{
					if (LastUserPos != null || posEditInCusMov)
					{
						string key = Core.dealer.HCtrl.CurAnim.plugName + "/" + Kind;
						string value = ((LastUserPos != null) ? LastUserPos.posName : "NotSet") + "/" + Helper.Vector3ToString(Hook.localPosition) + "/" + ((object)Hook.localRotation/*cast due to .constrained prefix*/).ToString();
						BinderUserPrefs[key] = value;
					}
					if (!Core.dealer.InH)
					{
						Core.dealer.WaitAndSaveBinderUserPrefs();
					}
				}
			}

			private void SearchUserPrefInDicAtStart()
			{
				//IL_0104: Unknown result type (might be due to invalid IL or missing references)
				//IL_0170: Unknown result type (might be due to invalid IL or missing references)
				if (!saveAndReadUserPref)
				{
					return;
				}
				string value = string.Empty;
				if (!BinderUserPrefs.TryGetValue(Core.dealer.HCtrl.CurAnim.plugName + "/" + Kind, out value))
				{
					return;
				}
				string[] array = value.Split(new string[1] { "/" }, StringSplitOptions.None);
				foreach (PoseDescr availablePose in availablePoses)
				{
					if (availablePose.posName == array[0])
					{
						LastUserPos = availablePose;
						break;
					}
				}
				List<string> list = PlugText.ParseStringList(array[1], new string[3] { "(", ")", "," });
				Hook.localPosition = new Vector3(float.Parse(list[0]), float.Parse(list[1]), float.Parse(list[2]));
				List<string> list2 = PlugText.ParseStringList(array[2], new string[3] { "(", ")", "," });
				Hook.localRotation = new Quaternion(float.Parse(list2[0]), float.Parse(list2[1]), float.Parse(list2[2]), float.Parse(list2[3]));
			}

