				List<PoseDescr> list = new List<PoseDescr>();
				foreach (PoseDescr item in allPosesForMainAnim)
				{
					if (item.forKind.Contains(buildInfo.kind))
					{
						list.Add(item);
					}
				}
				GameObject val = new GameObject();
				Binder binder = val.AddComponent<Binder>();
				binder.Kind = buildInfo.kind;
				binder.Root = val;
				binder.Root.transform.SetParent(ChaTools.FindInCha(Core.dealer.MainGirlCha, "cf_n_height"), false);
				binder.Root.transform.localPosition = buildInfo.offset;
