		public static void ReadAll()
		{
			posDescrList.Clear();
			excludedPos.Clear();
			bindersInfoDic.Clear();
			Type[] array = (Type[])Enum.GetValues(typeof(Type));
			foreach (Type type in array)
			{
				if (type != Type.Undefined)
				{
					ReadType(type);
				}
			}
			if (!debugDescr)
			{
				return;
			}
			Console.WriteLine("Excluded position : ");
			foreach (string excludedPo in excludedPos)
			{
				Console.WriteLine("\t" + excludedPo);
			}
			Console.WriteLine("");
		}

		private static void ReadType(Type typ)
		{
			//IL_002c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0032: Expected O, but got Unknown
			string text = "BepInEx/plugins/ksPlug/Required/BinderList/" + typ.ToString() + "/";
			if (!Directory.Exists(text))
			{
				return;
			}
			new List<string>();
			FolderAssist val = new FolderAssist();
			val.CreateFolderInfoEx(text, new string[1] { "*.txt" }, true);
			for (int i = 0; i < val.GetFileCount(); i++)
			{
				string content = PlugText.ReadFile(val.lstFile[i].FullPath);
				if (val.lstFile[i].FileName == "bindersOffsets")
				{
					ReadBindersInfo(content, typ);
					continue;
				}
				if (val.lstFile[i].FileName == "bindersExcluded")
				{
					ReadExcludedList(content);
					continue;
				}
				PoseDescr poseDescr = new PoseDescr();
				poseDescr.posName = val.lstFile[i].FileName;
				poseDescr.typ = typ;
				Family[] array = (Family[])Enum.GetValues(typeof(Family));
				for (int j = 0; j < array.Length; j++)
				{
					Family family = array[j];
					if (poseDescr.posName.Contains(family.ToString()))
					{
						poseDescr.family = family;
						break;
					}
				}
				ReadPosDescr(content, poseDescr);
				posDescrList.Add(poseDescr);
				DebugDescr(poseDescr);
			}
		}

		private static void ReadPosDescr(string content, PoseDescr descr)
		{
			//IL_0347: Unknown result type (might be due to invalid IL or missing references)
			//IL_034c: Unknown result type (might be due to invalid IL or missing references)
