				{
					descr.bundle = ParseInfoLine(text3) + ".unity3d";
				}
				if (text2.Contains("animFile"))
				{
					descr.animFile = ParseInfoLine(text3);
				}
				if (text2.Contains("animState"))
				{
					descr.animState = ParseInfoLine(text3);
				}
				if (text2.Contains("addSizePfx"))
				{
					descr.addSizePfx = bool.Parse(ParseInfoLine(text3));
				}
				if (text2.Contains("zOffset"))
				{
					descr.zOffset = float.Parse(ParseInfoLine(text3));
				}
				if (text2.Contains("neckPtn"))
				{
					descr.neckPtn = int.Parse(ParseInfoLine(text3));
				}
				if (text2.Contains("forKind"))
				{
					descr.forKind = ParseForKind(text3);
				}
				if (text2.Contains("{") || text2.Contains("[") || flag)
				{
					text += text3;
					if (text2.Contains("}") || text2.Contains("]"))
					{
						list.Add(text);
						text = string.Empty;
						flag = false;
					}
					else
					{
						flag = true;
					}
				}
			}
			string text4 = string.Empty;
			string text5 = string.Empty;
			foreach (string item in list)
			{
				if (item.Contains("isLeadAt"))
				{
					descr.isLeadAt = PlugText.ParseStringList(item, new string[3] { "{", "}", "," });
				}
				if (item.Contains("siruFlags"))
				{
					List<string> list2 = PlugText.ParseStringList(item, new string[3] { "[", "]", "," });
					for (int j = 0; j < descr.siruFlags.Length; j++)
					{
						descr.siruFlags[j] = bool.Parse(list2[j]);
					}
				}
				if (item.Contains("neckAndHeadOffsets"))
				{
					bool flag2 = false;
					foreach (Kind value in Enum.GetValues(typeof(Kind)))
					{
						if (item.Contains(value.ToString()))
						{
							flag2 = true;
							List<string> list3 = PlugText.ParseStringList(item, new string[3] { "{", "}", "," });
							float num = float.Parse(list3[0]);
							float num2 = float.Parse(list3[1]);
							float num3 = float.Parse(list3[2]);
							float num4 = float.Parse(list3[3]);
							float num5 = float.Parse(list3[4]);
							float num6 = float.Parse(list3[5]);
							descr.neckAndHeadOffsets[value] = (Vector3[])(object)new Vector3[2]
							{
