		private static string ParseInfoLine(string line)
		{
			line = Helper.GetStringAtIndex(line, "=", 2);
			if (line.Contains(";"))
			{
				line = Helper.GetStringAtIndex(line, ";", 1);
			}
			return line;
		}

		private static List<Kind> ParseForKind(string line)
		{
			string stringAtIndex = Helper.GetStringAtIndex(line, "=", 2);
			if (stringAtIndex.Contains(";"))
			{
				stringAtIndex = Helper.GetStringAtIndex(line, ";", 1);
			}
			string[] array = new string[1] { stringAtIndex };
			if (stringAtIndex.Contains("/"))
			{
				array = stringAtIndex.Split(new string[1] { "/" }, StringSplitOptions.None);
			}
			List<Kind> list = new List<Kind>();
			string[] array2 = array;
			foreach (string text in array2)
			{
				Kind[] array3 = (Kind[])Enum.GetValues(typeof(Kind));
				for (int j = 0; j < array3.Length; j++)
				{
					Kind item = array3[j];
					if (text.Contains(item.ToString()))
					{
						list.Add(item);
						break;
					}
				}
			}
			return list;
		}

		private static void ReadExcludedList(string content)
		{
			string[] array = content.Split(new string[1] { "\n" }, StringSplitOptions.None);
			bool flag = false;
			string text = string.Empty;
			List<string> list = new List<string>();
			string[] array2 = array;
			foreach (string text2 in array2)
			{
				string text3 = text2.Replace(" ", "");
				text3 = text3.Trim();
				if (text2.Contains("{") || flag)
				{
					text += text3;
					if (text2.Contains("}"))
					{
						list.Add(text);
						text = string.Empty;
						flag = false;
					}
					else
					{
						flag = true;
					}
				}
			}
			foreach (string item in list)
			{
				excludedPos.AddRange(PlugText.ParseStringList(item, new string[3] { "{", "}", "," }));
			}
		}

		private static void ReadBindersInfo(string content, Type typ)
		{
			string[] array = content.Split(new string[1] { "\n" }, StringSplitOptions.None);
			foreach (string text in array)
			{
				if (!text.Contains("//") && text.Contains("="))
				{
					string toSplit = text.Replace(" ", "").Trim();
					string text2 = Helper.GetStringAtIndex(toSplit, "=", 1);
					string stringAtIndex = Helper.GetStringAtIndex(toSplit, "=", 2);
					if (text2 == "Default")
					{
						text2 = typ.ToString() + text2;
					}
					bindersInfoDic[text2] = stringAtIndex;
				}
			}
		}

		public static void SetForGivenMainAnim(HAnims.AnimInfo mAnim)
		{
			if (getOnEachChange)
			{
				ReadAll();
			}
			if (!CheckIfMainAnimHasBinder(mAnim, ref familyAtCurMainAnim))
			{
				return;
			}
			foreach (BuildInfo item in GetBuildInfoAtThisAnim(mAnim))
			{
