		private static bool CheckIfMainAnimHasBinder(HAnims.AnimInfo mAnim, ref List<PoseDescr> availables)
		{
			availables.Clear();
			if (mAnim.ctx == HAnims.Context.Undefined || mAnim.ctx == HAnims.Context.Peep)
			{
				return false;
			}
			if (excludedPos.Contains(mAnim.plugName) || mAnim.plugName.Contains("3P") || mAnim.plugName.Contains("3S"))
			{
				return false;
			}
			foreach (PoseDescr posDescr in posDescrList)
			{
				if (mAnim.ctx.ToString() == posDescr.typ.ToString())
				{
					if (mAnim.plugName.Contains("Lay") && posDescr.family == Family.Lay)
					{
						availables.Add(posDescr);
					}
					if ((mAnim.plugName.Contains("Desk") || mAnim.plugName.Contains("Table")) && posDescr.family == Family.Desk)
					{
						availables.Add(posDescr);
					}
					if ((mAnim.plugName.Contains("Sit") || mAnim.plugName.Contains("Toilet")) && posDescr.family == Family.Sit)
					{
						availables.Add(posDescr);
					}
					if ((mAnim.plugName.Contains("Wall") || mAnim.plugName.Contains("Fence") || mAnim.plugName.Contains("Train")) && posDescr.family == Family.Wall)
					{
						availables.Add(posDescr);
					}
				}
			}
			return availables.Count != 0;
		}

		private static List<BuildInfo> GetBuildInfoAtThisAnim(HAnims.AnimInfo mAnim)
		{
			//IL_012b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0130: Unknown result type (might be due to invalid IL or missing references)
			List<BuildInfo> list = new List<BuildInfo>();
			string value = string.Empty;
			if (!bindersInfoDic.TryGetValue(mAnim.plugName, out value))
			{
				bindersInfoDic.TryGetValue(mAnim.ctx.ToString() + "Default", out value);
			}
			string[] array = new string[1] { value };
			if (value.Contains("/"))
			{
				array = value.Split(new string[1] { "/" }, StringSplitOptions.None);
			}
			string[] array2 = array;
			foreach (string toSplit in array2)
			{
				string stringAtIndex = Helper.GetStringAtIndex(toSplit, ":", 1);
				string stringAtIndex2 = Helper.GetStringAtIndex(toSplit, ":", 2);
				BuildInfo buildInfo = new BuildInfo();
				Kind[] array3 = (Kind[])Enum.GetValues(typeof(Type));
				for (int j = 0; j < array3.Length; j++)
				{
					Kind kind = array3[j];
					if (stringAtIndex == kind.ToString())
					{
						buildInfo.kind = kind;
						break;
					}
				}
				if (buildInfo.kind != Kind.Undefined)
				{
					buildInfo.offset = new Vector3(float.Parse(Helper.GetStringAtIndex(stringAtIndex2, ",", 1)), 0f, float.Parse(Helper.GetStringAtIndex(stringAtIndex2, ",", 2)));
					buildInfo.rotOffset = float.Parse(Helper.GetStringAtIndex(stringAtIndex2, ",", 3));
					list.Add(buildInfo);
				}
			}
			return list;
		}

