		public static Binder FindFreeBinder(Vector3 refPosition)
		{
			//IL_0078: Unknown result type (might be due to invalid IL or missing references)
			//IL_0080: Unknown result type (might be due to invalid IL or missing references)
			Binder result = null;
			List<Binder> list = new List<Binder>();
			foreach (Binder createdBinder in createdBinders)
			{
				if (createdBinder.IsFree)
				{
					list.Add(createdBinder);
				}
			}
			if (list.Count == 1)
			{
				result = list[0];
			}
			if (list.Count > 1)
			{
				float num = float.PositiveInfinity;
				foreach (Binder item in list)
				{
					float lenght = Helper.GetLenght(refPosition, ((Component)item).transform.position);
					if (lenght < num)
					{
						num = lenght;
						result = item;
					}
				}
			}
			return result;
		}

		public static bool HasFreeBinder()
		{
			foreach (Binder createdBinder in createdBinders)
			{
				if (createdBinder.IsFree)
				{
					return true;
				}
			}
			return false;
		}

		public static PoseDescr NextOrPrevInPoseDescrList(List<PoseDescr> posDescrs, PoseDescr refDescr, Enums.Way way)
		{
			switch (way)
			{
			case Enums.Way.Back:
			{
				for (int j = 0; j < posDescrs.Count; j++)
				{
					if (posDescrs[j].posName == refDescr.posName)
					{
						return posDescrs[(j == 0) ? (posDescrs.Count - 1) : (j - 1)];
					}
				}
				break;
			}
			case Enums.Way.Forward:
			{
				for (int i = 0; i < posDescrs.Count; i++)
				{
					if (posDescrs[i].posName == refDescr.posName)
					{
						return posDescrs[(i != posDescrs.Count - 1) ? (i + 1) : 0];
					}
				}
				break;
			}
			}
			return null;
		}

