		public static void SendHInfoInSave(ChaCore chaCore)
		{
			HInfo hInfo = chaCore.HInfo;
			Heroine hSaveData = chaCore.HSaveData;
			bool flag = hInfo.HCount.sonyuAnalOrg + hInfo.HCount.sonyuOrg + hInfo.HCount.aibuOrg != 0;
			bool num = hInfo.HCount.sonyuAnalInside + hInfo.HCount.sonyuAnalOutside + hInfo.HCount.sonyuCondomInside + hInfo.HCount.sonyuInside + hInfo.HCount.sonyuOutside + hInfo.HCount.houshiInside + hInfo.HCount.houshiOutside != 0;
			bool flag2 = hInfo.HCount.sonyuAnalSame + hInfo.HCount.sonyuSame != 0;
			int num2 = 0;
			if (flag)
			{
				num2 += 5;
			}
			if (num)
			{
				num2 += 5;
			}
			if (flag2)
			{
				num2 += 5;
			}
			if (num2 != 0)
			{
				num2 += 10;
				hSaveData.hExp = Mathf.Clamp(hSaveData.hExp + (float)num2, 0f, 100f);
				Player player = Game.Player;
				player.koikatsuPoint += num2;
			}
			hSaveData.AddHCount();
			hSaveData.isDayH = true;
			hSaveData.countHoushi += hInfo.HCount.houshiInside + hInfo.HCount.houshiOutside;
			float num3 = (float)(hInfo.HCount.houshiDrink + hInfo.HCount.houshiInside + hInfo.HCount.houshiOutside) * 20f;
			hSaveData.houshiExp = Mathf.Min(hSaveData.houshiExp + num3, 100f);
			hSaveData.isVirgin = ((!hSaveData.isAnalVirgin) ? hSaveData.isVirgin : (hInfo.HCount.isInsertKokan || hInfo.HCount.isInsertKokanVoiceCondition));
			hSaveData.isAnalVirgin = ((!hSaveData.isAnalVirgin) ? hSaveData.isAnalVirgin : (hInfo.HCount.isInsertAnal || hInfo.HCount.isInsertAnalVoiceCondition));
			float num4 = (float)hInfo.HCount.sonyuKokanPlay * 3f + (float)hInfo.HCount.sonyuOrg * 5f + (float)hInfo.HCount.sonyuSame * 10f + (float)hInfo.HCount.houshiOutside;
			hSaveData.countKokanH = Mathf.Min(hSaveData.countKokanH + num4, 100f);
			float num5 = (float)hInfo.HCount.sonyuAnalPlay * 3f + (float)hInfo.HCount.sonyuAnalOrg * 5f + (float)hInfo.HCount.sonyuAnalSame * 10f + (float)hInfo.HCount.houshiOutside;
			hSaveData.countAnalH = Mathf.Min(hSaveData.countKokanH + num5, 100f);
			hSaveData.countNamaInsert = Mathf.Min(hSaveData.countNamaInsert + hInfo.sessionNamaInsert, 1000);
			hSaveData.isKiss = hInfo.HCount.kiss != 0;
			for (int i = 0; i < hSaveData.hAreaExps.Length; i++)
			{
				hSaveData.hAreaExps[i] = Mathf.Clamp(hSaveData.hAreaExps[i] + hInfo.HCount.selectAreas[i] * 1f, 0f, 100f);
			}
			for (int j = 0; j < hSaveData.massageExps.Length; j++)
			{
				hSaveData.massageExps[j] = Mathf.Clamp(hSaveData.massageExps[j] + hInfo.HCount.selectMassages[j] * 1f, 0f, 100f);
			}
			JudgeH(chaCore);
			DebugInfos.InConsole(" Transmit H info to Heroine:" + ChaCore.Name(((CharaData)hSaveData).parameter));
		}

		public static void JudgeH(ChaCore chaCore)
		{
			HInfo hInfo = chaCore.HInfo;
			Heroine hSaveData = chaCore.HSaveData;
			float num = 0f;
			num += (float)((hInfo.HCount.aibuOrg + hInfo.HCount.sonyuSame + hInfo.HCount.sonyuAnalSame) * 2 + (hInfo.HCount.houshiInside + hInfo.HCount.houshiOutside + hInfo.HCount.sonyuOrg + hInfo.HCount.sonyuAnalOrg));
			num += (float)(hInfo.HCount.kiss * 5);
			if (hInfo.HCount.kiss > 10)
			{
				num *= 2f;
			}
			Statistic.AddFavor(hSaveData, num);
			float num2 = 0f;
			num2 += (float)((hInfo.HCount.aibuOrg + hInfo.HCount.sonyuSame + hInfo.HCount.sonyuAnalSame) * 2 + (hInfo.HCount.houshiInside + hInfo.HCount.houshiOutside + hInfo.HCount.sonyuOrg + hInfo.HCount.sonyuAnalOrg));
			num2 += (float)((hInfo.HCount.sonyuTare + hInfo.HCount.sonyuAnalTare) * 5);
			if (hInfo.HCount.sonyuOutside + hInfo.HCount.sonyuAnalOutside + hInfo.HCount.houshiOutside + hInfo.HCount.houshiDrink > 4)
			{
				num2 *= 2f;
			}
			Statistic.AddFavor(hSaveData, num2);
		}

		public static int MainBoyOrgasms()
		{
			HCtrl get = HCtrl.Get;
			if ((Object)(object)get == (Object)null)
			{
				return 0;
			}
			Count count = get.HFlag.count;
			int num = get.boyStartOrgasm + count.sonyuAnalInside + count.sonyuAnalOutside + count.sonyuCondomInside + count.sonyuInside + count.sonyuOutside + count.houshiInside + count.houshiOutside;
			ChaCore[] array = Object.FindObjectsOfType<ChaCore>();
			foreach (ChaCore chaCore in array)
			{
				if (chaCore.HInfo != null && (chaCore.Typ != ChaCore.Type.MainGirl || HManage.IsSecondMain()) && (chaCore.Typ != ChaCore.Type.SecondGirl || !HManage.IsSecondMain()))
				{
					Count hCount = chaCore.HInfo.HCount;
					num += hCount.sonyuAnalInside + hCount.sonyuAnalOutside + hCount.sonyuCondomInside + hCount.sonyuInside + hCount.sonyuOutside + hCount.houshiInside + hCount.houshiOutside;
				}
			}
			return num;
		}

