		public static int[] GirlAnyAndSameOrg(Count count, Statistic.Daily daily = null, bool debug = false)
		{
			int num = count.sonyuAnalOrg + count.sonyuOrg + count.aibuOrg;
			int num2 = count.sonyuAnalSame + count.sonyuSame;
			if (debug)
			{
				Console.WriteLine("GirlAnyAndSameOrg any " + num + " same " + num2);
			}
			if (Settings.AhegaoCount != Settings.AhegCount.EcchiSession && daily != null)
			{
				foreach (Count item in daily.ecchiHist)
				{
					num += item.sonyuAnalOrg + item.sonyuOrg + item.aibuOrg;
					num2 += item.sonyuAnalSame + item.sonyuSame;
					if (debug)
					{
						Console.WriteLine("GirlAnyAndSameOrg add history");
					}
				}
			}
			if (debug)
			{
				Console.WriteLine("GirlAnyAndSameOrg any at end " + num + " same at end " + num2);
			}
			return new int[2] { num, num2 };
		}

		public static void AddOrgasmToCount(Count count, OrgTyp typ)
		{
			if (count != null)
			{
				if (typ == OrgTyp.Aibu)
				{
					count.aibuOrg++;
				}
				if (typ == OrgTyp.SonyuSame)
				{
					count.sonyuSame++;
					count.sonyuOrg++;
				}
				if (typ == OrgTyp.SonyuSolo)
				{
					count.sonyuOrg++;
				}
			}
		}

		public static void AddExpToCount(Count count, float incr, ChaTools.Part part)
		{
			if (count == null)
			{
				return;
			}
			List<int> list = new List<int>();
			if (part == ChaTools.Part.BreastL || part == ChaTools.Part.BreastR)
			{
				list = new List<int> { 1, 5 };
			}
			if (part == ChaTools.Part.Chest)
			{
				list = new List<int> { 1 };
			}
			if (part == ChaTools.Part.Hip || part == ChaTools.Part.ButtL || part == ChaTools.Part.ButtR)
			{
				list = new List<int> { 4 };
			}
			if (part == ChaTools.Part.Kokan)
			{
				list = new List<int> { 2 };
			}
			if (part == ChaTools.Part.Anal)
			{
				list = new List<int> { 3 };
			}
			if (part == ChaTools.Part.Head)
			{
				list = new List<int> { 0 };
			}
			foreach (int item in list)
			{
				count.selectAreas[item] += incr;
				count.selectAreasGlobal[item] += incr;
			}
		}

