	public class DestroyAfterH : MonoBehaviour
	{
		private static string cmpName = "DestroyAfterH";

		private bool hasResultH;

		private bool inWaitDestruct;

		private void Start()
		{
			hasResultH = HCtrl.Get.HasResult;
		}

		private void LateUpdate()
		{
			if (Core.dealer.Ctx != Dealer.Context.H && !inWaitDestruct)
			{
				((MonoBehaviour)this).StartCoroutine(IE_WaitAndDestroy());
			}
		}

		private IEnumerator IE_WaitAndDestroy()
		{
			inWaitDestruct = true;
			if (hasResultH)
			{
				yield return (object)new WaitUntil((Func<bool>)(() => !Core.dealer.InWaitForResultGauge || (Core.dealer.ecchiEndByTresspass && Core.dealer.Ctx == Dealer.Context.H)));
				DebugInfos.InConsole((Core.dealer.ecchiEndByTresspass ? " Ended by Tresspss, destroying " : " Waited gauge and destroyed ") + ((Object)((Component)this).gameObject).name, cmpName);
				Object.Destroy((Object)(object)((Component)this).gameObject);
			}
			else
			{
				yield return (object)new WaitUntil((Func<bool>)(() => (Object)(object)Core.dealer.HCtrl == (Object)null));
				DebugInfos.InConsole(" Destroyed immediately " + ((Object)((Component)this).gameObject).name + " in no result ecchi scene", cmpName);
				Object.Destroy((Object)(object)((Component)this).gameObject);
