		public void AdaptSpeed(bool isWLoop, bool isSLoop)
		{
			//IL_0114: Unknown result type (might be due to invalid IL or missing references)
			//IL_011a: Unknown result type (might be due to invalid IL or missing references)
			bool flag = InfoMain.distance < 1.25f;
			Helper.TimerToZero(ref changeSpeedTimer);
			bool flag2 = changeSpeedTimer == 0f;
			if (changeSpeedTimer == 0f)
			{
				changeSpeedTimer = Random.Range(3.5f, 6f);
			}
			if (isWLoop || isSLoop)
			{
				if (flag && InfoMain.inMotion)
				{
					if (Mathf.Abs(speed - InfoMain.hFlagSpeed) > 0.01f)
					{
						speed = Mathf.MoveTowards(speed, InfoMain.hFlagSpeed, Time.deltaTime * Mathf.Lerp(1f, 0.5f, Mathf.Min(InfoMain.distance, 1f)));
					}
				}
				else
				{
					if (flag2)
					{
						Vector2 val = default(Vector2);
						((Vector2)(ref val))..ctor(Mathf.Lerp(1f, 2.25f, excitation * 0.01f), Mathf.Lerp(1.75f, 3f, excitation * 0.01f));
						targetSpeed = Random.Range(val.x, val.y);
					}
					speed = Mathf.MoveTowards(speed, targetSpeed, Time.deltaTime * 2f);
				}
			}
			else
			{
				speed = 1f;
			}
			((ChaInfo)Ai.Cha).animBody.speed = speed;
			if ((Object)(object)Partner1 != (Object)null)
			{
				((ChaInfo)Partner1.Ai.Cha).animBody.speed = speed;
