		public bool IsInOrgasmLoop()
		{
			if (Typ == Type.Tease)
			{
				Tease tease = this as Tease;
				if (tease.CurState != Tease.State.Orgasm_Start)
				{
					return tease.CurState == Tease.State.Orgasm_Loop;
				}
				return true;
			}
			if (Typ == Type.Mast)
			{
				return (this as Masturbate).CurState == Masturbate.State.Orgasm;
			}
			if (Typ == Type.Lesbian)
			{
				return (this as Lesbian).CurState == Lesbian.State.Orgasm;
			}
			if (Typ == Type.Serv)
			{
				Service service = this as Service;
				return new List<Service.State>
				{
					Service.State.IN_Start,
					Service.State.IN_Loop,
					Service.State.M_OUT_Start,
					Service.State.M_OUT_Loop
				}.Contains(service.CurState);
			}
			if (Typ == Type.Piston)
			{
				Piston piston = this as Piston;
				return new List<Piston.State>
				{
					Piston.State.SS_IN_Start,
					Piston.State.SS_IN_Loop,
					Piston.State.M_OUT_Start,
					Piston.State.A_SS_IN_Start,
					Piston.State.A_SS_IN_Loop,
					Piston.State.A_M_OUT_Start
				}.Contains(piston.CurState);
			}
			if (Typ == Type.Piston3P)
			{
				Piston3P piston3P = this as Piston3P;
				return new List<Piston3P.State>
				{
					Piston3P.State.SS_IN_Start,
					Piston3P.State.SS_IN_Start,
					Piston3P.State.M_OUT_Start,
					Piston3P.State.M_OUT_Loop
				}.Contains(piston3P.CurState);
			}
			return false;
		}

