		public static GuestAction Create(AIGuest ai, Type typ, AIGuest partner1 = null, AIGuest partner2 = null)
		{
			GuestAction guestAction = null;
			switch (typ)
			{
			case Type.Strip:
				guestAction = ((Component)ai.Cha).gameObject.AddComponent<Strip>();
				break;
			case Type.Mast:
				guestAction = ((Component)ai.Cha).gameObject.AddComponent<Masturbate>();
				break;
			case Type.Tease:
				guestAction = ((Component)ai.Cha).gameObject.AddComponent<Tease>();
				break;
			case Type.Lesbian:
				guestAction = ((Component)ai.Cha).gameObject.AddComponent<Lesbian>();
				if ((Object)(object)partner1 != (Object)null)
				{
					guestAction.Partner1 = CreateOnPartner(partner1, guestAction, typ);
				}
				break;
			case Type.Serv:
				guestAction = ((Component)ai.Cha).gameObject.AddComponent<Service>();
				if ((Object)(object)partner1 != (Object)null)
				{
					guestAction.Partner1 = CreateOnPartner(partner1, guestAction, typ);
				}
				break;
			case Type.Piston:
				guestAction = ((Component)ai.Cha).gameObject.AddComponent<Piston>();
				if ((Object)(object)partner1 != (Object)null)
				{
					guestAction.Partner1 = CreateOnPartner(partner1, guestAction, typ);
				}
				break;
			case Type.Piston3P:
				guestAction = ((Component)ai.Cha).gameObject.AddComponent<Piston3P>();
				if ((Object)(object)partner1 != (Object)null && (Object)(object)partner2 != (Object)null)
				{
					guestAction.Partner1 = CreateOnPartner(partner1, guestAction, typ);
					guestAction.Partner2 = CreateOnPartner(partner2, guestAction, typ);
				}
				break;
			case Type.Bound:
				guestAction = ((Component)ai.Cha).gameObject.AddComponent<Bound>();
				break;
			case Type.SpMove:
				guestAction = ((Component)ai.Cha).gameObject.AddComponent<SpecialMove>();
				break;
			}
			guestAction.Ai = ai;
			guestAction.Typ = typ;
			return guestAction;
		}

		public static GuestAction CreateOnPartner(AIGuest partner, GuestAction leader, Type typ)
		{
			if ((Object)(object)partner.gAction != (Object)null)
			{
				Object.Destroy((Object)(object)partner.gAction);
			}
			GuestAction result = (partner.gAction = Create(partner, typ));
			partner.gAction.Leader = leader;
			return result;
		}
	}
