		public static List<AnimInfo> OrganizeList(List<AnimInfo> list, string keyword, List<string> subKeys)
		{
			List<AnimInfo> list2 = new List<AnimInfo>();
			if (subKeys.Count != 0)
			{
				foreach (string subKey in subKeys)
				{
					foreach (AnimInfo item in list)
					{
						if (item.plugName.Contains(subKey) && item.plugName.Contains(keyword) && !list2.Contains(item))
						{
							list2.Add(item);
						}
					}
				}
			}
			foreach (AnimInfo item2 in list)
			{
				if (item2.plugName.Contains(keyword) && !list2.Contains(item2))
				{
					list2.Add(item2);
				}
			}
			return list2;
		}

