				return State.DrinkOrVomit;
			}
			return State.Undefined;
		}

		public static bool IsOrgasm()
		{
			return IsOrgasm(HCtrl.Get.CurState);
		}

		public static bool IsOrgasm(State state)
		{
			if (new List<State>
			{
				State.OrgBoth,
				State.OrgM,
				State.OrgF
			}.Contains(state))
			{
				return state != State.OrgOUT;
			}
			return false;
		}

		public static bool IsIdleOut(State state)
		{
			if (new List<State>
			{
				State.Idle,
				State.OrgOUT
			}.Contains(state))
			{
				return state != State.OrgOUT;
			}
			return false;
		}

		public static List<AnimInfo> CreateAnimInfoList(bool addExtra = true)
		{
			//IL_00d9: Unknown result type (might be due to invalid IL or missing references)
			List<AnimInfo> list = new List<AnimInfo>();
			List<AnimationListInfo>[] gameAnimationList = GetGameAnimationList();
			for (int i = 0; i < gameAnimationList.Length; i++)
			{
				for (int j = 0; j < gameAnimationList[i].Count; j++)
				{
					AnimInfo anim = new AnimInfo();
					anim.animList = gameAnimationList[i][j];
					anim.jpName = anim.animList.nameAnimation;
					string lastString = Helper.GetLastString(anim.animList.paramFemale.path.assetpath, "/", rmvExt: true);
					if (anim.animList.paramFemale.path.file.Contains("khr_"))
					{
						lastString = Helper.GetLastString(anim.animList.pathFemaleBase.assetpath, "/", rmvExt: true);
					}
					anim.asset = lastString + "/" + anim.animList.paramFemale.path.file;
					anim.ctx = GetContext(anim.animList.mode);
					anim.hasAnal = anim.animList.paramFemale.isAnal;
					string value = string.Empty;
					if (Names.AnimPlugNames().TryGetValue(anim.asset, out value))
					{
						anim.plugName = value;
					}
					GameAnimIksList.Feed(ref anim);
					ChaSiru.FlagsForVanillaPosition().TryGetValue(anim.plugName, out anim.siruFlags);
					list.Add(anim);
					if (anim.plugName == "Unknown")
					{
						DebugInfos.AnimInfo(anim);
					}
				}
			}
			if (HVanillaAnimation.Count == 0)
			{
				foreach (AnimInfo item in list)
				{
					HVanillaAnimation.Add(item);
				}
			}
			if (addExtra)
			{
				HExtraAnims.AdditionalAnimInfoList(list);
				List<string> list2 = new List<string>();
				foreach (AnimInfo item2 in list)
				{
					if (item2.isExtraAnim && item2.plugName.Contains("ksp"))
					{
						list2.Add(item2.plugName);
					}
				}
				foreach (AnimInfo item3 in list)
				{
					if (!item3.isExtraAnim && list2.Contains(item3.plugName + "_ksp"))
					{
						item3.hasPlugVersion = true;
					}
				}
			}
			return list;
		}

		public static AnimInfo FindInfoFromPlugName(string plugName, List<AnimInfo> lstAnimInfo)
		{
			foreach (AnimInfo item in lstAnimInfo)
			{
				if (item.plugName == plugName)
				{
					return item;
				}
			}
			return null;
		}

		public static AnimInfo FindInfoFromAssetName(string assetName, List<AnimInfo> lstAnimInfo)
		{
			foreach (AnimInfo item in lstAnimInfo)
			{
				if (item.asset.Contains(assetName))
				{
					return item;
				}
			}
			return null;
		}

		public static AnimInfo NextOrPrevInList(List<AnimInfo> anims, AnimInfo refAnim, Enums.Way way)
		{
			switch (way)
			{
			case Enums.Way.Back:
			{
				for (int j = 0; j < anims.Count; j++)
				{
					if (anims[j].plugName == refAnim.plugName)
					{
						return anims[(j == 0) ? (anims.Count - 1) : (j - 1)];
					}
				}
				break;
			}
			case Enums.Way.Forward:
			{
				for (int i = 0; i < anims.Count; i++)
				{
					if (anims[i].plugName == refAnim.plugName)
					{
						return anims[(i != anims.Count - 1) ? (i + 1) : 0];
					}
				}
				break;
			}
			}
			return null;
		}

