		public static CustomAnimDef BuildCustomDefFromString(string toParse)
		{
			CustomAnimDef customAnimDef = new CustomAnimDef();
			customAnimDef.IkF["Default"] = new List<string>
			{
				string.Empty,
				string.Empty,
				string.Empty,
				string.Empty
			};
			customAnimDef.IkM["Default"] = new List<string>
			{
				string.Empty,
				string.Empty,
				string.Empty,
				string.Empty
			};
			customAnimDef.IkF2["Default"] = new List<string>
			{
				string.Empty,
				string.Empty,
				string.Empty,
				string.Empty
			};
			customAnimDef.gwF["Default"] = new List<bool> { true, true, true, true };
			customAnimDef.gwM["Default"] = new List<bool> { true, true, true, true };
			customAnimDef.gwF2["Default"] = new List<bool> { true, true, true, true };
			string[] array = toParse.Split(new string[1] { "\n" }, StringSplitOptions.None);
			foreach (string text in array)
			{
				if (text.Contains("//"))
				{
					continue;
				}
				string text2 = (text.Contains(";") ? Helper.GetStringAtIndex(text, ";", 1) : text);
				if (text2.Contains("{"))
				{
					string stringAtIndex = Helper.GetStringAtIndex(text2, "{", 1);
					customAnimDef.assetName = Helper.GetStringAtIndex(stringAtIndex, "/", 1);
					customAnimDef.fem1Ctrl = Helper.GetStringAtIndex(stringAtIndex, "/", 2);
				}
				if (text2.Contains("baseAnim"))
				{
					customAnimDef.baseAnim = Helper.GetStringAtIndex(text2, "=", 2);
				}
				if (text2.Contains("plugName"))
				{
					customAnimDef.plugName = Helper.GetStringAtIndex(text2, "=", 2);
				}
				if (text2.Contains("mal1Ctrl"))
				{
					customAnimDef.mal1Ctrl = Helper.GetStringAtIndex(text2, "=", 2);
				}
				if (text2.Contains("fem2Ctrl"))
				{
					customAnimDef.fem2Ctrl = Helper.GetStringAtIndex(text2, "=", 2);
				}
				if (text2.Contains("cusDickTarg"))
				{
					customAnimDef.cusDickTarg = Helper.GetStringAtIndex(text2, "=", 2);
				}
				if (text2.Contains("motionIkCalcState"))
				{
					customAnimDef.motionIkCalcState = Helper.GetStringAtIndex(text2, "=", 2);
				}
				if (text2.Contains("neckFileG1"))
				{
					customAnimDef.neckFileG1 = Helper.GetStringAtIndex(text2, "=", 2);
				}
				if (text2.Contains("disableNeckG1"))
				{
					customAnimDef.disableNeckG1 = bool.Parse(Helper.GetStringAtIndex(text2, "=", 2));
				}
				if (text2.Contains("disableNeckG2"))
				{
