		public static void ReadIK(string info, ref Dictionary<string, List<string>> dic)
		{
			string stringAtIndex = Helper.GetStringAtIndex(info, "=", 1);
			string stringAtIndex2 = Helper.GetStringAtIndex(info, "=", 2);
			string stringAtIndex3 = Helper.GetStringAtIndex(stringAtIndex, ":", 2);
			List<string> list = new List<string>();
			string[] array = stringAtIndex2.Split(new string[1] { "," }, StringSplitOptions.None);
			foreach (string text in array)
			{
				if (text.Contains("Empty"))
				{
					list.Add(string.Empty);
				}
				else
				{
					list.Add(text);
				}
			}
			if (stringAtIndex3.Contains("/"))
			{
				array = stringAtIndex3.Split(new string[1] { "/" }, StringSplitOptions.None);
				foreach (string key in array)
				{
					dic[key] = list;
				}
			}
			else
			{
				dic[stringAtIndex3] = list;
			}
		}

