			for (int i = 0; i < val.GetFileCount(); i++)
			{
				string[] array = PlugText.ReadFile(val.lstFile[i].FullPath).Split(new string[1] { "\n" }, StringSplitOptions.None);
				string text = string.Empty;
				string[] array2 = array;
				foreach (string text2 in array2)
				{
