		public static List<HAnims.AnimInfo> AdditionalAnimInfoList(List<HAnims.AnimInfo> lstAnimInfo)
		{
			if (!Directory.Exists(addAnimListPath))
			{
				return lstAnimInfo;
			}
			if (Core.debug)
			{
				foreach (string item in ReadCustomAnimAsList())
				{
					CustomAnimDef customAnimDef = BuildCustomDefFromString(item);
					if (IsValidAnimDef(customAnimDef))
					{
						lstAnimInfo.Add(BuildAnimInfoFromCusDef(customAnimDef, HAnims.FindInfoFromPlugName(customAnimDef.baseAnim, HAnims.HVanillaAnimation)));
					}
				}
			}
			else
			{
				foreach (CustomAnimDef animCusDef in AnimCusDefs)
				{
					if (IsValidAnimDef(animCusDef))
					{
						lstAnimInfo.Add(BuildAnimInfoFromCusDef(animCusDef, HAnims.FindInfoFromPlugName(animCusDef.baseAnim, HAnims.HVanillaAnimation)));
					}
				}
			}
			return lstAnimInfo;
		}

