		public static void CopyToAnimInfo_Category(string src, ref HAnims.AnimInfo target)
		{
			//IL_001a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0020: Expected O, but got Unknown
			//IL_00f6: Unknown result type (might be due to invalid IL or missing references)
			//IL_00fd: Expected O, but got Unknown
			HAnims.AnimInfo animInfo = null;
			try
			{
				int category = int.Parse(src);
				target.animList.lstCategory = new List<Category>();
				Category val = new Category();
				val.category = category;
				target.animList.lstCategory.Add(val);
				DebugInfos.InConsole();
				DebugInfos.InConsole(" Parse " + target.plugName + " as an integer", "HExtraAnims.CopyToAnimInfo_Category");
				DebugInfos.InConsole();
				return;
			}
			catch
			{
			}
			foreach (HAnims.AnimInfo item in HAnims.HVanillaAnimation)
			{
				if (item.plugName == src)
				{
					animInfo = item;
					break;
				}
			}
			if (animInfo == null)
			{
				return;
			}
			target.animList.lstCategory = new List<Category>();
			foreach (Category item2 in animInfo.animList.lstCategory)
			{
				Category val2 = new Category();
				val2.category = item2.category;
				val2.fileMove = item2.fileMove;
				target.animList.lstCategory.Add(val2);
			}
		}
	}
