					if (bodyPart == ChaTools.Part.Kokan)
					{
						val = (AiInOrgasm ? new Vector3(0f, num2 * 0.00075f, num2 * -0.0005f) : new Vector3(0f, num2 * 0.002f, num2 * -0.0015f));
