					}
				}
			}
			Transform transform = item.transform;
			transform.localPosition += val;
			Transform transform2 = item.transform;
			transform2.localEulerAngles += val2;
			_aiInOrgasm = AiInOrgasm;
			_inMotion = InMotion;
		}

		private void LateUpdate()
		{
			if (curMotion == Motion.Manual && !Keys.LmbHold)
			{
				curMotion = Motion.Static;
			}
		}

