		public void ForceStatic()
		{
			SetMotion(Motion.Static);
		}

		public void SetMotion(Motion targetMotion, bool spread = false)
		{
			if (targetMotion == Motion.Auto)
			{
				if (curMotion == Motion.Auto)
				{
					targetMotion = Motion.Static;
				}
				foreach (HItem item in new List<HItem> { ai.hItemOnAnus, ai.hItemOnPussy })
				{
					if ((Object)(object)item != (Object)null && (Object)(object)item != (Object)(object)this && item.curMotion != targetMotion)
					{
						item.curMotion = targetMotion;
					}
				}
				if (spread)
				{
					List<HItem> list = Object.FindObjectsOfType<HItem>().ToList();
					if ((Object)(object)ai.hItemOnAnus != (Object)null && list.Contains(ai.hItemOnAnus))
					{
						list.Remove(ai.hItemOnAnus);
					}
					if ((Object)(object)ai.hItemOnPussy != (Object)null && list.Contains(ai.hItemOnPussy))
					{
						list.Remove(ai.hItemOnPussy);
					}
					foreach (HItem item2 in list)
					{
						if (item2.curMotion != targetMotion)
						{
							item2.curMotion = targetMotion;
						}
					}
				}
			}
			if (targetMotion == Motion.Manual)
			{
				((MonoBehaviour)this).StartCoroutine(IE_FreezeCamInManual());
			}
			curMotion = targetMotion;
		}

