		public static void EndH()
		{
			HCtrl get = HCtrl.Get;
			if (get.HasResult)
			{
				Core.dealer.WaitResultGauge();
			}
			bool flag = false;
			foreach (ChaCore item in Core.dealer.ChaCoresInH)
			{
				if (item.Typ == ChaCore.Type.MainGirl && (Object)(object)((CharaData)get.HFlag.lstHeroine[0]).chaCtrl != (Object)(object)item.Cha)
				{
