					Count.CopyHCountToHCount(item.HInfo.HCount, HCtrl.Get.HFlag.count);
					Count.HInfoToHFlag(item.HInfo, 0);
					ChaCore.SwapCharacter(item, ((Component)((CharaData)get.HFlag.lstHeroine[0]).chaCtrl).GetComponent<ChaCore>());
					DebugInfos.InConsoleCompact("Restaured MainGirl as " + ((ChaFile)((ChaInfo)((CharaData)get.HFlag.lstHeroine[0]).chaCtrl).chaFile).parameter.fullname, "HManage");
					if (HCtrl.Get.IsFirstH && !HCtrl.Get.IsDeflowered)
					{
						DebugInfos.InConsoleCompact(((ChaFile)((ChaInfo)((CharaData)get.HFlag.lstHeroine[0]).chaCtrl).chaFile).parameter.fullname + " still virgin at H end, adding 1 sonyuSame", "HManage");
						Count count = get.HFlag.count;
						count.sonyuSame++;
						Count count2 = get.HFlag.count;
						count2.sonyuInside++;
					}
					flag = true;
				}
				if (item.Typ == ChaCore.Type.SecondGirl && (Object)(object)((CharaData)get.HFlag.lstHeroine[1]).chaCtrl != (Object)(object)item.Cha)
				{
					ChaCore.SwapCharacter(item, ((Component)((CharaData)get.HFlag.lstHeroine[1]).chaCtrl).GetComponent<ChaCore>());
					DebugInfos.InConsoleCompact("Restaured SecondGirl as " + ((ChaFile)((ChaInfo)((CharaData)get.HFlag.lstHeroine[1]).chaCtrl).chaFile).parameter.fullname, "HManage");
				}
			}
			if (!flag)
			{
				Count.CopyHCountToHCount(HCtrl.Get.HFlag.count, HCtrl.Get.MainGirl.HInfo.HCount);
			}
			if (Core.dealer.InStory)
			{
				ChaCore[] array;
				if (SingletonInitializer<ActionScene>.instance.isPenetration && !get.IsTresspassH)
				{
					DebugInfos.InConsole("EndH BY Tresspass !!!!!!!!!!!!!!", "HManage.EndH");
					List<Heroine> list = new List<Heroine>();
					array = Object.FindObjectsOfType<ChaCore>();
					foreach (ChaCore chaCore in array)
					{
						if (chaCore.Sex == ChaCore.Gender.Girl && chaCore.Cha.GetActiveTop() && chaCore.HSaveData != null && !list.Contains(chaCore.HSaveData))
						{
							list.Add(chaCore.HSaveData);
						}
					}
					Core.dealer.HeroinesBeforeTrspass = list;
					Core.dealer.ecchiEndByTresspass = true;
					get.GetCurrentTimeAndStart(ref Core.dealer.tresspassTimes[0], ref Core.dealer.tresspassTimes[1]);
				}
				if (Object.op_Implicit((Object)(object)get) && get.IsInit)
				{
					get.RestoreVoiceRateAtStart();
				}
				if (!Core.dealer.ecchiEndByTresspass)
				{
					((MonoBehaviour)Core.dealer).StartCoroutine(Core.dealer.IE_WaitReturnOnMapAfterH());
				}
				DebugInfos.InConsole("EndH in Story, searching other girls", "HManage.EndH");
				HItem.DetachAll();
				GuestAction.RemoveAll();
				array = Object.FindObjectsOfType<ChaCore>();
				foreach (ChaCore chaCore2 in array)
				{
					if ((Object)(object)chaCore2.Cha == (Object)null || Object.op_Implicit((Object)(object)chaCore2.Npc) || Object.op_Implicit((Object)(object)chaCore2.FixNpc) || chaCore2.HSaveData == null)
					{
						continue;
					}
					if (Statistic.GetDaily(chaCore2.HSaveData) != null)
					{
						Statistic.GetDaily(chaCore2.HSaveData).ecchiHist.Add(chaCore2.HInfo.HCount);
						DebugInfos.InConsoleCompact("Add " + ChaCore.Name(((ChaInfo)chaCore2.Cha).fileParam) + " session HCount to Daily EcchiHistory", "HManage");
					}
					if (chaCore2.Typ != ChaCore.Type.MainGirl && chaCore2.Typ != ChaCore.Type.SecondGirl)
					{
						if (Object.op_Implicit((Object)(object)((Component)chaCore2.Cha).GetComponent<AIGuest>()))
						{
							((Component)chaCore2.Cha).GetComponent<AIGuest>().ResultPosition();
							DebugInfos.InConsoleCompact("Found AI Guest " + ChaCore.Name(((ChaInfo)chaCore2.Cha).fileParam), "HManage");
						}
						Count.SendHInfoInSave(chaCore2);
					}
				}
				GManage.DoChaInEcchiSnapshots();
			}
			DebugInfos.InConsole("Finished to run", "HManage.EndH");
		}

