				if ((Object)(object)val != (Object)null)
				{
					val.localPosition = Vector3.zero;
				}
				if ((Object)(object)touchBodyReact != (Object)null)
				{
					Object.Destroy((Object)(object)touchBodyReact);
				}
			}
			if ((Object)(object)base.Binder != (Object)null)
			{
				base.Binder.SetFree();
			}
		}

		public override void SetSiruOnCha()
		{
			ChaTools.AddSiruOnCha(base.Ai.Cha, curPos.siruFlags);
			if (Core.dealer.InStory && base.Ai.ChaCore.HSaveData != null)
			{
				Statistic.SetDailyEvent(base.Ai.ChaCore.HSaveData, new List<Statistic.DailyEvent> { Statistic.DailyEvent.cumOn });
			}
		}

		public override void DetachParticularities()
		{
		}

		public override void NextPosition(bool changeTyp, bool backward)
		{
			if (base.Binder.availablePoses.Count >= 2 && changePosDelay == 0f)
			{
				Binders.PoseDescr next = Binders.NextOrPrevInPoseDescrList(base.Binder.availablePoses, curPos, (!backward) ? Enums.Way.Forward : Enums.Way.Back);
				ChangeAnimation(next);
				changePosDelay = 0.5f;
			}
		}

		private void ChangeAnimation(Binders.PoseDescr next)
		{
			curPos = next;
			base.Ai.SetAnimTypAndAsset(Animations.Type.Bound, curPos.bundle, curPos.animFile, (curPos.addSizePfx ? (base.SizePrefix + "_") : "") + curPos.animState);
			PlayAndSetParticularities();
			base.Binder.SetUserPos(curPos);
			_hasItem = false;
		}

		public override void SetGuestActionMenuPose(MenuChara.PoseInfo posInfo)
		{
			ChangeAnimation(posInfo.posDescr);
		}

		public override List<Binders.PoseDescr> GetAvailablePoseDescr()
		{
			return base.Binder.availablePoses;
		}

		private void PlayAndSetParticularities()
		{
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			ChaTools.FindInCha(base.Ai.Cha, "cf_n_height").localPosition = new Vector3(0f, 0f, curPos.zOffset);
			base.Ai.Cha.ChangeLookNeckPtn(curPos.neckPtn, 1f);
			SetMotionIkSubstOffset();
			SearchSizeOffsets();
		}

		public override void AfterSwap()
		{
			SetMotionIkSubstOffset();
			SearchSizeOffsets(afterSwap: true);
		}

		private void SetMotionIkSubstOffset()
		{
			if (curPos.mIksOffset.Count != 0 && base.Ai.ChaCore.BoneCtrl.MotionIkOffsetAreEmpty)
			{
				base.Ai.ChaCore.BoneCtrl.SubscribeToAdvOffset(curPos.mIksOffset);
			}
		}

		public override void SearchSizeOffsets(bool afterSwap = false)
		{
			if (base.Ai.Cha.GetShapeBodyValue(0) < 0f)
			{
				SizeOffsets.SearchAndSubscribe(base.Ai.Cha, SizeOffsets.ChaTyp.G1, CurPos.animFile, CurPos.animState);
				if (afterSwap)
				{
					_hasItem = false;
				}
			}
		}

		private IEnumerator IE_Finish()
		{
			inFinish = true;
			((ChaInfo)base.Ai.Cha).animBody.speed = 1f;
			base.Ai.EvFlags.actionEvent = true;
			base.Ai.ReachOrgasm(Count.OrgTyp.Aibu);
			CurState = State.Orgasm_Loop;
			yield return (object)new WaitForSeconds(2.75f);
			base.Ai.EvFlags.actionEvent = true;
			CurState = State.Orgasm_A;
			StopItems();
			yield return (object)new WaitForSeconds(2f);
			excitation = 5f;
			inFinish = false;
			CurState = State.Idle;
		}

		public override IEnumerator IE_Init()
		{
			yield return (object)new WaitUntil((Func<bool>)(() => (Object)(object)base.Binder != (Object)null));
			curPos = base.Binder.availablePoses[0];
			foreach (Binders.PoseDescr availablePose in base.Binder.availablePoses)
			{
				if (availablePose.isLeadAt.Contains(HCtrl.Get.CurAnim.plugName))
				{
					curPos = availablePose;
					break;
				}
			}
			if (base.Binder.LastUserPos != null)
			{
				curPos = base.Binder.LastUserPos;
			}
			base.Ai.SetAnimTypAndAsset(Animations.Type.Bound, curPos.bundle, curPos.animFile, (curPos.addSizePfx ? (base.SizePrefix + "_") : "") + curPos.animState);
			base.Binder.AttachGuestAction(this);
			base.Ai.Mover.SetMoverPosition(((Component)base.Binder.Hook).transform.position, ((Component)base.Binder.Hook).transform.rotation);
			CurState = State.Idle;
			PlayAndSetParticularities();
			base.Binder.SetUserPos(curPos);
			SetDontCollideOn();
			isInit = true;
		}

		public static Bound ActionAs(GuestAction guestAction)
		{
			return guestAction as Bound;
		}
	}
	public class Piston3P : GuestAction
	{
		public enum State
		{
			Idle,
			Insert,
			InsertIdle,
			WLoop,
			SLoop,
			OLoop,
			SS_IN_Start,
			SS_IN_Loop,
			SS_IN_A,
			IN_A,
			M_OUT_Start,
			M_OUT_Loop,
			OUT_A,
			Pull,
			Drop
		}

		private static List<HAnims.AnimInfo> available3P = new List<HAnims.AnimInfo>();

		private bool inInsertion;

		private float matchStateTimer = 0.1f;

		public bool IsPenisInserted => !NotInsertStates.Contains(CurState);

		public List<State> NotInsertStates => new List<State>
		{
			State.Idle,
			State.M_OUT_Loop,
			State.OUT_A,
			State.Drop
		};

		public bool IsWLoop => new List<State> { State.WLoop }.Contains(CurState);

		public bool IsSLoop => new List<State> { State.SLoop }.Contains(CurState);

		public bool IsOLoop => new List<State> { State.OLoop }.Contains(CurState);

		public bool IsInsideOrg => new List<State>
		{
			State.SS_IN_Start,
			State.SS_IN_Loop
		}.Contains(CurState);

		public bool IsOutOrg => new List<State>
		{
			State.M_OUT_Start,
			State.M_OUT_Loop
		}.Contains(CurState);

		public bool IsAfterCum => new List<State>
		{
			State.SS_IN_A,
			State.IN_A,
			State.OUT_A,
			State.Drop
		}.Contains(CurState);

		public State CurState { get; private set; }

		public HAnims.AnimInfo Anim { get; private set; }

		public override void Update()
		{
			if (!isInit || !base.IsLeader || inFinish || inDetach || !IsPenisInserted || inInsertion)
			{
				return;
			}
			if (!(InfoMain.distance < 0.9f) || !InfoMain.inMotion || !(InfoMain.highestGaugeVal > 70f) || !(excitation > 97f))
			{
				IncreaseEx();
			}
			State state = CurState;
			if (InfoMain.distance < 0.9f && InfoMain.inMotion && Anim.ctx == InfoMain.ctx)
			{
				if ((InfoMain.inWLoop && !IsWLoop) || (InfoMain.inSLoop && !IsSLoop))
				{
					Helper.TimerToZero(ref matchStateTimer);
					if (matchStateTimer == 0f)
					{
						matchStateTimer = Random.Range(0.05f, 0.65f);
						state = (InfoMain.inWLoop ? State.WLoop : (InfoMain.inSLoop ? State.SLoop : CurState));
					}
				}
			}
			else
			{
				state = ((!(excitation > 45f)) ? ((!IsWLoop) ? State.WLoop : CurState) : ((!IsSLoop) ? State.SLoop : CurState));
			}
			bool flag = CurState != state;
			if (flag)
			{
				PlayAndSetParticularities(state);
				if (Random.Range(0f, 100f) > 50f)
				{
					GuestAction.SetActionEvent(base.Ai);
				}
				if (Random.Range(0f, 100f) > 50f)
				{
					GuestAction.SetActionEvent(base.Partner1.Ai);
				}
				if (Random.Range(0f, 100f) > 50f)
				{
					GuestAction.SetActionEvent(base.Partner2.Ai);
				}
			}
			if (excitation == 100f && !inFinish)
			{
				((MonoBehaviour)this).StartCoroutine(IE_Finish());
				return;
			}
			if (!flag && !inFinish && ActionEventAlarmTimer())
			{
				float num = Random.Range(0f, 100f);
				if (num > 45f)
				{
					if (num < 55f)
					{
						GuestAction.SetActionEvent(base.Ai);
					}
					else
					{
						GuestAction.SetActionEvent(base.Partner1.Ai);
						GuestAction.SetActionEvent(base.Partner2.Ai);
					}
				}
			}
			if (IsWLoop || IsSLoop)
			{
				CalcFluctuation();
				((ChaInfo)base.Ai.Cha).animBody.SetFloat("motion", base.Fluctuation);
				((ChaInfo)base.Partner1.Ai.Cha).animBody.SetFloat("motion", base.Fluctuation);
				((ChaInfo)base.Partner2.Ai.Cha).animBody.SetFloat("motion", base.Fluctuation);
			}
		}

		public override void LateUpdate()
		{
			//IL_0057: Unknown result type (might be due to invalid IL or missing references)
			//IL_006c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0096: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ab: Unknown result type (might be due to invalid IL or missing references)
			if (isInit && base.IsLeader && !inDetach)
			{
				QueryInfoFromMain();
				AdaptSpeed(IsWLoop, IsSLoop);
				base.Partner1.Ai.Mover.SetMoverPosition(((Component)base.Ai.Cha).transform.position, ((Component)base.Ai.Cha).transform.rotation);
				base.Partner2.Ai.Mover.SetMoverPosition(((Component)base.Ai.Cha).transform.position, ((Component)base.Ai.Cha).transform.rotation);
				if (changePosDelay != 0f)
				{
					Helper.TimerToZero(ref changePosDelay);
				}
			}
		}

		public override void OnDestroy()
		{
			base.Ai.SetAnimTypAndClip(base.startAnimTyp, base.startAnimClip);
			((ChaInfo)base.Ai.Cha).animBody.speed = 1f;
			base.Ai.Cha.ChangeLookNeckPtn(1, 1f);
		}

		public override void Init()
		{
			if (!base.IsLeader)
			{
				isInit = true;
			}
			else
			{
				((MonoBehaviour)this).StartCoroutine(IE_Init());
			}
		}

		public override IEnumerator IE_Init()
		{
			yield return (object)new WaitUntil((Func<bool>)(() => base.Partner1.isInit));
			Anim = Helper.RandomInList(available3P);
			Quaternion rotation = Quaternion.LookRotation(Vector3.Cross(Helper.GetDir(((Component)base.Partner1.Ai.Cha).transform.position, ((Component)Core.dealer.MainGirlCha).transform.position), Vector3.up), Vector3.up);
			base.Partner1.Ai.Mover.SetMoverPosition(((Component)base.Partner1.Ai.Cha).transform.position, rotation);
			base.Ai.Mover.SetMoverPosition(((Component)base.Partner1.Ai.Cha).transform.position, rotation);
			base.Partner2.Ai.Mover.SetMoverPosition(((Component)base.Partner1.Ai.Cha).transform.position, rotation);
			base.Ai.SetAnimTypAndAsset(Animations.Type.Piston, BundleFromAnimInfo(Anim, isMale: true), AssetFromAnimInfo(Anim, isMale: true), "Idle");
			base.Partner1.Ai.SetAnimTypAndAsset(Animations.Type.Piston, BundleFromAnimInfo(Anim), AssetFromAnimInfo(Anim), "Idle");
			base.Partner2.Ai.SetAnimTypAndAsset(Animations.Type.Piston, BundleFromAnimInfo(Anim, isMale: false, isGirl2: true), AssetFromAnimInfo(Anim, isMale: false, isGirl2: true), "Idle");
			PlayAndSetParticularities(State.Idle);
			AdaptClothesToAnim();
			((MonoBehaviour)this).StartCoroutine(IE_Insert());
			isInit = true;
		}

		private void PlayAndSetParticularities(State state)
		{
			CurState = state;
			ActionAs(base.Partner1).CurState = state;
			ActionAs(base.Partner2).CurState = state;
			PlayAnimState(state.ToString(), addSizePrefix: false);
			base.Partner1.PlayAnimState(state.ToString(), addSizePrefix: false);
			base.Partner2.PlayAnimState(state.ToString(), addSizePrefix: false);
			((ChaInfo)base.Ai.Cha).animBody.SetFloat("height", Anim.plugName.Contains("sw") ? base.Partner2.Ai.Cha.GetShapeBodyValue(0) : base.Partner1.Ai.Cha.GetShapeBodyValue(0));
			((ChaInfo)base.Partner1.Ai.Cha).animBody.SetFloat("height", base.Partner1.Ai.Cha.GetShapeBodyValue(0));
			((ChaInfo)base.Partner2.Ai.Cha).animBody.SetFloat("height", base.Partner2.Ai.Cha.GetShapeBodyValue(0));
			AdaptNeck();
		}

		public override void NextPosition(bool changeTyp, bool backward)
		{
			if (!base.IsLeader)
			{
				base.Leader.NextPosition(changeTyp, backward);
			}
			else if (changePosDelay == 0f)
			{
				HAnims.AnimInfo animInfo = null;
				animInfo = HAnims.NextOrPrevInList(available3P, Anim, (!backward) ? Enums.Way.Forward : Enums.Way.Back);
				ChangeAnimation(animInfo);
				changePosDelay = 0.5f;
			}
		}

		private void ChangeAnimation(HAnims.AnimInfo next)
		{
			base.Ai.Cha.ChangeLookNeckPtn(1, 1f);
			base.Partner1.Ai.Cha.ChangeLookNeckPtn(1, 1f);
			base.Partner2.Ai.Cha.ChangeLookNeckPtn(1, 1f);
			Anim = next;
			base.Ai.SetAnimTypAndAsset(Animations.Type.Piston, BundleFromAnimInfo(Anim, isMale: true), AssetFromAnimInfo(Anim, isMale: true), "Idle");
			base.Partner1.Ai.SetAnimTypAndAsset(Animations.Type.Piston, BundleFromAnimInfo(Anim), AssetFromAnimInfo(Anim), "Idle");
			base.Partner2.Ai.SetAnimTypAndAsset(Animations.Type.Piston, BundleFromAnimInfo(Anim, isMale: false, isGirl2: true), AssetFromAnimInfo(Anim, isMale: false, isGirl2: true), "Idle");
			PlayAndSetParticularities(CurState);
			AdaptClothesToAnim();
		}

		public override void SetGuestActionMenuPose(MenuChara.PoseInfo posInfo)
		{
			if (!base.IsLeader)
			{
				base.Leader.SetGuestActionMenuPose(posInfo);
			}
			else
			{
				ChangeAnimation(posInfo.animInf);
			}
		}

		public override List<HAnims.AnimInfo> GetAvailableAnimInfos()
		{
			if (!base.IsLeader)
			{
				return base.Leader.GetAvailableAnimInfos();
			}
			return available3P;
		}

		private void AdaptNeck()
		{
			base.Ai.Cha.ChangeLookNeckPtn(3, 1f);
			base.Partner1.Ai.Cha.ChangeLookNeckPtn(3, 1f);
			base.Partner2.Ai.Cha.ChangeLookNeckPtn(3, 1f);
		}

		private void AdaptClothesToAnim()
		{
			Clothes.RevealCrotch(base.Ai.Cha);
			Clothes.RevealCrotch(base.Partner1.Ai.Cha);
			Clothes.RevealCrotch(base.Partner2.Ai.Cha);
		}

		private IEnumerator IE_Insert()
		{
			inInsertion = true;
			yield return (object)new WaitForSeconds(Random.Range(1.25f, 2f));
			PlayAndSetParticularities(State.Insert);
			yield return (object)new WaitForSeconds(Time.deltaTime);
			yield return (object)new WaitForSeconds(ChaTools.StateDuration(base.Ai.Cha));
			PlayAndSetParticularities(State.InsertIdle);
			yield return (object)new WaitForSeconds(Time.deltaTime);
			yield return (object)new WaitForSeconds(ChaTools.StateDuration(base.Ai.Cha));
			PlayAndSetParticularities(State.WLoop);
			yield return (object)new WaitForSeconds(Time.deltaTime);
			inInsertion = false;
		}

		private IEnumerator IE_Finish()
		{
			inFinish = true;
			GuestAction.SetActionEvent(base.Ai, 0f, byPassKiss: true);
			bool inside = Random.Range(0f, 100f) > 40f;
			PlayAndSetParticularities(State.OLoop);
			yield return (object)new WaitForSeconds(Random.Range(4.5f, 6f));
			base.Ai.ReachOrgasm(Count.OrgTyp.SonyuSame, !inside);
			base.Partner1.Ai.ReachOrgasm(Count.OrgTyp.SonyuSame);
			base.Partner2.Ai.ReachOrgasm(Count.OrgTyp.SonyuSame);
			PlayAndSetParticularities(inside ? State.SS_IN_Start : State.M_OUT_Start);
			GuestAction.SetActionEvent(base.Ai, 0f, byPassKiss: true);
			GuestAction.SetActionEvent(base.Partner1.Ai, 0f, byPassKiss: true);
			GuestAction.SetActionEvent(base.Partner2.Ai, 0f, byPassKiss: true);
			yield return (object)new WaitForSeconds(Time.deltaTime);
			yield return (object)new WaitForSeconds(ChaTools.StateDuration(base.Ai.Cha));
			excitation = 5f;
			PlayAndSetParticularities(inside ? State.SS_IN_Loop : State.M_OUT_Loop);
			yield return (object)new WaitForSeconds(Random.Range(3.5f, 5f));
			PlayAndSetParticularities(inside ? State.SS_IN_A : State.OUT_A);
			GuestAction.SetActionEvent(base.Partner1.Ai, 0.5f);
			GuestAction.SetActionEvent(base.Partner2.Ai, 0.5f);
			yield return (object)new WaitForSeconds(Random.Range(inside ? 1.5f : 3.5f, inside ? 2.5f : 5f));
			if (inside)
			{
				PlayAndSetParticularities(State.Pull);
				yield return (object)new WaitForSeconds(Time.deltaTime);
				yield return (object)new WaitForSeconds(ChaTools.StateDuration(base.Ai.Cha));
				PlayAndSetParticularities(State.Drop);
				yield return (object)new WaitForSeconds(Random.Range(3f, 4.25f));
			}
			yield return (object)new WaitForEndOfFrame();
			inFinish = false;
			if (!startByUser)
			{
				DetachPartners();
			}
			else
			{
				((MonoBehaviour)this).StartCoroutine(IE_Insert());
			}
		}

		private static string BundleFromAnimInfo(HAnims.AnimInfo info, bool isMale = false, bool isGirl2 = false)
		{
			if (isMale)
			{
				return info.animList.pathMaleBase.assetpath + ":" + info.animList.paramMale.path.assetpath;
			}
			if (isGirl2)
			{
				return info.animList.pathFemaleBase1.assetpath + ":" + info.animList.paramFemale1.path.assetpath;
			}
			return info.animList.pathFemaleBase.assetpath + ":" + info.animList.paramFemale.path.assetpath;
		}

		private static string AssetFromAnimInfo(HAnims.AnimInfo info, bool isMale = false, bool isGirl2 = false)
		{
			if (isMale)
			{
				return info.animList.pathMaleBase.file + "/" + info.animList.paramMale.path.file;
			}
			if (isGirl2)
			{
				return info.animList.pathFemaleBase1.file + "/" + info.animList.paramFemale1.path.file;
			}
			return info.animList.pathFemaleBase.file + "/" + info.animList.paramFemale.path.file;
		}

		public static void ListAvailableAnims()
		{
			available3P.Clear();
			foreach (HAnims.AnimInfo hAnimInfo in Core.dealer.HCtrl.HAnimInfos)
			{
				if (!string.IsNullOrEmpty(hAnimInfo.animList.paramFemale1.path.file) && hAnimInfo.ctx == HAnims.Context.Piston && hAnimInfo.plugName.Contains("Lay"))
				{
					available3P.Add(hAnimInfo);
				}
			}
		}

		public static Piston3P ActionAs(GuestAction guestAction)
		{
			return guestAction as Piston3P;
		}
	}
	public class Lesbian : GuestAction
	{
		public enum State
		{
			WLoop,
			MLoop,
			SLoop,
			OLoop,
			Orgasm,
			Orgasm_A,
			Orgasm_B
		}

		public bool inLicking;

		public State CurState { get; private set; }

		public Animations.Clip ClipLayShell => Animations.Clip.LesbianA_01;

		public Animations.Clip ClipLayCunni => Animations.Clip.LesbianA_02;

		public Animations.Clip ClipStandFinger => Animations.Clip.LesbianA_03;

		public Animations.Clip ClipStandCunni => Animations.Clip.LesbianA_04;

		public Animations.Clip ClipSitCunni => Animations.Clip.LesbianA_10;

