				((ChaInfo)base.Partner1.Ai.Cha).animBody.SetFloat("motion", base.Fluctuation);
			}
			if (excitation == 100f && !inFinish)
			{
				((MonoBehaviour)this).StartCoroutine(IE_Finish());
