			//IL_0084: Unknown result type (might be due to invalid IL or missing references)
			if (!isInit)
			{
				return;
			}
			if (!base.IsLeader && CurState != ActionAs(base.Leader).CurState)
			{
				CurState = ActionAs(base.Leader).CurState;
			}
			if (base.IsLeader && !inDetach)
			{
				base.Partner1.Ai.Mover.SetMoverPosition(((Component)base.Ai.Cha).transform.position, ((Component)base.Ai.Cha).transform.rotation);
				ForceTongueVisibility();
				if (changePosDelay != 0f)
				{
					Helper.TimerToZero(ref changePosDelay);
				}
			}
		}

		public override void OnDestroy()
