			((ChaInfo)base.Ai.Cha).animBody.speed = 1f;
			base.Ai.Cha.ChangeLookNeckPtn(1, 1f);
		}

		public override void NextPosition(bool changeTyp, bool backward)
		{
			if (inFinish || changePosDelay != 0f)
			{
				return;
			}
			if (!base.IsLeader)
			{
				base.Leader.NextPosition(changeTyp, backward);
			}
			else if (bindFamilyAtStart != Binders.Family.Sit)
			{
				if (base.Ai.AnimClip == ClipLayCunni || base.Ai.AnimClip == ClipStandCunni)
				{
					ActionAs(base.Partner1).inLicking = false;
					base.Partner1.Ai.Cha.ChangeLookNeckPtn(1, 1f);
				}
				Animations.Clip animClip = base.Ai.AnimClip;
				List<Animations.Clip> list = new List<Animations.Clip> { ClipLayShell, ClipLayCunni, ClipStandFinger, ClipStandCunni };
				animClip = (backward ? Helper.PrevInList(list, base.Ai.AnimClip) : Helper.NextInList(list, base.Ai.AnimClip));
				ChangeAnimation(animClip);
				changePosDelay = 0.5f;
			}
		}

		private void ChangeAnimation(Animations.Clip next)
		{
			base.Ai.ChaCore.CtrlIK.AssumeDefaultTargets();
			base.Partner1.Ai.ChaCore.CtrlIK.AssumeDefaultTargets();
			base.Ai.ApplyAnimClip(next);
			base.Partner1.Ai.ApplyAnimClip(GetBclip(next));
			PlayAndSetParticularities(CurState);
			AdaptClothesToAnim();
		}

		public override void SetGuestActionMenuPose(MenuChara.PoseInfo posInfo)
		{
			if (!base.IsLeader)
			{
				base.Leader.SetGuestActionMenuPose(posInfo);
			}
			else
			{
				ChangeAnimation(posInfo.clip);
			}
		}

		public override List<Animations.Clip> GetAvailableAnimClips()
		{
			if (!base.IsLeader)
			{
				return base.Leader.GetAvailableAnimClips();
			}
			if (bindFamilyAtStart != Binders.Family.Sit)
			{
				return new List<Animations.Clip> { ClipLayShell, ClipLayCunni, ClipStandFinger, ClipStandCunni };
			}
			return new List<Animations.Clip> { ClipSitCunni };
		}

		public override void DetachParticularities()
		{
			if (base.IsLeader)
			{
				List<int> layerIds = new List<int>();
				ChaTools.ResetDynAndLayerWeight(base.Ai.Cha, layerIds);
				if (base.Ai.AnimClip == ClipStandFinger)
				{
					layerIds = new List<int> { 73, 74 };
				}
				ChaTools.ResetDynAndLayerWeight(base.Partner1.Ai.Cha, layerIds);
			}
		}

		public override void Init()
		{
			if (!base.IsLeader)
			{
				isInit = true;
			}
			else
			{
				((MonoBehaviour)this).StartCoroutine(IE_Init());
			}
		}

		public override IEnumerator IE_Init()
		{
			yield return (object)new WaitUntil((Func<bool>)(() => base.Partner1.isInit));
			Animations.Clip clip = Helper.RandomInList(new List<Animations.Clip>
			{
				Animations.Clip.LesbianA_03,
				Animations.Clip.LesbianA_04
			});
			if (base.Partner1.startAnimTyp == Animations.Type.Crouch)
			{
				clip = Helper.RandomInList(new List<Animations.Clip>
				{
					Animations.Clip.LesbianA_01,
					Animations.Clip.LesbianA_02
				});
			}
			if (bindFamilyAtStart == Binders.Family.Sit)
			{
				clip = ClipSitCunni;
			}
			if (bindFamilyAtStart != Binders.Family.Undefined)
			{
				SetDontCollideOn();
			}
			if (bindFamilyAtStart == Binders.Family.Sit)
			{
				SetActionMatchMainHeightOn();
			}
			Quaternion rotation = Quaternion.LookRotation(Vector3.Cross(Helper.GetDir(((Component)base.Partner1.Ai.Cha).transform.position, ((Component)Core.dealer.MainGirlCha).transform.position), Vector3.up), Vector3.up);
			if (bindFamilyAtStart != Binders.Family.Undefined && bindRotAtStart != Quaternion.identity)
			{
				rotation = bindRotAtStart;
			}
			base.Partner1.Ai.Mover.SetMoverPosition(((Component)base.Partner1.Ai.Cha).transform.position, rotation);
			base.Ai.Mover.SetMoverPosition(((Component)base.Partner1.Ai.Cha).transform.position, rotation);
			base.Ai.SetAnimTypAndClip(Animations.Type.LesbianA, clip);
			base.Partner1.Ai.SetAnimTypAndClip(Animations.Type.LesbianB, GetBclip(clip));
			CurState = State.WLoop;
			PlayAndSetParticularities(CurState);
			AdaptClothesToAnim();
			isInit = true;
		}

		private void PlayAndSetParticularities(State state)
		{
			PlayAnimState(state.ToString(), addSizePrefix: false);
			base.Partner1.PlayAnimState(state.ToString(), addSizePrefix: false);
			((ChaInfo)base.Ai.Cha).animBody.SetFloat("height1", base.Partner1.Ai.Cha.GetShapeBodyValue(0));
			((ChaInfo)base.Ai.Cha).animBody.SetFloat("Breast1", base.Partner1.Ai.Cha.GetShapeBodyValue(4));
			((ChaInfo)base.Partner1.Ai.Cha).animBody.SetFloat("height1", base.Ai.Cha.GetShapeBodyValue(0));
			((ChaInfo)base.Partner1.Ai.Cha).animBody.SetFloat("Breast1", base.Ai.Cha.GetShapeBodyValue(4));
			AdaptNeckAndExpr();
			AdaptDynAndLayer();
			AdaptIksToState();
		}

		private void AdaptDynAndLayer()
		{
			if (base.Ai.AnimClip == ClipStandFinger)
			{
				ChaTools.ResetDynAndLayerWeight(base.Partner1.Ai.Cha, new List<int> { 73, 74 });
				if (CurState == State.WLoop)
				{
					base.Partner1.Ai.Cha.playDynamicBoneBust((DynamicBoneKind)0, false);
					base.Partner1.Ai.Cha.setLayerWeight(1f, 73);
				}
				if (CurState == State.MLoop || CurState == State.SLoop || CurState == State.OLoop)
				{
					base.Partner1.Ai.Cha.playDynamicBoneBust((DynamicBoneKind)0, false);
					base.Partner1.Ai.Cha.playDynamicBoneBust((DynamicBoneKind)1, false);
					base.Partner1.Ai.Cha.setLayerWeight(1f, 73);
					base.Partner1.Ai.Cha.setLayerWeight(1f, 74);
				}
			}
		}

		private void ForceTongueVisibility()
		{
			if (base.Ai.AnimClip == ClipLayCunni || base.Ai.AnimClip == ClipStandCunni)
			{
				base.Partner1.Ai.Cha.ChangeTongueState((byte)1);
				ActionAs(base.Partner1).inLicking = CurState != State.Orgasm && CurState != State.Orgasm_A && CurState != State.Orgasm_B;
			}
		}

		private void AdaptNeckAndExpr()
		{
			overExpr = FaceExpr.Type.Neutral;
			base.Partner1.overExpr = FaceExpr.Type.Neutral;
			if (base.Ai.AnimClip == ClipLayCunni || base.Ai.AnimClip == ClipStandCunni || base.Ai.AnimClip == ClipSitCunni)
			{
				if (CurState != State.Orgasm && CurState != State.Orgasm_A)
				{
					_ = CurState;
					_ = 6;
				}
				base.Partner1.Ai.Cha.ChangeLookNeckPtn(3, 1f);
			}
			if (base.Ai.AnimClip == ClipSitCunni && (CurState == State.WLoop || CurState == State.MLoop || CurState == State.SLoop || CurState == State.OLoop))
			{
				base.Partner1.overExpr = FaceExpr.Type.Lick;
			}
		}

		private void AdaptIksToState()
		{
			if (base.Ai.AnimClip == ClipStandFinger)
			{
				if (CurState == State.WLoop)
				{
					base.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.L_Hand, ChaTools.FindInCha(base.Partner1.Ai.Cha, "k_f_spine02_00"));
					base.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.R_Hand, ChaTools.FindInCha(base.Partner1.Ai.Cha, "k_f_mune00L_00"));
				}
				if (CurState == State.MLoop || CurState == State.SLoop || CurState == State.OLoop)
				{
					base.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.L_Hand, ChaTools.FindInCha(base.Partner1.Ai.Cha, "k_f_mune00R_00"));
					base.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.R_Hand, ChaTools.FindInCha(base.Partner1.Ai.Cha, "k_f_mune00L_00"));
				}
				if (CurState == State.Orgasm || CurState == State.Orgasm_A || CurState == State.Orgasm_B)
				{
					base.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.L_Hand, ChaTools.FindInCha(base.Ai.Cha, "cf_pv_hand_L"));
					base.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.R_Hand, ChaTools.FindInCha(base.Ai.Cha, "k_f_spine03_00"));
				}
				if (CurState == State.WLoop || CurState == State.SLoop)
				{
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.L_Hand, ChaTools.FindInCha(base.Ai.Cha, "k_f_kosi01_00"));
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.R_Hand, ChaTools.FindInCha(base.Ai.Cha, "k_f_kosi02_00"));
				}
				if (CurState == State.MLoop || CurState == State.OLoop || CurState == State.Orgasm || CurState == State.Orgasm_A || CurState == State.Orgasm_B)
				{
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.L_Hand, ChaTools.FindInCha(base.Partner1.Ai.Cha, "cf_pv_hand_L"));
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.R_Hand, ChaTools.FindInCha(base.Ai.Cha, "k_f_kosi02_00"));
				}
			}
			if (base.Ai.AnimClip == ClipLayCunni)
			{
				if (CurState == State.Orgasm_A || CurState == State.Orgasm_B)
				{
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.L_Hand, ChaTools.FindInCha(base.Partner1.Ai.Cha, "cf_pv_hand_L"));
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.R_Hand, ChaTools.FindInCha(base.Partner1.Ai.Cha, "cf_pv_hand_R"));
				}
				else
				{
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.L_Hand, ChaTools.FindInCha(base.Ai.Cha, "k_f_legupR_00"));
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.R_Hand, ChaTools.FindInCha(base.Ai.Cha, "k_f_legupL_00"));
				}
			}
			if (base.Ai.AnimClip == ClipStandCunni)
			{
				if (CurState == State.OLoop || CurState == State.Orgasm || CurState == State.Orgasm_A)
				{
					base.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.L_Hand, ChaTools.FindInCha(base.Partner1.Ai.Cha, "k_f_head_01"));
					base.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.R_Hand, ChaTools.FindInCha(base.Partner1.Ai.Cha, "k_f_head_00"));
				}
				if (CurState == State.SLoop)
				{
					base.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.L_Hand, ChaTools.FindInCha(base.Ai.Cha, "k_f_kosi01_00"));
					base.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.R_Hand, ChaTools.FindInCha(base.Partner1.Ai.Cha, "k_f_head_00"));
				}
				if (CurState == State.MLoop)
				{
					base.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.L_Hand, ChaTools.FindInCha(base.Ai.Cha, "cf_pv_hand_L"));
					base.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.R_Hand, ChaTools.FindInCha(base.Partner1.Ai.Cha, "k_f_head_00"));
				}
				if (CurState == State.WLoop)
				{
					base.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.L_Hand, ChaTools.FindInCha(base.Ai.Cha, "cf_pv_hand_L"));
					base.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.R_Hand, ChaTools.FindInCha(base.Ai.Cha, "cf_pv_hand_R"));
				}
				if (CurState == State.WLoop || CurState == State.Orgasm_B)
				{
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.L_Hand, ChaTools.FindInCha(base.Ai.Cha, "k_f_legupR_00"));
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.R_Hand, ChaTools.FindInCha(base.Ai.Cha, "k_f_legupL_00"));
				}
				if (CurState == State.MLoop || CurState == State.SLoop || CurState == State.OLoop || CurState == State.Orgasm)
				{
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.L_Hand, ChaTools.FindInCha(base.Partner1.Ai.Cha, "k_f_kosi02_00"));
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.R_Hand, ChaTools.FindInCha(base.Ai.Cha, "k_f_legupL_00"));
				}
				if (CurState == State.Orgasm_A)
				{
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.L_Hand, ChaTools.FindInCha(base.Partner1.Ai.Cha, "k_f_legupL_00"));
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.R_Hand, ChaTools.FindInCha(base.Ai.Cha, "k_f_legupL_00"));
