		}

		private void AdaptClothesToAnim()
		{
			if (base.Ai.AnimClip == ClipLayShell || base.Ai.AnimClip == ClipStandCunni)
			{
				Clothes.RevealCrotch(base.Ai.Cha);
				Clothes.RevealCrotch(base.Partner1.Ai.Cha);
			}
			if (base.Ai.AnimClip == ClipLayCunni || base.Ai.AnimClip == ClipSitCunni)
			{
				Clothes.RevealCrotch(base.Ai.Cha);
			}
			if (base.Ai.AnimClip == ClipStandFinger)
			{
				Clothes.RevealCrotch(base.Ai.Cha);
				Clothes.RevealBreast(base.Partner1.Ai.Cha);
			}
		}

		private IEnumerator IE_Finish()
		{
			inFinish = true;
			GuestAction.SetActionEvent(base.Ai, 0f, byPassKiss: true);
			CurState = State.OLoop;
			PlayAndSetParticularities(CurState);
			yield return (object)new WaitForSeconds(Random.Range(3.5f, 6f));
			GuestAction.SetActionEvent(base.Ai, 0f, byPassKiss: true);
			GuestAction.SetActionEvent(base.Partner1.Ai, 0f, byPassKiss: true);
			base.Ai.ReachOrgasm(Count.OrgTyp.Aibu);
			base.Partner1.Ai.ReachOrgasm(Count.OrgTyp.Aibu);
			CurState = State.Orgasm;
			PlayAndSetParticularities(CurState);
			yield return (object)new WaitForSeconds(Time.deltaTime);
			yield return (object)new WaitForSeconds(ChaTools.StateDuration(base.Ai.Cha));
			excitation = 5f;
			CurState = State.Orgasm_A;
			PlayAndSetParticularities(CurState);
			yield return (object)new WaitForSeconds(Random.Range(2.5f, 3.5f));
			GuestAction.SetActionEvent(base.Ai, 0.5f);
			CurState = State.Orgasm_B;
			PlayAndSetParticularities(CurState);
			yield return (object)new WaitForSeconds(2.5f);
			yield return (object)new WaitForEndOfFrame();
			inFinish = false;
			if (!startByUser)
			{
				DetachPartners();
				yield break;
			}
			CurState = State.WLoop;
			PlayAndSetParticularities(CurState);
		}

		private static Animations.Clip GetBclip(Animations.Clip A_clip)
		{
			string lastString = Helper.GetLastString(A_clip.ToString(), "_");
			foreach (Animations.Clip item in Animations.GetClipListFromTyp(Animations.Type.LesbianB))
			{
				if (item.ToString().Contains(lastString))
				{
					return item;
				}
			}
			return Animations.Clip.LesbianB_01;
		}

		public static Lesbian ActionAs(GuestAction guestAction)
		{
			return guestAction as Lesbian;
		}
	}
	public class Masturbate : GuestAction
	{
		public enum State
		{
			WLoop,
			MLoop,
			SLoop,
			OLoop,
			Orgasm,
			Orgasm_A,
			Orgasm_B
		}

		private bool waitForFinishEnd;

		private bool addHeightToState;

		private List<Animations.Clip> availables = new List<Animations.Clip>();

		private List<int> layerInUse = new List<int>();

		public State CurState { get; private set; }

		public override void Update()
		{
			if (!isInit || waitForFinishEnd)
			{
				return;
			}
			IncreaseEx();
			State curState = CurState;
			curState = ((!(excitation < 25f)) ? ((excitation < 50f) ? State.MLoop : State.SLoop) : State.WLoop);
			bool flag = false;
			if (CurState != curState)
			{
				CurState = curState;
				PlayAndSetParticularities();
				((ChaInfo)base.Ai.Cha).animBody.speed = 1f;
				if (Random.Range(0f, 100f) > 40f)
				{
					GuestAction.SetActionEvent(base.Ai);
				}
				flag = true;
			}
			if (excitation == 100f && !inFinish)
			{
				((MonoBehaviour)this).StartCoroutine(IE_Finish());
				return;
			}
			if (!flag && ActionEventAlarmTimer() && Random.Range(0f, 100f) > 55f)
			{
				GuestAction.SetActionEvent(base.Ai);
			}
			if (CurState == State.MLoop)
			{
				CalcFluctuation();
				((ChaInfo)base.Ai.Cha).animBody.SetFloat("motion", base.Fluctuation);
			}
		}

		public override void LateUpdate()
		{
			if (isInit)
			{
				ChaTools.SetDefaultAnimatorValue(base.Ai.Cha);
				if (changePosDelay != 0f)
				{
					Helper.TimerToZero(ref changePosDelay);
				}
			}
		}

		public override void OnDestroy()
		{
			SetLayer(0f);
			base.Ai.SetAnimTypAndClip(base.startAnimTyp, base.startAnimClip);
			((ChaInfo)base.Ai.Cha).animBody.speed = 1f;
			base.Ai.excitation = excitation;
			if (base.Ai.InHomeAtcion)
			{
				base.Ai.homeActions.ResetActionTimeAndLimit(5f, 10f);
				((MonoBehaviour)base.Ai.homeActions).StartCoroutine(base.Ai.homeActions.IE_ForceAnimState());
			}
		}

		private IEnumerator IE_Finish()
		{
			inFinish = true;
			waitForFinishEnd = true;
			GuestAction.SetActionEvent(base.Ai, 0.1f, byPassKiss: true);
			CurState = State.OLoop;
			PlayAndSetParticularities();
			yield return (object)new WaitForSeconds(Random.Range(3.5f, 6f));
			GuestAction.SetActionEvent(base.Ai, 0f, byPassKiss: true);
			CurState = State.Orgasm;
			PlayAndSetParticularities();
			base.Ai.ReachOrgasm(Count.OrgTyp.Aibu);
			if (base.Ai.InHomeAtcion)
			{
				Statistic.SetDailyEvent(CtrlHome.FindSave(base.Ai.Cha), new List<Statistic.DailyEvent> { Statistic.DailyEvent.homeMast });
			}
			yield return (object)new WaitForSeconds(Time.deltaTime);
			yield return (object)new WaitForSeconds(ChaTools.StateDuration(base.Ai.Cha));
			inFinish = false;
			excitation = 5f;
			CurState = State.Orgasm_A;
			PlayAndSetParticularities();
			GuestAction.SetActionEvent(base.Ai, 1.5f);
			yield return (object)new WaitForSeconds(Random.Range(3.5f, 4.5f));
			CurState = State.Orgasm_B;
			PlayAndSetParticularities();
			yield return (object)new WaitForSeconds(4f);
			if (!startByUser || base.Ai.InHomeAtcion)
			{
				Object.Destroy((Object)(object)this);
				yield break;
			}
			waitForFinishEnd = false;
			CurState = State.WLoop;
			PlayAndSetParticularities();
		}

		public override void NextPosition(bool changeTyp, bool backward)
		{
			if (!inFinish && !waitForFinishEnd && changePosDelay == 0f && availables.Count != 1)
			{
				Animations.Clip next = (backward ? Helper.PrevInList(availables, base.Ai.AnimClip) : Helper.NextInList(availables, base.Ai.AnimClip));
				ChangeAnimation(next);
				changePosDelay = 0.5f;
			}
		}

		private void ChangeAnimation(Animations.Clip next)
		{
			SetLayer(0f);
			base.Ai.ApplyAnimClip(next);
			PlayAndSetParticularities();
		}

		public override void SetGuestActionMenuPose(MenuChara.PoseInfo posInfo)
		{
			ChangeAnimation(posInfo.clip);
		}

		private void PlayAndSetParticularities()
		{
			base.Ai.ChaCore.BoneCtrl.Reset();
			PlayAnimState(CurState.ToString(), addHeightToState);
			SetLayer(1f);
			AdaptIksToState();
			SearchSizeOffsets();
		}

		private void SetLayer(float w)
		{
			ChaTools.ResetDynAndLayerWeight(base.Ai.Cha, layerInUse);
			layerInUse.Clear();
			if (w == 0f)
			{
				return;
			}
			if (base.Ai.AnimClip == Animations.Clip.Mast_04 && w == 1f)
			{
				if (CurState == State.WLoop)
				{
					layerInUse.Add(115);
					base.Ai.Cha.playDynamicBoneBust((DynamicBoneKind)0, false);
					base.Ai.Cha.playDynamicBoneBust((DynamicBoneKind)1, false);
				}
				else if (CurState == State.MLoop)
				{
					layerInUse.Add(116);
					base.Ai.Cha.playDynamicBoneBust((DynamicBoneKind)0, false);
				}
			}
			foreach (int item in layerInUse)
			{
				((ChaInfo)base.Ai.Cha).animBody.SetLayerWeight(item, w);
			}
		}

		private void AdaptIksToState()
		{
			if (base.Ai.InH)
			{
				if (base.Ai.AnimClip == Animations.Clip.Mast_04)
				{
					HAnims.AnimInfo animInfo = HAnims.FindInfoFromAssetName("kht_f_07", HCtrl.Get.HAnimInfos);
					SetGoalsFromAnim(base.Ai, animInfo.IkF);
				}
				if (base.Ai.AnimClip == Animations.Clip.Mast_11)
				{
					HAnims.AnimInfo animInfo2 = HAnims.FindInfoFromAssetName("kht_f_06", HCtrl.Get.HAnimInfos);
					SetGoalsFromAnim(base.Ai, animInfo2.IkF);
				}
			}
		}

		private void SetGoalsFromAnim(AIGuest aiToSet, Dictionary<string, List<string>> ikDic)
		{
			List<string> goals = new List<string>();
			if (!IKS.GetGoalsTargetFromDic(CurState.ToString(), ikDic, ref goals))
			{
				return;
			}
			for (int i = 0; i < 4; i++)
			{
				if (goals[i] == "Empty" || string.IsNullOrEmpty(goals[i]))
				{
					aiToSet.ChaCore.CtrlIK.SetTarget((CtrlIK.Typ)i);
					continue;
				}
				Helper.GetStringAtIndex(goals[i], ":", 1).Trim();
				string name = Helper.GetStringAtIndex(goals[i], ":", 2).Trim();
