		public override void Init()
		{
			//IL_01bb: Unknown result type (might be due to invalid IL or missing references)
			//IL_01c0: Unknown result type (might be due to invalid IL or missing references)
			//IL_01cd: Unknown result type (might be due to invalid IL or missing references)
			//IL_01d2: Unknown result type (might be due to invalid IL or missing references)
			//IL_01ee: Unknown result type (might be due to invalid IL or missing references)
			//IL_01f3: Unknown result type (might be due to invalid IL or missing references)
			List<Animations.Clip> list = new List<Animations.Clip>();
			if (base.Ai.InHomeAtcion)
			{
				if (base.Ai.HomeSpot != null && base.Ai.HomeSpot.spotTyp == CtrlHome.SpotTyp.Wall)
				{
					availables = Animations.wallMasts;
				}
				if (base.Ai.HomeSpot != null && (base.Ai.HomeSpot.spotTyp == CtrlHome.SpotTyp.BedEdge || base.Ai.HomeSpot.spotTyp == CtrlHome.SpotTyp.Chair))
				{
					availables = Animations.sitMasts;
				}
				if (base.Ai.HomeSpot != null && base.Ai.HomeSpot.spotTyp == CtrlHome.SpotTyp.Bed)
				{
					availables = Animations.crouchMasts;
				}
				if (availables.Count == 0)
				{
					availables = Animations.standMasts;
				}
			}
			else
			{
				if (bindFamilyAtStart == Binders.Family.Undefined || bindFamilyAtStart == Binders.Family.Lay)
				{
					list = ((base.startAnimTyp == Animations.Type.Crouch) ? Animations.crouchMasts : Animations.standMasts);
					availables.AddRange(Animations.crouchMasts);
					availables.AddRange(Animations.standMasts);
				}
				if (bindFamilyAtStart == Binders.Family.Desk)
				{
					availables = Animations.deskMasts;
				}
				if (bindFamilyAtStart == Binders.Family.Sit)
				{
					availables = Animations.sitMasts;
				}
				if (bindFamilyAtStart == Binders.Family.Wall)
				{
					availables = Animations.wallMasts;
				}
				if (bindFamilyAtStart != Binders.Family.Undefined)
				{
					SetDontCollideOn();
				}
				if (bindFamilyAtStart == Binders.Family.Sit || bindFamilyAtStart == Binders.Family.Desk)
				{
					SetActionMatchMainHeightOn();
				}
			}
			base.Ai.SetAnimTypAndClip(Animations.Type.Mast, Helper.RandomInList((list.Count != 0) ? list : availables));
			CurState = State.WLoop;
			PlayAndSetParticularities();
			Clothes.RevealCrotch(base.Ai.Cha);
			if (bindFamilyAtStart != Binders.Family.Undefined && bindRotAtStart != Quaternion.identity)
			{
				Quaternion rotation = bindRotAtStart;
				base.Ai.Mover.SetMoverPosition(((Component)base.Ai.Cha).transform.position, rotation);
			}
			isInit = true;
		}
	}
	public class Piston : GuestAction
	{
		public enum State
		{
			Idle,
			Insert,
			InsertIdle,
			WLoop,
			SLoop,
			OLoop,
			SS_IN_Start,
			SS_IN_Loop,
			SS_IN_A,
			IN_A,
			M_OUT_Start,
			M_OUT_Loop,
			OUT_A,
			Pull,
			Drop,
			A_Idle,
			A_Insert,
			A_InsertIdle,
			A_WLoop,
			A_SLoop,
			A_OLoop,
			A_SS_IN_Start,
			A_SS_IN_Loop,
			A_SS_IN_A,
