			A_M_OUT_Start,
			A_M_OUT_Loop,
			A_OUT_A,
			A_Pull,
			A_Drop
		}

		private static List<HAnims.AnimInfo> availableLay = new List<HAnims.AnimInfo>();

		private static List<HAnims.AnimInfo> availableAnalLay = new List<HAnims.AnimInfo>();

		private static List<HAnims.AnimInfo> availableStand = new List<HAnims.AnimInfo>();

		private static List<HAnims.AnimInfo> availableAnalStand = new List<HAnims.AnimInfo>();

		private List<HAnims.AnimInfo> availableAll = new List<HAnims.AnimInfo>();

		private List<HAnims.AnimInfo> availableAnalAll = new List<HAnims.AnimInfo>();

		private static List<HAnims.AnimInfo> availableDesk = new List<HAnims.AnimInfo>();

		private static List<HAnims.AnimInfo> availableAnalDesk = new List<HAnims.AnimInfo>();

		private static List<HAnims.AnimInfo> availableSit = new List<HAnims.AnimInfo>();

		private static List<HAnims.AnimInfo> availableAnalSit = new List<HAnims.AnimInfo>();

		private static List<HAnims.AnimInfo> availableWall = new List<HAnims.AnimInfo>();

		private static List<HAnims.AnimInfo> availableAnalWall = new List<HAnims.AnimInfo>();

