		private static List<HAnims.AnimInfo> availableAnalPool = new List<HAnims.AnimInfo>();

		private bool inInsertion;

		private bool gayRelation;

		private bool anal;

		private float matchStateTimer = 0.1f;

		public bool IsPenisInserted => !NotInsertStates.Contains(CurState);

		public List<State> NotInsertStates => new List<State>
		{
			State.Idle,
			State.M_OUT_Loop,
			State.OUT_A,
			State.Drop,
			State.A_Idle,
			State.A_M_OUT_Loop,
			State.A_OUT_A,
			State.A_Drop
		};

		public bool IsWLoop => new List<State>
		{
			State.WLoop,
			State.A_WLoop
		}.Contains(CurState);

		public bool IsSLoop => new List<State>
		{
			State.SLoop,
			State.A_SLoop
		}.Contains(CurState);

		public bool IsOLoop => new List<State>
		{
