		{
			State.SS_IN_Start,
			State.SS_IN_Loop,
			State.A_SS_IN_Start,
			State.A_SS_IN_Start
		}.Contains(CurState);

		public bool IsOutOrg => new List<State>
		{
			State.M_OUT_Start,
			State.M_OUT_Loop,
			State.A_M_OUT_Start,
			State.A_M_OUT_Loop
		}.Contains(CurState);

