		private void AdaptDickGoal()
		{
			if (IsPenisInserted)
			{
				base.Ai.ChaCore.GenitalBoy.CreateLookAt(base.Partner1.Ai.Cha, anal ? "k_f_ana_00" : "k_f_kokan_00");
