		private void SetGoalsFromAnim(AIGuest aiToSet, Dictionary<string, List<string>> ikDic)
		{
			List<string> goals = new List<string>();
			if (!IKS.GetGoalsTargetFromDic(CurState.ToString(), ikDic, ref goals))
			{
				return;
			}
			for (int i = 0; i < 4; i++)
			{
				if (goals[i] == "Empty" || string.IsNullOrEmpty(goals[i]))
				{
					aiToSet.ChaCore.CtrlIK.SetTarget((CtrlIK.Typ)i);
					continue;
				}
				string text = Helper.GetStringAtIndex(goals[i], ":", 1).Trim();
				string name = Helper.GetStringAtIndex(goals[i], ":", 2).Trim();
				aiToSet.ChaCore.CtrlIK.SetTarget((CtrlIK.Typ)i, ChaTools.FindInCha((text == "G1") ? base.Partner1.Ai.Cha : base.Ai.Cha, name));
			}
		}

		private void AdaptIksToState()
		{
			if (Anim.isExtraAnim || Anim.gameAnmIkDicExists)
			{
				SetGoalsFromAnim(base.Ai, Anim.IkM);
				SetGoalsFromAnim(base.Partner1.Ai, Anim.IkF);
			}
		}

		private void AdaptClothesToAnim()
		{
			Clothes.RevealCrotch(base.Ai.Cha);
			Clothes.RevealCrotch(base.Partner1.Ai.Cha);
		}

		private IEnumerator IE_Insert(float waitTime = -1f)
		{
			inInsertion = true;
			yield return (object)new WaitForSeconds((waitTime == -1f) ? Random.Range(1.25f, 2f) : waitTime);
			anal = ((Anim.hasAnal && (Random.Range(0f, 100f) > 50f || gayRelation)) ? true : false);
			PlayAndSetParticularities((!anal) ? State.Insert : State.A_Insert);
			yield return (object)new WaitForSeconds(Time.deltaTime);
			yield return (object)new WaitForSeconds(ChaTools.StateDuration(base.Ai.Cha));
			PlayAndSetParticularities(anal ? State.A_InsertIdle : State.InsertIdle);
			yield return (object)new WaitForSeconds(Random.Range(0.25f, 0.75f));
			PlayAndSetParticularities(CurWLoop);
			yield return (object)new WaitForSeconds(Time.deltaTime);
			inInsertion = false;
		}

		private IEnumerator IE_Finish()
		{
			inFinish = true;
			GuestAction.SetActionEvent(base.Ai, 0f, byPassKiss: true);
			bool inside = Random.Range(0f, 100f) > 40f;
			PlayAndSetParticularities(anal ? State.A_OLoop : State.OLoop);
			yield return (object)new WaitForSeconds(Random.Range(3.5f, 6f));
			base.Ai.ReachOrgasm(Count.OrgTyp.SonyuSame, !inside);
			base.Partner1.Ai.ReachOrgasm(Count.OrgTyp.SonyuSame, base.Partner1.Ai.IsBoy);
			PlayAndSetParticularities((!inside) ? (anal ? State.A_M_OUT_Start : State.M_OUT_Start) : (anal ? State.A_SS_IN_Start : State.SS_IN_Start));
			GuestAction.SetActionEvent(base.Ai, 0f, byPassKiss: true);
			GuestAction.SetActionEvent(base.Partner1.Ai, 0f, byPassKiss: true);
			yield return (object)new WaitForSeconds(Time.deltaTime);
			yield return (object)new WaitForSeconds(ChaTools.StateDuration(base.Ai.Cha));
			excitation = 5f;
			PlayAndSetParticularities((!inside) ? (anal ? State.A_M_OUT_Loop : State.M_OUT_Loop) : (anal ? State.A_SS_IN_Loop : State.SS_IN_Loop));
			if (!inside)
			{
				ChaTools.AddSiruOnCha(base.Partner1.Ai.Cha, Anim.siruFlags);
			}
			if (inside && !anal && Settings.BellyInflWithBuddy && base.Partner1.Ai.IsGirl && Object.op_Implicit((Object)(object)((Component)base.Partner1.Ai.Cha).gameObject.GetComponent<BellyCtrl>()))
			{
				((Component)base.Partner1.Ai.Cha).gameObject.GetComponent<BellyCtrl>().buddyCumsIn = true;
			}
			yield return (object)new WaitForSeconds(Random.Range(3.5f, 5f));
			if (base.Partner1.Ai.IsGirl && Object.op_Implicit((Object)(object)((Component)base.Partner1.Ai.Cha).gameObject.GetComponent<BellyCtrl>()))
			{
				((Component)base.Partner1.Ai.Cha).gameObject.GetComponent<BellyCtrl>().buddyCumsIn = false;
			}
			PlayAndSetParticularities((!inside) ? (anal ? State.A_OUT_A : State.OUT_A) : (anal ? State.A_SS_IN_A : State.SS_IN_A));
			if (!inside)
			{
				anal = false;
			}
			GuestAction.SetActionEvent(base.Ai, 0.5f);
			yield return (object)new WaitForSeconds(Random.Range(inside ? 1.5f : 3.5f, inside ? 2.5f : 5f));
			if (inside)
			{
				PlayAndSetParticularities(anal ? State.A_Pull : State.Pull);
				yield return (object)new WaitForSeconds(Time.deltaTime);
				yield return (object)new WaitForSeconds(ChaTools.StateDuration(base.Ai.Cha));
				PlayAndSetParticularities(anal ? State.A_Drop : State.Drop);
				anal = false;
				yield return (object)new WaitForSeconds(Random.Range(3f, 4.25f));
			}
			yield return (object)new WaitForEndOfFrame();
			inFinish = false;
			if (!startByUser)
			{
				DetachPartners();
			}
			else
			{
				((MonoBehaviour)this).StartCoroutine(IE_Insert());
			}
		}

		private void GetAvailableAnims()
		{
			if (bindFamilyAtStart == Binders.Family.Undefined || bindFamilyAtStart == Binders.Family.Lay)
			{
				availableAll.AddRange(gayRelation ? availableAnalLay : availableLay);
				availableAll.AddRange(gayRelation ? availableAnalLay : availableStand);
				if (Core.dealer.MapID == 0 || Core.dealer.MapID == 36)
				{
					availableAll.AddRange(gayRelation ? availableAnalPool : availablePool);
				}
			}
			if (bindFamilyAtStart == Binders.Family.Sit)
			{
				availableAll.AddRange(gayRelation ? availableAnalSit : availableSit);
			}
			if (bindFamilyAtStart == Binders.Family.Desk)
			{
				availableAll.AddRange(gayRelation ? availableAnalDesk : availableDesk);
			}
			if (bindFamilyAtStart == Binders.Family.Wall)
			{
				availableAll.AddRange(gayRelation ? availableAnalWall : availableWall);
			}
			foreach (HAnims.AnimInfo item in availableAll)
			{
				if (item.hasAnal)
				{
					availableAnalAll.Add(item);
				}
			}
		}

		private static string BundleFromAnimInfo(HAnims.AnimInfo info, bool isMale = false)
		{
			if (isMale)
			{
				return info.animList.pathMaleBase.assetpath + ":" + info.animList.paramMale.path.assetpath;
			}
			return info.animList.pathFemaleBase.assetpath + ":" + info.animList.paramFemale.path.assetpath;
		}

		private static string AssetFromAnimInfo(HAnims.AnimInfo info, bool isMale = false)
		{
			if (isMale)
			{
				return "khs_m_base/" + info.animList.paramMale.path.file;
			}
			return "khs_f_base/" + info.animList.paramFemale.path.file;
		}

		public static void ListAvailableAnims()
		{
			availableLay.Clear();
			availableAnalLay.Clear();
			availableStand.Clear();
			availableAnalStand.Clear();
			availableDesk.Clear();
			availableAnalDesk.Clear();
			availableSit.Clear();
			availableAnalSit.Clear();
			availableWall.Clear();
			availableAnalWall.Clear();
			availablePool.Clear();
			availableAnalPool.Clear();
			foreach (HAnims.AnimInfo hAnimInfo in Core.dealer.HCtrl.HAnimInfos)
			{
				if (Settings.FilterDblInPosUI && hAnimInfo.hasPlugVersion)
				{
					continue;
				}
				if (hAnimInfo.ctx == HAnims.Context.Piston && hAnimInfo.plugName.Contains("Lay") && string.IsNullOrEmpty(hAnimInfo.animList.paramFemale1.path.file))
				{
					availableLay.Add(hAnimInfo);
					if (hAnimInfo.hasAnal)
					{
						availableAnalLay.Add(hAnimInfo);
					}
				}
				if (hAnimInfo.ctx == HAnims.Context.Piston && hAnimInfo.plugName.Contains("Stand") && string.IsNullOrEmpty(hAnimInfo.animList.paramFemale1.path.file))
				{
					availableStand.Add(hAnimInfo);
					if (hAnimInfo.hasAnal)
					{
						availableAnalStand.Add(hAnimInfo);
					}
				}
				if (hAnimInfo.ctx == HAnims.Context.Piston && Helper.IsWordContainsGivenWords(hAnimInfo.plugName, new List<string> { "Desk" }) && string.IsNullOrEmpty(hAnimInfo.animList.paramFemale1.path.file))
				{
					availableDesk.Add(hAnimInfo);
					if (hAnimInfo.hasAnal)
					{
						availableAnalDesk.Add(hAnimInfo);
					}
				}
				if (hAnimInfo.ctx == HAnims.Context.Piston && Helper.IsWordContainsGivenWords(hAnimInfo.plugName, new List<string> { "Sit", "Toilet" }) && string.IsNullOrEmpty(hAnimInfo.animList.paramFemale1.path.file))
				{
					availableSit.Add(hAnimInfo);
					if (hAnimInfo.hasAnal)
					{
						availableAnalSit.Add(hAnimInfo);
					}
				}
				if (hAnimInfo.ctx == HAnims.Context.Piston && Helper.IsWordContainsGivenWords(hAnimInfo.plugName, new List<string> { "Wall", "Fence", "Train" }) && string.IsNullOrEmpty(hAnimInfo.animList.paramFemale1.path.file))
				{
					availableWall.Add(hAnimInfo);
					if (hAnimInfo.hasAnal)
					{
						availableAnalWall.Add(hAnimInfo);
					}
				}
				if (hAnimInfo.ctx == HAnims.Context.Piston && Helper.IsWordContainsGivenWords(hAnimInfo.plugName, new List<string> { "Pool" }) && string.IsNullOrEmpty(hAnimInfo.animList.paramFemale1.path.file))
				{
					availablePool.Add(hAnimInfo);
					if (hAnimInfo.hasAnal)
					{
						availableAnalPool.Add(hAnimInfo);
					}
				}
			}
			HAnims.OrderAnimList(ref availableLay);
			HAnims.OrderAnimList(ref availableAnalLay);
			HAnims.OrderAnimList(ref availableStand);
			HAnims.OrderAnimList(ref availableAnalStand);
			HAnims.OrderAnimList(ref availableDesk);
			HAnims.OrderAnimList(ref availableAnalDesk);
			HAnims.OrderAnimList(ref availableSit);
			HAnims.OrderAnimList(ref availableAnalSit);
			HAnims.OrderAnimList(ref availableWall);
			HAnims.OrderAnimList(ref availableAnalWall);
			HAnims.OrderAnimList(ref availablePool);
			HAnims.OrderAnimList(ref availableAnalPool);
		}

		public static Piston ActionAs(GuestAction guestAction)
		{
			return guestAction as Piston;
		}
	}
	public class Service : GuestAction
	{
		public enum State
		{
			Idle,
			WLoop,
			SLoop,
			OLoop,
			IN_Start,
			IN_Loop,
			M_OUT_Start,
			M_OUT_Loop,
			OUT_A,
			Oral_Idle_IN,
			Oral_Idle,
			Drink_IN,
			Drink,
			Drink_A,
			Vomit_IN,
			Vomit,
			Vomit_A,
			Stop_Idle
		}

		private static List<State> oralOnlyStates = new List<State>
		{
			State.Oral_Idle_IN,
			State.Oral_Idle,
			State.Drink_IN,
			State.Drink,
			State.Drink_A,
			State.Vomit_IN,
			State.Vomit,
			State.Vomit_A,
			State.IN_Start,
			State.IN_Loop
		};

		private List<HAnims.AnimInfo> handjobs = new List<HAnims.AnimInfo>();

		private List<HAnims.AnimInfo> footjobs = new List<HAnims.AnimInfo>();

		private List<HAnims.AnimInfo> humpjobs = new List<HAnims.AnimInfo>();

		private List<HAnims.AnimInfo> mouthjobs = new List<HAnims.AnimInfo>();

		private List<HAnims.AnimInfo> boobsjobs = new List<HAnims.AnimInfo>();

		private List<HAnims.AnimInfo> otherjobs = new List<HAnims.AnimInfo>();

		public int kindAtStart = -1;

		private int kindService;

		private float matchStateTimer = 0.1f;

		private bool inStart;

		public bool IsWLoop => new List<State> { State.WLoop }.Contains(CurState);

		public bool IsSLoop => new List<State> { State.SLoop }.Contains(CurState);

		public bool IsOLoop => new List<State> { State.OLoop }.Contains(CurState);

		public bool IsInsideOrg => new List<State>
		{
			State.IN_Start,
			State.IN_Loop
		}.Contains(CurState);

		public bool IsOutOrg => new List<State>
		{
			State.M_OUT_Start,
			State.M_OUT_Loop
		}.Contains(CurState);

		public bool IsAfterCum => new List<State>
		{
			State.Oral_Idle_IN,
			State.Oral_Idle,
			State.OUT_A
		}.Contains(CurState);

		public bool IsMouthServ => HManage.IsInMouthService((Anim != null) ? Anim.plugName : "");

		public bool IsLickServ
		{
			get
			{
				if (!HManage.IsLickService(Anim.plugName))
				{
					return Anim.asset.Contains("khh_f_64");
				}
				return true;
			}
		}

		public bool Is69 => Helper.IsWordContainsGivenWords(Anim.plugName, new List<string> { "69", "YingYang" });

		public State CurState { get; private set; }

		public HAnims.AnimInfo Anim { get; private set; }

		public override void Update()
		{
			if (!isInit || !base.IsLeader || inFinish || inDetach || inStart)
			{
				return;
			}
			if (!(InfoMain.distance < 0.9f) || !InfoMain.inMotion || !(InfoMain.highestGaugeVal > 70f) || !(excitation > 97f))
			{
				IncreaseEx();
			}
			State state = CurState;
			if (InfoMain.distance < 0.9f && InfoMain.inMotion && Anim.ctx == InfoMain.ctx)
			{
				if ((InfoMain.inWLoop && !IsWLoop) || (InfoMain.inSLoop && !IsSLoop))
				{
					Helper.TimerToZero(ref matchStateTimer);
					if (matchStateTimer == 0f)
					{
						matchStateTimer = Random.Range(0.05f, 0.65f);
						state = (InfoMain.inWLoop ? State.WLoop : (InfoMain.inSLoop ? State.SLoop : CurState));
					}
				}
			}
			else
			{
				state = ((!(excitation > 45f)) ? ((!IsWLoop) ? State.WLoop : CurState) : ((!IsSLoop) ? State.SLoop : CurState));
			}
			bool flag = CurState != state;
			if (flag)
			{
				PlayAndSetParticularities(state);
				if (Random.Range(0f, 100f) > 50f)
				{
					GuestAction.SetActionEvent(base.Ai);
				}
				if (Random.Range(0f, 100f) > 50f)
				{
					GuestAction.SetActionEvent(base.Partner1.Ai);
				}
			}
			if (excitation == 100f && !inFinish)
			{
				((MonoBehaviour)this).StartCoroutine(IE_Finish());
				return;
			}
			if (!flag && !inFinish && ActionEventAlarmTimer())
			{
				float num = Random.Range(0f, 100f);
				if (num > 45f)
				{
					if (num < 75f)
					{
						GuestAction.SetActionEvent(base.Ai);
					}
					else
					{
						GuestAction.SetActionEvent(base.Partner1.Ai);
					}
				}
			}
			if (IsWLoop || IsSLoop)
			{
				CalcFluctuation();
				((ChaInfo)base.Ai.Cha).animBody.SetFloat("motion", base.Fluctuation);
				((ChaInfo)base.Partner1.Ai.Cha).animBody.SetFloat("motion", base.Fluctuation);
			}
			((ChaInfo)base.Ai.Cha).animBody.SetFloat("height", base.Partner1.Ai.Cha.GetShapeBodyValue(0));
			((ChaInfo)base.Partner1.Ai.Cha).animBody.SetFloat("height", base.Partner1.Ai.Cha.GetShapeBodyValue(0));
			((ChaInfo)base.Ai.Cha).animBody.SetFloat("Breast", base.Partner1.Ai.Cha.GetShapeBodyValue(4));
			((ChaInfo)base.Partner1.Ai.Cha).animBody.SetFloat("Breast", base.Partner1.Ai.Cha.GetShapeBodyValue(4));
		}

		public override void LateUpdate()
		{
			//IL_0057: Unknown result type (might be due to invalid IL or missing references)
			//IL_006c: Unknown result type (might be due to invalid IL or missing references)
			if (isInit && base.IsLeader && !inDetach)
			{
				QueryInfoFromMain();
				AdaptSpeed(IsWLoop, IsSLoop);
				base.Partner1.Ai.Mover.SetMoverPosition(((Component)base.Ai.Cha).transform.position, ((Component)base.Ai.Cha).transform.rotation);
				if (base.Ai.Cha.GetLookNeckPtn() != (base.Ai.InKiss ? 1 : 3))
				{
					base.Ai.Cha.ChangeLookNeckPtn(base.Ai.InKiss ? 1 : 3, 1f);
				}
				if (!IsMouthServ && base.Partner1.Ai.Cha.GetLookNeckPtn() != (base.Partner1.Ai.InKiss ? 1 : 3))
				{
					base.Partner1.Ai.Cha.ChangeLookNeckPtn(base.Partner1.Ai.InKiss ? 1 : 3, 1f);
				}
				if (changePosDelay != 0f)
				{
					Helper.TimerToZero(ref changePosDelay);
				}
			}
		}

		public override void OnDestroy()
		{
			if (base.IsLeader)
			{
				SetLayer(0f);
				GenitalBoy.RemoveLookAt(base.Ai.Cha);
			}
			base.Ai.SetAnimTypAndClip(base.startAnimTyp, base.startAnimClip);
			((ChaInfo)base.Ai.Cha).animBody.speed = 1f;
			base.Ai.Cha.ChangeLookNeckPtn(1, 1f);
		}

		public override void DetachParticularities()
		{
			if (base.IsLeader && changePosDelay == 0f)
			{
				GenitalBoy.RemoveLookAt(base.Ai.Cha);
				ChaTools.ResetDynAndLayerWeight(base.Partner1.Ai.Cha, new List<int>());
			}
		}

		public override void NextPosition(bool changeTyp, bool backward)
		{
			if (inFinish || changePosDelay != 0f)
			{
				return;
			}
			if (!base.IsLeader)
			{
				base.Leader.NextPosition(changeTyp, backward);
				return;
			}
			HAnims.AnimInfo next = null;
			if (changeTyp)
			{
				kindService = Helper.NextInList(new List<int> { 0, 1, 2 }, kindService);
				List<HAnims.AnimInfo> list = ((kindService == 0) ? handjobs : ((kindService == 1) ? mouthjobs : boobsjobs));
				if (list.Count == 0)
				{
					list = mouthjobs;
				}
				next = Helper.RandomInList(list);
			}
			if (!changeTyp)
			{
				next = HAnims.NextOrPrevInList((kindService == 0) ? otherjobs : ((kindService == 1) ? mouthjobs : boobsjobs), Anim, (!backward) ? Enums.Way.Forward : Enums.Way.Back);
			}
			ChangeAnimation(next);
			changePosDelay = 0.5f;
		}

		private void ChangeAnimation(HAnims.AnimInfo next)
		{
			SetLayer(0f);
			GenitalBoy.RemoveLookAt(base.Ai.Cha);
			base.Ai.Cha.ChangeLookNeckPtn(1, 1f);
			base.Partner1.Ai.Cha.ChangeLookNeckPtn(1, 1f);
			Anim = next;
			base.Ai.SetAnimTypAndAsset(Animations.Type.Service, BundleFromAnimInfo(Anim, isMale: true), AssetFromAnimInfo(Anim, isMale: true), "Idle");
			base.Partner1.Ai.SetAnimTypAndAsset(Animations.Type.Service, BundleFromAnimInfo(Anim), AssetFromAnimInfo(Anim), "Idle");
			kindService = Anim.animList.kindHoushi;
			PlayAndSetParticularities(CurState);
			AdaptClothesToAnim();
		}

		public override void SetGuestActionMenuPose(MenuChara.PoseInfo posInfo)
		{
			if (!base.IsLeader)
			{
				base.Leader.SetGuestActionMenuPose(posInfo);
			}
			else
			{
				ChangeAnimation(posInfo.animInf);
			}
		}

		public override void SearchSizeOffsets(bool afterSwap = false)
		{
			if (base.Partner1.Ai.Cha.GetShapeBodyValue(0) < 0f)
			{
				SizeOffsets.SearchAndSubscribe(base.Ai.Cha, SizeOffsets.ChaTyp.B1, Anim.asset, CurState.ToString());
				SizeOffsets.SearchAndSubscribe(base.Partner1.Ai.Cha, SizeOffsets.ChaTyp.G1, Anim.asset, CurState.ToString());
				CtrlBones.SetHeightPartner(base.Ai.Cha, base.Partner1.Ai.Cha);
			}
		}

		public override void AfterSwap()
		{
			if (!base.IsLeader)
			{
				base.Leader.AfterSwap();
				return;
			}
			base.Ai.ChaCore.BoneCtrl.Reset();
			base.Partner1.Ai.ChaCore.BoneCtrl.Reset();
			SearchSizeOffsets(afterSwap: true);
		}

		public override void Init()
		{
			if (!base.IsLeader)
			{
				isInit = true;
			}
			else
			{
				((MonoBehaviour)this).StartCoroutine(IE_Init());
			}
		}

		public override IEnumerator IE_Init()
		{
			yield return (object)new WaitUntil((Func<bool>)(() => base.Partner1.isInit));
			GetAvailableAnims();
			if (bindFamilyAtStart != Binders.Family.Undefined)
			{
				SetDontCollideOn();
			}
			if (bindFamilyAtStart == Binders.Family.Sit || bindFamilyAtStart == Binders.Family.Desk)
			{
				SetActionMatchMainHeightOn();
			}
			new List<HAnims.AnimInfo>();
			List<HAnims.AnimInfo> list;
			if (kindAtStart != -1)
			{
				kindService = kindAtStart;
				list = ((kindService == 0) ? handjobs : ((kindService == 1) ? mouthjobs : ((kindService == 4) ? footjobs : ((kindService == 5) ? humpjobs : boobsjobs))));
				kindService = ((kindService != 4 && kindService != 5) ? kindService : 0);
			}
			else
			{
				kindService = Helper.RandomInList(new List<int> { 0, 1, 2, 0, 1, 2 });
				list = ((kindService == 0) ? handjobs : ((kindService == 1) ? mouthjobs : boobsjobs));
			}
			if (list.Count == 0)
			{
				list = mouthjobs;
			}
			Anim = Helper.RandomInList(list);
			Quaternion rotation = Quaternion.LookRotation(Vector3.Cross(Helper.GetDir(((Component)base.Partner1.Ai.Cha).transform.position, ((Component)Core.dealer.MainGirlCha).transform.position), Vector3.up), Vector3.up);
			if (bindFamilyAtStart != Binders.Family.Undefined && bindRotAtStart != Quaternion.identity)
			{
				rotation = bindRotAtStart;
			}
			base.Partner1.Ai.Mover.SetMoverPosition(((Component)base.Partner1.Ai.Cha).transform.position, rotation);
			base.Ai.Mover.SetMoverPosition(((Component)base.Partner1.Ai.Cha).transform.position, rotation);
			base.Ai.SetAnimTypAndAsset(Animations.Type.Service, BundleFromAnimInfo(Anim, isMale: true), AssetFromAnimInfo(Anim, isMale: true), "Idle");
			base.Partner1.Ai.SetAnimTypAndAsset(Animations.Type.Service, BundleFromAnimInfo(Anim), AssetFromAnimInfo(Anim), "Idle");
			AdaptClothesToAnim();
			PlayAndSetParticularities(State.Stop_Idle);
			((MonoBehaviour)this).StartCoroutine(IE_Start());
			isInit = true;
		}

		private State ConformStateToCurAnim(State state)
		{
			if (oralOnlyStates.Contains(state) && !IsMouthServ)
			{
				return state switch
				{
					State.IN_Start => State.M_OUT_Start, 
					State.IN_Loop => State.M_OUT_Loop, 
					_ => State.Idle, 
				};
			}
			return state;
		}

		private void PlayAndSetParticularities(State state)
		{
			_ = base.Partner1.SizePrefix;
			CurState = ConformStateToCurAnim(state);
			ActionAs(base.Partner1).CurState = state;
			base.Ai.ChaCore.BoneCtrl.Reset();
			base.Partner1.Ai.ChaCore.BoneCtrl.Reset();
			PlayAnimState(state.ToString(), addSizePrefix: false);
			base.Partner1.PlayAnimState(state.ToString(), addSizePrefix: false);
			AdaptNeckAndExpr();
			AdaptDynAndLayer();
			AdaptIksToState();
			AdaptDickGoal();
			SearchSizeOffsets();
		}

		private void AdaptDynAndLayer()
		{
			if (Anim.plugName.Contains("Paizuri") && !Anim.asset.Contains("khh_f_13"))
			{
				ChaTools.ResetDynAndLayerWeight(base.Partner1.Ai.Cha, new List<int>());
				if (CurState == State.WLoop || CurState == State.SLoop || CurState == State.OLoop)
				{
					base.Partner1.Ai.Cha.playDynamicBoneBust((DynamicBoneKind)0, false);
					base.Partner1.Ai.Cha.playDynamicBoneBust((DynamicBoneKind)1, false);
				}
			}
		}

		private void SetLayer(float w)
		{
			if (Anim.isExtraAnim)
			{
				w = 0f;
			}
			if (Anim.animList.paramFemale.lstIdLayer.Count != 0 && Anim.animList.paramFemale.lstIdLayer[0] != -1)
			{
				base.Partner1.Ai.Cha.setLayerWeight(w, Anim.animList.paramFemale.lstIdLayer[0]);
			}
		}

		private void AdaptIksToState()
		{
			SetLayer(1f);
			string word = (Anim.asset.Contains("/") ? Helper.GetLastString(Anim.asset, "/") : Anim.asset);
			List<string> keywords = new List<string>
			{
				"khh_f_11", "khh_f_12", "khh_f_15", "khh_f_27", "khh_f_28", "khh_f_30", "khh_f_31", "khh_f_64", "khh_f_43", "khh_f_44",
				"khh_f_47"
			};
			if (Helper.IsWordContainsGivenWords(word, keywords, exactMatch: true))
			{
				if (CurState != State.Idle)
				{
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.L_Hand, ChaTools.FindInCha(base.Partner1.Ai.Cha, "k_f_mune00L_00"));
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.R_Hand, ChaTools.FindInCha(base.Partner1.Ai.Cha, "k_f_mune00R_00"));
				}
				else
				{
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.L_Hand);
					base.Partner1.Ai.ChaCore.CtrlIK.SetTarget(CtrlIK.Typ.R_Hand);
				}
			}
			if (Anim.isExtraAnim)
			{
				SetGoalsFromAnim(base.Ai, Anim.IkM);
				SetGoalsFromAnim(base.Partner1.Ai, Anim.IkF);
			}
		}

		private void SetGoalsFromAnim(AIGuest aiToSet, Dictionary<string, List<string>> ikDic)
		{
			List<string> goals = new List<string>();
			if (!IKS.GetGoalsTargetFromDic(CurState.ToString(), ikDic, ref goals))
			{
				return;
			}
			for (int i = 0; i < 4; i++)
			{
				if (goals[i] == "Empty" || string.IsNullOrEmpty(goals[i]))
				{
					aiToSet.ChaCore.CtrlIK.SetTarget((CtrlIK.Typ)i);
					continue;
				}
				string text = Helper.GetStringAtIndex(goals[i], ":", 1).Trim();
				string name = Helper.GetStringAtIndex(goals[i], ":", 2).Trim();
				aiToSet.ChaCore.CtrlIK.SetTarget((CtrlIK.Typ)i, ChaTools.FindInCha((text == "G1") ? base.Partner1.Ai.Cha : base.Ai.Cha, name));
			}
		}

		private void AdaptDickGoal()
		{
			if (IsMouthServ)
			{
				if (CurState == State.WLoop || CurState == State.SLoop || CurState == State.OLoop || CurState == State.IN_Start || CurState == State.IN_Loop)
				{
					base.Ai.ChaCore.GenitalBoy.CreateLookAt(base.Partner1.Ai.Cha, "k_f_head_00");
				}
				else
				{
					GenitalBoy.RemoveLookAt(base.Ai.Cha);
				}
			}
