		private void ForceMouthAndTongue()
		{
			if (IsMouthServ && new List<State>
			{
				State.WLoop,
				State.SLoop,
				State.OLoop,
				State.IN_Start,
				State.IN_Loop
			}.Contains(CurState) && base.Partner1.Ai.Cha.GetMouthPtn() != 22)
			{
				base.Partner1.Ai.Cha.ChangeMouthPtn(22, false);
				base.Partner1.Ai.Cha.ChangeMouthOpenMax(1f);
				((FBSBase)((ChaInfo)base.Partner1.Ai.Cha).mouthCtrl).OpenMin = 1f;
			}
			if (IsLickServ && new List<State>
			{
				State.WLoop,
				State.SLoop
			}.Contains(CurState) && base.Partner1.Ai.Cha.GetMouthPtn() != 24)
			{
				base.Partner1.Ai.Cha.ChangeMouthPtn(24, false);
				base.Partner1.Ai.Cha.ChangeMouthOpenMax(1f);
				((FBSBase)((ChaInfo)base.Partner1.Ai.Cha).mouthCtrl).OpenMin = 1f;
				base.Partner1.Ai.Cha.ChangeTongueState((byte)1);
			}
			if (Is69 && new List<State>
			{
				State.WLoop,
				State.SLoop
			}.Contains(CurState) && base.Partner1.Ai.Cha.GetMouthPtn() != 24)
			{
				base.Ai.Cha.ChangeMouthPtn(24, false);
				base.Ai.Cha.ChangeMouthOpenMax(1f);
				((FBSBase)((ChaInfo)base.Ai.Cha).mouthCtrl).OpenMin = 1f;
				base.Ai.Cha.ChangeTongueState((byte)1);
			}
		}

		private void AdaptNeckAndExpr()
		{
			overExpr = FaceExpr.Type.Neutral;
			base.Partner1.overExpr = FaceExpr.Type.Neutral;
			if (IsMouthServ && new List<State>
			{
				State.WLoop,
				State.SLoop,
				State.OLoop,
				State.IN_Start,
				State.IN_Loop
			}.Contains(CurState) && base.Partner1.Ai.Cha.GetMouthPtn() != 22)
			{
				base.Partner1.overExpr = FaceExpr.Type.Suck;
			}
			if (IsLickServ && new List<State>
			{
				State.WLoop,
				State.SLoop
			}.Contains(CurState))
			{
				base.Partner1.overExpr = FaceExpr.Type.Lick;
			}
			if (Is69)
			{
				if (new List<State>
				{
					State.WLoop,
					State.SLoop,
					State.OLoop
				}.Contains(CurState))
				{
					overExpr = FaceExpr.Type.Lick;
				}
				if (new List<State>
				{
					State.WLoop,
					State.SLoop,
					State.OLoop,
					State.IN_Loop,
					State.IN_Start
				}.Contains(CurState))
				{
					base.Partner1.overExpr = FaceExpr.Type.Suck;
				}
			}
			if (overExpr != FaceExpr.Type.Neutral)
			{
				base.Ai.Cha.ChangeLookNeckPtn(3, 1f);
			}
			if (base.Partner1.overExpr != FaceExpr.Type.Neutral)
			{
				base.Partner1.Ai.Cha.ChangeLookNeckPtn(3, 1f);
			}
		}

		private void AdaptClothesToAnim()
		{
			Clothes.RevealCrotch(base.Ai.Cha);
			if (kindService == 2)
			{
				Clothes.RevealBreast(base.Partner1.Ai.Cha);
			}
			if (Anim.isSpSrv)
			{
				Clothes.RevealCrotch(base.Partner1.Ai.Cha);
			}
		}

		private IEnumerator IE_Start()
		{
			inStart = true;
			yield return (object)new WaitForSeconds(Random.Range(1.75f, 3.5f));
			PlayAndSetParticularities(State.WLoop);
			yield return (object)new WaitForSeconds(0.5f);
			inStart = false;
		}

		private IEnumerator IE_Finish()
		{
			inFinish = true;
			GuestAction.SetActionEvent(base.Ai, 0f, byPassKiss: true);
			bool inside = ((IsMouthServ && Random.Range(0f, 100f) > 40f) ? true : false);
			PlayAndSetParticularities(State.OLoop);
			yield return (object)new WaitForSeconds(Random.Range(3.5f, 6f));
			GuestAction.SetActionEvent(base.Ai, 0f, byPassKiss: true);
			GuestAction.SetActionEvent(base.Partner1.Ai, 0f, byPassKiss: true);
			base.Ai.ReachOrgasm(Count.OrgTyp.Aibu, !inside);
			if (Anim.isSpSrv)
			{
				base.Partner1.Ai.ReachOrgasm(Count.OrgTyp.Aibu, !inside);
			}
			PlayAndSetParticularities(inside ? State.IN_Start : State.M_OUT_Start);
			yield return (object)new WaitForSeconds(Time.deltaTime);
			yield return (object)new WaitForSeconds(ChaTools.StateDuration(base.Ai.Cha));
			excitation = 5f;
			PlayAndSetParticularities(inside ? State.IN_Loop : State.M_OUT_Loop);
			inside = CurState == State.IN_Loop && inside;
			if (inside && Settings.AddSiruOnTong)
			{
				CtrlTongSiru.GetOrCreate(base.Partner1.Ai.Cha);
			}
			if (!inside)
			{
				ChaTools.AddSiruOnCha(base.Partner1.Ai.Cha, Anim.siruFlags);
			}
			yield return (object)new WaitForSeconds(Random.Range(3.5f, 5f));
			GuestAction.SetActionEvent(base.Ai, 0.5f);
			if (inside)
			{
				PlayAndSetParticularities(State.Oral_Idle_IN);
				yield return (object)new WaitForSeconds(Time.deltaTime);
				yield return (object)new WaitForSeconds((CurState == State.Idle) ? 0f : ChaTools.StateDuration(base.Ai.Cha));
				PlayAndSetParticularities(State.Oral_Idle);
				yield return (object)new WaitForSeconds((CurState == State.Idle) ? 0f : Random.Range(1.5f, 2.5f));
				bool drink = Random.Range(0f, 100f) > 40f;
				PlayAndSetParticularities(drink ? State.Drink_IN : State.Vomit_IN);
				yield return (object)new WaitForSeconds(Time.deltaTime);
				yield return (object)new WaitForSeconds((CurState == State.Idle) ? 0f : ChaTools.StateDuration(base.Ai.Cha));
				PlayAndSetParticularities(drink ? State.Drink : State.Vomit);
				yield return (object)new WaitForSeconds(Time.deltaTime);
				yield return (object)new WaitForSeconds((CurState == State.Idle) ? 0f : ChaTools.StateDuration(base.Ai.Cha));
				PlayAndSetParticularities(drink ? State.Drink_A : State.Vomit_A);
			}
			else if (CurState != State.Idle)
			{
				PlayAndSetParticularities(State.OUT_A);
			}
			yield return (object)new WaitForSeconds((CurState == State.Idle) ? 1f : Random.Range(2.5f, 3.75f));
			yield return (object)new WaitForEndOfFrame();
			inFinish = false;
			if (!startByUser)
			{
				DetachPartners();
			}
			else
			{
				((MonoBehaviour)this).StartCoroutine(IE_Start());
			}
		}

		private void GetAvailableAnims()
		{
			List<HAnims.AnimInfo> list = new List<HAnims.AnimInfo>();
			if (bindFamilyAtStart == Binders.Family.Undefined || bindFamilyAtStart == Binders.Family.Lay)
			{
				foreach (HAnims.AnimInfo hAnimInfo in Core.dealer.HCtrl.HAnimInfos)
				{
					bool flag = hAnimInfo.isSpSrv && (hAnimInfo.plugName.Contains("Lay_Finger") || (base.Ai.IsBoy && base.Partner1.Ai.IsBoy));
					if (hAnimInfo.ctx == HAnims.Context.Service && hAnimInfo.plugName.Contains("Lay") && string.IsNullOrEmpty(hAnimInfo.animList.paramFemale1.path.file) && !flag)
					{
						list.Add(hAnimInfo);
					}
				}
				foreach (HAnims.AnimInfo hAnimInfo2 in Core.dealer.HCtrl.HAnimInfos)
				{
					bool flag2 = hAnimInfo2.isSpSrv && (hAnimInfo2.plugName.Contains("Lay_Finger") || (base.Ai.IsBoy && base.Partner1.Ai.IsBoy));
					if (hAnimInfo2.ctx == HAnims.Context.Service && hAnimInfo2.plugName.Contains("Stand") && string.IsNullOrEmpty(hAnimInfo2.animList.paramFemale1.path.file) && !flag2)
					{
						list.Add(hAnimInfo2);
					}
				}
			}
			else
			{
				List<string> keywords = new List<string>();
				if (bindFamilyAtStart == Binders.Family.Sit)
				{
					keywords = new List<string> { "Sit", "Toilet" };
				}
				if (bindFamilyAtStart == Binders.Family.Desk)
				{
					keywords = new List<string> { "Desk" };
				}
				if (bindFamilyAtStart == Binders.Family.Wall)
				{
					keywords = new List<string> { "Wall", "Fence", "Train" };
				}
				foreach (HAnims.AnimInfo hAnimInfo3 in Core.dealer.HCtrl.HAnimInfos)
				{
					bool isSpSrv = hAnimInfo3.isSpSrv;
					if (hAnimInfo3.ctx == HAnims.Context.Service && Helper.IsWordContainsGivenWords(hAnimInfo3.plugName, keywords) && string.IsNullOrEmpty(hAnimInfo3.animList.paramFemale1.path.file) && !isSpSrv)
					{
						list.Add(hAnimInfo3);
					}
				}
			}
			foreach (HAnims.AnimInfo item in list)
			{
				if (item.animList.kindHoushi == 0 && !item.plugName.Contains("Foot") && !item.plugName.Contains("Hump"))
				{
					handjobs.Add(item);
				}
				if (item.animList.kindHoushi == 0 && item.plugName.Contains("Foot"))
				{
					footjobs.Add(item);
				}
				if (item.animList.kindHoushi == 0 && item.plugName.Contains("Hump"))
				{
					humpjobs.Add(item);
				}
				if (item.animList.kindHoushi == 1)
				{
					mouthjobs.Add(item);
				}
				if (item.animList.kindHoushi == 2)
				{
					boobsjobs.Add(item);
				}
			}
			otherjobs.AddRange(handjobs);
			otherjobs.AddRange(footjobs);
			otherjobs.AddRange(humpjobs);
		}

		private static string BundleFromAnimInfo(HAnims.AnimInfo info, bool isMale = false)
		{
			if (isMale)
			{
				return info.animList.pathMaleBase.assetpath + ":" + info.animList.paramMale.path.assetpath;
			}
			return info.animList.pathFemaleBase.assetpath + ":" + info.animList.paramFemale.path.assetpath;
		}

		private static string AssetFromAnimInfo(HAnims.AnimInfo info, bool isMale = false)
		{
			if (isMale)
			{
				return "khh_m_base/" + info.animList.paramMale.path.file;
			}
			return "khh_f_base/" + info.animList.paramFemale.path.file;
		}

		public override List<HAnims.AnimInfo> GetAvailableAnimInfos()
		{
			if (!base.IsLeader)
			{
				return base.Leader.GetAvailableAnimInfos();
			}
			List<HAnims.AnimInfo> list = new List<HAnims.AnimInfo>();
			list.AddRange(footjobs);
			list.AddRange(handjobs);
			list.AddRange(humpjobs);
			list.AddRange(boobsjobs);
			list.AddRange(mouthjobs);
			list.AddRange(otherjobs);
			return list;
		}

		public static Service ActionAs(GuestAction guestAction)
		{
			return guestAction as Service;
		}
	}
	public class SpecialMove : GuestAction
	{
		private Animations.Clip curClip = Animations.Clip.Dance_01;

		private Vector2[] headAnimCtrlranges;

		public int loops = -1;

		private static float randomStart;

		public override void LateUpdate()
		{
			//IL_001a: Unknown result type (might be due to invalid IL or missing references)
			//IL_001f: Unknown result type (might be due to invalid IL or missing references)
			if (isInit)
			{
				AnimatorStateInfo currentAnimatorStateInfo = ((ChaInfo)base.Ai.Cha).animBody.GetCurrentAnimatorStateInfo(0);
				float normalizedTime = ((AnimatorStateInfo)(ref currentAnimatorStateInfo)).normalizedTime;
				for (int i = 0; i < headAnimCtrlranges.Length; i++)
				{
					base.Ai.Cha.ChangeLookNeckPtn((!(headAnimCtrlranges[i].x < normalizedTime) || !(normalizedTime < headAnimCtrlranges[i].y)) ? 1 : 3, 1f);
				}
				if (changePosDelay != 0f)
				{
					Helper.TimerToZero(ref changePosDelay);
				}
				runTimer += Time.unscaledDeltaTime;
				if (runTimer > voiceTime)
				{
					runTimer = 0f;
					voiceTime = Random.Range(6f, 13f);
					base.Ai.Face.Speak(((float)Random.Range(0, 100) > 40f) ? Voices.Type.Laught : Voices.Type.Comment);
				}
			}
		}

		public override void OnDestroy()
		{
			base.Ai.SetAnimTypAndClip(base.startAnimTyp, base.startAnimClip);
			((ChaInfo)base.Ai.Cha).animBody.speed = 1f;
			base.Ai.Cha.ChangeLookNeckPtn(1, 1f);
		}

		private IEnumerator IE_WaitEndAndReplay()
		{
			yield return (object)new WaitForSeconds(Time.deltaTime);
			float num = ChaTools.StateDuration(base.Ai.Cha) - Time.deltaTime;
			yield return (object)new WaitForSeconds(num);
			if (!Animations.perfectLoop.Contains(curClip))
			{
				yield return (object)new WaitForSeconds(2f);
			}
			loops = ((loops == -1) ? (-1) : Mathf.Max(loops - 1, 0));
			if (loops != 0)
			{
				PlayAnimState(Animations.GetStateFromClip(curClip).ToString(), addSizePrefix: false);
				((MonoBehaviour)this).StartCoroutine(IE_WaitEndAndReplay());
			}
			else
			{
				Object.Destroy((Object)(object)this);
			}
		}

		public override void NextPosition(bool changeTyp, bool backward)
		{
			if (!inFinish && changePosDelay == 0f)
			{
				List<Animations.Clip> availableAnimClips = GetAvailableAnimClips();
				Animations.Clip next = (backward ? Helper.PrevInList(availableAnimClips, base.Ai.AnimClip) : Helper.NextInList(availableAnimClips, base.Ai.AnimClip));
				ChangeAnimation(next);
				changePosDelay = 0.5f;
			}
		}

		private void ChangeAnimation(Animations.Clip next)
		{
			((MonoBehaviour)this).StopAllCoroutines();
			curClip = next;
			base.Ai.SetAnimTypAndClip(Animations.GetTypFromClip(curClip), curClip);
			base.Ai.ChaCore.CtrlIK.SetWeightsToZero();
			headAnimCtrlranges = Animations.RangesThatLeadHead(Animations.GetAssetNameFromClip(curClip));
			((MonoBehaviour)this).StartCoroutine(IE_WaitEndAndReplay());
		}

		public override void SetGuestActionMenuPose(MenuChara.PoseInfo posInfo)
		{
			ChangeAnimation(posInfo.clip);
		}

		public void SetClip(Animations.Clip clip, int loopRepeat = -1)
		{
			curClip = clip;
			if (loopRepeat != -1)
			{
				loops = loopRepeat;
			}
		}

		public override List<Animations.Clip> GetAvailableAnimClips()
		{
			return SpActionClipList();
		}

		public static List<Animations.Clip> SpActionClipList()
		{
			List<Animations.Clip> clipListFromTyp = Animations.GetClipListFromTyp(Animations.Type.Dance);
			clipListFromTyp.AddRange(Animations.GetClipListFromTyp(Animations.Type.Stretch));
			return clipListFromTyp;
		}

		public override void Init()
		{
			((MonoBehaviour)this).StartCoroutine(IE_Init());
		}

		public override IEnumerator IE_Init()
		{
			randomStart = Helper.RandomChance(randomStart);
			yield return (object)new WaitForSeconds(randomStart / 300f);
			ChangeAnimation(curClip);
			((MonoBehaviour)this).StartCoroutine(IE_WaitEndAndReplay());
			isInit = true;
		}

		public static SpecialMove ActionAs(GuestAction guestAction)
		{
			return guestAction as SpecialMove;
		}
	}
	public class Strip : GuestAction
	{
		public enum StripTyp
		{
			Strip,
			Redress
		}

		public bool doTop;

		public bool doBot;

		public StripTyp stripTyp;

		public override void OnDestroy()
		{
			base.Ai.SetAnimTypAndClip(base.startAnimTyp, base.startAnimClip);
			((ChaInfo)base.Ai.Cha).animBody.speed = 1f;
			base.Ai.EvFlags.strip = false;
			if (base.Ai.InHomeAtcion)
			{
				base.Ai.homeActions.ResetActionTimeAndLimit(5f, 10f);
				((MonoBehaviour)base.Ai.homeActions).StartCoroutine(base.Ai.homeActions.IE_ForceAnimState());
			}
		}

		private IEnumerator IE_DoStripTease(float waitAtStart, bool top, bool bottom)
		{
			base.Ai.EvFlags.strip = true;
			List<int> available = Clothes.GetAvailables(base.Ai.Cha);
			float partInbetween = 1f;
			yield return (object)new WaitForSeconds(waitAtStart);
			if (top)
			{
				if (available.Contains(0) && Clothes.GetState(base.Ai.Cha, 0) != 3)
				{
					base.Ai.ApplyAnimClip(Animations.Clip.StripTop_01, fade: false);
					yield return (object)new WaitForSeconds(1.25f);
					while (Clothes.GetState(base.Ai.Cha, 0) != 3)
					{
						base.Ai.Cha.SetClothesStateNext(0);
						yield return (object)new WaitForSeconds(partInbetween);
					}
				}
				if (available.Contains(2) && Clothes.GetState(base.Ai.Cha, 2) != 3)
				{
					base.Ai.ApplyAnimClip(Animations.Clip.StripBra_01, fade: false);
					yield return (object)new WaitForSeconds(1.75f);
					while (Clothes.GetState(base.Ai.Cha, 2) != 3)
					{
						base.Ai.Cha.SetClothesStateNext(2);
						yield return (object)new WaitForSeconds(partInbetween);
					}
				}
			}
			if (bottom)
			{
				AnimatorStateInfo currentAnimatorStateInfo;
				if (available.Contains(8) && Clothes.GetState(base.Ai.Cha, 8) == 0)
				{
					base.Ai.ApplyAnimClip(Animations.Clip.PeepShower_01, fade: false);
					Animator animBody = ((ChaInfo)base.Ai.Cha).animBody;
					currentAnimatorStateInfo = ((ChaInfo)base.Ai.Cha).animBody.GetCurrentAnimatorStateInfo(0);
					animBody.Play(((AnimatorStateInfo)(ref currentAnimatorStateInfo)).fullPathHash, 0, 0.5f);
					yield return (object)new WaitForSeconds(2f);
					base.Ai.Cha.SetClothesState(8, (byte)3, true);
					yield return (object)new WaitForSeconds(2f);
				}
				if (available.Contains(5) && Clothes.GetState(base.Ai.Cha, 5) != 3)
				{
					base.Ai.ApplyAnimClip(Animations.Clip.StripBot_01, fade: false);
					Animator animBody2 = ((ChaInfo)base.Ai.Cha).animBody;
					currentAnimatorStateInfo = ((ChaInfo)base.Ai.Cha).animBody.GetCurrentAnimatorStateInfo(0);
					animBody2.Play(((AnimatorStateInfo)(ref currentAnimatorStateInfo)).fullPathHash, 0, 0.5f);
					yield return (object)new WaitForSeconds(0.75f);
					while (Clothes.GetState(base.Ai.Cha, 5) != 3)
					{
						base.Ai.Cha.SetClothesStateNext(5);
						yield return (object)new WaitForSeconds(partInbetween);
					}
				}
				if (available.Contains(1) && Clothes.GetState(base.Ai.Cha, 1) == 0)
				{
					base.Ai.ApplyAnimClip(Animations.Clip.StripBot_01, fade: false);
					yield return (object)new WaitForSeconds(1.5f);
					int rt = 0;
					while (Clothes.GetState(base.Ai.Cha, 1) != 3)
					{
						base.Ai.Cha.SetClothesStateNext(1);
						yield return (object)new WaitForSeconds(partInbetween);
						int num = rt + 1;
						rt = num;
						if (rt > 3)
						{
							break;
						}
					}
				}
				if (available.Contains(3) && Clothes.GetState(base.Ai.Cha, 3) != 3)
				{
					base.Ai.ApplyAnimClip(Animations.Clip.PeepShower_01, fade: false);
					Animator animBody3 = ((ChaInfo)base.Ai.Cha).animBody;
					currentAnimatorStateInfo = ((ChaInfo)base.Ai.Cha).animBody.GetCurrentAnimatorStateInfo(0);
					animBody3.Play(((AnimatorStateInfo)(ref currentAnimatorStateInfo)).fullPathHash, 0, 0.35f);
					yield return (object)new WaitForSeconds(0.5f);
					while (Clothes.GetState(base.Ai.Cha, 3) != 3)
					{
						base.Ai.Cha.SetClothesStateNext(3);
						yield return (object)new WaitForSeconds(partInbetween);
					}
				}
			}
			yield return (object)new WaitForSeconds(partInbetween);
			yield return (object)new WaitForSeconds(1f);
			base.Ai.EvFlags.strip = false;
			Object.Destroy((Object)(object)this);
		}

		private IEnumerator IE_DoRedress(float waitAtStart, bool top, bool bottom)
		{
			base.Ai.EvFlags.strip = true;
			List<int> available = Clothes.GetAvailables(base.Ai.Cha);
			float partInbetween = 1f;
			yield return (object)new WaitForSeconds(waitAtStart);
			if (bottom && available.Contains(3) && Clothes.GetState(base.Ai.Cha, 3) != 0)
			{
				base.Ai.ApplyAnimClip(Animations.Clip.RedressBot_01, fade: false);
				yield return (object)new WaitForSeconds(1f);
				while (Clothes.GetState(base.Ai.Cha, 3) != 0)
				{
					base.Ai.Cha.SetClothesStatePrev(3);
					yield return (object)new WaitForSeconds(partInbetween);
