		private IEnumerator IE_Finish()
		{
			inFinish = true;
			((ChaInfo)base.Ai.Cha).animBody.speed = 1f;
			base.Ai.EvFlags.actionEvent = true;
			base.Ai.ReachOrgasm(Count.OrgTyp.Aibu);
			CurState = State.Orgasm_Start;
			PlayAnimState(StateToString(CurState));
			yield return (object)new WaitForSeconds(Time.deltaTime);
			AnimatorStateInfo currentAnimatorStateInfo = ((ChaInfo)base.Ai.Cha).animBody.GetCurrentAnimatorStateInfo(0);
			yield return (object)new WaitForSeconds(((AnimatorStateInfo)(ref currentAnimatorStateInfo)).length);
			excitation = 0f;
			CurState = State.Orgasm_Loop;
