			if (((ChaInfo)base.Ai.Cha).fileParam.personality == 8)
			{
				loopNumber = Random.Range(4, 7);
			}
			while (loopNumber > 0)
			{
				DebugInfos.InConsole("Running loop " + loopNumber);
				PlayAnimState(StateToString(CurState));
				yield return (object)new WaitForSeconds(Time.deltaTime);
				currentAnimatorStateInfo = ((ChaInfo)base.Ai.Cha).animBody.GetCurrentAnimatorStateInfo(0);
				yield return (object)new WaitForSeconds(((AnimatorStateInfo)(ref currentAnimatorStateInfo)).length);
				loopNumber--;
