			CurState = State.Orgasm_A;
			PlayAnimState(StateToString(CurState));
			yield return (object)new WaitForSeconds(Random.Range(1.5f, 2.5f));
			base.Ai.EvFlags.actionEvent = true;
			excitation = base.Ai.MinEx;
