				yield break;
			}
			CurState = State.Idle;
			PlayAnimState(StateToString(CurState));
		}

		private string GetSubString()
		{
			string result = string.Empty;
			List<string> value = new List<string>();
			if (Animations.BundleDictionary().TryGetValue(base.Ai.AnimClip, out value))
			{
				result = Helper.GetStringAtIndex(value[3], "_", 2);
			}
			return result;
		}

		private string StateToString(State state)
		{
			return (new List<State>
			{
				State.Idle,
				State.Touch,
				State.Loop
			}.Contains(state) ? (subString + "_") : "") + state;
		}

		public override List<Animations.Clip> GetAvailableAnimClips()
		{
			return Animations.GetClipListFromTyp(Animations.Type.Tease);
		}

		public override void NextPosition(bool changeTyp, bool backward)
		{
			if (!inFinish && changePosDelay == 0f)
			{
				List<Animations.Clip> clipListFromTyp = Animations.GetClipListFromTyp(Animations.Type.Tease);
				Animations.Clip next = (backward ? Helper.PrevInList(clipListFromTyp, base.Ai.AnimClip) : Helper.NextInList(clipListFromTyp, base.Ai.AnimClip));
				ChangeAnimation(next);
				changePosDelay = 0.5f;
			}
		}

		private void ChangeAnimation(Animations.Clip next)
		{
			base.Ai.ApplyAnimClip(next);
			subString = GetSubString();
			PlayAnimState(StateToString(CurState));
			AdaptNeck();
		}

		public override void SetGuestActionMenuPose(MenuChara.PoseInfo posInfo)
		{
			ChangeAnimation(posInfo.clip);
		}

		public override void Init()
		{
			Animations.Clip clip = Animations.Clip.Tease_05;
			if (base.startAnimTyp == Animations.Type.Crouch)
			{
				clip = Helper.RandomInList(new List<Animations.Clip>
				{
					Animations.Clip.Tease_01,
					Animations.Clip.Tease_02
				});
			}
			base.Ai.SetAnimTypAndClip(Animations.Type.Tease, clip);
			subString = GetSubString();
			((MonoBehaviour)this).StartCoroutine(IE_PlayTouch());
			isInit = true;
		}

		private IEnumerator IE_PlayTouch()
		{
			CurState = State.Touch;
			PlayAnimState(StateToString(CurState));
			yield return (object)new WaitForSeconds(Time.deltaTime);
			AnimatorStateInfo currentAnimatorStateInfo = ((ChaInfo)base.Ai.Cha).animBody.GetCurrentAnimatorStateInfo(0);
			float length = ((AnimatorStateInfo)(ref currentAnimatorStateInfo)).length;
			yield return (object)new WaitForSeconds(length);
			CurState = State.Idle;
			PlayAnimState(StateToString(CurState));
		}
	}
