			WatchOLoop,
			WatchOrg,
			ComOrg,
			AimChange,
			Kiss,
			AfterKiss,
			ActionEvent
		}

		public class EventTracer
		{
			public bool strip;

			public bool touch;

			public bool kiss;

			public bool endKiss;

			public bool swap;

			public bool noSwap;

			public bool afterSwap;

			public bool actionEvent;

			public float lastAimChange = 7f;

			public float startPoseTimer = 3f;

			public bool _inGrab;

			public bool inGrab;

			public GuestAction gAction;

			public EventType curEvent;

			public HAnims.State _hState;
		}

		public enum Choice
		{
			MgStart,
			MgSpeedChange,
			MgMotionChange,
			MgSwap,
			MgPosChange,
			MgPull,
			MgWin,
			MgOralChoice,
			GgMast,
			GgDoLez,
