			public List<Animations.Clip> thinkableClips = new List<Animations.Clip>();
		}

		public const string className = "AIManage";

		public const bool debugChoices = true;

		public static List<EventType> OnlyRunOnceEvents = new List<EventType>
		{
			EventType.Touch,
			EventType.Grab,
			EventType.Release,
			EventType.AfterKiss,
			EventType.AfterSwap,
			EventType.RefuseSwap,
			EventType.AimChange,
			EventType.ActionEvent,
			EventType.WatchOLoop,
			EventType.WatchOrg
		};

		public static EventType ParseEventTracer(EventTracer evFlag, AI ai)
		{
			evFlag.gAction = ai.gAction;
			bool flag = (Object)(object)evFlag.gAction != (Object)null;
			if (evFlag.startPoseTimer != 0f)
			{
				Helper.TimerToZero(ref evFlag.startPoseTimer);
				return EventType.Hello;
			}
			if (evFlag.strip)
			{
				return EventType.Strip;
			}
			if (evFlag.noSwap)
			{
				evFlag.noSwap = false;
				return EventType.RefuseSwap;
			}
			if (evFlag.actionEvent)
			{
				evFlag.actionEvent = false;
				return EventType.ActionEvent;
			}
			if (evFlag.afterSwap)
			{
				evFlag.afterSwap = false;
				return EventType.AfterSwap;
			}
			if (evFlag.swap)
			{
				return EventType.Swap;
			}
			if (evFlag.kiss)
			{
				return EventType.Kiss;
			}
			if (evFlag.endKiss)
			{
				evFlag.endKiss = false;
				evFlag.lastAimChange = 4f;
				return EventType.AfterKiss;
			}
			if (evFlag.touch)
			{
				evFlag.touch = false;
				return EventType.Touch;
			}
			evFlag.inGrab = ai.InBoobsGrab || ai.InButtGrab;
			if (evFlag.inGrab != evFlag._inGrab)
			{
				EventType result = EventType.None;
				if (evFlag.inGrab && !evFlag._inGrab)
				{
					result = EventType.Grab;
				}
				if (!evFlag.inGrab && evFlag._inGrab)
				{
					result = EventType.Release;
				}
				evFlag._inGrab = evFlag.inGrab;
				return result;
			}
			if (evFlag._hState != Core.dealer.HState)
			{
				evFlag._hState = Core.dealer.HState;
				if (!flag)
				{
					if (Core.dealer.HState == HAnims.State.OLoop)
					{
						return EventType.WatchOLoop;
					}
					if (HAnims.IsOrgasm(Core.dealer.HState))
					{
						return EventType.WatchOrg;
					}
					return EventType.StateChange;
				}
			}
			if (evFlag.lastAimChange != 0f)
			{
				Helper.TimerToZero(ref evFlag.lastAimChange);
			}
			if (evFlag.lastAimChange == 0f)
			{
				evFlag.lastAimChange = Random.Range(4.5f, 7f);
				return EventType.AimChange;
			}
			return EventType.None;
		}

		public static bool DoChoice(AI ai, Choice choice, float chanceTrigger = 100f)
		{
			ai.Mind.actChanceDraw = Helper.RandomChance(ai.Mind.actChanceDraw);
			DebugInfos.InConsoleCompact(" " + ChaCore.Name(((ChaInfo)ai.Cha).fileParam) + " choice(" + choice.ToString() + ") actChanceDraw is : " + ai.Mind.actChanceDraw, "AIManage.DoChoice");
			if (chanceTrigger != 100f && ai.Mind.actChanceDraw > chanceTrigger)
			{
				DebugInfos.InConsoleCompact("\t" + choice.ToString() + " failed. trigger is : " + chanceTrigger, "AIManage.DoChoice");
				return false;
			}
			DebugInfos.InConsoleCompact("\t" + choice.ToString() + " succeded at trigger : " + chanceTrigger, "AIManage.DoChoice");
			switch (choice)
			{
			case Choice.MgStart:
				if (ai.HCtx == HAnims.Context.Service)
				{
					HAction.HFlagClick((ClickKind)((ai.HFlag.nowAnimStateName.Contains("Stop") || ai.HFlag.nowAnimStateName.Contains("_A")) ? 14 : 5), voiceStop: true);
				}
				if (ai.HCtx == HAnims.Context.Piston)
				{
					((MonoBehaviour)ai).StartCoroutine(AIMain.IE_AutoStartPiston(ai));
				}
				break;
			case Choice.MgMotionChange:
				HAction.HFlagClick((ClickKind)6);
				break;
			case Choice.MgPull:
				HAction.HFlagClick((ClickKind)13, voiceStop: true);
				break;
			case Choice.MgSpeedChange:
				HManage.HSpeedChanger.Create();
				break;
			case Choice.MgOralChoice:
				HAction.HFlagClick((ClickKind)((ai.Mind.actChanceDraw > 45f) ? 11 : 12), voiceStop: true);
				break;
			case Choice.MgSwap:
			{
				List<AIGuest> availableGirlForSwap = HManage.GetAvailableGirlForSwap();
				if (availableGirlForSwap.Count == 0)
				{
					return false;
				}
				((MonoBehaviour)ai).StartCoroutine(AIMain.IE_AutoSwap(ai, Helper.RandomInList(availableGirlForSwap)));
				break;
			}
			case Choice.MgPosChange:
			{
				List<Enums.ChainTyp> list = new List<Enums.ChainTyp>();
				if (Random.Range(0f, 100f) < 50f)
				{
					list = new List<Enums.ChainTyp>
					{
						Enums.ChainTyp.SrvFoot,
						Enums.ChainTyp.SrvBreast,
						Enums.ChainTyp.SrvHump,
						Enums.ChainTyp.SrvMouth,
						Enums.ChainTyp.SrvHand
					};
				}
				else
				{
					list = new List<Enums.ChainTyp>
					{
						Enums.ChainTyp.Vagina,
						Enums.ChainTyp.Anal
					};
					if (Settings.MgFavoriteHole > 50)
					{
						list = new List<Enums.ChainTyp> { Enums.ChainTyp.Anal };
					}
				}
				((MonoBehaviour)ai).StartCoroutine(AIMain.IE_AutoChangePosition(ai, Helper.RandomInList(list)));
				break;
			}
			case Choice.MgWin:
				((MonoBehaviour)ai).StartCoroutine(AIMain.IE_AutoBoyOrgasm(ai));
				break;
			case Choice.GgMast:
				ai.gAction = GuestAction.Create(ai as AIGuest, GuestAction.Type.Mast);
				break;
			case Choice.GgDoLez:
			{
				List<AIGuest> availableForLesbian = HManage.GetAvailableForLesbian(ai as AIGuest);
				if (availableForLesbian.Count == 0 || ai.IsCloseFromMBoy)
				{
					return false;
				}
				((MonoBehaviour)ai).StartCoroutine(AIGuest.IE_StartGuestsRelation(ai as AIGuest, Helper.RandomInList(availableForLesbian), GuestAction.Type.Lesbian));
				break;
			}
			case Choice.GgDoSp:
			{
				bool flag = AIGuest.AIasGuest(ai).AnimTyp == Animations.Type.Crouch;
				if (ai.IsCloseFromMBoy && flag)
				{
					return false;
				}
				if (ai.Mind.thinkableClips.Count == 0)
				{
					ai.Mind.thinkableClips.AddRange(Animations.thinkableSpMove);
				}
				ai.Mind.thinkableClips.Shuffle();
				Animations.Clip clip = Helper.RandomInList(ai.Mind.thinkableClips);
				if (ai.IsCloseFromMBoy && (clip == Animations.Clip.Stretch_01 || clip == Animations.Clip.Dance_03))
				{
					ai.Mind.thinkableClips.Clear();
					ai.Mind.thinkableClips.AddRange(Animations.thinkableSpMove);
					ai.Mind.thinkableClips.Remove(Animations.Clip.Stretch_01);
					ai.Mind.thinkableClips.Remove(Animations.Clip.Dance_03);
					clip = Animations.Clip.Stretch_04;
				}
				int loopRepeat = 1;
				if (clip == Animations.Clip.Stretch_03)
				{
					loopRepeat = Random.Range(1, 3);
				}
				if (clip == Animations.Clip.Stretch_04)
				{
					loopRepeat = Random.Range(2, 4);
				}
				if (clip == Animations.Clip.Dance_05 || clip == Animations.Clip.Dance_03)
				{
					loopRepeat = Random.Range(2, 5);
				}
				ai.gAction = GuestAction.Create(ai as AIGuest, GuestAction.Type.SpMove);
				SpecialMove.ActionAs(ai.gAction).SetClip(clip, loopRepeat);
				ai.Mind.thinkableClips.Remove(clip);
				break;
			}
			}
			ai.Mind.act = choice;
			if (new List<Choice>
			{
				Choice.MgPosChange,
				Choice.MgSwap
			}.Contains(choice))
			{
				((MonoBehaviour)ai).StartCoroutine(ai.IE_LimitChoice());
			}
			DebugInfos.InConsole(" Confirm " + ChaCore.Name(((ChaInfo)ai.Cha).fileParam) + " choice : " + choice, "AIManage.DoChoice");
			return true;
		}
	}
