		public override void Start()
		{
			DebugInfos.InConsole(" Started on " + ((ChaInfo)base.ChaCore.Cha).fileParam.fullname, "AIGuest");
			EvFlags = new AIS.EventTracer();
			GuestTyp = ((base.ChaCore.Sex != ChaCore.Gender.Girl) ? GuestType.Boy : GuestType.Girl);
			if (GuestTyp == GuestType.Boy)
			{
				DefineBoyPersonality();
			}
			((MonoBehaviour)this).StartCoroutine(IE_Init());
			AnimItems = new List<Item>();
		}

		public override void LateUpdate()
		{
			if (!IsInit)
			{
				return;
			}
			if (AIS.OnlyRunOnceEvents.Contains(EvFlags.curEvent))
			{
				if (EvFlags.curEvent == AIS.EventType.WatchOrg)
				{
					IncreaseExcitation(Random.Range(20f, 45f) / 10f, 95f);
				}
				EvFlags.curEvent = AIS.EventType.None;
			}
			AIS.EventType eventType = AIS.ParseEventTracer(EvFlags, this);
			if (EvFlags.curEvent != eventType && eventType != AIS.EventType.None)
			{
				EvFlags.curEvent = eventType;
			}
			if (InKiss && GuestTyp == GuestType.Girl)
			{
				if (Core.dealer.mInfos.mmbShortPress)
				{
					AskForSwap();
				}
				IncreaseExcitation(Core.dealer.mInfos.dragLenght * Time.deltaTime * 5f, 95f, ChaTools.Part.Head);
			}
			if (excitation < minEx)
			{
				excitation = minEx;
			}
			breath.active = !base.InAction && !CreatedByCtrlHome;
			if (!CreatedByCtrlHome && !CreatedByEstCtrl)
			{
				AutoThink();
			}
			if (GuestTyp == GuestType.Girl)
			{
				PlayBodySound();
			}
			if (changePosDelay != 0f)
			{
				Helper.TimerToZero(ref changePosDelay);
			}
			if (!Core.dealer.InStory || !Core.dealer.ecchiEndByTresspass || Core.dealer.Ctx == Dealer.Context.H || !(Core.dealer.Scenario == "penetration_heroine"))
			{
				return;
			}
			HScene instance = Singleton<HScene>.Instance;
			if (!((Object)(object)instance != (Object)null))
			{
				return;
			}
			foreach (Heroine item in instance.GetFieldValue<List<Heroine>>("heroineList"))
			{
				if (base.ChaCore.HSaveData != null && base.ChaCore.HSaveData == item && ((ChaInfo)base.Cha).visibleAll)
				{
					((ChaInfo)base.Cha).visibleAll = false;
				}
			}
		}

		public void ReachOrgasm(Count.OrgTyp typ, bool isOut = false)
		{
			if (CanSquirt(Enums.Squirts.PussyOrg))
			{
				Squirt(ChaTools.Part.Kokan);
			}
			if (CanSquirt(Enums.Squirts.BreastOrg))
			{
				Squirt(ChaTools.Part.BreastL);
				Squirt(ChaTools.Part.BreastR);
			}
			if (isOut && CanShoot())
			{
				GenitalBoy.Shoot(base.Cha);
			}
			if (base.InH)
			{
				Count.AddOrgasmToCount(base.ChaCore.HInfo.HCount, typ);
				CalcMinExcitation();
			}
		}

		private void CalcMinExcitation()
		{
			if (Settings.GirlExGain != 0 && Settings.GirlExMax != 0)
			{
				minEx = Mathf.Clamp((float)(Settings.GirlExGain * Count.GirlOrgasms(base.ChaCore.HInfo.HCount)), 0f, (float)Settings.GirlExMax);
			}
		}

		public void IncreaseExcitation(float incr, float max = 100f, ChaTools.Part part = ChaTools.Part.Undefined)
		{
			if (base.InAction)
			{
				gAction.AddToEx(incr, max);
			}
			else
			{
				excitation = ((excitation < max) ? (excitation + incr) : excitation);
			}
			if (part != ChaTools.Part.Undefined)
			{
				if (base.InH)
				{
					Count.AddExpToCount(base.ChaCore.HInfo.HCount, incr, part);
				}
				else if (Core.dealer.InStory)
				{
					Count.AddExpToSav(ChaCore.TryToGetSaveFromChaCore(((Component)base.Cha).gameObject), incr, part);
				}
			}
		}

