		public bool CanSwap()
		{
			if (Core.dealer.InProcess || GuestTyp == GuestType.Boy)
			{
				return false;
			}
			if (Core.dealer.Ctx == Dealer.Context.Esthetic)
			{
				return true;
			}
			bool flag = false;
			if (base.HCtx == HAnims.Context.Tease || base.HCtx == HAnims.Context.Peep)
			{
				flag = base.HState != HAnims.State.OrgF;
			}
			if (base.HCtx == HAnims.Context.Service)
			{
				flag = base.HState == HAnims.State.Idle || base.HState == HAnims.State.Motion || base.HState == HAnims.State.OLoop || base.HState == HAnims.State.OrgOUT || base.HState == HAnims.State.OrgM;
			}
			if (base.HCtx == HAnims.Context.Piston)
			{
				flag = base.HState == HAnims.State.Idle || base.HState == HAnims.State.OrgOUT || base.HState == HAnims.State.Drop || base.HState == HAnims.State.Motion || base.HState == HAnims.State.OrgIdle || base.HState == HAnims.State.InsertIdle || base.HState == HAnims.State.OrgBoth || base.HState == HAnims.State.OrgM;
			}
			bool flag2 = false;
			if (base.InAction && flag)
			{
				if (gAction.Typ == GuestAction.Type.Mast && !gAction.inFinish)
				{
					flag2 = true;
				}
				if (gAction.Typ == GuestAction.Type.Bound && !gAction.inFinish)
				{
					flag2 = true;
				}
				if (gAction.Typ == GuestAction.Type.Lesbian && !gAction.inFinish)
				{
					flag2 = true;
				}
				if (gAction.Typ == GuestAction.Type.Tease && !gAction.inFinish)
				{
					flag2 = true;
				}
				if (gAction.Typ == GuestAction.Type.Piston && !gAction.IsInOrgasmLoop())
				{
					flag2 = true;
				}
				if (gAction.Typ == GuestAction.Type.SpMove)
				{
					flag2 = true;
				}
				flag = flag2;
			}
			return flag;
		}

		public void NextPosition(bool changeTyp, bool backward = false)
		{
			if (base.InAction)
			{
				gAction.NextPosition(changeTyp, backward);
			}
			else if (changePosDelay == 0f)
			{
				changePosDelay = 0.33f;
				if (CreatedByCtrlHome && (Object)(object)homeActions != (Object)null)
				{
					homeActions.NextPosition(backward);
				}
				else if (!changeTyp)
				{
					List<Animations.Clip> clipListFromTyp = Animations.GetClipListFromTyp(AnimTyp, GuestTyp);
					AnimClip = (backward ? Helper.PrevInList(clipListFromTyp, AnimClip) : Helper.NextInList(clipListFromTyp, AnimClip));
					ApplyAnimClip();
				}
				else if (AnimTyp == Animations.Type.Stand)
				{
					ApplyAnimTyp(Animations.Type.Crouch);
				}
				else
				{
					_ = AnimTyp;
					_ = 2;
					ApplyAnimTyp(Animations.Type.Stand);
				}
			}
		}

		public void ResultPosition(bool positionCha = false)
		{
			//IL_003b: Unknown result type (might be due to invalid IL or missing references)
			if (AnimTyp != Animations.Type.Stand)
			{
				ApplyAnimTyp(Animations.Type.Stand);
			}
			if (positionCha)
			{
				WSpace.Contact contact = WSpace.SearchGuestPosAround();
				mover.SetContact(contact);
