		public void AdaptPositionToContact(WSpace.PosLevel posLevel)
		{
			if (!base.InAction)
			{
				if (posLevel == WSpace.PosLevel.Higher && AnimTyp != Animations.Type.Crouch)
				{
					ApplyAnimTyp(Animations.Type.Crouch);
				}
				if (posLevel == WSpace.PosLevel.Lower && AnimTyp != Animations.Type.Stand)
				{
					ApplyAnimTyp(Animations.Type.Stand);
				}
				if (posLevel == WSpace.PosLevel.Same)
				{
					AdaptAnimToHAnim();
				}
			}
		}

		public void AdaptAnimToHAnim()
		{
			if ((Object)(object)Core.dealer.HCtrl == (Object)null || base.InAction)
			{
				return;
			}
			if (Core.dealer.HCtrl.CurAnim.plugName.Contains("Lay"))
			{
				if (AnimTyp != Animations.Type.Crouch)
				{
					ApplyAnimTyp(Animations.Type.Crouch);
				}
			}
			else if (AnimTyp != Animations.Type.Stand)
			{
				ApplyAnimTyp(Animations.Type.Stand);
			}
		}

