		private void ApplyAnimClip(bool fade = true)
		{
			if (fade)
			{
				Cam.DoFade(0.1f);
			}
			AnimAsset = Animations.GetAssetNameFromClip(AnimClip);
			RemoveAnimItem();
			base.ChaCore.BoneCtrl.Reset();
			Animations.LoadAnim(base.Cha, AnimClip);
			ChaTools.SetDefaultAnimatorValue(base.Cha);
			Face.ApplyNeckOffsetOnPoseChange();
			if (!CreatedByCtrlHome)
			{
				base.ChaCore.CtrlIK.AssumeAnimGoalsAsTarget();
			}
			LoadAnimItem();
			Animations.ApplyCustomAnimClipOffsets(base.ChaCore.BoneCtrl, AnimClip);
			SetCtrlBonesOfst();
			if (CreatedByCtrlHome)
			{
				base.ChaCore.CtrlIK.SetAllWeights(0f);
			}
		}

		private void ApplyAnimAsset(string bundle, string asset, string state, bool fade = true)
		{
			if (fade)
			{
				Cam.DoFade(0.1f);
			}
			AnimAsset = asset;
			RemoveAnimItem();
			base.ChaCore.BoneCtrl.Reset();
			Animations.LoadAnim(base.Cha, bundle, asset, state);
			ChaTools.SetDefaultAnimatorValue(base.Cha);
			Face.ApplyNeckOffsetOnPoseChange();
			base.ChaCore.CtrlIK.AssumeAnimGoalsAsTarget();
			LoadAnimItem();
			SetCtrlBonesOfst();
		}

		public override void LoadAnimItem(string assetName = "")
		{
			AnimItems = GameAssets.CheckAndAddItemsToAnim(AnimAsset, base.Cha, 1);
		}

		private void SetCtrlBonesOfst(bool afterSwap = false)
		{
			if (base.InAction)
			{
				if (afterSwap)
				{
					gAction.AfterSwap();
				}
			}
			else if (base.Cha.GetShapeBodyValue(0) < 0f)
			{
				SizeOffsets.SearchAndSubscribe(base.Cha, SizeOffsets.ChaTyp.G1, AnimAsset);
			}
		}

		private void DefineBoyPersonality()
		{
			((ChaInfo)base.Cha).fileParam.personality = ((Settings.BoyParam == Settings.BoyParamDef.FromSave) ? ChaTools.GetBoyPersonality(ChaTools.BoyPersoParam(base.Cha)) : Helper.RandomInList(ChaTools.BoyAvailablePerso));
			((ChaInfo)base.Cha).fileParam.voiceRate = ((Settings.BoyParam == Settings.BoyParamDef.FromSave) ? ChaTools.GetBoyVoiceRate(ChaTools.BoyVoiceRateParam(base.Cha)) : (-0.2f));
		}

		private IEnumerator IE_Kiss()
		{
			EvFlags.kiss = true;
			((MonoBehaviour)Core.dealer).StartCoroutine(Core.dealer.IE_InGuestKiss(this));
			if (!base.InAction || (base.InAction && gAction.Typ == GuestAction.Type.Bound))
			{
				BodyReact.Create(base.Cha, BodyReact.Type.AutoLoop, 0);
			}
			CameraControl_Ver2 camCtrl = Object.FindObjectOfType<CameraControl_Ver2>();
			GlobalMethod.SetCameraMoveFlag(camCtrl, false);
			yield return (object)new WaitUntil((Func<bool>)(() => !Keys.LmbHold || !EvFlags.kiss));
			if (EvFlags.kiss)
			{
				EvFlags.endKiss = true;
			}
			EvFlags.kiss = false;
			GlobalMethod.SetCameraMoveFlag(camCtrl, true);
		}

		private IEnumerator IE_PullForSwap(AIGuest swapGuest)
		{
			pullForSwap = true;
			bool inOrgasm = base.HState == HAnims.State.OrgM || base.HState == HAnims.State.OrgBoth;
			string stateAtStart = base.HFlag.nowAnimStateName;
			bool isAnal = stateAtStart.Contains("A_") || base.HFlag.isAnalPlay;
