		public void AskToLeave()
		{
			if (Core.dealer.Ctx == Dealer.Context.Esthetic || Core.dealer.Ctx == Dealer.Context.EstResult)
			{
				return;
			}
			bool flag = false;
			if (Core.dealer.InStory && base.InH)
			{
				if (base.ChaCore.Typ != ChaCore.Type.Common)
				{
					flag = true;
				}
				if (base.InAction && gAction.IsGroup && ((Object.op_Implicit((Object)(object)gAction.Partner1) && gAction.Partner1.Ai.ChaCore.Typ != ChaCore.Type.Common) || (Object.op_Implicit((Object)(object)gAction.Partner2) && gAction.Partner2.Ai.ChaCore.Typ != ChaCore.Type.Common)))
				{
					flag = true;
				}
			}
			if (flag)
			{
				return;
			}
			if (base.InAction && gAction.IsGroup)
			{
				if (Object.op_Implicit((Object)(object)gAction.Partner1))
				{
					gAction.Partner1.Ai.DeleteGuest();
				}
				if (Object.op_Implicit((Object)(object)gAction.Partner2))
				{
					gAction.Partner2.Ai.DeleteGuest();
				}
			}
			if (base.InAction && gAction.Typ == GuestAction.Type.Bound)
			{
				gAction.Binder.SetFree();
			}
			DeleteGuest();
		}

