		public static IEnumerator IE_StartSoloAction(AIGuest aiGuest, GuestAction.Type actTyp, bool startByUser = false, float waitTimeAtStart = 0f)
		{
			yield return (object)new WaitForSeconds(waitTimeAtStart);
			Binders.Family binderFamily = Binders.Family.Undefined;
			Quaternion binderRotation = Quaternion.identity;
			if (aiGuest.InAction)
			{
				if (aiGuest.gAction.Typ == GuestAction.Type.Bound)
				{
					binderFamily = aiGuest.Binder.Family;
					binderRotation = aiGuest.Binder.Hook.rotation;
				}
				Object.Destroy((Object)(object)aiGuest.gAction);
				yield return (object)new WaitForSeconds(Time.deltaTime);
				aiGuest.DetachAttachedItems();
			}
			aiGuest.gAction = GuestAction.Create(aiGuest, actTyp);
			aiGuest.gAction.startByUser = startByUser;
			aiGuest.gAction.bindFamilyAtStart = binderFamily;
			aiGuest.gAction.bindRotAtStart = binderRotation;
		}

		public static IEnumerator IE_StartGuestsRelation(AIGuest aiGuest, AIGuest partner, GuestAction.Type relTyp, bool startByUser = false, ChaTools.Part targPart = ChaTools.Part.Undefined, AIGuest partner2 = null)
		{
			aiGuest.Mind.inExecute = true;
			partner.Mind.inExecute = true;
			Binders.Family binderFamily = Binders.Family.Undefined;
			Quaternion binderRotation = Quaternion.identity;
			if (aiGuest.InAction)
			{
				if (aiGuest.gAction.Typ == GuestAction.Type.Bound)
				{
					binderFamily = aiGuest.Binder.Family;
					binderRotation = aiGuest.Binder.Hook.rotation;
				}
				Object.Destroy((Object)(object)aiGuest.gAction);
				yield return (object)new WaitForSeconds(Time.deltaTime);
				aiGuest.DetachAttachedItems();
			}
			if (partner.InAction)
			{
				if (partner.gAction.Typ == GuestAction.Type.Bound)
				{
					binderFamily = partner.Binder.Family;
					binderRotation = partner.Binder.Hook.rotation;
				}
				if (partner.gAction.IsGroup)
				{
					partner.gAction.DetachPartners();
				}
				else
				{
					Object.Destroy((Object)(object)partner.gAction);
				}
				yield return (object)new WaitForSeconds(Time.deltaTime);
				partner.DetachAttachedItems();
			}
			aiGuest.gAction = GuestAction.Create(aiGuest, relTyp, partner, partner2);
			aiGuest.gAction.startByUser = startByUser;
			aiGuest.gAction.bindFamilyAtStart = binderFamily;
			aiGuest.gAction.bindRotAtStart = binderRotation;
			if (relTyp == GuestAction.Type.Serv && targPart != ChaTools.Part.Undefined)
			{
				Service obj = aiGuest.gAction as Service;
				int kindAtStart;
				switch (targPart)
				{
				default:
					kindAtStart = 0;
					break;
				case ChaTools.Part.Chest:
					kindAtStart = 5;
					break;
				case ChaTools.Part.Leg:
					kindAtStart = 4;
					break;
				case ChaTools.Part.Head:
					kindAtStart = 1;
					break;
				case ChaTools.Part.BreastL:
				case ChaTools.Part.BreastR:
					kindAtStart = 2;
					break;
				}
				obj.kindAtStart = kindAtStart;
			}
			aiGuest.Mind.inExecute = false;
			partner.Mind.inExecute = false;
		}

