		public void BreakAction(bool breakByUser = false)
		{
			if (!base.InAction)
			{
				return;
			}
			if (gAction.IsGroup)
			{
				gAction.DetachPartners(breakByUser);
			}
			if (IsBound)
			{
				gAction.Binder.DetachChara();
			}
			if (gAction.Typ == GuestAction.Type.Mast || gAction.Typ == GuestAction.Type.Strip || gAction.Typ == GuestAction.Type.SpMove)
			{
				Object.Destroy((Object)(object)gAction);
				if (gAction.Typ == GuestAction.Type.Mast && breakByUser)
				{
					excitation = 0f;
				}
			}
		}

