		private Setting VoiceSettings(VoiceType vTyp)
		{
			//IL_013d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0142: Unknown result type (might be due to invalid IL or missing references)
			//IL_0149: Unknown result type (might be due to invalid IL or missing references)
			//IL_0151: Unknown result type (might be due to invalid IL or missing references)
			//IL_0159: Unknown result type (might be due to invalid IL or missing references)
			//IL_016f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0188: Expected O, but got Unknown
			int personality = ((ChaInfo)base.Cha).fileParam.personality;
			string text = Voices.ParsePersoId(personality);
			string text2 = "c" + text;
			string text3 = ((personality >= 40) ? "70" : "00");
			string text4 = ((personality >= 40) ? "71" : "01");
			string text5 = "sound/data/pcm/";
			string text6 = string.Empty;
			string assetBundleName = string.Empty;
			if (vTyp == VoiceType.Kiss)
			{
				text6 = Helper.RandomInList((base.HFlag.gaugeFemale >= 70f) ? kissVoices_hiEx : kissVoices_lowEx);
				assetBundleName = text5 + text2 + "/h/" + text4 + ".unity3d";
			}
			if (vTyp == VoiceType.Laught)
			{
				text6 = Helper.RandomInList(laughtVoices);
			}
			if (vTyp == VoiceType.Yes)
			{
				text6 = Helper.RandomInList(yesVoices);
			}
			if (vTyp == VoiceType.Comment)
			{
				text6 = Helper.RandomInList(comVoices);
			}
			if (vTyp == VoiceType.Laught || vTyp == VoiceType.Yes || vTyp == VoiceType.Comment)
			{
				assetBundleName = text5 + text2 + "/adm/" + text3 + ".unity3d";
			}
			text6 = text6.Replace("99", text);
			DebugInfos.InConsole(" VoiceSettings : " + text6);
			return new Setting
			{
				no = personality,
				assetBundleName = assetBundleName,
				assetName = text6,
				pitch = ((ChaInfo)base.Cha).fileParam.voicePitch,
				voiceTrans = base.HFlag.transVoiceMouth[HFlagId]
			};
		}

