		public override IEnumerator IE_Init()
		{
			if (Core.dealer.InH)
			{
				yield return (object)new WaitUntil((Func<bool>)(() => (Object)(object)HCtrl.Get != (Object)null && HCtrl.Get.IsInit && ((ChaInfo)base.Cha).loadEnd && ((ChaInfo)base.Cha).visibleAll));
				if (Settings.DrawInfoInH)
				{
					string text = string.Empty;
					HCtrl get = HCtrl.Get;
					if (get.CurAnim.ctx == HAnims.Context.Tease || get.CurAnim.ctx == HAnims.Context.Service || get.CurAnim.ctx == HAnims.Context.Piston)
					{
						text = base.Name + " is ready for sex...";
					}
					if (get.CurAnim.ctx == HAnims.Context.Peep)
					{
						text = "Peeping on " + base.Name + "...";
					}
					HMsgToMessenger(text);
				}
				DebugInfos.InConsole("Initialized on " + base.Name + " in H", "AIMain");
			}
			else
			{
				yield return (object)new WaitUntil((Func<bool>)(() => ((ChaInfo)base.Cha).loadEnd && ((ChaInfo)base.Cha).visibleAll));
				DebugInfos.InConsole("Initialized on " + base.Name + " in " + Core.dealer.Ctx, "AIMain");
			}
			IsInit = true;
		}

