			if (get.HasSecondGirl && HManage.IsSecondMain())
			{
				AI component = ((Component)get.SecondGirl).GetComponent<AI>();
				if ((Object)(object)component != (Object)null && component.Mind != null)
				{
					return component.Mind.inExecute;
				}
			}
			AI component2 = ((Component)get.MainGirl).GetComponent<AI>();
			if ((Object)(object)component2 != (Object)null && component2.Mind != null)
			{
				return component2.Mind.inExecute;
			}
			return false;
		}

		public static IEnumerator IE_AutoStartPiston(AI ai)
		{
			ai.Mind.inExecute = true;
			if (!ai.DickIsIn())
			{
				ai.Mind.holeChanceDraw = Helper.RandomChance(ai.Mind.holeChanceDraw);
				if ((ai.Mind.holeChanceDraw < (float)Settings.MgFavoriteHole || Settings.MgFavoriteHole == 100) && ai.HAnim.hasAnal)
				{
					HAction.AnalInsert(askFor: false, checkVoiceWait: false, byPassFirstInsert: true);
				}
				else
				{
					HAction.Insert(askFor: false, checkVoiceWait: false, byPassFirstInsert: true);
				}
				yield return (object)new WaitUntil((Func<bool>)(() => ai.DickIsIn() && ai.HState != HAnims.State.Insert));
				yield return (object)new WaitForSeconds(0.5f);
			}
			yield return (object)new WaitForSeconds(0.75f);
			HAction.HFlagClick((ClickKind)28, voiceStop: true);
			ai.Mind.inExecute = false;
		}

		public static IEnumerator IE_AutoSwap(AI ai, AIGuest target)
		{
			ai.Mind.inExecute = true;
			yield return (object)new WaitForEndOfFrame();
			((MonoBehaviour)target).StartCoroutine(target.IE_Swap());
			yield return (object)new WaitUntil((Func<bool>)(() => !target.InSwap));
			ai.Mind.thinkDelay = Random.Range(2.5f, 4.5f);
			ai.Mind.inExecute = false;
		}

		public static IEnumerator IE_AutoBoyOrgasm(AI ai)
		{
			ai.Mind.inExecute = true;
			float num = ((ai.HCtx == HAnims.Context.Service && !HManage.IsInMouthService()) ? 0f : ((ai.HCtx == HAnims.Context.Service) ? 55f : 80f));
			HAction.HFlagClick((ClickKind)((Random.Range(0f, 100f) > num) ? 10 : 9), voiceStop: true);
			yield return (object)new WaitForSeconds(1.5f);
			yield return (object)new WaitUntil((Func<bool>)(() => !ai.HFlag.voiceWait));
			ai.Mind.thinkDelay = Random.Range(7f, 9f);
			ai.Mind.inExecute = false;
		}

		public static IEnumerator IE_AutoChangePosition(AI ai, Enums.ChainTyp posTyp)
		{
			ai.Mind.inExecute = true;
			HAnims.AnimInfo curAnim = HCtrl.Get.CurAnim;
			yield return (object)new WaitForEndOfFrame();
			if (MenuPose.ChainAnims(posTyp, isQuickChain: false))
			{
				yield return (object)new WaitUntil((Func<bool>)(() => curAnim != HCtrl.Get.CurAnim));
				ai.Mind.thinkDelay = Random.Range(2.5f, 3.5f);
			}
			ai.Mind.inExecute = false;
		}
	}
