		public static Type GetTypFromClip(Clip clip)
		{
			string text = (clip.ToString().Contains("_") ? Helper.GetStringAtIndex(clip.ToString(), "_", 1) : clip.ToString());
			foreach (Type value in Enum.GetValues(typeof(Type)))
			{
				if (text == value.ToString())
				{
					return value;
				}
			}
			return Type.Stand;
		}

		public static List<Clip> GetClipListFromTyp(Type typ, AIGuest.GuestType guestType = AIGuest.GuestType.Girl)
		{
			List<Clip> list = new List<Clip>();
			foreach (Clip value in Enum.GetValues(typeof(Clip)))
			{
				if ((value.ToString().Contains("_") ? Helper.GetStringAtIndex(value.ToString(), "_", 1) : value.ToString()) == typ.ToString())
				{
					list.Add(value);
				}
			}
			if (guestType == AIGuest.GuestType.Boy && Settings.BoyPosture == Settings.BoyPostureTyp.NoGirly)
			{
				foreach (Clip girlishPose in girlishPoses)
				{
					list.Remove(girlishPose);
				}
			}
			return list;
		}

		public static RuntimeAnimatorController LoadAnimator(Clip clip, ref string state)
		{
			string empty = string.Empty;
			_ = string.Empty;
			string empty2 = string.Empty;
			List<string> value = new List<string>();
			if (BundleDictionary().TryGetValue(clip, out value))
			{
				empty = value[0];
				string text = value[1];
				empty2 = value[2];
				state = value[3];
				RuntimeAnimatorController result = CommonLib.LoadAsset<RuntimeAnimatorController>(text, empty2, false, empty, true);
				AssetBundleManager.UnloadAssetBundle(text, true, (string)null, false);
				return result;
			}
			return null;
		}

		public static bool LoadAnim(ChaControl cha, Clip clip)
		{
			string empty = string.Empty;
			string empty2 = string.Empty;
			string empty3 = string.Empty;
			string empty4 = string.Empty;
			List<string> value = new List<string>();
			if (BundleDictionary().TryGetValue(clip, out value))
			{
				empty = value[0];
				empty2 = value[1];
				empty3 = value[2];
				empty4 = value[3];
				LoadAnim(cha, empty2, empty3, empty4, empty);
				return true;
			}
			return false;
		}

		public static string GetAssetNameFromClip(Clip clip)
		{
			Type typFromClip = GetTypFromClip(clip);
			if (typFromClip == Type.Dance || typFromClip == Type.Stretch || typFromClip == Type.Sit || typFromClip == Type.Home)
			{
				return GetFromClip(clip, 2) + "/" + GetFromClip(clip, 3);
			}
			return GetFromClip(clip, 2);
		}

		public static string GetStateFromClip(Clip clip)
		{
			return GetFromClip(clip, 3);
		}

		private static string GetFromClip(Clip clip, int i)
		{
			List<string> value = new List<string>();
			if (BundleDictionary().TryGetValue(clip, out value))
			{
				return value[i];
			}
			return string.Empty;
		}

		public static void LoadAnim(ChaControl cha, string bundle, string asset, string state = "Idle", string manifest = "abdata")
		{
			bool flag = ((asset.Contains("/") || bundle.Contains(":")) ? true : false);
			string text = ((flag && bundle.Contains(":")) ? Helper.GetStringAtIndex(bundle, ":", 1) : bundle);
			if (!text.Contains(".unity3d"))
			{
				text += ".unity3d";
			}
			string text2 = ((flag && asset.Contains("/")) ? Helper.GetStringAtIndex(asset, "/", 1) : asset);
			string text3 = string.Empty;
			string text4 = string.Empty;
			cha.LoadAnimation(text, text2, manifest);
			if (flag)
			{
				text3 = (bundle.Contains(":") ? Helper.GetStringAtIndex(bundle, ":", 2) : bundle);
				text4 = (asset.Contains("/") ? Helper.GetStringAtIndex(asset, "/", 2) : asset);
				Animator animBody = ((ChaInfo)cha).animBody;
				RuntimeAnimatorController val = CommonLib.LoadAsset<RuntimeAnimatorController>(text3, text4, false, manifest, true);
				if ((Object)(object)val != (Object)null)
				{
					animBody.runtimeAnimatorController = (RuntimeAnimatorController)(object)Animator.SetupAnimatorOverrideController(animBody.runtimeAnimatorController, val);
				}
				AssetBundleManager.UnloadAssetBundle(text3, true, (string)null, false);
			}
			cha.syncPlay(state, 0, 0f);
			ChaTools.SetDefaultAnimatorValue(cha);
			foreach (MotionIK item in MotionIK.Setup(new List<ChaControl> { cha }))
			{
				item.Calc("Idle");
				item.enabled = true;
				if (Object.op_Implicit((Object)(object)((Component)cha).GetComponent<CtrlIK>()))
				{
					((Component)cha).GetComponent<CtrlIK>().CheckTargets(item);
				}
			}
			cha.ChangeMouthPtn(1, false);
			if (Core.debug && debugLoadInfo)
			{
				Console.WriteLine("Loading animation: has base? " + flag);
				Console.WriteLine("bundle: " + text);
				Console.WriteLine("asset: " + text2);
				Console.WriteLine("sub bundle: " + text3);
				Console.WriteLine("sub asset: " + text4);
				Console.WriteLine("state: " + state);
				Console.WriteLine("Cha Height: " + cha.GetShapeBodyValue(0));
				Console.WriteLine("animator Height parameter: " + ((ChaInfo)cha).animBody.GetFloat("height"));
				Console.WriteLine("");
			}
		}

