		public static void ApplyCustomAnimClipOffsets(CtrlBones bc, Clip clip)
		{
			//IL_002c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0031: Unknown result type (might be due to invalid IL or missing references)
			//IL_0051: Unknown result type (might be due to invalid IL or missing references)
			//IL_0056: Unknown result type (might be due to invalid IL or missing references)
			if (clip == Clip.Crouch_04)
			{
				CtrlBones.Offsets offsets = new CtrlBones.Offsets();
				CtrlBones.Offsets offsets2 = new CtrlBones.Offsets();
				offsets.partNm = "spine2";
				offsets.rotOfst = new Vector3(0f, 7f, 0f);
				offsets2.partNm = "spine3";
				offsets2.rotOfst = new Vector3(0f, 14f, 0f);
				bc.SubscribeToOffset(offsets, CtrlBones.OffsetType.Custom);
				bc.SubscribeToOffset(offsets2, CtrlBones.OffsetType.Custom);
			}
		}

