		public static Vector2[] RangesThatLeadHead(string asset)
		{
			//IL_0043: Unknown result type (might be due to invalid IL or missing references)
			//IL_0048: Unknown result type (might be due to invalid IL or missing references)
			//IL_006d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0072: Unknown result type (might be due to invalid IL or missing references)
			//IL_0083: Unknown result type (might be due to invalid IL or missing references)
			//IL_0088: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ad: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b2: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c8: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ed: Unknown result type (might be due to invalid IL or missing references)
			//IL_00f2: Unknown result type (might be due to invalid IL or missing references)
			string text = (asset.Contains("/") ? Helper.GetLastString(asset, "/") : asset);
			Vector2[] result = (Vector2[])(object)new Vector2[0];
			if (text == "pole_dance_00")
			{
				result = (Vector2[])(object)new Vector2[1]
				{
					new Vector2(0.7f, 1.5f)
				};
			}
			if (text == "stretch_03")
			{
				result = (Vector2[])(object)new Vector2[2]
				{
					new Vector2(0.16f, 0.68f),
					new Vector2(0.8f, 0.94f)
				};
			}
			if (text == "stretch_00")
			{
				result = (Vector2[])(object)new Vector2[2]
				{
					new Vector2(0.14f, 0.28f),
					new Vector2(0.45f, 0.95f)
				};
			}
			if (asset == "live/01")
			{
				result = (Vector2[])(object)new Vector2[1]
				{
					new Vector2(0.17f, 0.97f)
				};
			}
			return result;
		}
