		public HAnims.State HState => Core.dealer.HState;

		public HAnims.Context HCtx => Core.dealer.HCtx;

		public bool IsMain
		{
			get
			{
				if (Core.dealer.InH && !((Object)(object)Core.dealer.HCtrl == (Object)null) && (!Object.op_Implicit((Object)(object)Core.dealer.HCtrl) || Core.dealer.HCtrl.IsInit))
				{
					return (Object)(object)((CharaData)Singleton<HFlag>.Instance.lstHeroine[0]).chaCtrl == (Object)(object)cha;
				}
				return false;
			}
		}

		public bool IsSecond
		{
			get
			{
				if (Core.dealer.InH && (!Object.op_Implicit((Object)(object)Core.dealer.HCtrl) || (Core.dealer.HCtrl.IsInit && Core.dealer.HCtrl.HasSecondGirl)))
				{
					return (Object)(object)((CharaData)Core.dealer.HCtrl.HFlag.lstHeroine[1]).chaCtrl == (Object)(object)cha;
				}
				return false;
			}
		}

		public bool IsBoyOrg
		{
			get
			{
				if (Core.dealer.InH && HCtx == HAnims.Context.Piston && (HState == HAnims.State.OrgM || HState == HAnims.State.OrgBoth))
				{
					return !HCtrl.Get.HFlag.nowAnimStateName.Contains("Start");
				}
				return false;
			}
		}

		private void Start()
		{
			_addBellyCtrl = Settings.AddBellyCtrl;
			chaCore = ((Component)this).GetComponent<ChaCore>();
			cha = chaCore.Cha;
			((MonoBehaviour)this).StartCoroutine(IE_Init());
			DebugInfos.InConsole(" Start on " + ChaCore.Name(((ChaInfo)cha).fileParam), cmpName, debug);
		}

		private void Update()
		{
			if (!isInit || !_addBellyCtrl || !cha.GetActiveTop() || (isNpc && Core.dealer.InH))
			{
				return;
			}
			if (Core.dealer.InH && ((IsMain && !HManage.IsSecondMain()) || (IsSecond && HManage.IsSecondMain())) && IsBoyOrg && !Core.dealer.HCtrl.HFlag.isCondom && !Core.dealer.HCtrl.HFlag.isAnalPlay && !InInsemination)
			{
				((MonoBehaviour)this).StartCoroutine(IE_Inseminate());
			}
			if (Core.dealer.InH && buddyCumsIn && !InInsemination)
			{
				((MonoBehaviour)this).StartCoroutine(IE_Inseminate(fromBuddy: true));
			}
			if (inReduce && !InInsemination && inflation != 0f && !IsPregnant())
			{
				inflation = Mathf.Max(inflation - Time.deltaTime * 0.025f * (float)Settings.MilkReduceSpeed, 0f);
			}
			if (Core.dealer.InStory && _inReduce && !inReduce)
			{
				List<Heroine> list = DealTool.ContextualSaveListForComparison(chaCore);
				if (list.Count != 0)
				{
					if (list.Count == 1)
					{
						Statistic.SetValueInDaily(Statistic.GetDaily(list[0]), Statistic.DailyParam.Inflation, inflation.ToString());
					}
					else
					{
						foreach (Heroine item in list)
						{
							if ((chaCore.HSaveData != null && chaCore.HSaveData == item) || (chaCore.HSaveData == null && ((ChaInfo)cha).fileParam.fullname == ((CharaData)item).parameter.fullname))
							{
								Statistic.SetValueInDaily(Statistic.GetDaily(item), Statistic.DailyParam.Inflation, inflation.ToString());
								break;
							}
						}
					}
				}
			}
			_inReduce = inReduce;
		}

		private void LateUpdate()
		{
			//IL_0142: Unknown result type (might be due to invalid IL or missing references)
			//IL_0147: Unknown result type (might be due to invalid IL or missing references)
			//IL_015b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0180: Unknown result type (might be due to invalid IL or missing references)
			//IL_0194: Unknown result type (might be due to invalid IL or missing references)
			//IL_01a8: Unknown result type (might be due to invalid IL or missing references)
			//IL_01cd: Unknown result type (might be due to invalid IL or missing references)
			//IL_01e1: Unknown result type (might be due to invalid IL or missing references)
			//IL_01f5: Unknown result type (might be due to invalid IL or missing references)
			//IL_021a: Unknown result type (might be due to invalid IL or missing references)
			//IL_022e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0242: Unknown result type (might be due to invalid IL or missing references)
			if (!isInit || !_addBellyCtrl || inSave)
			{
				return;
			}
			if (isNpc)
			{
				isNpcActive = cha.GetActiveTop();
				if (_isNpcActive != isNpcActive)
				{
					if (!isNpcActive)
					{
						AssumeStartValues();
					}
					else
					{
						GetValuesFromDaily(ref inflation, ref bustSize);
						forceUpdate = true;
					}
					_isNpcActive = isNpcActive;
				}
				if (!isNpcActive)
				{
					return;
				}
			}
			if (!cha.GetActiveTop())
			{
				return;
			}
			if (forceRefreshAfterH)
			{
				forceRefreshAfterH = false;
				forceUpdate = true;
				GetValuesFromDaily(ref inflation, ref bustSize);
				DebugInfos.InConsole(" Force refresh after H on " + ChaCore.Name(((ChaInfo)cha).fileParam), cmpName);
			}
			if (inflation != _inflation || forceUpdate)
			{
				cha.SetShapeBodyValue(4, Mathf.Lerp(bustSize, bustSize + 0.15f, inflation));
				forceUpdate = false;
				_inflation = inflation;
			}
			LerpInflation(waist2, new Vector3(0f, 0f, 0.014f), Vector3.zero, new Vector3(0.077f, 0f, 0.18f), inflation);
			LerpInflation(waist1, new Vector3(0f, -0.021f, 0.045f), new Vector3(8.245f, 0f, 0f), new Vector3(0.111f, 0f, 0.54f), inflation);
			LerpInflation(spine1, new Vector3(0f, 0.002f, 0.011f), new Vector3(-5.182f, 0f, 0f), new Vector3(0.313f, 0f, 0.69f), inflation);
			LerpInflation(spine2, new Vector3(0f, 0f, 0.0025f), new Vector3(-1.073f, 0f, 0f), new Vector3(0.045f, 0f, 0.036f), inflation);
			if (InInsemination && CanInflate())
			{
				float num = 0.013f;
				inflation = Mathf.Clamp(inflation + Time.deltaTime * num * (float)Settings.BellySpeed, 0f, 1f);
				if (Core.dealer.InStory && inflation == 1f && chaCore.HSaveData != null)
				{
					Statistic.Daily daily = Statistic.GetDaily(chaCore.HSaveData);
					if (daily != null && daily.isRiskyDay && !daily.pregnant)
					{
						daily.pregnant = true;
						Statistic.TriggerPregnancy(daily.save);
						((MonoBehaviour)this).StartCoroutine(IE_PregAlert());
					}
				}
			}
			if (_addBellyCtrl != Settings.AddBellyCtrl)
			{
				_addBellyCtrl = Settings.AddBellyCtrl;
				if (!Settings.AddBellyCtrl)
				{
					inflation = 0f;
					AssumeStartValues();
				}
			}
		}

		private IEnumerator IE_PregAlert()
		{
			if (Core.dealer.InH)
			{
				Core.dealer.Msgn.ReceiveMessage(Messenger.Type.TopCorner_R, "! Warning ! " + ((ChaInfo)cha).fileParam.firstname + " is pregnant", 5f);
				AudioSource pregAlert = Sound.Play((SystemSE)2);
				pregAlert.loop = true;
				yield return (object)new WaitForSeconds(3f);
				if ((Object)(object)pregAlert != (Object)null)
				{
					pregAlert.Stop();
				}
			}
		}

		private void OnDestroy()
		{
			if (!Core.dealer.InStory && isInit)
			{
				AssumeStartValues();
			}
		}

		private void AutoDestroy()
		{
			Object.Destroy((Object)(object)this);
		}

		private bool CanInflate()
		{
			if (!Core.dealer.InStory)
			{
				return Settings.AddBellyCtrl;
			}
			Statistic.Daily daily = Statistic.GetDaily(chaCore.HSaveData);
			if (Settings.BellyOpenDay == Settings.BellyDay.RiskDay && daily != null && !daily.isRiskyDay && !daily.pregnant)
			{
				return false;
			}
			return Settings.AddBellyCtrl;
		}

		private bool IsPregnant()
		{
			if (Core.dealer.InStory && chaCore.HSaveData != null && Statistic.GetDaily(chaCore.HSaveData) != null)
			{
				return Statistic.GetDaily(chaCore.HSaveData).pregnant;
			}
			if (Core.dealer.Ctx == Dealer.Context.Event && Core.dealer.eventInfo != null && Core.dealer.eventInfo.saves.Count > 0)
			{
				Statistic.Daily daily = Statistic.GetDaily(Core.dealer.eventInfo.saves[0]);
				if (daily != null && daily.pregnant)
				{
					return true;
				}
			}
			return false;
		}

		private void SearchBreastValuesFromNpc(ref float size)
		{
			if (!Core.dealer.InStory)
			{
				return;
			}
			List<Heroine> list = DealTool.ContextualSaveListForComparison(chaCore);
			if (list.Count == 0)
			{
				return;
			}
			foreach (Heroine item in list)
			{
				Fix fixChara = SingletonInitializer<ActionScene>.instance.fixChara;
				if ((Object)(object)fixChara != (Object)null && (Object)(object)((Component)((Base)fixChara).chaCtrl).GetComponent<BellyCtrl>() != (Object)null && ((Component)((Base)fixChara).chaCtrl).GetComponent<BellyCtrl>().isInit && ((Base)fixChara).heroine == item)
				{
					size = ((Component)((Base)fixChara).chaCtrl).GetComponent<BellyCtrl>().startValues.bustSize;
					DebugInfos.InConsole("Found a corresponding component on " + ChaCore.Name(((ChaInfo)cha).fileParam) + " FIX, picking breast size from it", cmpName, debug);
					return;
				}
			}
			foreach (Heroine item2 in list)
			{
				for (int i = 0; i < SingletonInitializer<ActionScene>.instance.npcList.Count; i++)
				{
					NPC val = SingletonInitializer<ActionScene>.instance.npcList[i];
					if ((Object)(object)((Component)((Base)val).chaCtrl).GetComponent<BellyCtrl>() != (Object)null && ((Component)((Base)val).chaCtrl).GetComponent<BellyCtrl>().isInit && ((Base)val).heroine == item2)
					{
						size = ((Component)((Base)val).chaCtrl).GetComponent<BellyCtrl>().startValues.bustSize;
						DebugInfos.InConsole("Found a corresponding component on " + ChaCore.Name(((ChaInfo)cha).fileParam) + " NPC, picking breast size from it", cmpName, debug);
						return;
					}
				}
			}
		}

		private void GetValuesFromDaily(ref float value, ref float bustSize)
		{
			if (!Core.dealer.InStory)
			{
				return;
			}
			string text = "";
			Heroine val = null;
			if ((Object)(object)chaCore.Npc != (Object)null)
			{
				val = ((Base)chaCore.Npc).heroine;
				text = "(FROM NPC)";
			}
			if ((Object)(object)chaCore.FixNpc != (Object)null)
			{
				val = ((Base)chaCore.FixNpc).heroine;
				text = "(FROM FIX)";
			}
			if (Core.dealer.InH)
			{
				val = chaCore.HSaveData;
				text = "(FROM HSaveData)";
			}
			if (Core.dealer.Ctx == Dealer.Context.Esthetic)
			{
				if (chaCore.HSaveData != null)
				{
					val = chaCore.HSaveData;
				}
				else
				{
					val = Core.dealer.girlInEsthetic;
					text = "(FROM Esthetic Cha)";
				}
			}
			if (val == null && Core.dealer.Ctx == Dealer.Context.Event && Core.dealer.eventInfo != null && Core.dealer.eventInfo.saves.Count > 0)
			{
				if (Core.dealer.eventInfo.saves.Count == 1)
				{
					val = Core.dealer.eventInfo.saves[0];
				}
				else
				{
					foreach (Heroine safe in Core.dealer.eventInfo.saves)
					{
						if (ChaCore.Name(((ChaInfo)cha).fileParam) == ChaCore.Name(((CharaData)safe).parameter))
						{
							val = safe;
						}
					}
				}
				text = "(FROM Event Save Cha)";
			}
			if (Core.dealer.InStory && Core.dealer.Ctx == Dealer.Context.Event && Object.op_Implicit((Object)(object)Singleton<ActionScene>.Instance))
			{
				HScene instance = Singleton<HScene>.Instance;
				if ((Object)(object)instance != (Object)null && Singleton<ActionScene>.Instance.isPenetration)
				{
					foreach (Heroine item in instance.GetFieldValue<List<Heroine>>("heroineList"))
					{
						if (((CharaData)item).parameter.fullname == ((ChaInfo)cha).fileParam.fullname)
						{
							val = item;
							DebugInfos.InConsole(" PICK DAILY FROM " + ((CharaData)item).parameter.fullname + " in event penetration_heroine", cmpName);
						}
					}
				}
			}
			if (val == null && Core.dealer.eventInfo.saves.Count > 0)
			{
				val = Core.dealer.eventInfo.saves[0];
				text = "(FROM Event Save Cha in UNEXPECTED CONTEXT)";
			}
			if (CtrlHome.IsActive)
			{
				val = CtrlHome.FindSave(cha);
				text = "(FROM CtrlHome )";
			}
			Statistic.Daily daily = Statistic.GetDaily(val);
			if (daily != null)
			{
				value = daily.bellyBuldge;
				bustSize = daily.bustSize;
				DebugInfos.InConsoleCompact("Found " + text + ChaCore.Name(((ChaInfo)cha).fileParam) + " inflation from daily, value is " + value, cmpName + ".GetInflationFromDaily", debug);
			}
		}

		private void StoreStartValues()
		{
			CopyBoneValues(waist1, startValues.waist1);
			CopyBoneValues(waist2, startValues.waist2);
			CopyBoneValues(spine1, startValues.spine1);
			CopyBoneValues(spine2, startValues.spine2);
			startValues.bustSize = bustSize;
			startValues.inflation = inflation;
		}

		private void AssumeStartValues()
		{
			CopyBoneValues(startValues.waist1, waist1);
			CopyBoneValues(startValues.waist2, waist2);
			CopyBoneValues(startValues.spine1, spine1);
			CopyBoneValues(startValues.spine2, spine2);
			bustSize = startValues.bustSize;
			((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[4] = bustSize;
			if (!isNpc && cha.GetActiveTop())
			{
				cha.SetShapeBodyValue(4, bustSize);
			}
		}

