		private IEnumerator IE_Inseminate(bool fromBuddy = false)
		{
			InInsemination = true;
			if (!fromBuddy)
			{
				yield return (object)new WaitUntil((Func<bool>)(() => HState != HAnims.State.OrgM && HState != HAnims.State.OrgBoth));
			}
			if (fromBuddy)
			{
				yield return (object)new WaitUntil((Func<bool>)(() => buddyCumsIn));
			}
			InInsemination = false;
			if (Core.dealer.InStory && CanInflate())
			{
				Statistic.SetValueInDaily(Statistic.GetDaily(chaCore.HSaveData), Statistic.DailyParam.Inflation, inflation.ToString());
			}
		}

		private IEnumerator IE_Init()
		{
			yield return (object)new WaitUntil((Func<bool>)(() => chaCore.IsInit && cha.GetActiveTop() && ((ChaInfo)cha).loadEnd));
			if (isNpc)
			{
				yield return (object)new WaitUntil((Func<bool>)(() => (Object)(object)ChaTools.FindInCha(cha, "cf_s_waist02") != (Object)null));
			}
			yield return (object)new WaitForEndOfFrame();
			waist2 = GetBone("cf_s_waist02");
			waist1 = GetBone("cf_s_waist01");
			spine1 = GetBone("cf_s_spine01");
			spine2 = GetBone("cf_s_spine02");
			if (waist2 == null || waist1 == null || spine1 == null || spine2 == null)
			{
				DebugInfos.InConsole(" WARNING : Can't Find Bones for " + ChaCore.Name(((ChaInfo)cha).fileParam), cmpName, debug);
			}
			bustSize = ((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[4];
			GetValuesFromDaily(ref inflation, ref bustSize);
			StoreStartValues();
			_inflation = inflation;
			forceUpdate = true;
			isInit = true;
			DebugInfos.InConsole("Initialized " + ChaCore.Name(((ChaInfo)cha).fileParam), cmpName, debug);
		}

