			BellyCtrl component2 = ((Component)cha2).GetComponent<BellyCtrl>();
			if (!((Object)(object)component == (Object)null) && !((Object)(object)component2 == (Object)null) && component.isInit && component2.isInit)
			{
				SwapBoneValues(component.waist1, component2.waist1);
				SwapBoneValues(component.waist2, component2.waist1);
				SwapBoneValues(component.spine1, component2.spine1);
				SwapBoneValues(component.spine2, component2.spine2);
				float num = component.bustSize;
				component.bustSize = component2.bustSize;
				component2.bustSize = num;
				float num2 = component.inflation;
				component.inflation = component2.inflation;
				component2.inflation = num2;
				component.forceUpdate = true;
				component2.forceUpdate = true;
			}
		}

