	public class BodyReact : MonoBehaviour
	{
		public enum Type
		{
			Once,
			ManualLoop,
			AutoLoop,
			Breath
		}

		public const string cmpName = "BodyReact";

		public const bool debug = true;

		public Vector2 speedRange = new Vector2(2f, 6f);

		private Type typ;

		private ChaControl cha;

		private FullBodyBipedIK fullBody;

		private float reaction;

		public float speed = 1.75f;

		public float amplitude = 0.01f;

		private float offset_x;

		private float offset_y;

		private float offset_z;

		private int delOnButClearId = -1;

		private bool inWaitDestroy;

		public bool active;

		public float DragLenght => Core.dealer.mInfos.dragLenght;

		private void Start()
		{
			if ((Object)(object)cha == (Object)null)
			{
				cha = ((Component)this).gameObject.GetComponent<ChaControl>();
			}
			fullBody = ChaTools.GetBodyIkSolver(cha);
		}

		private void Update()
		{
			//IL_029c: Unknown result type (might be due to invalid IL or missing references)
			//IL_02b3: Unknown result type (might be due to invalid IL or missing references)
			//IL_02b8: Unknown result type (might be due to invalid IL or missing references)
			//IL_02bd: Unknown result type (might be due to invalid IL or missing references)
			if ((Object)(object)fullBody == (Object)null)
			{
				return;
			}
			if (typ == Type.Once)
			{
				reaction = Mathf.Clamp(reaction + Time.deltaTime * Time.timeScale * speed, 0f, 1f);
				float num = Mathf.Lerp(0f, (float)Math.PI, reaction);
				float num2 = Mathf.Lerp(0f, (float)Math.PI * 3f, reaction);
				offset_x = Mathf.Sin(num2) * amplitude * Mathf.Sin(num);
				offset_z = Mathf.Cos(num2) * amplitude * Mathf.Sin(num);
				if (reaction == 1f)
				{
					Object.Destroy((Object)(object)this);
				}
			}
			if (typ == Type.ManualLoop || typ == Type.AutoLoop)
			{
				speed = Mathf.Lerp(speedRange.x, speedRange.y, (typ == Type.ManualLoop) ? DragLenght : 0.4f);
				reaction += Time.deltaTime * Time.timeScale * speed;
				amplitude = ((typ == Type.ManualLoop) ? Mathf.Lerp(0.0075f, 0.012f, DragLenght * 0.7f) : 0.0075f);
				offset_x = (inWaitDestroy ? Mathf.MoveTowards(offset_x, 0f, Time.deltaTime * 0.1f) : (Mathf.Sin(reaction) * amplitude));
				offset_z = (inWaitDestroy ? Mathf.MoveTowards(offset_z, 0f, Time.deltaTime * 0.1f) : (Mathf.Cos(reaction) * amplitude));
				if (delOnButClearId != -1 && !Input.GetMouseButton(delOnButClearId) && !inWaitDestroy)
				{
					inWaitDestroy = true;
				}
			}
			if (typ == Type.Breath)
			{
				speed = 2f;
				amplitude = 0.005f;
				reaction += Time.deltaTime * Time.timeScale * speed;
				offset_y = ((!active) ? 0f : (Mathf.Sin(reaction) * (amplitude * 0.25f)));
				offset_z = ((!active) ? 0f : (Mathf.Cos(reaction) * amplitude));
			}
			IKEffector bodyEffector = fullBody.solver.bodyEffector;
			bodyEffector.positionOffset += new Vector3(offset_x, offset_y, offset_z);
			if (inWaitDestroy && offset_x == 0f)
			{
				Object.Destroy((Object)(object)this);
			}
		}

		private void OnDestroy()
		{
			DebugInfos.InConsole("Destroyed on " + ChaCore.Name(((ChaInfo)cha).fileParam), "BodyReact." + typ);
		}

		private static BodyReact HasBodyReactOfType(ChaControl cha, Type targetTyp)
		{
			BodyReact[] components = ((Component)cha).gameObject.GetComponents<BodyReact>();
			foreach (BodyReact bodyReact in components)
			{
				if (bodyReact.typ == targetTyp || (targetTyp == Type.AutoLoop && bodyReact.typ == Type.ManualLoop) || (targetTyp == Type.ManualLoop && bodyReact.typ == Type.AutoLoop))
				{
					return bodyReact;
				}
			}
			return null;
		}

		public static BodyReact Create(ChaControl cha, Type typ, int delOnButClearId = -1)
		{
			BodyReact bodyReact = null;
			if (Object.op_Implicit((Object)(object)HasBodyReactOfType(cha, typ)))
			{
				bodyReact = HasBodyReactOfType(cha, typ);
			}
			else
			{
				bodyReact = ((Component)cha).gameObject.AddComponent<BodyReact>();
				bodyReact.cha = cha;
			}
			bodyReact.typ = typ;
			bodyReact.delOnButClearId = delOnButClearId;
			return bodyReact;
		}
	}
