		public static Offsets BuildOffsetsFromText(string text)
		{
			string[] array = text.Split(new string[1] { "/" }, StringSplitOptions.None);
			if (array.Length < 2)
			{
				return null;
			}
			Offsets offsets = new Offsets();
			offsets.partNm = array[0].Trim();
			string[] array2 = array[1].Split(new string[1] { "," }, StringSplitOptions.None);
			foreach (string text2 in array2)
			{
				if (text2.Contains(":"))
				{
					string[] array3 = text2.Split(new string[1] { ":" }, StringSplitOptions.None);
					array3[1] = (array3[1].Contains(";") ? array3[1].Replace(";", "") : array3[1]);
					if (array3[0].Contains("rx"))
					{
						offsets.rotOfst.x = float.Parse(array3[1].Trim());
					}
					if (array3[0].Contains("ry"))
					{
						offsets.rotOfst.y = float.Parse(array3[1].Trim());
					}
					if (array3[0].Contains("rz"))
					{
						offsets.rotOfst.z = float.Parse(array3[1].Trim());
					}
					if (array3[0].Contains("tx"))
					{
						offsets.posOfst.x = float.Parse(array3[1].Trim());
					}
					if (array3[0].Contains("ty"))
					{
						offsets.posOfst.y = float.Parse(array3[1].Trim());
					}
					if (array3[0].Contains("tz"))
					{
						offsets.posOfst.z = float.Parse(array3[1].Trim());
					}
				}
			}
			return offsets;
		}

