	public class BreastStretcher : MonoBehaviour
	{
		public class Tweak
		{
			public Transform trs;

			public Vector3 locPos = Vector3.zero;

			public Vector3 locScl = Vector3.one;
		}

		public const string cmpName = "BreastStretcher";

		public const string bone1name = "cf_s_bust00";

		public const string bone2name = "cf_j_bust01";

		public const string bone3name = "cf_j_bust02";

		public const string bone4name = "cf_j_bust03";

		public const string def1name = "cf_s_bust01";

		public const string def2name = "cf_s_bust02";

		public const string def3name = "cf_s_bust03";

		public const string def4name = "cf_d_bnip01";

		private Tweak bone1;

		private Tweak bone2;

		private Tweak bone3;

		private Tweak bone4;

		private Tweak def1;

		private Tweak def2;

		private Tweak def3;

		private Tweak def4;

		private ChaControl cha;

		private GrabCtrl grabCtrl;

		private DynamicBone_Ver02 dynChain;

		private ChaTools.Part breastTyp;

		private BreastStretcher leader;

		private float oscillation;

		private float lengthVar = 1f;

		private bool inWaitDestroy;

		private bool isInit;

		public bool HasLeader => (Object)(object)leader != (Object)null;

		private List<Tweak> Bones => new List<Tweak> { bone1, bone2, bone3, bone4 };

		private List<Tweak> Deformers => new List<Tweak> { def1, def2, def3, def4 };

		private void Start()
		{
			((MonoBehaviour)this).StartCoroutine(IE_Init());
		}

		private void LateUpdate()
		{
			//IL_003a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0041: Unknown result type (might be due to invalid IL or missing references)
			//IL_0051: Unknown result type (might be due to invalid IL or missing references)
			//IL_01ae: Unknown result type (might be due to invalid IL or missing references)
			//IL_01be: Unknown result type (might be due to invalid IL or missing references)
			//IL_01c3: Unknown result type (might be due to invalid IL or missing references)
			//IL_009a: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a1: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b1: Unknown result type (might be due to invalid IL or missing references)
			//IL_00df: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ea: Unknown result type (might be due to invalid IL or missing references)
			//IL_0227: Unknown result type (might be due to invalid IL or missing references)
			//IL_025d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0262: Unknown result type (might be due to invalid IL or missing references)
			if (!isInit)
			{
				return;
			}
			if (inWaitDestroy)
			{
				foreach (Tweak bone in Bones)
				{
					bone.trs.localPosition = Vector3.MoveTowards(bone.trs.localPosition, bone.locPos, Time.deltaTime * 0.1f);
				}
				foreach (Tweak deformer in Deformers)
				{
					deformer.trs.localScale = Vector3.MoveTowards(deformer.trs.localScale, deformer.locScl, Time.deltaTime * 0.1f);
				}
				if (def1.trs.localScale == def1.locScl)
				{
					Object.Destroy((Object)(object)this);
				}
				return;
			}
			float num = Mathf.Lerp(-0.025f, 0.125f, Mathf.Min(((Vector3)(ref dynChain.Force)).magnitude * 100f, 1f));
			oscillation = (HasLeader ? leader.oscillation : (oscillation + Time.deltaTime * Time.timeScale * 6f));
			lengthVar = Mathf.Sin(oscillation) * 0.025f + num;
			float num2 = lengthVar / (float)Bones.Count;
			foreach (Tweak bone2 in Bones)
			{
				bone2.trs.localPosition = bone2.locPos + new Vector3(0f, 0f, num2);
			}
			float num3 = Mathf.Sqrt(1f / (1f + lengthVar * 5f));
			int num4 = 0;
			foreach (Tweak deformer2 in Deformers)
			{
				deformer2.trs.localScale = deformer2.locScl + new Vector3(num3 - 1f, num3 - 1f, (num4 == Deformers.Count - 1) ? (lengthVar * 2.5f) : 0f);
				num4++;
			}
			if ((breastTyp == ChaTools.Part.BreastL && !grabCtrl.LftBoobInGrab) || (breastTyp == ChaTools.Part.BreastR && !grabCtrl.RgtBoobInGrab))
			{
				inWaitDestroy = true;
			}
		}

		private void OnDestroy()
		{
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_005d: Unknown result type (might be due to invalid IL or missing references)
			foreach (Tweak bone in Bones)
			{
				bone.trs.localPosition = bone.locPos;
			}
			foreach (Tweak deformer in Deformers)
			{
				deformer.trs.localScale = deformer.locScl;
			}
			DebugInfos.InConsole("Destroyed", "BreastStretcher");
		}

		private IEnumerator IE_Init()
		{
			yield return (object)new WaitUntil((Func<bool>)(() => cha.GetActiveTop()));
			grabCtrl = ((Component)cha).gameObject.GetComponent<GrabCtrl>();
			string text = ((breastTyp == ChaTools.Part.BreastL) ? "_L" : "_R");
			bone1 = CreateTweak(cha, "cf_s_bust00" + text);
			bone2 = CreateTweak(cha, "cf_j_bust01" + text);
			bone3 = CreateTweak(cha, "cf_j_bust02" + text);
			bone4 = CreateTweak(cha, "cf_j_bust03" + text);
			def1 = CreateTweak(cha, "cf_s_bust01" + text);
			def2 = CreateTweak(cha, "cf_s_bust02" + text);
			def3 = CreateTweak(cha, "cf_s_bust03" + text);
			def4 = CreateTweak(cha, "cf_d_bnip01" + text);
			BreastStretcher[] components = ((Component)cha).gameObject.GetComponents<BreastStretcher>();
			foreach (BreastStretcher breastStretcher in components)
			{
				if ((Object)(object)breastStretcher != (Object)(object)this)
				{
					leader = breastStretcher;
				}
			}
			isInit = true;
		}

		private static Tweak CreateTweak(ChaControl cha, string boneName)
		{
			//IL_0019: Unknown result type (might be due to invalid IL or missing references)
			//IL_001e: Unknown result type (might be due to invalid IL or missing references)
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			//IL_002f: Unknown result type (might be due to invalid IL or missing references)
			Tweak obj = new Tweak
			{
				trs = ChaTools.FindInCha(cha, boneName)
			};
			obj.locPos = obj.trs.localPosition;
			obj.locScl = obj.trs.localScale;
			return obj;
		}

		private static bool HasThisBreastType(ChaControl cha, ChaTools.Part breastTyp)
		{
			BreastStretcher[] components = ((Component)cha).gameObject.GetComponents<BreastStretcher>();
			for (int i = 0; i < components.Length; i++)
			{
				if (components[i].breastTyp == breastTyp)
				{
					return true;
				}
			}
			return false;
		}

		public static BreastStretcher Create(ChaControl cha, ChaTools.Part bodyPart, DynamicBone_Ver02 dynChain)
		{
			if ((bodyPart != ChaTools.Part.BreastL && bodyPart != ChaTools.Part.BreastR) || HasThisBreastType(cha, bodyPart))
			{
				return null;
			}
			BreastStretcher breastStretcher = ((Component)cha).gameObject.AddComponent<BreastStretcher>();
			breastStretcher.cha = cha;
			breastStretcher.breastTyp = bodyPart;
			breastStretcher.dynChain = dynChain;
			return breastStretcher;
		}
	}
	public class BreastPusher : MonoBehaviour
	{
		public const string cmpName = "BreastPusher";

		private bool debug;

		private bool debugNpcVis;

		private ChaCore chaCore;

		private ChaControl cha;

		private float size;

		private float spacing;

		private float horizontalPos;

		private float depht;

		private float verticalPos;

		private float verticalAngle;

		private float roundness;

		private float areolaDepht;

		private float nipDepht;

		private float softness;

		private float weight;

		private float[] valuesAtstart = new float[10];

		private bool pusherSetting;

		private bool breastVis;

		private bool breastVis_;

		private bool isNpc;

		private bool isNpcActive;

		private bool _isNpcActive;

		private bool isInit;

		private bool visStateBeforSave;

		private void Start()
		{
			pusherSetting = Settings.AddBreastPusher;
			chaCore = ((Component)this).GetComponent<ChaCore>();
			cha = chaCore.Cha;
			((MonoBehaviour)this).StartCoroutine(IE_Init());
		}

		private void Update()
		{
			if (!isInit)
			{
				return;
			}
			if (isNpc)
			{
				isNpcActive = cha.GetActiveTop();
				if (_isNpcActive != isNpcActive)
				{
					if (!isNpcActive)
					{
						SetBreastValues(visible: true);
						DebugInfos.InConsole("Npc " + ChaCore.Name(((ChaInfo)cha).fileParam) + " NOT visible disable component", "BreastPusher", debugNpcVis);
					}
					else
					{
						SetBreastValues(breastVis);
						DebugInfos.InConsole("Npc " + ChaCore.Name(((ChaInfo)cha).fileParam) + " IS VISIBLE, enable component", "BreastPusher", debugNpcVis);
					}
					_isNpcActive = isNpcActive;
				}
				if (!isNpcActive || Core.dealer.InH)
				{
					return;
				}
			}
			if (!cha.GetActiveTop())
			{
				return;
			}
			breastVis = Clothes.IsBreastVisible(cha);
			if (breastVis_ != breastVis)
			{
				if (Core.dealer.InH)
				{
					((MonoBehaviour)this).StartCoroutine(IE_SetBreastValues(breastVis));
				}
				else
				{
					SetBreastValues(breastVis);
				}
			}
			breastVis_ = breastVis;
			if (pusherSetting != Settings.AddBreastPusher)
			{
				SetBreastValues(breastVis);
				pusherSetting = Settings.AddBreastPusher;
			}
		}

		private void OnDestroy()
		{
			if (!Core.dealer.InStory || !isInit)
			{
				if (!isInit)
				{
					DebugInfos.InConsole("Uninitialized component destroyed on " + ChaCore.Name(((ChaInfo)cha).fileParam), "BreastPusher", debug);
				}
				return;
			}
			((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[5] = valuesAtstart[0];
			((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[6] = valuesAtstart[1];
			((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[7] = valuesAtstart[2];
			((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[8] = valuesAtstart[3];
			((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[9] = valuesAtstart[4];
			((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[10] = valuesAtstart[5];
			((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[11] = valuesAtstart[6];
			((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[13] = valuesAtstart[7];
			((ChaFile)((ChaInfo)cha).chaFile).custom.body.bustSoftness = valuesAtstart[8];
			((ChaFile)((ChaInfo)cha).chaFile).custom.body.bustWeight = valuesAtstart[9];
			DebugInfos.InConsole("Destroyed on " + ChaCore.Name(((ChaInfo)cha).fileParam) + " removed and restore default values", "BreastPusher", debug);
		}

		private IEnumerator IE_Init()
		{
			yield return (object)new WaitUntil((Func<bool>)(() => chaCore.IsInit && cha.GetActiveTop() && ((ChaInfo)cha).loadEnd));
			yield return (object)new WaitForEndOfFrame();
			if (!isNpc && Core.dealer.InStory)
			{
				SearchValuesFromNpc();
			}
			size = Mathf.Clamp(((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[4], 0f, 1f);
			verticalPos = ((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[5];
			spacing = ((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[6];
			horizontalPos = ((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[7];
			verticalAngle = ((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[8];
			depht = ((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[9];
			roundness = ((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[10];
			areolaDepht = ((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[11];
			nipDepht = ((ChaFile)((ChaInfo)cha).chaFile).custom.body.shapeValueBody[13];
			softness = ((ChaFile)((ChaInfo)cha).chaFile).custom.body.bustSoftness;
			weight = ((ChaFile)((ChaInfo)cha).chaFile).custom.body.bustWeight;
			StoreStartValue();
			breastVis = Clothes.IsBreastVisible(cha);
			breastVis_ = breastVis;
			SetBreastValues(breastVis);
			isInit = true;
			DebugInfos.InConsole("Breast Pusher is initialized on " + ChaCore.Name(((ChaInfo)cha).fileParam), "BreastPusher", debug);
			if (((ChaInfo)cha).hiPoly)
			{
				cha.playDynamicBoneBust((DynamicBoneKind)0, true);
				cha.playDynamicBoneBust((DynamicBoneKind)1, true);
			}
		}

		private void StoreStartValue()
		{
			valuesAtstart[0] = verticalPos;
			valuesAtstart[1] = spacing;
			valuesAtstart[2] = horizontalPos;
			valuesAtstart[3] = verticalAngle;
			valuesAtstart[4] = depht;
			valuesAtstart[5] = roundness;
			valuesAtstart[6] = areolaDepht;
			valuesAtstart[7] = nipDepht;
			valuesAtstart[8] = softness;
			valuesAtstart[9] = weight;
		}

		private void SetBreastValues(bool visible)
		{
			if (visible || !Settings.AddBreastPusher)
			{
				((ChaFile)((ChaInfo)cha).chaFile).custom.body.bustSoftness = softness;
				((ChaFile)((ChaInfo)cha).chaFile).custom.body.bustWeight = weight;
				cha.SetShapeBodyValue(5, verticalPos);
				cha.SetShapeBodyValue(6, spacing);
				cha.SetShapeBodyValue(7, horizontalPos);
				cha.SetShapeBodyValue(8, verticalAngle);
				cha.SetShapeBodyValue(9, depht);
				cha.SetShapeBodyValue(10, roundness);
				cha.SetShapeBodyValue(11, areolaDepht);
				cha.SetShapeBodyValue(13, nipDepht);
			}
			else
			{
				((ChaFile)((ChaInfo)cha).chaFile).custom.body.bustSoftness = Mathf.Clamp(softness - 0.425f, 0.025f, float.PositiveInfinity);
				((ChaFile)((ChaInfo)cha).chaFile).custom.body.bustWeight = Mathf.Clamp(weight - 0.5f, 0f, float.PositiveInfinity);
				cha.SetShapeBodyValue(5, verticalPos + 0.75f * Mathf.Clamp(size, 0.3f, 0.75f));
				cha.SetShapeBodyValue(6, spacing - 0.2f * Mathf.Clamp(size, 0.35f, 0.6f));
				cha.SetShapeBodyValue(7, horizontalPos - 0.2f * Mathf.Clamp(size, 0.3f, 0.6f));
				cha.SetShapeBodyValue(8, verticalAngle + 0.3f * Mathf.Clamp(size, 0.35f, 0.4f));
				cha.SetShapeBodyValue(9, Mathf.Clamp(depht - 0.4f * Mathf.Clamp(size, 0f, 0.7f), 0f, float.PositiveInfinity));
				cha.SetShapeBodyValue(10, roundness + 0.3f * Mathf.Clamp(size, 0.25f, 0.75f));
				cha.SetShapeBodyValue(11, Mathf.Clamp(areolaDepht - 0.4f, 0f, float.PositiveInfinity));
				cha.SetShapeBodyValue(13, Mathf.Clamp(nipDepht - 0.35f, 0f, float.PositiveInfinity));
				cha.SetShapeBodyValue(11, areolaDepht);
				cha.SetShapeBodyValue(13, nipDepht);
			}
		}

		public static void SuspendAll()
		{
			BreastPusher[] array = Object.FindObjectsOfType<BreastPusher>();
			foreach (BreastPusher breastPusher in array)
			{
