				if ((Object)(object)fixChara != (Object)null && (Object)(object)((Component)((Base)fixChara).chaCtrl).GetComponent<BreastPusher>() != (Object)null && ((Component)((Base)fixChara).chaCtrl).GetComponent<BreastPusher>().isInit && ((Base)fixChara).heroine == item)
