						DebugInfos.InConsole("Found a corresponding component on " + ChaCore.Name(((ChaInfo)cha).fileParam) + " NPC, picking value from it", "BreastPusher", debug);
						return;
					}
				}
			}
		}

		private void SetValueFromOtherPusher(BreastPusher other)
