			((ChaFile)((ChaInfo)cha).chaFile).custom.body.bustWeight = other.weight;
			cha.SetShapeBodyValue(5, other.verticalPos);
			cha.SetShapeBodyValue(6, other.spacing);
			cha.SetShapeBodyValue(7, other.horizontalPos);
			cha.SetShapeBodyValue(8, other.verticalAngle);
