		{
			BreastPusher component = ((Component)cha1).GetComponent<BreastPusher>();
			BreastPusher component2 = ((Component)cha2).GetComponent<BreastPusher>();
			if ((Object)(object)component == (Object)null || (Object)(object)component2 == (Object)null)
			{
				return false;
			}
			if (!component.isInit || !component2.isInit)
			{
				return false;
			}
			float num = component.size;
			float num2 = component.spacing;
			float num3 = component.horizontalPos;
			float num4 = component.depht;
			float num5 = component.verticalPos;
			float num6 = component.verticalAngle;
			float num7 = component.roundness;
			float num8 = component.areolaDepht;
			float num9 = component.nipDepht;
			float num10 = component.softness;
			float num11 = component.weight;
			component.size = component2.size;
			component.spacing = component2.spacing;
			component.horizontalPos = component2.horizontalPos;
			component.depht = component2.depht;
			component.verticalPos = component2.verticalPos;
			component.verticalAngle = component2.verticalAngle;
			component.roundness = component2.roundness;
			component.areolaDepht = component2.areolaDepht;
			component.nipDepht = component2.nipDepht;
			component.softness = component2.softness;
			component.weight = component2.weight;
			component2.size = num;
			component2.spacing = num2;
			component2.horizontalPos = num3;
			component2.depht = num4;
			component2.verticalPos = num5;
			component2.verticalAngle = num6;
			component2.roundness = num7;
			component2.areolaDepht = num8;
			component2.nipDepht = num9;
			component2.softness = num10;
			component2.weight = num11;
			component.ForceRefresh();
			component2.ForceRefresh();
			return true;
		}

		public static void AddOnAllNpcs()
		{
			if (Settings.AddBreastPusher && !Core.OtherMods.Contains(Enums.Mod.PSHUP))
			{
