				if ((Object)(object)fixChara != (Object)null)
				{
					Create(((Base)fixChara).chaCtrl, isNpc: true);
				}
				for (int i = 0; i < SingletonInitializer<ActionScene>.instance.npcList.Count; i++)
				{
					Create(((Base)SingletonInitializer<ActionScene>.instance.npcList[i]).chaCtrl, isNpc: true);
				}
			}
		}

		public static void RemoveOnAllNpcs()
		{
			BreastPusher[] array = Object.FindObjectsOfType<BreastPusher>();
			foreach (BreastPusher breastPusher in array)
			{
				if (breastPusher.isNpc)
				{
					breastPusher.AutoDestroy();
				}
			}
			DebugInfos.InConsole(" Call on RemoveOnAllNpcs()", "BreastPusher");
		}

		public static BreastPusher Create(ChaControl cha, bool isNpc = false)
		{
			if (!Settings.AddBreastPusher || (Object)(object)cha == (Object)null || Core.OtherMods.Contains(Enums.Mod.PSHUP))
