			{
				Core.dealer.ChaCoresInH.Add(this);
				CtrlIK = CtrlIK.Create(Cha);
				BoneCtrl = CtrlBones.Create(Cha);
			}
			HFlag instance = Singleton<HFlag>.Instance;
			if (Sex == Gender.Boy && birthContext == Dealer.Context.H)
			{
				GenitalBoy = GenitalBoy.Create(Cha);
				if ((Object)(object)maleBodySiruTxt == (Object)null)
				{
					maleBodySiruTxt = CommonLib.LoadAsset<Texture2D>("studio_k/mat/04.unity3d", "liquid01_m", true, string.Empty, true);
				}
				((ChaInfo)Cha).customMatBody.SetTexture("_Texture2", (Texture)(object)maleBodySiruTxt);
				if ((Object)(object)instance != (Object)null && (Object)(object)((CharaData)instance.player).chaCtrl == (Object)(object)Cha)
				{
					Typ = Type.MainBoy;
					HCtrl.SetMainBoyToHCtrl(this, 0);
				}
				if ((Object)(object)instance != (Object)null && (Object)(object)((CharaData)instance.player).chaCtrl != (Object)(object)Cha)
				{
					AI.Create(this, AI.Type.Guest);
				}
			}
			if (Sex == Gender.Girl && birthContext != Dealer.Context.Default)
			{
				GrabCtrl = GrabCtrl.Create(Cha, birthContext != Dealer.Context.H);
				((ChaFile)ChaFileGhost).CopyAll((ChaFile)(object)((ChaInfo)Cha).chaFile);
				if (birthContext == Dealer.Context.H)
				{
					if ((Object)(object)instance != (Object)null && (Object)(object)((CharaData)instance.lstHeroine[0]).chaCtrl == (Object)(object)Cha)
					{
						HSaveData = instance.lstHeroine[0];
						HInfo = Count.CreateInfo(Core.dealer.InStory ? instance.lstHeroine[0] : instance.lstHeroine[0], instance.count);
						if (!Core.dealer.InStory)
						{
							Core.dealer.HCtrl.FreeHDefCount = Count.CloneInfo(HInfo);
							Console.WriteLine("CLONING MAIN GIRL H INFO AT FREE H Start");
						}
						Typ = Type.MainGirl;
						CreationId = 0;
						AI.Create(this, AI.Type.MainGirl);
						FaceTxt = CreateFaceText(((ChaFile)((CharaData)instance.lstHeroine[0]).charFile).facePngData);
						HCtrl.SetMainGirlToHCtrl(this, 0);
						((MonoBehaviour)this).StartCoroutine(IE_SearchMainNpcBase());
						if (Core.dealer.InStory && Core.dealer.StoryHInf != null)
						{
							Core.dealer.StoryHInf.mainGirlSavAtStart = instance.lstHeroine[0];
						}
						if (Core.dealer.InStory)
						{
							GManage.ChaSnapshot andApplySnapshot = GManage.GetAndApplySnapshot((CharaData)(object)instance.lstHeroine[0], Cha);
							if (andApplySnapshot != null && andApplySnapshot.orgAtEcchiEnd != 0)
							{
								if (Object.op_Implicit((Object)(object)Singleton<HFlag>.Instance))
								{
									Singleton<HFlag>.Instance.count.aibuOrg = andApplySnapshot.orgAtEcchiEnd;
								}
								HInfo.HCount.aibuOrg = andApplySnapshot.orgAtEcchiEnd;
							}
						}
					}
					else if ((Object)(object)instance != (Object)null && instance.lstHeroine.Count > 1 && (Object)(object)((CharaData)instance.lstHeroine[1]).chaCtrl == (Object)(object)Cha)
					{
						HSaveData = instance.lstHeroine[1];
						HInfo = Count.CreateInfo(Core.dealer.InStory ? instance.lstHeroine[1] : instance.lstHeroine[1], null);
						Typ = Type.SecondGirl;
						AI.Create(this, AI.Type.MainGirl);
						FaceTxt = CreateFaceText(((ChaFile)((CharaData)instance.lstHeroine[1]).charFile).facePngData);
						HCtrl.SetMainGirlToHCtrl(this, 1);
						CreationId = 1;
						if (Core.dealer.InStory && Core.dealer.StoryHInf != null)
						{
							Core.dealer.StoryHInf.secGirlSavAtStart = instance.lstHeroine[1];
						}
						if (Core.dealer.InStory)
						{
							GManage.ChaSnapshot andApplySnapshot2 = GManage.GetAndApplySnapshot((CharaData)(object)instance.lstHeroine[1], Cha);
							if (andApplySnapshot2 != null && andApplySnapshot2.orgAtEcchiEnd != 0)
							{
								HInfo.HCount.aibuOrg = andApplySnapshot2.orgAtEcchiEnd;
							}
						}
					}
					else
					{
						AI.Create(this, AI.Type.Guest);
						if (HSaveData != null)
						{
							GManage.ChaSnapshot andApplySnapshot3 = GManage.GetAndApplySnapshot((CharaData)(object)HSaveData, Cha);
							if (andApplySnapshot3 != null && andApplySnapshot3.orgAtEcchiEnd != 0 && HInfo != null && HInfo.HCount != null)
							{
								HInfo.HCount.aibuOrg = andApplySnapshot3.orgAtEcchiEnd;
							}
						}
					}
				}
			}
			if (!Core.dealer.InCharaMaker && Core.dealer.GameMenuCtx != Dealer.MenuCtx.Booking)
			{
				if (Sex == Gender.Girl)
				{
					BreastPusher.Create(Cha, (Object)(object)Npc != (Object)null || (Object)(object)FixNpc != (Object)null);
					BellyCtrl.Create(Cha, (Object)(object)Npc != (Object)null || (Object)(object)FixNpc != (Object)null);
					if ((Object)(object)Npc == (Object)null && (Object)(object)FixNpc == (Object)null)
					{
						GenitalGirl = GenitalGirl.Create(Cha);
					}
				}
				if (Sex == Gender.Girl && birthContext == Dealer.Context.Default && (Object)(object)Npc == (Object)null && (Object)(object)FixNpc == (Object)null)
				{
					if (!CreationComesFromCtrlHome)
					{
						AI.Create(this, AI.Type.MainGirl);
						Core.dealer.EventCha = Cha;
						if (Core.dealer.eventInfo.chas.Count == 0)
						{
							Events.ClearInfo(Core.dealer.eventInfo);
							Core.dealer.eventInfo.chas.Add(Cha);
							Events.SearchMissingSave();
						}
					}
					if (CreationComesFromCtrlHome)
					{
						(AI.Create(this, AI.Type.Guest) as AIGuest).CreatedByCtrlHome = true;
					}
					GrabCtrl = GrabCtrl.Create(Cha, searchForGrab: true);
					CtrlIK = CtrlIK.Create(Cha);
					BoneCtrl = CtrlBones.Create(Cha);
				}
			}
			if (Core.dealer.InCharaMaker && Sex == Gender.Boy)
			{
				MakerCtrl.Create(Cha);
			}
			DebugInfos.InConsoleCompact(" Init on " + ((ChaFile)((ChaInfo)Cha).chaFile).parameter.fullname + " gender is " + Sex.ToString() + "(ctx:" + birthContext.ToString() + ")" + (Object.op_Implicit((Object)(object)FixNpc) ? "(Fix Chara)" : ""), cmpName);
			isInit = true;
		}

