		public static void SwapCharacter(ChaCore src, ChaCore target, bool swapHUiFace = false)
		{
			//IL_0092: Unknown result type (might be due to invalid IL or missing references)
			//IL_0099: Expected O, but got Unknown
			Type typ = src.Typ;
			Type typ2 = target.Typ;
			int creationId = src.CreationId;
			int creationId2 = target.CreationId;
			byte[] siruOnGirl = ChaTools.GetSiruOnGirl(src.Cha);
			byte[] siruOnGirl2 = ChaTools.GetSiruOnGirl(target.Cha);
			bool num = CtrlBodySiru.HasComponent(src.Cha);
			bool flag = CtrlBodySiru.HasComponent(target.Cha);
			int lv = 0;
			CtrlTongSiru.GetSiruLvAndDestroy(src.Cha, ref lv);
			int lv2 = 0;
			CtrlTongSiru.GetSiruLvAndDestroy(target.Cha, ref lv2);
			float voiceRate = ((ChaInfo)src.Cha).fileParam.voiceRate;
			float voiceRate2 = ((ChaInfo)target.Cha).fileParam.voiceRate;
			ChaFileControl val = new ChaFileControl();
			((ChaFile)val).CopyAll((ChaFile)(object)((ChaInfo)target.Cha).chaFile);
			((ChaFile)((ChaInfo)target.Cha).chaFile).CopyAll((ChaFile)(object)((ChaInfo)src.Cha).chaFile);
			((ChaFile)((ChaInfo)src.Cha).chaFile).CopyAll((ChaFile)(object)val);
			target.Cha.Reload(false, false, false, false);
			target.Cha.ChangeCoordinateTypeAndReload(true);
			src.Cha.Reload(false, false, false, false);
			src.Cha.ChangeCoordinateTypeAndReload(true);
			ChaTools.SetSiruOnCha(src.Cha, siruOnGirl2);
			ChaTools.SetSiruOnCha(target.Cha, siruOnGirl);
			if (num)
			{
				CtrlBodySiru.GetOrCreate(target.Cha, reInit: true);
			}
			if (flag)
			{
				CtrlBodySiru.GetOrCreate(src.Cha, reInit: true);
			}
			CtrlTongSiru.GetOrCreate(target.Cha, lv, forceCreate: true);
			CtrlTongSiru.GetOrCreate(src.Cha, lv2, forceCreate: true);
			src.SetType(typ2);
			((Component)target).GetComponent<ChaCore>().SetType(typ);
			src.CreationId = creationId2;
			target.CreationId = creationId;
			if (Core.dealer.InStory)
			{
				Heroine hSaveData = target.HSaveData;
				target.HSaveData = src.HSaveData;
				src.HSaveData = hSaveData;
				DebugInfos.InConsoleCompact("Target Girl is now " + ((CharaData)target.HSaveData).parameter.fullname, cmpName + ".SwapCha");
				DebugInfos.InConsoleCompact("Source Girl is now " + ((CharaData)src.HSaveData).parameter.fullname, cmpName + ".SwapCha");
			}
			if (target.HInfo != null && src.HInfo != null)
			{
				Count.HInfo hInfo = Count.CloneInfo(target.HInfo);
				target.HInfo = src.HInfo;
				src.HInfo = hInfo;
			}
			BreastPusher.TryValuesSwap(src.Cha, target.Cha);
			BellyCtrl.TryValuesSwap(src.Cha, target.Cha);
			((ChaInfo)target.Cha).fileParam.voiceRate = voiceRate;
			((ChaInfo)src.Cha).fileParam.voiceRate = voiceRate2;
			ChaTools.SetFaceShadowsStrenght(target.Cha);
			ChaTools.SetFaceShadowsStrenght(src.Cha);
			ChaTools.SetBodyShadowsStrenght(target.Cha);
			ChaTools.SetBodyShadowsStrenght(src.Cha);
			if (swapHUiFace)
			{
				HCtrl.Get.HSprite.rawFace.texture = (Texture)(object)src.FaceTxt;
				Texture2D faceTxt = CreateFaceText(ImageConversion.EncodeToPNG(src.FaceTxt));
				src.FaceTxt = target.FaceTxt;
				target.FaceTxt = faceTxt;
			}
		}

