		public static void InformNpcWhoIsInH(Heroine her, bool considerFix = false)
		{
			if (Core.dealer.InStory && her != null)
			{
				ChaCore chaCore = FindChaCoreNpcFromSave(her);
				if ((Object)(object)chaCore != (Object)null && (Object)(object)chaCore.Npc != (Object)null)
				{
					((MonoBehaviour)chaCore).StartCoroutine(chaCore.IE_NpcWaitForHEnd(chaCore.Npc));
					DebugInfos.InConsole("Found NPC " + Name(((ChaInfo)chaCore.Cha).fileParam) + " match with HSave " + Name(((CharaData)her).parameter), "InformNpcWhoIsInH");
				}
			}
		}

		public static ChaCore FindChaCoreNpcFromSave(Heroine her, bool considerFix = false)
		{
			if (her == null)
			{
				return null;
			}
			ChaCore[] array = Object.FindObjectsOfType<ChaCore>();
			for (int i = 0; i < array.Length; i++)
			{
				if (((Object)(object)array[i].Npc != (Object)null && ((Base)array[i].Npc).heroine == her) || (considerFix && (Object)(object)array[i].FixNpc != (Object)null && ((Base)array[i].FixNpc).heroine == her))
				{
					return array[i];
				}
			}
			return null;
		}

		public static Heroine TryToGetSaveFromChaCore(GameObject goToTest)
		{
			if (!Object.op_Implicit((Object)(object)goToTest.GetComponent<ChaCore>()))
			{
				return null;
			}
			ChaCore component = goToTest.GetComponent<ChaCore>();
			if (component.HSaveData != null)
			{
				return component.HSaveData;
			}
			if ((Object)(object)component.Npc != (Object)null)
			{
				return ((Base)component.Npc).heroine;
			}
			if ((Object)(object)component.FixNpc != (Object)null)
			{
				return ((Base)component.FixNpc).heroine;
			}
			if (CtrlHome.IsActive)
			{
				return CtrlHome.FindSave(component.Cha);
			}
			return null;
		}

		public static int GetRelation(ChaCore core)
		{
			if ((Object)(object)core == (Object)null)
			{
				return 0;
			}
			if (Object.op_Implicit((Object)(object)core.Npc))
			{
				return ((Base)core.Npc).heroine.relation;
			}
			if (Object.op_Implicit((Object)(object)core.FixNpc))
			{
				return ((Base)core.FixNpc).heroine.relationNPC;
			}
			if (core.HSaveData != null)
			{
				if (core.HSaveData.fixCharaID >= 0)
				{
					return core.HSaveData.relation;
				}
				return core.HSaveData.relationNPC;
			}
			return 0;
		}

