		public static List<FileInfo> GetGirlSaveList()
		{
			List<FileInfo> chaFiles = new List<FileInfo>();
			foreach (Heroine heroine in Game.HeroineList)
			{
				AddGirlSaveFileToList(heroine, ref chaFiles);
			}
			return chaFiles;
		}

		public static List<FileInfo> GetGirlCardList()
		{
			int num = (Settings.LimitLoadChaFile ? Settings.ChaFileLimit : (-1));
			List<FileInfo> chaFilesInfo = new List<FileInfo>();
			GetChaFileFromFolder(AppContext.BaseDirectory + "/DefaultData/chara/female/", 1, ref chaFilesInfo, num);
			GetChaFileFromFolder(AppContext.BaseDirectory + "/UserData/chara/female/", 1, ref chaFilesInfo, (num != -1) ? Mathf.Max(num - chaFilesInfo.Count, 0) : (-1));
			return chaFilesInfo;
		}

		public static List<FileInfo> GetMaleCardList()
		{
			List<FileInfo> chaFilesInfo = new List<FileInfo>();
			GetChaFileFromFolder(AppContext.BaseDirectory + "/UserData/chara/male/", 0, ref chaFilesInfo);
			return chaFilesInfo;
		}

		private static List<FileInfo> GetChaFileFromFolder(string path, int sex, ref List<FileInfo> chaFilesInfo, int cardLimit = -1)
		{
			//IL_0017: Unknown result type (might be due to invalid IL or missing references)
			//IL_001d: Expected O, but got Unknown
			//IL_00f5: Unknown result type (might be due to invalid IL or missing references)
			//IL_00fc: Expected O, but got Unknown
			if (!Directory.Exists(path))
			{
				return chaFilesInfo;
			}
			string[] directories = Directory.GetDirectories(path, "*");
			FolderAssist val = new FolderAssist();
			val.CreateFolderInfoEx(path, new string[1] { "*.png" }, true);
			int num = 0;
			for (int i = 0; i < val.GetFileCount(); i++)
			{
				if (cardLimit != -1 && num >= cardLimit)
				{
					return chaFilesInfo;
				}
				AddChaFileToList(val.lstFile[i], sex, "Root", ref chaFilesInfo);
				num++;
			}
			string[] array = directories;
			foreach (string text in array)
			{
				val.CreateFolderInfoEx(text, new string[1] { "*.png" }, true);
				string lastString = Helper.GetLastString(text, "/");
				string[] directories2 = Directory.GetDirectories(path + "/" + lastString + "/", "*");
				for (int k = 0; k < val.GetFileCount(); k++)
				{
					AddChaFileToList(val.lstFile[k], sex, lastString, ref chaFilesInfo);
				}
				if (directories2.Length == 0)
				{
					continue;
				}
				FolderAssist val2 = new FolderAssist();
				string[] array2 = directories2;
				foreach (string text2 in array2)
				{
					val2.CreateFolderInfoEx(text2, new string[1] { "*.png" }, true);
					for (int m = 0; m < val2.GetFileCount(); m++)
					{
						if (cardLimit != -1 && num >= cardLimit)
						{
							return chaFilesInfo;
						}
						AddChaFileToList(val2.lstFile[m], sex, lastString, ref chaFilesInfo);
						num++;
					}
				}
			}
			return chaFilesInfo;
		}

		private static void AddChaFileToList(FileInfo fileInfo, int sex, string folderFilter, ref List<FileInfo> chaFiles)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Expected O, but got Unknown
			ChaFileControl val = new ChaFileControl();
			if (val.LoadCharaFile(fileInfo.FullPath, (byte)sex, false, true))
			{
				FileInfo fileInfo2 = new FileInfo();
				fileInfo2.File = val;
				int num = (int)((float)(Screen.height / 6) * 1.5f);
				fileInfo2.png = (Texture)(object)PngAssist.ChangeTextureFromByte(((ChaFile)val).pngData, (int)((float)num * 0.7f), num);
				fileInfo2.filter = folderFilter;
				fileInfo2.cardPath = fileInfo.FullPath;
				chaFiles.Add(fileInfo2);
			}
		}

		private static void AddGirlSaveFileToList(Heroine heroine, ref List<FileInfo> chaFiles)
		{
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			//IL_000c: Expected O, but got Unknown
			FileInfo fileInfo = new FileInfo();
			ChaFileControl val = new ChaFileControl();
			((ChaFile)val).CopyAll((ChaFile)(object)((CharaData)heroine).charFile);
			fileInfo.File = val;
			int num = Screen.height / 6;
			((ChaFile)val).facePngData = ((ChaFile)((CharaData)heroine).charFile).facePngData;
			((ChaFile)val).pngData = ((ChaFile)((CharaData)heroine).charFile).pngData;
			fileInfo.png = (Texture)(object)PngAssist.ChangeTextureFromByte(((ChaFile)val).facePngData, (int)((float)num * 0.7f), num);
			fileInfo.Save = heroine;
			fileInfo.filter = StayingPlace(((CharaData)heroine).schoolClass);
			chaFiles.Add(fileInfo);
		}

		private static string StayingPlace(int id)
		{
			return id switch
			{
				-1 => "All", 
				0 => "Hotel", 
				1 => "Guest House", 
				2 => "T-Center", 
				_ => "Unknown", 
			};
		}
	}
