		private void Start()
		{
			cha = ((Component)this).GetComponent<ChaControl>();
			ai = ((Component)cha).GetComponent<AI>();
			((MonoBehaviour)this).StartCoroutine(IE_Init());
		}

		private void LateUpdate()
		{
			if (isInit && (ChaTools.IsClean(cha) || !Settings.EnhanceBukkake))
			{
				Object.Destroy((Object)(object)this);
			}
		}

		private void OnDestroy()
		{
			try
			{
				((ChaInfo)cha).customMatBody.SetTexture("_liquidmask", maskBody);
				((ChaInfo)cha).customMatFace.SetTexture("_liquidmask", maskFace);
			}
			catch
			{
			}
		}

		private IEnumerator IE_Init(float wait = 0f)
		{
			if (wait != 0f)
			{
				yield return (object)new WaitForSeconds(wait);
			}
			yield return (object)new WaitUntil((Func<bool>)(() => cha.GetActiveTop() && ((ChaInfo)cha).loadEnd));
			yield return (object)new WaitForEndOfFrame();
			if ((Object)(object)custMaskBody == (Object)null)
			{
				custMaskBody = CommonLib.LoadAsset<Texture2D>("studio_k/mat/04.unity3d", "cf_body_01_ml", true, string.Empty, true);
			}
			if ((Object)(object)custMaskFace == (Object)null)
			{
				custMaskFace = CreateTexture.PlainTxt(16, Color.cyan);
			}
			maskBody = ((ChaInfo)cha).customMatBody.GetTexture("_liquidmask");
			maskFace = ((ChaInfo)cha).customMatFace.GetTexture("_liquidmask");
			((ChaInfo)cha).customMatBody.SetTexture("_liquidmask", (Texture)(object)custMaskBody);
			((ChaInfo)cha).customMatFace.SetTexture("_liquidmask", (Texture)(object)custMaskFace);
			isInit = true;
		}

		public static bool HasComponent(ChaControl cha)
		{
			return (Object)(object)((Component)cha).GetComponent<CtrlBodySiru>() != (Object)null;
		}

		public static CtrlBodySiru GetOrCreate(ChaControl cha, bool reInit = false)
		{
			if (!Settings.EnhanceBukkake)
			{
				return null;
			}
			CtrlBodySiru ctrlBodySiru = null;
			if ((Object)(object)((Component)cha).GetComponent<CtrlBodySiru>() != (Object)null)
			{
				ctrlBodySiru = ((Component)cha).GetComponent<CtrlBodySiru>();
				if (reInit)
				{
					((MonoBehaviour)ctrlBodySiru).StartCoroutine(ctrlBodySiru.IE_Init(Time.deltaTime));
				}
			}
			else
			{
				ctrlBodySiru = ((Component)cha).gameObject.AddComponent<CtrlBodySiru>();
			}
			return ctrlBodySiru;
		}
	}
	public class CtrlTongSiru : MonoBehaviour
	{
		private readonly Color ambientCol = new Color(0.019f, 0.027f, 0.039f, 0.75f);

		private static Texture2D siruTxt;

		private static Texture2D mainTex;

		private static Texture2D maskTex;

		private Texture normalMap;

		private Texture detailMask;

		private ChaControl cha;

		private AI Ai;

		private int lv;

		private int _lv;

		private float kissTimer;

		private List<Renderer> tonguesRnds = new List<Renderer>();

		private bool _addSiruOnTong;

		private bool isInit;

		private void Start()
		{
			cha = ((Component)this).GetComponent<ChaControl>();
			Ai = ((Component)this).GetComponent<AI>();
			_addSiruOnTong = Settings.AddSiruOnTong;
			_lv = lv;
			Init();
		}

		private void LateUpdate()
		{
			//IL_013f: Unknown result type (might be due to invalid IL or missing references)
			if (!isInit)
			{
				return;
			}
			if (cha.GetMouthPtn() == 23 || cha.GetMouthPtn() == 24)
			{
				if (Ai.IsInKiss() && Core.dealer.mInfos.dragLenght > 0.25f)
				{
					kissTimer += Time.deltaTime;
				}
			}
			else if (kissTimer != 0f)
			{
				kissTimer = 0f;
			}
			if (kissTimer > 5f)
			{
				lv = Mathf.Clamp(lv - 1, 0, 2);
			}
			if (_lv != lv || Settings.AddSiruOnTong != _addSiruOnTong)
			{
				foreach (Renderer tonguesRnd in tonguesRnds)
				{
					ChaTools.SetSiruOnMaterial(tonguesRnd.material, _addSiruOnTong ? lv : 0, onFace: true);
				}
				_addSiruOnTong = Settings.AddSiruOnTong;
				_lv = lv;
				kissTimer = 0f;
			}
			foreach (Renderer tonguesRnd2 in tonguesRnds)
			{
				tonguesRnd2.material.SetColor(ChaShader._ambientshadowG, ambientCol);
			}
			if (!Settings.AddSiruOnTong)
			{
				Object.Destroy((Object)(object)this);
			}
		}

		private void OnDestroy()
		{
		}

		private void Init()
		{
			((MonoBehaviour)this).StartCoroutine(IE_Init());
		}

		private IEnumerator IE_Init()
		{
			yield return (object)new WaitUntil((Func<bool>)(() => cha.GetActiveTop() && ((ChaInfo)cha).loadEnd));
			yield return (object)new WaitForEndOfFrame();
			if ((Object)(object)siruTxt == (Object)null)
			{
				LoadSiruTexture();
			}
			if ((Object)(object)mainTex == (Object)null)
			{
				mainTex = CreateTexture.PlainTxt(64, new Color(1f, 0.71f, 0.71f, 1f));
			}
			if ((Object)(object)maskTex == (Object)null)
			{
				maskTex = CreateTexture.PlainTxt(16, new Color(0f, 1f, 1f, 1f));
			}
			SearchAndSetTongues();
			isInit = true;
		}

		private void SearchAndSetTongues()
		{
			//IL_01ac: Unknown result type (might be due to invalid IL or missing references)
			List<Transform> list = new List<Transform>();
			Transform[] componentsInChildren = ((Component)cha).GetComponentsInChildren<Transform>(true);
			foreach (Transform val in componentsInChildren)
			{
				if (((Object)val).name == "o_tang")
				{
					list.Add(val);
				}
			}
			foreach (Transform item in list)
			{
				Renderer component = ((Component)item).gameObject.GetComponent<Renderer>();
				if ((Object)(object)component == (Object)null || tonguesRnds.Contains(component))
				{
					continue;
				}
				Transform[] componentsInParent = ((Component)component).gameObject.GetComponentsInParent<Transform>();
				if (componentsInParent.Length < 2 || !(((Object)((Component)componentsInParent[1]).gameObject).name == "p_tang"))
				{
					tonguesRnds.Add(component);
					if ((Object)(object)normalMap == (Object)null)
					{
						normalMap = component.material.GetTexture("_NormalMap");
					}
					if ((Object)(object)detailMask == (Object)null)
					{
						detailMask = component.material.GetTexture("_DetailMask");
					}
					component.material.shader = Shader.Find("Koikano/main_skin");
					component.material.SetTexture("_MainTex", (Texture)(object)mainTex);
					component.material.SetTexture("_liquidmask", (Texture)(object)maskTex);
					component.material.SetTexture("_NormalMap", normalMap);
					component.material.SetTexture("_DetailMask", detailMask);
					component.material.SetTexture("_Texture2", (Texture)(object)siruTxt);
					ChaTools.SetSiruOnMaterial(component.material, lv, onFace: true);
					component.material.SetColor(ChaShader._ambientshadowG, ambientCol);
				}
			}
		}

		private void LoadSiruTexture()
		{
			siruTxt = CommonLib.LoadAsset<Texture2D>("studio_k/mat/04.unity3d", "liquid01_t", true, string.Empty, true);
		}

		public static bool HasComponent(ChaControl cha)
		{
			return (Object)(object)((Component)cha).GetComponent<CtrlTongSiru>() != (Object)null;
		}

		public static void GetSiruLvAndDestroy(ChaControl cha, ref int lv)
		{
			if (HasComponent(cha))
			{
				CtrlTongSiru component = ((Component)cha).GetComponent<CtrlTongSiru>();
				lv = component.lv;
				Object.Destroy((Object)(object)component);
			}
		}

		public static CtrlTongSiru GetOrCreate(ChaControl cha, int siruLv = 2, bool forceCreate = false)
		{
			if (!Settings.AddSiruOnTong)
			{
				return null;
			}
			CtrlTongSiru ctrlTongSiru = null;
			if ((Object)(object)((Component)cha).GetComponent<CtrlTongSiru>() != (Object)null && !forceCreate)
			{
				ctrlTongSiru = ((Component)cha).GetComponent<CtrlTongSiru>();
			}
			else
			{
				if (siruLv == 0)
				{
					return null;
				}
				ctrlTongSiru = ((Component)cha).gameObject.AddComponent<CtrlTongSiru>();
			}
			ctrlTongSiru.lv = siruLv;
			return ctrlTongSiru;
		}
	}
	public class DealCha
	{
		public static void TryToUpdateFileStatus(ChaControl cha)
		{
			Dealer dealer = Core.dealer;
			Clothes.UpdateBaseClothesStatus((dealer.IsEventCtx && dealer.eventInfo.saves.Count != 0) ? dealer.eventInfo.saves[0] : ChaCore.TryToGetSaveFromChaCore(((Component)cha).gameObject), cha);
		}

		public static void Inputs()
		{
			//IL_052f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0723: Unknown result type (might be due to invalid IL or missing references)
			//IL_0837: Unknown result type (might be due to invalid IL or missing references)
			//IL_0a1a: Unknown result type (might be due to invalid IL or missing references)
			//IL_08d6: Unknown result type (might be due to invalid IL or missing references)
			//IL_0658: Unknown result type (might be due to invalid IL or missing references)
			Dealer dealer = Core.dealer;
			if (dealer.mInfos.dblClickRmb)
			{
				ChaTools.ColDefinition colDefinition = (Core.dealer.InH ? HAction.ColDefUnderCursor : Dealer.ColDefUnderCursor);
				if ((Object)(object)colDefinition != (Object)null && !Core.dealer.CursorOverUIS)
				{
					if (Keys.MmbHold)
					{
						if (Clothes.Redress(colDefinition, Keys.CtrlMod))
						{
							Sound.Play((SystemSE)22);
							TryToUpdateFileStatus(colDefinition.cha);
						}
					}
					else if ((!Object.op_Implicit((Object)(object)((Component)colDefinition.cha).GetComponent<AIGuest>()) || !((Component)colDefinition.cha).GetComponent<AIGuest>().InStripTease) && true && Clothes.RemoveCloth(colDefinition, dealer.mInfos.lmbHold))
					{
						Sound.Play((SystemSE)22);
						TryToUpdateFileStatus(colDefinition.cha);
					}
				}
			}
			if (!Core.dealer.InH && !CtrlHome.IsActive && dealer.mInfos.dblClickLmb)
			{
				ChaTools.ColDefinition colDefUnderCursor = Dealer.ColDefUnderCursor;
				if ((Object)(object)colDefUnderCursor != (Object)null && (Object)(object)colDefUnderCursor.cha != (Object)null)
				{
					Transform targFromColDef = FreeCam.GetTargFromColDef(colDefUnderCursor.cha, colDefUnderCursor);
					if (!Core.dealer.HasFreeCam && Dealer.FreeCamPossibleCtxs.Contains(Core.dealer.Ctx))
					{
						Core.dealer.AddFreeCam(targFromColDef);
					}
					else if (Core.dealer.HasFreeCam && !Core.dealer.InFreeCam)
					{
						Core.dealer.FreeCam.isDisabled = false;
					}
					else
					{
						FreeCam.SetTarget(targFromColDef);
					}
				}
			}
			if (!Core.dealer.InH && (CtrlHome.IsActive || (Object)(object)Core.dealer.EstCtrl != (Object)null) && Keys.LmbClick)
			{
				ChaTools.ColDefinition colDefUnderCursor2 = Dealer.ColDefUnderCursor;
				if ((Object)(object)colDefUnderCursor2 != (Object)null && colDefUnderCursor2.part == ChaTools.Part.Head && (Object)(object)colDefUnderCursor2.cha != (Object)null && (Object)(object)((Component)colDefUnderCursor2.cha).GetComponent<AIGuest>() != (Object)null)
				{
					((Component)colDefUnderCursor2.cha).GetComponent<AIGuest>().Kiss();
					if (!Core.dealer.InKissOrGrab)
					{
						Core.dealer.SetInKissOrGrab();
					}
				}
			}
			if (Core.dealer.InStory && Keys.ShootPhoto)
			{
				ChaTools.ColDefinition colDefinition2 = ChaTools.SearchColDefInCamSight();
				if ((Object)(object)colDefinition2 != (Object)null)
				{
					ChaCore component = ((Component)colDefinition2.cha).GetComponent<ChaCore>();
					if ((Object)(object)component != (Object)null)
					{
						Heroine val = null;
						bool flag = false;
						if (Core.dealer.Ctx == Dealer.Context.H)
						{
							ChaList.FileInfo fileInfoFromCreationId = MenuInvite.GetFileInfoFromCreationId(component.CreationId);
							if (fileInfoFromCreationId != null)
							{
								val = fileInfoFromCreationId.Save;
							}
							else if ((Object)(object)component == (Object)(object)Core.dealer.HCtrl.MainBoy)
							{
								flag = true;
							}
						}
						if (Core.dealer.Ctx == Dealer.Context.Esthetic && Core.dealer.girlInEsthetic != null)
						{
							val = Core.dealer.girlInEsthetic;
						}
						if (Core.dealer.Ctx == Dealer.Context.Event && Core.dealer.eventInfo.saves.Count != 0)
						{
							val = Core.dealer.eventInfo.saves[0];
						}
						if (Core.dealer.Ctx == Dealer.Context.Default)
						{
							if (Object.op_Implicit((Object)(object)component.Npc) || Object.op_Implicit((Object)(object)component.FixNpc))
							{
								val = (Object.op_Implicit((Object)(object)component.FixNpc) ? ((Base)component.FixNpc).heroine : ((Base)component.Npc).heroine);
							}
							else if (CtrlHome.IsActive)
							{
								val = CtrlHome.FindSave(component.Cha);
							}
						}
						if (val != null || flag)
						{
							((MonoBehaviour)Core.dealer).StartCoroutine(IE_ShootPhoto(colDefinition2.cha));
						}
					}
				}
			}
			if (Core.dealer.Ctx != Dealer.Context.H && Core.dealer.Ctx != Dealer.Context.Event && Core.dealer.mInfos.lmbShortPress)
			{
				ChaTools.ColDefinition colDefinition3 = ChaTools.SearchColDefUnderCursor();
				List<ChaTools.Part> list = new List<ChaTools.Part>
				{
					ChaTools.Part.Hip,
					ChaTools.Part.Leg,
					ChaTools.Part.Arm,
					ChaTools.Part.Kokan,
					ChaTools.Part.ButtL,
					ChaTools.Part.ButtR
				};
				if (Object.op_Implicit((Object)(object)colDefinition3) && list.Contains(colDefinition3.part))
				{
					AI.ReactToHit(colDefinition3.cha, colDefinition3.part);
				}
			}
			if (Keys.RmbHold && Keys.LmbClick && !Keys.AltMod && (Core.dealer.Ctx != Dealer.Context.H || ((Object)(object)Core.dealer.HCtrl != (Object)null && !Core.dealer.HCtrl.CursorOverUIS)) && ChaTools.Clean(Core.dealer.InH ? HAction.ColDefUnderCursor : Dealer.ColDefUnderCursor, doBubble: true))
			{
				Sound.Play((SystemSE)12);
			}
			if (Keys.CtrlMod && Keys.ClothInteraction && !Keys.ShiftMod)
			{
				ChaTools.ColDefinition colDefinition4 = (Core.dealer.InH ? HAction.ColDefUnderCursor : Dealer.ColDefUnderCursor);
				if ((Object)(object)colDefinition4 != (Object)null)
				{
					if (dealer.IsEventCtx && (Object)(object)dealer.MainGirlCha != (Object)null)
					{
						Clothes.NextCoordinate(colDefinition4.cha, dealer.eventInfo.saves[0]);
					}
					else
					{
						Heroine save = ChaCore.TryToGetSaveFromChaCore(((Component)colDefinition4.cha).gameObject);
						Clothes.NextCoordinate(colDefinition4.cha, save);
					}
					Cam.DoFade(0.1f);
				}
			}
			if (!Map.CyclesOnMap.Contains(dealer.NowCycle))
			{
				return;
			}
			if (dealer.InStory && dealer.Ctx == Dealer.Context.Default && (Keys.OnMapAskEcchi || Keys.OnMapAskPeep))
			{
				List<ChaCore> list2 = new List<ChaCore>();
				List<int> list3 = new List<int>();
