		public static IEnumerator IE_ShootPhoto(ChaControl cha)
		{
			yield return (object)new WaitForEndOfFrame();
			byte[] pngData = new byte[0];
			GameAssets.CreatePng(ref pngData, null, null, Camera.main, null, 2);
			string text = ChaCore.Name(((ChaInfo)cha).fileParam);
			DebugInfos.InConsole("TAKING A PHOTO OF " + text);
			string text2 = Helper.FindFreeFileName(Settings.PhotoPath, text.Replace(" ", "") + "_shot_", "png");
			using (FileStream output = new FileStream(text2, FileMode.Create, FileAccess.Write))
			{
				using BinaryWriter binaryWriter = new BinaryWriter(output);
				binaryWriter.Write(pngData);
			}
			MenuDiary.TryToAddToPhotoList(text2);
		}

