		public static IEnumerator IE_QueryAirTags(List<AirTag> tags)
		{
			List<string> msgs = new List<string>();
			List<Messenger.TagMsg> tagTyps = new List<Messenger.TagMsg>();
			foreach (AirTag tag in tags)
			{
				Messenger.TagMsg tagMsg = Messenger.TagMsg.Undefined;
				string item = tag.Query(ref tagMsg);
				msgs.Add(item);
				tagTyps.Add(tagMsg);
			}
			int i = 0;
			while (i < msgs.Count)
			{
				yield return (object)new WaitForSeconds(Random.Range(0.025f, 0.095f));
				Core.dealer.Msgn.ReceiveMessage(Messenger.Type.TopCorner_R, msgs[i], 7f, replace: false, write: false, lerp: true, tagTyps[i]);
				Sound.Play((SystemSE)5);
				int num = i + 1;
				i = num;
			}
		}

		public static IEnumerator IE_StickAirTag(ChaCore chaCore, bool waitFromDist = true, ChaTools.Part bp = ChaTools.Part.Undefined)
		{
			float num = (waitFromDist ? Mathf.Min(chaCore.npcInfo.distance * 0.15f, 2.5f) : 0f);
			if (chaCore.npcInfo.distance < 9f || !waitFromDist)
			{
				bool addTag = AirTag.Create(chaCore.Cha);
				yield return (object)new WaitForSeconds(num);
				if (addTag)
				{
					yield return (object)new WaitForEndOfFrame();
					string text = ((bp != ChaTools.Part.Undefined) ? AirTag.GetAttachMsg(ChaCore.Name(((ChaInfo)chaCore.Cha).fileParam, Settings.FirstNameFirst), bp) : ("AirTag® stuck on " + ChaCore.Name(((ChaInfo)chaCore.Cha).fileParam, Settings.FirstNameFirst)));
					Core.dealer.Msgn.ReceiveMessage(Messenger.Type.TopCorner_R, text, 5f, replace: false);
					Sound.Play((SystemSE)12);
					World.EditKoikatsuPoint(-1);
				}
			}
		}

		public static IEnumerator IE_SetNpcAction(ChaCore chaCore, int action)
		{
			yield return (object)new WaitForSeconds(Random.Range(0.5f, 1.4f));
			if (((CharaData)((Base)chaCore.Npc).heroine).parameter.attribute.likeGirls && action == 4)
			{
				bool flag = false;
				ChaCore[] array = Object.FindObjectsOfType<ChaCore>();
				foreach (ChaCore chaCore2 in array)
				{
					if ((Object)(object)chaCore2.Npc != (Object)null && ((Base)chaCore2.Npc).mapNo == Core.dealer.MapID && (Object)(object)chaCore2.Npc != (Object)(object)chaCore && chaCore2.Npc.AI.actionNo != 27 && ((CharaData)((Base)chaCore.Npc).heroine).parameter.attribute.likeGirls)
					{
						SingletonInitializer<ActionScene>.instance.actCtrl.AddDesire(26, ((Base)chaCore.Npc).heroine, 65);
						break;
					}
				}
				if (flag)
				{
					action = 27;
				}
			}
			if (chaCore.Npc.AI.actionNo != action && chaCore.Npc.AI.result.actionNo != action)
			{
				if (action == 4)
				{
					SingletonInitializer<ActionScene>.instance.actCtrl.AddDesire(4, ((Base)chaCore.Npc).heroine, 10);
					chaCore.Npc.AI.SetAction(action, -1);
				}
				if (action == 29)
				{
					SingletonInitializer<ActionScene>.instance.actCtrl.AddDesire(5, ((Base)chaCore.Npc).heroine, 5);
					chaCore.Npc.AI.SetAction(29, Core.dealer.MapID);
				}
				if (action == 1 || action == 2)
				{
					SingletonInitializer<ActionScene>.instance.actCtrl.AddDesire(action, ((Base)chaCore.Npc).heroine, 10);
					chaCore.Npc.AI.SetAction(action, -1);
				}
			}
			else
			{
				DebugInfos.InConsole(ChaCore.Name(((ChaInfo)((Base)chaCore.Npc).chaCtrl).fileParam) + " already has action " + action + ", skipping", "IE_SetNpcAction");
			}
		}

