		public class ColDefinition : MonoBehaviour
		{
			public Part part;

			public ChaControl cha;

			private float delaySiruColTimer;

			private void LateUpdate()
			{
				if (delaySiruColTimer != 0f)
				{
					Helper.TimerToZero(ref delaySiruColTimer);
				}
			}

			public void AdaptSiruOnCollision(bool onBack, bool add, Vector3 contactPos)
			{
				//IL_0143: Unknown result type (might be due to invalid IL or missing references)
				if (delaySiruColTimer != 0f)
				{
					return;
				}
				bool[] onParts = new bool[5];
				if (part == Part.BreastL || part == Part.BreastR || part == Part.Chest)
				{
					onParts = new bool[5]
					{
						false,
						!onBack,
						false,
						onBack,
						false
					};
				}
				if (part == Part.Head)
				{
					onParts = new bool[5] { true, false, false, false, false };
					if (cha.GetMouthPtn() == 24 && Settings.AddSiruOnTong)
					{
						CtrlTongSiru.GetOrCreate(cha, add ? 2 : 0);
					}
				}
				if (part == Part.Hip || part == Part.Kokan || part == Part.Anal || part == Part.ButtL || part == Part.ButtR || part == Part.Leg)
				{
					onParts = new bool[5]
					{
						false,
						false,
						!onBack,
						false,
						onBack
					};
				}
				if (add)
				{
					if (AddSiruOnCha(cha, onParts) && Core.dealer.InStory && Object.op_Implicit((Object)(object)((Component)cha).GetComponent<AI>()))
					{
						((Component)cha).GetComponent<AI>().EjaOnChaToDaily();
					}
				}
				else
				{
					RemoveSiruOnCha(cha, onParts);
				}
				if (Object.op_Implicit((Object)(object)((Component)cha).GetComponent<AI>()))
				{
					((Component)cha).GetComponent<AI>().ReactToHit(part);
				}
				if (!add)
				{
					GameAssets.CreateBubble(contactPos);
				}
				delaySiruColTimer = 1.25f;
			}
		}

