		private static Part GetPartFromName(string name)
		{
			switch (name)
			{
			case "Chest":
			case "Neck":
				return Part.Chest;
			case "Head":
				return Part.Head;
			case "Hip":
				return Part.Hip;
			default:
				if (name.Contains("Arm") || name.Contains("Forearm") || name.Contains("Hand"))
				{
					return Part.Arm;
				}
				if (name.Contains("Thigh") || name.Contains("Shin") || name.Contains("Foot"))
				{
					return Part.Leg;
				}
				return name switch
				{
					"L_Breast" => Part.BreastL, 
					"R_Breast" => Part.BreastR, 
					"Kokan" => Part.Kokan, 
					"Anal" => Part.Anal, 
					"L_Butt" => Part.ButtL, 
					"R_Butt" => Part.ButtR, 
					_ => Part.Undefined, 
				};
			}
		}

