				string stringAtIndex2 = Helper.GetStringAtIndex(item.Key, "/", 2);
				Transform val = FindInCha(cha, stringAtIndex2);
				if ((Object)(object)val == (Object)null)
				{
					DebugInfos.InConsoleCompact("Can't find " + stringAtIndex2 + " on chara " + ((ChaInfo)cha).fileParam.fullname, "ChaTools.AddColliders");
					return false;
				}
				Part partFromName = GetPartFromName(stringAtIndex);
				GameObject val2 = new GameObject(stringAtIndex + "_root");
				GameObject obj = GameObject.CreatePrimitive((PrimitiveType)0);
				obj.AddComponent<Rigidbody>().isKinematic = true;
				obj.transform.SetParent(val2.transform, false);
				val2.transform.SetParent(val, false);
				ColDefinition colDefinition = obj.AddComponent<ColDefinition>();
				colDefinition.cha = cha;
				colDefinition.part = partFromName;
				((Object)obj).name = stringAtIndex;
				((Component)colDefinition).gameObject.transform.localPosition = item.Value[0];
				((Component)colDefinition).gameObject.transform.localScale = item.Value[1] * 0.3f;
				Collider component = ((Component)colDefinition).gameObject.GetComponent<Collider>();
				if (!Helper.IsHomothetic(item.Value[1]))
				{
					component.enabled = false;
					component.isTrigger = true;
					if ((Object)(object)((Component)colDefinition).gameObject.GetComponent<MeshCollider>() == (Object)null)
					{
						((Component)colDefinition).gameObject.AddComponent<MeshCollider>();
					}
					else
					{
						((Collider)((Component)colDefinition).gameObject.GetComponent<MeshCollider>()).enabled = true;
					}
				}
				((Component)colDefinition).gameObject.GetComponent<Renderer>().enabled = debugDraw;
				ColDefsManager.GetOrCreate(cha, ((Component)colDefinition).gameObject);
			}
			return true;
		}

