		public static bool AddSiruOnCha(ChaControl cha, bool[] onParts)
		{
			bool result = false;
			byte[] siruOnGirl = GetSiruOnGirl(cha);
			for (int i = 0; i < onParts.Length; i++)
			{
				if (onParts[i] && siruOnGirl[i] < 2)
				{
					siruOnGirl[i]++;
					result = true;
				}
			}
			SetSiruOnCha(cha, siruOnGirl);
			return result;
		}

		public static void RemoveSiruOnCha(ChaControl cha, bool[] onParts)
		{
			byte[] siruOnGirl = GetSiruOnGirl(cha);
			for (int i = 0; i < onParts.Length; i++)
			{
				if (onParts[i] && siruOnGirl[i] != 0)
				{
					siruOnGirl[i]--;
				}
			}
			SetSiruOnCha(cha, siruOnGirl);
		}

