		public static bool CleanPart(ChaControl cha, Part part)
		{
			switch (part)
			{
			case Part.Chest:
			case Part.Arm:
			case Part.BreastL:
			case Part.BreastR:
			{
				int siruFlags2 = cha.GetSiruFlags((SiruParts)1);
				if (siruFlags2 != 0)
				{
					cha.SetSiruFlags((SiruParts)1, (byte)(siruFlags2 - 1));
				}
				int siruFlags3 = cha.GetSiruFlags((SiruParts)3);
				if (siruFlags3 != 0)
				{
					cha.SetSiruFlags((SiruParts)3, (byte)(siruFlags3 - 1));
				}
				if (siruFlags2 == 0)
				{
					return siruFlags3 != 0;
				}
				return true;
			}
			case Part.Hip:
			case Part.Leg:
			case Part.Kokan:
			case Part.Anal:
			case Part.ButtL:
			case Part.ButtR:
			{
				int siruFlags4 = cha.GetSiruFlags((SiruParts)2);
				if (siruFlags4 != 0)
				{
					cha.SetSiruFlags((SiruParts)2, (byte)(siruFlags4 - 1));
				}
				int siruFlags5 = cha.GetSiruFlags((SiruParts)4);
				if (siruFlags5 != 0)
				{
					cha.SetSiruFlags((SiruParts)4, (byte)(siruFlags5 - 1));
				}
				if (siruFlags4 == 0)
				{
					return siruFlags5 != 0;
				}
				return true;
			}
			case Part.Head:
			{
				int siruFlags = cha.GetSiruFlags((SiruParts)0);
				if (siruFlags != 0)
				{
					cha.SetSiruFlags((SiruParts)0, (byte)(siruFlags - 1));
				}
				return siruFlags != 0;
			}
			default:
				return false;
			}
		}

