			}
			if (Core.dealer.InH && (Ctx == Context.InMasturbate || Ctx == Context.InTease))
			{
				list = new List<AimTyp> { item, item };
			}
			if (Core.dealer.InH && Ctx == Context.InLesbian)
			{
				list = new List<AimTyp>
				{
