		public static AudioSource StaticSpeak(Voices.Clip clip, ChaControl cha, Transform voiceTrs, bool force = false)
		{
			if (!force && Voice.IsPlay())
			{
				return null;
			}
			AudioSource component = ((Component)voiceTrs).GetComponent<AudioSource>();
			if ((Object)(object)component != (Object)null)
			{
				component.Stop();
			}
			component = Voice.Play(Voices.Loader(clip, ((ChaInfo)cha).fileParam.personality, ((ChaInfo)cha).fileParam.voicePitch, voiceTrs));
			cha.SetLipSync(component);
			return component;
		}

		private Transform FindAimTransform(AimTyp aim)
		{
