			{
				HFlag hFlag = HCtrl.Get.HFlag;
				switch (aim)
				{
				case AimTyp.Camera:
					return ((Component)Camera.main).transform;
				case AimTyp.B1Face:
					return ChaTools.FindInCha(((CharaData)hFlag.player).chaCtrl, "cf_J_NoseBridge_rx");
				case AimTyp.B1Chest:
					return ChaTools.FindInCha(((CharaData)hFlag.player).chaCtrl, "cf_j_spine03");
				case AimTyp.B1Penis:
					return ChaTools.FindInCha(((CharaData)hFlag.player).chaCtrl, "cf_j_kokan");
				case AimTyp.B1Knob:
					return ChaTools.FindInCha(((CharaData)hFlag.player).chaCtrl, "cm_J_dan109_00");
				case AimTyp.G1Face:
					return ChaTools.FindInCha(((CharaData)hFlag.lstHeroine[0]).chaCtrl, "cf_J_NoseBridge_rx");
				case AimTyp.G1Chest:
					return ChaTools.FindInCha(((CharaData)hFlag.lstHeroine[0]).chaCtrl, "cf_j_spine03");
				case AimTyp.G1Vagin:
					return ChaTools.FindInCha(((CharaData)hFlag.lstHeroine[0]).chaCtrl, "cf_j_kokan");
				case AimTyp.G2Face:
					return ChaTools.FindInCha(((CharaData)hFlag.lstHeroine[1]).chaCtrl, "cf_J_NoseBridge_rx");
				case AimTyp.G2Chest:
					return ChaTools.FindInCha(((CharaData)hFlag.lstHeroine[1]).chaCtrl, "cf_j_spine03");
				case AimTyp.G2Vagin:
					return ChaTools.FindInCha(((CharaData)hFlag.lstHeroine[1]).chaCtrl, "cf_j_kokan");
				case AimTyp.Partner:
					if (ai.InAction)
					{
						ChaControl val = null;
						val = ((!ai.gAction.IsLeader) ? ai.gAction.Leader.Ai.Cha : (((Object)(object)ai.gAction.Partner2 == (Object)null) ? ai.gAction.Partner1.Ai.Cha : Helper.RandomInList(new List<ChaControl>
						{
							ai.gAction.Partner1.Ai.Cha,
							ai.gAction.Partner2.Ai.Cha
						})));
						if (Object.op_Implicit((Object)(object)val))
						{
							return ChaTools.FindInCha(val, "cf_J_NoseBridge_rx");
						}
					}
					break;
				}
			}
			return ((Component)Camera.main).transform;
		}

