	public class FaceExpr
	{
		public enum Type
		{
			Neutral,
			Kiss,
			Horny1,
			Horny2,
			Cum,
			Lick,
			Suck,
			Sad
		}

		public class Expression
		{
			public int eyebrows;

			public float eyebrowsOpMax = 1f;

			public int eyes;

			public float eyesOpMax = 1f;

			public int mouth;

			public float mouthOpMax = 1f;

			public float mouthOpMin;

			public int tears;

			public bool blink = true;

			public bool shakeSpec;

			public bool redCheek;
		}

		public static void SetExpression(ChaControl cha, Expression expr)
		{
			//IL_00cd: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d2: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ea: Unknown result type (might be due to invalid IL or missing references)
			//IL_0099: Unknown result type (might be due to invalid IL or missing references)
			//IL_009e: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b6: Unknown result type (might be due to invalid IL or missing references)
			cha.ChangeEyebrowPtn(expr.eyebrows, true);
			cha.ChangeEyebrowOpenMax(expr.eyebrowsOpMax);
			cha.ChangeEyesPtn(expr.eyes, true);
			cha.ChangeEyesOpenMax(expr.eyesOpMax);
			cha.ChangeMouthPtn(expr.mouth, true);
			cha.ChangeMouthOpenMax(expr.mouthOpMax);
			((FBSBase)((ChaInfo)cha).mouthCtrl).OpenMin = expr.mouthOpMin;
			cha.tearsLv = (byte)expr.tears;
			cha.ChangeEyesBlinkFlag(expr.blink);
			cha.ChangeEyesShaking(expr.shakeSpec);
			if (expr.redCheek)
			{
				Color cheekColor = ((ChaInfo)cha).fileCustom.face.baseMakeup.cheekColor;
				cheekColor.a = 0.28f;
				((ChaInfo)cha).customMatFace.SetColor("_overcolor2", cheekColor);
			}
			else
			{
				Color cheekColor2 = ((ChaInfo)cha).fileCustom.face.baseMakeup.cheekColor;
				cheekColor2.a = 0f;
				((ChaInfo)cha).customMatFace.SetColor("_overcolor2", cheekColor2);
			}
		}

		public static Expression GetExpression(Type typ, bool inAhegao, bool forceTongueOut = false)
		{
			Expression expression = new Expression();
			if (typ == Type.Neutral && inAhegao)
			{
				expression.eyes = 19;
				expression.eyebrows = 2;
				expression.mouth = 1;
				expression.mouthOpMin = 0.1f;
			}
			if (typ == Type.Kiss)
			{
				expression.eyebrows = 13;
				expression.eyes = 1;
				expression.eyesOpMax = 0f;
				expression.mouth = (inAhegao ? 24 : 23);
			}
			if (typ == Type.Horny1)
			{
				expression.eyes = (inAhegao ? 20 : 4);
				expression.eyesOpMax = 0.9f;
				expression.mouth = ((!inAhegao) ? 1 : 26);
			}
			if (typ == Type.Horny2)
			{
				expression.eyebrows = 2;
				expression.eyes = (inAhegao ? 11 : 7);
				expression.eyesOpMax = 0.8f;
				expression.mouth = (inAhegao ? 19 : 2);
			}
			if (typ == Type.Lick)
			{
				expression.eyebrows = 14;
				expression.eyes = 7;
				expression.eyesOpMax = 0.8f;
				expression.mouthOpMin = 0.6f;
				expression.mouth = 21;
			}
			if (typ == Type.Suck)
			{
				expression.eyebrows = 14;
				expression.eyes = 7;
				expression.eyesOpMax = 0.8f;
				expression.mouthOpMin = 1f;
				expression.mouth = 22;
			}
			if (typ == Type.Cum)
			{
				expression.eyebrows = 2;
				expression.eyes = (inAhegao ? 25 : 3);
				expression.mouth = (inAhegao ? 24 : 2);
			}
			if (typ == Type.Sad)
			{
				expression.eyebrows = 13;
				expression.eyes = 7;
				expression.mouth = 33;
			}
			if (inAhegao)
			{
				expression.redCheek = true;
				expression.shakeSpec = true;
				expression.tears = 3;
				expression.eyebrowsOpMax = Mathf.Max(expression.eyebrowsOpMax - 0.1f, 0f);
				expression.eyesOpMax = Mathf.Max(expression.eyesOpMax - 0.2f, 0f);
			}
			if (forceTongueOut)
			{
				expression.mouth = 24;
			}
			return expression;
		}
	}
