			}
			bool includeSpecial = Ai.excitation > 15f;
			int specialAddTime = ((Ai.excitation > 20f) ? 2 : ((Ai.excitation > 30f) ? 3 : ((!(Ai.excitation > 45f)) ? 1 : 5)));
			if (!IsTargetByClothMenu && changeSpotDraw >= 60f && CtrlHome.GetNextSpot(ref nextSpot, Spot, includeSpecial, specialAddTime) && !inMove)
