		private void PlaySpotAnim(bool atWalkEnd = false)
		{
			//IL_02da: Unknown result type (might be due to invalid IL or missing references)
			List<Animations.Clip> list = new List<Animations.Clip>();
			((MonoBehaviour)this).StopAllCoroutines();
			if (Spot.spotTyp == CtrlHome.SpotTyp.Special)
			{
				list = ((!(Ai.excitation < 35f)) ? new List<Animations.Clip>
				{
					Animations.Clip.Dance_04,
					Animations.Clip.Dance_07,
					Animations.Clip.Dance_10,
					Animations.Clip.Dance_11
				} : new List<Animations.Clip>
				{
					Animations.Clip.Dance_01,
					Animations.Clip.Dance_02,
					Animations.Clip.Dance_05
				});
				if (Spot.excludedClips.Count != 0)
				{
					foreach (Animations.Clip excludedClip in Spot.excludedClips)
					{
						list.Remove(excludedClip);
					}
				}
				Spot.clips.Clear();
				foreach (Animations.Clip item in list)
				{
					if (!actionClips.Contains(item))
					{
						Spot.clips.Add(item);
					}
				}
				if (list.Count > 1 && list.Contains(curClip))
				{
					list.Remove(curClip);
				}
				Animations.Clip clip = Helper.RandomInList(list);
				int count = list.Count;
				if (Clothes.GetAvailables(Ai.Cha).Count != 0 && !IsTargetByClothMenu)
				{
					bool flag = Clothes.HasCloth(Ai.Cha);
					for (int i = 0; i < count; i++)
					{
						list.Add(flag ? Animations.Clip.StripBra_01 : Animations.Clip.RedressBra_01);
					}
					if (!ChaTools.IsClean(Ai.Cha))
					{
						list = new List<Animations.Clip>
						{
							flag ? Animations.Clip.StripBra_01 : Animations.Clip.RedressBra_01,
							flag ? Animations.Clip.StripBra_01 : Animations.Clip.RedressBra_01
						};
					}
				}
				list.Shuffle();
				Animations.Clip clip2 = (curClip = Helper.RandomInList(list));
				Ai.IncreaseExcitation(10f);
				if ((clip2 == Animations.Clip.StripBra_01 || clip2 == Animations.Clip.RedressBra_01) && !Ai.InAction)
				{
					curClip = clip;
					Ai.SetAnimClipButDontPlay(clip, autoSetTyp: true);
					Cam.DoFade(0.25f);
					Ai.gAction = GuestAction.Create(Ai, GuestAction.Type.Strip);
					Ai.gAction.SetStripFlag(top: true, bot: true);
					if (clip2 == Animations.Clip.RedressBra_01)
					{
						(Ai.gAction as Strip).stripTyp = Strip.StripTyp.Redress;
						int num = Mathf.Max(girlAtHome.coordinateId - 1, 0);
						ChaTools.CleanAll(Ai.Cha, doBubble: true);
						((ChaFile)((ChaInfo)Ai.Cha).chaFile).status.coordinateType = num;
						Ai.Cha.ChangeCoordinateTypeAndReload(Clothes.GetCoordTyp(num), true);
						Ai.Cha.SetClothesStateAll((byte)3);
						girlAtHome.coordinateId = num;
					}
					actionLimit = float.PositiveInfinity;
					return;
				}
			}
			else
			{
				list.AddRange(Spot.clips);
				if (list.Count > 1 && list.Contains(curClip))
				{
					list.Remove(curClip);
				}
				curClip = Helper.RandomInList(list);
				Ai.IncreaseExcitation(2.5f);
			}
			Ai.ApplyAnimClip(curClip, fade: true, autoSetTyp: true);
			((MonoBehaviour)this).StartCoroutine(IE_WaitEndAndAdapt());
		}

		private void SetMoverToSpotPos()
		{
			//IL_0011: Unknown result type (might be due to invalid IL or missing references)
			//IL_002b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0030: Unknown result type (might be due to invalid IL or missing references)
			Ai.Mover.SetMoverPosition(Spot.pos, Quaternion.Euler(new Vector3(0f, Spot.rotY, 0f)));
		}

		private IEnumerator IE_MoveToNextSpot(CtrlHome.Spot nextSpot)
		{
			yield return (object)new WaitForEndOfFrame();
			Spot.attachedGirl = null;
			Spot = null;
			inMove = true;
			Ai.Mover.SetMoverPosition(startPos, Ai.Mover.RootRot);
			curClip = Animations.Clip.Walk_01;
			Ai.ApplyAnimClip(curClip, fade: true, autoSetTyp: true);
			yield return (object)new WaitUntil((Func<bool>)(() => !inMove));
			actionLimit = DefineActionLimit() + 5f;
			actionTime = 0f;
			nextSpot.isTargeted = false;
			nextSpot.attachedGirl = girlAtHome;
			Spot = nextSpot;
			yield return (object)new WaitForEndOfFrame();
			SetMoverToSpotPos();
			PlaySpotAnim(atWalkEnd: true);
		}

		private IEnumerator IE_WaitEndAndAdapt()
		{
			yield return (object)new WaitForSeconds(Time.deltaTime);
			float num = ChaTools.StateDuration(Ai.Cha) - Time.deltaTime;
			yield return (object)new WaitForSeconds(num);
			if (!Animations.perfectLoop.Contains(curClip))
			{
				yield return (object)new WaitForSeconds(2.5f);
			}
			if (!ActionLimitCameFromClips.Contains(curClip))
			{
				PlayAnimState(Animations.GetStateFromClip(curClip).ToString(), replay: true);
			}
			if (ActionLimitCameFromClips.Contains(curClip))
			{
				ChangeActionAuto();
			}
		}

		private IEnumerator IE_Init()
		{
			yield return (object)new WaitUntil((Func<bool>)(() => Ai.IsInit && (Object)(object)Ai.Mover != (Object)null));
			yield return (object)new WaitForSeconds(Time.deltaTime * 2f);
			yield return (object)new WaitForEndOfFrame();
			SetMoverToSpotPos();
			isInit = true;
			actionLimit = DefineActionLimit();
			PlaySpotAnim();
		}

		public static HomeActions Create(AIGuest ai, CtrlHome.Spot startSpot, CtrlHome.GirlAtHome girlAtHome)
		{
			HomeActions homeActions = ((Component)ai).gameObject.AddComponent<HomeActions>();
			homeActions.Ai = ai;
			homeActions.Spot = startSpot;
			homeActions.girlAtHome = girlAtHome;
			return homeActions;
		}
	}
	public class MakerCtrl : MonoBehaviour
	{
		public const string cmpName = "MakerCtrl";

		private ChaControl cha;

		private int pitchParam;

		private int persoParam;

		private int personality;

		private AudioSource lastAudio;

		private void Start()
		{
			cha = ((Component)this).gameObject.GetComponent<ChaControl>();
			GetParamAndDefinePerso();
			DefineVoiceRate();
		}

		private void LateUpdate()
		{
			if (persoParam != ChaTools.BoyPersoParam(cha))
			{
				GetParamAndDefinePerso(playVoice: true);
			}
			if (pitchParam != ChaTools.BoyVoiceRateParam(cha))
			{
				DefineVoiceRate(playVoice: true);
			}
		}

		private void OnDestroy()
		{
			DebugInfos.InConsole(" Destroyed", "MakerCtrl");
		}

		private void GetParamAndDefinePerso(bool playVoice = false)
		{
			persoParam = ChaTools.BoyPersoParam(cha);
			personality = ChaTools.GetBoyPersonality(persoParam);
			((ChaInfo)cha).fileParam.personality = personality;
			if (playVoice)
			{
				PlayVoiceSample();
			}
			DebugInfos.InConsole(" tracked param changed to " + persoParam + " personality set to " + personality, "MakerCtrl");
		}

		private void DefineVoiceRate(bool playVoice = false)
		{
			pitchParam = ChaTools.BoyVoiceRateParam(cha);
			((ChaInfo)cha).fileParam.voiceRate = ChaTools.GetBoyVoiceRate(pitchParam);
			if (playVoice)
			{
				PlayVoiceSample(Voices.Type.Comment);
			}
		}

		private void PlayVoiceSample(Voices.Type smpTyp = Voices.Type.Hello)
		{
			if ((Object)(object)lastAudio != (Object)null)
			{
				lastAudio.Stop();
			}
			Voices.Clip clip = Helper.RandomInList(Voices.GetClipListFromTyp(smpTyp));
			lastAudio = CtrlFace.StaticSpeak(clip, cha, ChaTools.FindInCha(cha, "cf_J_MouthMove"), force: true);
		}

		public static MakerCtrl Create(ChaControl cha)
		{
			MakerCtrl result = ((Component)cha).gameObject.AddComponent<MakerCtrl>();
			DebugInfos.InConsole(" Created on " + ChaCore.Name(((ChaInfo)cha).fileParam), "MakerCtrl");
			return result;
		}
	}
