			}
			itms.col.isTrigger = (skipColTriggerOff ? true : false);
			if (movTyp == MoveType.Custom)
			{
				yield return (object)new WaitUntil((Func<bool>)(() => !Core.dealer.InMoversCustomMove || HManage.forceCusMovEnd));
