				val.CreateFolderInfoEx("BepInEx/plugins/ksPlug/Required/OffsetsForSmaller/", new string[1] { "*.txt" }, true);
				for (int i = 0; i < val.GetFileCount(); i++)
				{
					ReadFile(val.lstFile[i].FileName);
				}
			}
		}

		public static void ReadFile(string fileName, bool nameIsPath = true)
		{
			string path = "BepInEx/plugins/ksPlug/Required/OffsetsForSmaller/" + fileName + ".txt";
			if (!File.Exists(path))
			{
				return;
			}
			string[] array = PlugText.ReadFile(path).Split(new string[1] { "\n" }, StringSplitOptions.None);
			bool flag = false;
			string text = string.Empty;
			List<string> list = new List<string>();
			string[] array2 = array;
			foreach (string text2 in array2)
			{
				if (text2.Contains("//"))
				{
					continue;
				}
				string text3 = text2.Replace(" ", "");
				text3 = text3.Trim();
				if (text2.Contains("{") || flag)
				{
					text += text3;
					if (text2.Contains("}"))
					{
						list.Add(text);
						text = string.Empty;
						flag = false;
					}
					else
					{
						flag = true;
					}
				}
			}
			Dictionary<string, List<CtrlBones.Offsets>> dictionary = new Dictionary<string, List<CtrlBones.Offsets>>();
			bool flag2 = false;
			foreach (string item in list)
			{
				string key = Helper.GetStringAtIndex(item, "=", 1).Trim();
				List<string> list2 = PlugText.ParseStringList(Helper.GetStringAtIndex(item, "=", 2), new string[3] { "{", "}", ";" });
				List<CtrlBones.Offsets> list3 = new List<CtrlBones.Offsets>();
				foreach (string item2 in list2)
				{
					CtrlBones.Offsets offsets = CtrlBones.BuildOffsetsFromText(item2);
					if (offsets != null)
					{
						list3.Add(offsets);
					}
				}
				if (list3.Count > 0)
				{
					flag2 = true;
					dictionary[key] = list3;
				}
			}
			if (flag2)
			{
				offsetInfoDic[fileName] = dictionary;
			}
		}

		public static void SearchAndSubscribe(ChaControl cha, ChaTyp chaTyp, string animAsset, string animState = "", bool isMainCha = false)
		{
			CtrlBones component = ((Component)cha).gameObject.GetComponent<CtrlBones>();
			if (!Settings.OffsetOversized || (Object)(object)component == (Object)null)
			{
				return;
			}
			animAsset = (animAsset.Contains("/") ? Helper.GetLastString(animAsset, "/", rmvExt: true) : animAsset);
			Dictionary<string, List<CtrlBones.Offsets>> value = new Dictionary<string, List<CtrlBones.Offsets>>();
			if (!offsetInfoDic.TryGetValue(animAsset, out value))
			{
				return;
			}
			foreach (KeyValuePair<string, List<CtrlBones.Offsets>> item in value)
			{
				string text = Helper.GetStringAtIndex(item.Key, "/", 1).Trim();
				string text2 = Helper.GetStringAtIndex(item.Key, "/", 2).Trim();
				if (!(chaTyp.ToString() == text) || (!(text2 == "Default") && (string.IsNullOrEmpty(animState) || !(animState == text2))))
				{
					continue;
				}
				foreach (CtrlBones.Offsets item2 in item.Value)
				{
					component.SubscribeToOffset(item2, CtrlBones.OffsetType.ExtraSizeOffset);
				}
			}
		}
	}
