					if (value.burnBySun)
					{
						value.negEvents.Add(-49);
						int item = ((int)(Helper.Round(value.suntanStrenght) * 10f) + 50) * -1;
						value.negEvents.Add(item);
					}
					foreach (int negEvent in value.negEvents)
					{
						key.talkEvent.Add(negEvent);
					}
					((ChaFile)((CharaData)key).charFile).custom.body.shapeValueBody[4] = value.bustSize;
				}
			}
			DailyDic.Clear();
