		private static Daily CreateDailyFromSave(Heroine save)
		{
			//IL_006d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0056: Unknown result type (might be due to invalid IL or missing references)
			//IL_0072: Unknown result type (might be due to invalid IL or missing references)
			//IL_0079: Unknown result type (might be due to invalid IL or missing references)
			//IL_007e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0083: Unknown result type (might be due to invalid IL or missing references)
			//IL_0108: Unknown result type (might be due to invalid IL or missing references)
			//IL_010e: Invalid comparison between Unknown and I4
			Daily daily = new Daily();
			daily.save = save;
			daily.bustSize = ((ChaFile)((CharaData)save).charFile).custom.body.shapeValueBody[4];
			daily.burnBySun = save.talkEvent.Contains(-49);
			daily.skinDefColor = (daily.burnBySun ? ((ChaFile)((CharaData)save).charFile).custom.body.sunburnColor : ((ChaFile)((CharaData)save).charFile).custom.body.skinMainColor);
			daily.suntanColor = ChaTools.GetSuntanColor(daily.skinDefColor);
			if (daily.burnBySun)
			{
				float num = 0f;
				for (int i = 0; i <= 10; i++)
				{
					int item = (i + 50) * -1;
					if (save.talkEvent.Contains(item))
					{
						num = i;
						break;
					}
				}
				daily.suntanStrenght = num / 10f;
				DebugInfos.InConsole("!!! " + ((CharaData)save).firstname + " has custom sunburn, strength is " + daily.suntanStrenght);
			}
			daily.pregnant = IsSavePregnant(save);
			daily.isRiskyDay = (int)HFlag.GetMenstruation(save.MenstruationDay) == 1;
			if (daily.pregnant)
			{
				daily.bellyBuldge = 1f;
				daily.pregDay = GetPregnancyDay(daily.save);
			}
			for (int num2 = -1; num2 > -130; num2--)
			{
				if (save.talkEvent.Contains(num2))
				{
					daily.negEvents.Add(num2);
				}
			}
			DebugInfos.InConsoleCompact(" Create daily for " + ChaCore.Name(((CharaData)save).parameter) + ", " + (daily.isRiskyDay ? "RISKY DAY!" : "Safe day"), "Statistic", debug);
			return daily;
		}

