			if (num2 == -1)
			{
				((CharaData)sav).parameter.interest.answer[1] = coi;
				return;
			}
			int num3 = Mathf.Abs(((CharaData)sav).parameter.interest.answer[0] - coi);
			int num4 = Mathf.Abs(((CharaData)sav).parameter.interest.answer[1] - coi);
			if (num3 < num4 && coi != 4)
			{
				((CharaData)sav).parameter.interest.answer[0] = coi;
			}
			else if (num4 < num3 && coi != 0)
			{
				((CharaData)sav).parameter.interest.answer[1] = coi;
			}
			else
			{
				((CharaData)sav).parameter.interest.answer[0] = coi;
			}
		}

		public static int GetMaxFavor(Heroine sav)
		{
			return ((sav.fixCharaID < 0) ? sav.relationNPC : sav.relation) switch
			{
				1 => 100, 
				0 => 75, 
				_ => 150, 
			};
		}

		public static int GetRelationCustomID(Heroine sav)
		{
			bool flag = sav.countKokanH + sav.countAnalH + sav.houshiExp != 0f;
			switch ((sav.fixCharaID < 0) ? sav.relationNPC : sav.relation)
			{
			default:
				if (sav.relation != 2)
				{
					return 4;
				}
				return 3;
			case 1:
				if (flag)
				{
					return 2;
				}
				return 1;
			case 0:
				return 0;
			}
		}

		public static int GetRelationID(Heroine sav)
		{
			if (sav.fixCharaID >= 0)
			{
				return sav.relation;
			}
			return sav.relationNPC;
		}

		public static void CorrectVirginityValues(Heroine sav)
		{
			if (sav.isVirgin && sav.countKokanH != 0f)
			{
				sav.countKokanH = 0f;
			}
			else if (sav.isVirgin && sav.countKokanH != 0f)
			{
				sav.isVirgin = false;
			}
			else if (!sav.isVirgin && sav.countKokanH == 0f)
			{
				sav.countKokanH = 1f;
			}
			if (sav.isAnalVirgin && sav.countAnalH != 0f)
			{
				sav.countAnalH = 0f;
			}
			else if (sav.isAnalVirgin && sav.countAnalH != 0f)
			{
				sav.isAnalVirgin = false;
			}
			else if (!sav.isAnalVirgin && sav.countAnalH == 0f)
			{
				sav.countAnalH = 1f;
			}
		}

		public static void ClampHExpTo100(Heroine sav)
		{
			sav.countKokanH = Mathf.Min(100f, sav.countKokanH);
			sav.countAnalH = Mathf.Min(100f, sav.countAnalH);
			sav.houshiExp = Mathf.Min(100f, sav.houshiExp);
			for (int i = 0; i < sav.hAreaExps.Length; i++)
			{
				sav.hAreaExps[i] = Mathf.Min(100f, sav.hAreaExps[i]);
			}
			for (int j = 0; j < sav.massageExps.Length; j++)
			{
				sav.massageExps[j] = Mathf.Min(100f, sav.massageExps[j]);
			}
		}

		public static void SetDailyEvent(Heroine her, List<DailyEvent> events, Daily daily = null)
		{
			if (daily == null)
			{
				daily = GetDaily(her);
			}
			if (daily != null)
			{
				if (events.Contains(DailyEvent.wakeTogether))
				{
					daily.wakeTogether = true;
				}
				if (events.Contains(DailyEvent.esthetic))
				{
					daily.esthetic++;
				}
				if (events.Contains(DailyEvent.talkEvent))
				{
					daily.talkEvent++;
				}
				if (events.Contains(DailyEvent.homeMast))
				{
					daily.homeMast++;
				}
				if (events.Contains(DailyEvent.cumOn))
				{
					daily.cumOn++;
				}
				if (events.Contains(DailyEvent.timeTogether))
				{
					daily.timeTogether += Time.deltaTime;
				}
				if (events.Contains(DailyEvent.hTimeTogether))
				{
					daily.hTimeTogether += Time.deltaTime;
				}
			}
		}

		public static int GetHCountFromHistory(Daily daily, CountTyp typ, Count sessionCount = null)
		{
			int num = 0;
			int num2 = 7;
			List<Count> list = new List<Count>();
			list.AddRange(daily.ecchiHist);
			if (sessionCount != null)
			{
				list.Add(sessionCount);
			}
			foreach (Count item in list)
			{
				if (typ == CountTyp.Kiss)
				{
					num += item.kiss;
				}
				if (typ == CountTyp.InPussyEja)
				{
					num += item.sonyuInside * num2;
				}
				if (typ == CountTyp.InAssEja)
				{
					num += item.sonyuAnalInside * num2;
				}
				if (typ == CountTyp.InMouthEja)
				{
					num += Mathf.Max(item.houshiInside - item.houshiVomit, 0) * num2;
				}
				if (typ == CountTyp.TotalOrg)
				{
					num += item.sonyuAnalOrg + item.sonyuOrg + item.aibuOrg;
				}
				if (typ == CountTyp.OutQuantity)
				{
					num += item.houshiOutside * num2 + item.sonyuOutside * num2 + item.sonyuOutside * num2;
				}
			}
			if (typ == CountTyp.OutQuantity)
			{
				num += daily.cumOn * num2;
			}
			if (typ == CountTyp.TotalOrg)
			{
				num += daily.homeMast;
			}
			return num;
		}

		public static bool IsSavePregnant(Heroine sav)
		{
			return GetDaily(sav)?.negEvents.Contains(-100) ?? sav.talkEvent.Contains(-100);
		}

		public static void TriggerPregnancy(Heroine sav, bool updateSave = false)
		{
			Daily daily = GetDaily(sav);
			if (daily != null)
			{
				daily.negEvents.Add(-100);
				daily.negEvents.Add(-101);
				daily.pregnant = true;
				daily.pregDay = 1;
				daily.bellyBuldge = 1f;
			}
			if (updateSave)
			{
				sav.talkEvent.Add(-100);
			}
			sav.talkEvent.Add(-101);
		}

		public static bool SetPregnancyNextDay(Heroine sav)
		{
			Daily daily = GetDaily(sav);
			bool flag = false;
			if (daily != null)
			{
				if (!daily.negEvents.Contains(-100))
				{
					return false;
				}
				for (int i = 1; i < 29; i++)
				{
					int num = (i + 100) * -1;
					if (daily.negEvents.Contains(num) && num != -128)
					{
						int num2 = num - 1;
						daily.negEvents.Add(num2);
						daily.negEvents.Remove(num);
						if ((num2 + 100) * -1 > Settings.PregnancyLimit)
						{
							flag = true;
						}
						break;
					}
				}
			}
			if (flag)
			{
				RemovePregancyFromSave(sav);
				Core.dealer.Msgn.ReceiveMessage(Messenger.Type.TopCorner_R, ((CharaData)sav).firstname + " has delivered her baby !!! ", 7f, replace: false);
			}
			return flag;
		}

		public static int GetPregnancyDay(Heroine sav)
		{
			Daily daily = GetDaily(sav);
			for (int i = 1; i < 29; i++)
			{
				int item = (i + 100) * -1;
				if (daily != null)
				{
					if (daily.negEvents.Contains(item))
					{
						return i;
					}
				}
				else if (sav.talkEvent.Contains(item))
				{
					return i;
				}
			}
			return -1;
		}

		public static void RemovePregancyFromSave(Heroine sav)
		{
			Daily daily = GetDaily(sav);
			for (int i = 0; i < 29; i++)
			{
				int item = (i + 100) * -1;
				if (sav.talkEvent.Contains(item))
				{
					sav.talkEvent.Remove(item);
				}
				if (daily != null && daily.negEvents.Contains(item))
				{
					daily.negEvents.Remove(item);
				}
			}
			if (daily != null)
			{
				daily.pregnant = false;
			}
		}

		public static void RemoveNegEventsFromSave(Heroine sav)
		{
			for (int num = -1; num > -130; num--)
			{
				if (sav.talkEvent.Contains(num))
				{
					sav.talkEvent.Remove(num);
				}
			}
		}

