		public static int PlaceToSaveEvent(int stayPlace)
		{
			return (stayPlace + 10) * -1;
		}

		public static void RemoveStayWithPlayerPlace(Heroine sav, bool includeDaily = false)
		{
			Daily daily = GetDaily(sav);
			int[] array = new int[3] { -10, -11, -12 };
			foreach (int item in array)
			{
				sav.talkEvent.Remove(item);
				if (daily != null && includeDaily)
				{
					daily.negEvents.Remove(item);
				}
			}
		}

		public static void RemoveStayWithPlayerPlace(ref List<int> listToClean)
		{
			int[] array = new int[3] { -10, -11, -12 };
			foreach (int item in array)
			{
				listToClean.Remove(item);
			}
		}

		public static void SetStayWithPlayerPlace(Heroine sav, int stayPlace)
		{
			//IL_0011: Unknown result type (might be due to invalid IL or missing references)
			if (Core.dealer.Ctx == Dealer.Context.Default && (int)Core.dealer.NowCycle == 0)
			{
				RemoveStayWithPlayerPlace(sav);
				sav.talkEvent.Add(PlaceToSaveEvent(stayPlace));
			}
			Daily daily = GetDaily(sav);
			if (daily != null)
			{
				RemoveStayWithPlayerPlace(ref daily.negEvents);
				daily.negEvents.Add(PlaceToSaveEvent(stayPlace));
			}
		}

		public static bool IsStayingWithPlayer(Heroine sav, int stayPlace)
		{
			return GetDaily(sav)?.negEvents.Contains(PlaceToSaveEvent(stayPlace)) ?? sav.talkEvent.Contains(PlaceToSaveEvent(stayPlace));
		}

		public static bool RoomIsFull(int stayPlace)
		{
			int num = 0;
			foreach (Heroine heroine in Game.HeroineList)
			{
				if (IsStayingWithPlayer(heroine, stayPlace))
				{
					num++;
				}
			}
			return num >= CtrlHome.MaxGirl;
		}

		public static void ManagePlaceWithPlayer(int stayPlace)
		{
			List<Heroine> list = new List<Heroine>();
			foreach (Heroine heroine in Game.HeroineList)
			{
				int item = PlaceToSaveEvent(stayPlace);
				Daily daily = GetDaily(heroine);
				if (heroine.talkEvent.Contains(item) || (daily != null && daily.negEvents.Contains(item)))
				{
					list.Add(heroine);
				}
			}
			if (list.Count >= CtrlHome.MaxGirl)
			{
				RemoveStayWithPlayerPlace(list[list.Count - 1]);
				Daily daily2 = GetDaily(list[list.Count - 1]);
				if (daily2 != null)
				{
					RemoveStayWithPlayerPlace(ref daily2.negEvents);
				}
			}
		}
	}
