		public static Loader Loader(Clip clip, int perso, float pitch, Transform audioSrcTrs, bool debugVoiceLoader = false)
		{
			//IL_0023: Unknown result type (might be due to invalid IL or missing references)
			//IL_0029: Expected O, but got Unknown
			DebugInfos.InConsoleCompact(" Try to load " + clip, "Voice.Loader", debugVoiceLoader);
			Loader val = new Loader();
			Dictionary<Clip, List<string>> dictionary = VoicePaths(perso);
			List<string> value = new List<string>();
			dictionary.TryGetValue(clip, out value);
			val.no = perso;
			val.pitch = pitch;
			val.bundle = value[0];
			val.asset = value[1];
			val.settingNo = ((!Core.dealer.InH) ? 1 : (-1));
			DebugInfos.InConsoleCompact("\tbundle : " + val.asset.ToString() + " perso :" + val.no, "Voice.Loader", debugVoiceLoader);
			if ((Object)(object)audioSrcTrs != (Object)null)
			{
				val.voiceTrans = audioSrcTrs;
			}
			return val;
		}
	}
